def correction_chain(message: AIMessage, **kwargs) -> str:
    # match unquoted values until the next key or the end of the json object
    pattern = (
        r"(\"[a-zA-Z0-9_]*\"):\s*(.*?)(?=(,\n\s*(\"[a-zA-Z0-9_]*\"):|\n}$|\n}.{3,5}$))"
    )

    def correct_content(match):
        key, value = match.groups()[0], match.groups()[1]

        if kwargs.get("double_quates2single_quate", False):
            value = re.sub(r'"', "'", value)

        # single backslashes not indicating python special character should be removed
        PATTERN_WORD = (
            r'(?<!\\)(?:\\\\)*\\(?!["\\\/]|[bfnrt](?![a-zA-Z])|u[0-9a-fA-F]{4})'
        )
        corrected_value = re.sub(PATTERN_WORD, r"\\\\", value)

        if kwargs.get("ensure_value_quates", False):
            corrected_value = (
                corrected_value[1:-1]
                if (corrected_value.startswith("'") and corrected_value.endswith("'"))
                else corrected_value
            )
            # quote the corrected value
            return f'{key}: "{corrected_value}"'
        else:
            return f"{key}: {corrected_value}"

    return re.sub(pattern, correct_content, message.content, flags=re.DOTALL)

class LangChainAIService(AIServiceProtocol):
    def __init__(self, llm_model_factory: ILLMModelFactory):
        self.llm_model_factory = llm_model_factory

    async def process(
        self,
        prompt: StructuredPrompt,
        input_variables: Optional[BaseModel] = None,
        cleanse_llm_text: bool = False,
        **kwargs,
    ) -> Dict[str, Any]:
        model = self.llm_model_factory[prompt.ai_model_hint, prompt.ai_model_engine]
        parser = StructuredOutputParser.from_response_schemas(
            [ResponseSchema(**schema) for schema in prompt.schemas],
        )
        tmpl = PromptTemplate(
            template=prompt.template,
            input_variables=prompt.input_variables,
            partial_variables={"format_instructions": parser.get_format_instructions()},
        )
        chain = await self.create_chain(cleanse_llm_text, model, parser, tmpl)
        return await chain.with_config(
            configurable={"llm_temperature": prompt.temperature},
        ).ainvoke(input_variables.model_dump(mode="json"))

    @staticmethod
    async def create_chain(cleanse_llm_text: bool, model, parser, tmpl: PromptTemplate):
        if cleanse_llm_text:
            chain = tmpl | model | llm_result_correction_chain | parser
        else:
            chain = tmpl | model | parser
        return chain

class AzureLangchainLLM(ILLMModel, AzureChatOpenAI):
    def __init__(self, settings: BaseLLMModelSetting, **kwargs):
        super(AzureLangchainLLM, self).__init__()
        AzureChatOpenAI.__init__(
            self,
            openai_api_version=settings.connection_config.azure_api_version,
            openai_api_key=settings.connection_config.azure_key,
            deployment_name=settings.ai_model_name,
            temperature=settings.temperature,
            azure_endpoint=settings.connection_config.azure_endpoint,
            openai_api_type=settings.connection_config.azure_api_type,
            model_name=settings.ai_model_name,
        )

        self.configurable_fields(
            temperature=ConfigurableField(
                id="temperature",
                name="LLM Temperature",
                description="The temperature of the LLM",
            ),
        )
        self._settings = settings
        self._openai_fallback: OpenAILangchainLLM | None = None

    @property
    def model_id(self):
        return self.model_name

    def _initialize_fallback(self) -> OpenAILangchainLLM:
        """Initialize OpenAI fallback with connection settings from environment.

        Returns:
            Configured OpenAI LLM instance.
        """
        fallback_connection = LLMConnectionSetting()
        fallback_settings = BaseLLMModelSetting(
            framework=self._settings.framework,
            engine_name="openai",
            ai_model_name=self._settings.ai_model_name,
            temperature=self._settings.temperature,
            connection_config=fallback_connection,
        )
        return OpenAILangchainLLM(settings=fallback_settings)

    def set_parameters(self, model_name=None, temperature=None, *args, **kwargs):
        pass

    def invoke(self, *args, **kwargs):
        """Invoke Azure LLM with fallback to OpenAI on failure.

        Returns:
            LLM response.

        Raises:
            Exception: If both Azure and OpenAI fallback fail.
        """
        try:
            return super().invoke(*args, **kwargs)
        except (RateLimitError, Exception) as e:
            LOGGER.warning(f"Azure LLM invoke failed with error: {type(e).__name__}. Switching to OpenAI fallback.")
            if self._openai_fallback is None:
                self._openai_fallback = self._initialize_fallback()
            return self._openai_fallback.invoke(*args, **kwargs)

    async def ainvoke(self, *args, **kwargs):
        """Asynchronously invoke Azure LLM with fallback to OpenAI on failure.

        Returns:
            LLM response.

        Raises:
            Exception: If both Azure and OpenAI fallback fail.
        """
        try:
            return await super().ainvoke(*args, **kwargs)
        except Exception as e:
            LOGGER.warning(
                f"Azure LLM ainvoke failed with error: {type(e).__name__}: {str(e)}. Switching to OpenAI fallback."
            )
            if self._openai_fallback is None:
                self._openai_fallback = self._initialize_fallback()
            return await self._openai_fallback.ainvoke(*args, **kwargs)

    async def astream(self, *args, **kwargs):
        """Asynchronously stream Azure LLM responses with fallback to OpenAI on failure.

        Yields:
            Streaming chunks from the LLM.

        Raises:
            Exception: If both Azure and OpenAI fallback fail.
        """
        try:
            async for chunk in super().astream(*args, **kwargs):
                yield chunk
        except Exception as e:
            LOGGER.warning(
                f"Azure LLM astream failed with error: {type(e).__name__}: {str(e)}. Switching to OpenAI fallback."
            )
            if self._openai_fallback is None:
                self._openai_fallback = self._initialize_fallback()
            async for chunk in self._openai_fallback.astream(*args, **kwargs):
                yield chunk

    def function_call(
        self,
        input_message: str = "",
        system_prompt: str = "",
        template: str = None,
        schema: dict = None,
    ):
        try:
            result = self.invoke(
                input=[SystemMessage(system_prompt), HumanMessage(input_message)]
                if template is None
                else [SystemMessage(template)],
                functions=[schema],
                function_call={"name": schema["name"]},
            )
            return json.loads(result.additional_kwargs["function_call"]["arguments"])
        except (RateLimitError, Exception) as e:
            LOGGER.warning(f"Azure LLM failed with error: {type(e).__name__}. Switching to OpenAI fallback.")
            if self._openai_fallback is None:
                self._openai_fallback = self._initialize_fallback()
            return self._openai_fallback.function_call(
                input_message=input_message,
                system_prompt=system_prompt,
                template=template,
                schema=schema,
            )

    async def a_function_call(
        self,
        input_message: str = "",
        system_prompt: str = "",
        template: str = None,
        schema: dict = None,
    ):
        try:
            result = await self.ainvoke(
                input=[SystemMessage(system_prompt), HumanMessage(input_message)]
                if template is None
                else [SystemMessage(template)],
                functions=[schema],
                function_call={"name": schema["name"]},
            )
            return json.loads(result.additional_kwargs["function_call"]["arguments"])
        except (RateLimitError, Exception) as e:
            LOGGER.warning(f"Azure LLM async call failed with error: {type(e).__name__}. Switching to OpenAI fallback.")
            if self._openai_fallback is None:
                self._openai_fallback = self._initialize_fallback()
            return await self._openai_fallback.a_function_call(
                input_message=input_message,
                system_prompt=system_prompt,
                template=template,
                schema=schema,
            )

class OpensourceCustomModel(LLM):
    url_address: str

    async def _call(
        self,
        prompt: str,
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> str:
        if stop is not None:
            raise ValueError("stop kwargs are not permitted.")

        str_response = await self.send_request(self.url_address, prompt)

        return str_response

    @staticmethod
    async def send_request(url, prompt):
        data = {"prompt": prompt}
        async with aiohttp.ClientSession() as session:
            async with session.post(url, json=data) as response:
                if response.status == 200:
                    return await response.text()
                else:
                    return f"Failed to send POST request. Status: {response.status}"

    def _stream(
        self,
        prompt: str,
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> Iterator[GenerationChunk]:
        for char in prompt[: self.n]:
            chunk = GenerationChunk(text=char)
            if run_manager:
                run_manager.on_llm_new_token(chunk.text, chunk=chunk)

            yield chunk

    @property
    def _identifying_params(self) -> Dict[str, Any]:
        """Return a dictionary of identifying parameters."""
        return {
            # The model name allows users to specify custom token counting
            # rules in LLM monitoring applications (e.g., in LangSmith users
            # can provide per token pricing for their model and monitor
            # costs for the given LLM.)
            "model_name": "CustomChatModel",
        }

    @property
    def _llm_type(self) -> str:
        """Get the type of language model used by this chat model. Used for logging purposes only."""
        return "custom"

class GeminiLangchainLLM(ILLMModel, Runnable):
    def __init__(self, settings: BaseLLMModelSetting, **kwargs):
        self._settings = settings
        self._api_keys = settings.connection_config.gemini_api_keys
        self._current_key_index = 0
        self._unavailable_keys = {}
        self._key_lock = asyncio.Lock()
        self._openai_fallback: OpenAILangchainLLM = None

        ILLMModel.__init__(self)

        self._llm = ChatGoogleGenerativeAI(
            google_api_key=self._api_keys[self._current_key_index],
            model=settings.ai_model_name,
            temperature=settings.temperature,
            verbose=False,
            max_retries=2,
            **kwargs,
        )

        self._llm.configurable_fields(
            temperature=ConfigurableField(
                id="temperature",
                name="LLM Temperature",
                description="The temperature of the LLM",
            ),
        )

    @property
    def model_id(self):
        return self._llm.model

    @property
    def model_name(self):
        return self._llm.model

    @property
    def temperature(self):
        return self._llm.temperature

    @property
    def google_api_key(self):
        return self._llm.google_api_key

    def _mark_key_unavailable(self, key_index: int, duration_seconds: int = 60):
        expiration_time = time.time() + duration_seconds
        self._unavailable_keys[key_index] = expiration_time
        LOGGER.info(f"Key at index {key_index} marked unavailable for {duration_seconds} seconds")

    def _is_key_available(self, key_index: int) -> bool:
        if key_index not in self._unavailable_keys:
            return True

        expiration_time = self._unavailable_keys[key_index]
        if time.time() > expiration_time:
            del self._unavailable_keys[key_index]
            return True

        return False

    def _find_next_available_key(self) -> int:
        if len(self._api_keys) <= 1:
            raise Exception("No alternative API keys available")

        start_index = self._current_key_index
        current = (start_index + 1) % len(self._api_keys)

        while current != start_index:
            if self._is_key_available(current):
                return current
            current = (current + 1) % len(self._api_keys)

        if self._is_key_available(start_index):
            return start_index

        min_expiration = float("inf")
        earliest_key = 0

        for idx, expiration in self._unavailable_keys.items():
            if expiration < min_expiration:
                min_expiration = expiration
                earliest_key = idx

        return earliest_key

    def set_parameters(self, model_name=None, temperature=None, *args, **kwargs):
        model_name = self.model_name if model_name is None else model_name
        temperature = self.temperature if temperature is None else temperature

        self._llm = ChatGoogleGenerativeAI(
            google_api_key=self.google_api_key,
            model=model_name,
            temperature=temperature,
            verbose=False,
            max_retries=2,
            **kwargs,
        )

    def _find_next_untried_key(self, tried_keys: set) -> int:
        if len(self._api_keys) <= 1:
            return self._current_key_index

        for i in range(len(self._api_keys)):
            key_index = (self._current_key_index + i + 1) % len(self._api_keys)
            if key_index not in tried_keys and self._is_key_available(key_index):
                return key_index

        return self._find_next_available_key()

    def invoke(
        self,
        *args,
        **kwargs: Any,
    ) -> ChatResult:
        max_key_attempts = 1
        tried_keys = set()

        for attempt in range(max_key_attempts):
            try:
                tried_keys.add(self._current_key_index)

                return self._llm.invoke(*args, **kwargs)
            except Exception as e:
                error_message = str(e).lower()

                try:
                    delay_seconds = e.details[2].retry_delay.seconds + 10
                except Exception:
                    delay_seconds = 60

                if any(keyword in error_message for keyword in API_KEY_ERROR_PATTERN):
                    if attempt >= max_key_attempts - 1:
                        LOGGER.error(
                            f"All {max_key_attempts} attempts failed when calling a Gemini chain. Raising error."
                        )
                        break

                    self._mark_key_unavailable(self._current_key_index, delay_seconds)

                    next_key_index = self._find_next_untried_key(tried_keys)
                    if next_key_index == self._current_key_index and (
                        len(tried_keys) >= len(self._api_keys) or attempt >= max_key_attempts - 1
                    ):
                        LOGGER.error("All available keys for Gemini have been tried. Raising error.")
                        break

                    self._current_key_index = next_key_index
                    new_api_key = self._api_keys[self._current_key_index]

                    LOGGER.info(f"Switching to API key at index {self._current_key_index}")

                    self._llm = ChatGoogleGenerativeAI(
                        google_api_key=new_api_key,
                        model=self.model_name,
                        temperature=self.temperature,
                        verbose=False,
                        max_retries=2,
                    )
                else:
                    LOGGER.error(f"Non-API key error in invoke: {e}")
                    break

        if self._openai_fallback:
            return self._openai_fallback.invoke(*args, **kwargs)

        raise Exception(f"Failed after {max_key_attempts} API key attempts")

    async def ainvoke(
        self,
        *args,
        **kwargs: Any,
    ) -> ChatResult:
        default_max_key_attempts = 1
        max_key_attempts = (
            args[1].get("configurable", {}).get("max_key_attempts", default_max_key_attempts)
            if len(args) > 1
            else default_max_key_attempts
        )
        tried_keys = set()

        for attempt in range(max_key_attempts):
            try:
                tried_keys.add(self._current_key_index)

                return await self._llm.ainvoke(*args, **kwargs)
            except Exception as e:
                error_message = str(e).lower()

                try:
                    delay_seconds = e.details[2].retry_delay.seconds + 10
                except Exception:
                    delay_seconds = 60

                if any(keyword in error_message for keyword in API_KEY_ERROR_PATTERN):
                    if attempt >= max_key_attempts - 1:
                        LOGGER.error(
                            f"All {max_key_attempts} attempts failed when calling a Gemini chain. Raising error."
                        )
                        break

                    async with self._key_lock:
                        self._mark_key_unavailable(self._current_key_index, delay_seconds)

                        next_key_index = await self._find_next_untried_key_async(tried_keys)
                        if next_key_index == self._current_key_index and (
                            len(tried_keys) >= len(self._api_keys) or attempt >= max_key_attempts - 1
                        ):
                            LOGGER.error("All available keys for Gemini have been tried. Raising error.")
                            break

                        self._current_key_index = next_key_index
                        new_api_key = self._api_keys[self._current_key_index]

                        LOGGER.info(f"Switching to API key at index {self._current_key_index}")

                        self._llm = ChatGoogleGenerativeAI(
                            google_api_key=new_api_key,
                            model=self.model_name,
                            temperature=self.temperature,
                            verbose=False,
                            max_retries=2,
                        )
                else:
                    LOGGER.error(f"Non-API key error in ainvoke: {e}")
                    break

        if self._openai_fallback:
            return await self._openai_fallback.ainvoke(*args, **kwargs)

        raise Exception(f"Failed after {max_key_attempts} API key attempts")

    async def _find_next_untried_key_async(self, tried_keys: set) -> int:
        if len(self._api_keys) <= 1:
            return self._current_key_index

        for i in range(len(self._api_keys)):
            key_index = (self._current_key_index + i + 1) % len(self._api_keys)
            if key_index not in tried_keys and self._is_key_available(key_index):
                return key_index

        return self._find_next_available_key()

    def function_call(
        self,
        input_message: str = "",
        system_prompt: str = "",
        template: str = None,
        schema: dict = None,
    ):
        result = self.invoke(
            input=(
                [SystemMessage(system_prompt), HumanMessage(input_message)]
                if template is None
                else [SystemMessage(template)]
            ),
            tools=[schema],
            tool_choice=None,
        )
        return json.loads(result.additional_kwargs["tool_calls"][0]["function"]["arguments"])

    async def a_function_call(
        self,
        input_message: str = "",
        system_prompt: str = "",
        template: str = None,
        schema: dict = None,
    ):
        result = await self.ainvoke(
            input=(
                [SystemMessage(system_prompt), HumanMessage(input_message)]
                if template is None
                else [SystemMessage(template)]
            ),
            tools=[schema],
            tool_choice=None,
        )
        return json.loads(result.additional_kwargs["tool_calls"][0]["function"]["arguments"])

class OpenAILangchainLLM(ILLMModel, ChatOpenAI):
    def __init__(self, settings: BaseLLMModelSetting, **kwargs):
        super(OpenAILangchainLLM, self).__init__()
        self._settings = settings
        self._model_name = settings.ai_model_name
        self._temperature = settings.temperature
        self._api_key = settings.connection_config.openai_api_token
        self._base_url = settings.connection_config.base_openai_url
        self._fallback_llm = None

        # Define extra parameters for local engines
        self._kwargs = {}
        if settings.engine_name == "local":
            self._kwargs = {
                "tiktoken_model_name": "cl100k_base",
                "extra_body": {"chat_template_kwargs": {"enable_thinking": False}},
            }

        # Initialize the primary LLM
        # IMPORTANT: We do NOT put tool_choice here to keep the base object 'clean'
        if settings.connection_config.backup_proxy:
            kwargs["http_client"] = httpx.Client(proxy=settings.connection_config.backup_proxy)
        self._llm = ChatOpenAI(
            api_key=self._api_key,
            model=self._model_name,
            temperature=self._temperature,
            base_url=self._base_url,
            **self._kwargs,
        )

    @property
    def model_id(self):
        return self._llm.model_name

    def set_parameters(self, model_name=None, temperature=None, *args, **kwargs):
        model_name = model_name or self._model_name
        temperature = temperature or self._temperature

        super(OpenAILangchainLLM, self).__init__()
        self._llm = ChatOpenAI(
            api_key=self._api_key, model=model_name, temperature=temperature, base_url=self._base_url, **self._kwargs
        )

    def invoke(self, *args, **kwargs):
        # Apply local-specific logic if this instance is local
        if self._settings.engine_name == "local":
            kwargs = self._set_local_tool_choice(kwargs)

        try:
            return self._llm.invoke(*args, **kwargs)
        except Exception as e:
            # If we are already the local model, we can't fallback further
            if self._settings.engine_name == "local":
                raise e

            if self._fallback_llm is None:
                fallback = self._get_fallback()
                if fallback is None:
                    raise e

            LOGGER.warning(f"Primary LLM failed: {type(e).__name__}. Switching to local fallback.")
            # Always set tool_choice for fallback since it's always local
            kwargs = self._set_local_tool_choice(kwargs)
            return self._fallback_llm._llm.invoke(*args, **kwargs)

    async def ainvoke(self, *args, **kwargs):
        """Invoke the LLM asynchronously with timeout and fallback support.

        If the primary LLM does not respond within the configured timeout,
        or raises an exception, the call is retried on the fallback LLM.

        Args:
            *args: Positional arguments forwarded to the underlying LLM.
            **kwargs: Keyword arguments forwarded to the underlying LLM.

        Returns:
            The LLM response.

        Raises:
            Exception: If both primary and fallback LLMs fail.
        """
        if self._settings.engine_name == "local":
            kwargs = self._set_local_tool_choice(kwargs)

        try:
            return await asyncio.wait_for(
                self._llm.ainvoke(*args, **kwargs),
                timeout=160.0,
            )
        except (asyncio.TimeoutError, Exception) as e:
            reason = "timed out" if isinstance(e, asyncio.TimeoutError) else type(e).__name__
            LOGGER.warning(f"Primary LLM failed ({reason}). Switching to fallback LLM.")
            fallback = self._get_fallback()
            if fallback is None:
                raise e
            if fallback._settings.engine_name == "local":
                kwargs = self._set_local_tool_choice(kwargs)
            return await fallback._llm.ainvoke(*args, **kwargs)

    def stream(self, *args, **kwargs):
        if self._settings.engine_name == "local":
