                raise
            LOGGER.warning(f"OpenAI LLM a_function_call failed: {type(e).__name__}. Switching to local fallback.")
            return await fallback.a_function_call(
                input_message=input_message,
                system_prompt=system_prompt,
                template=template,
                schema=schema,
            )

    def _set_local_tool_choice(self, kwargs):
        """Adjusts tool_choice for local vLLM compatibility.

        When tools/functions are present, use 'auto'.
        When no tools are present, use 'none' (required by vLLM with --enable-auto-tool-choice).

        Args:
            kwargs: The kwargs dict passed to LLM call.

        Returns:
            Updated kwargs with appropriate tool_choice setting.
        """
        # Check if tools are present in the call
        has_tools = "tools" in kwargs or "functions" in kwargs

        if has_tools:
            # Tools exist - use 'auto' if not already specified
            if "tool_choice" not in kwargs:
                kwargs["tool_choice"] = "auto"
        else:
            # No tools - MUST use 'none' for vLLM validator
            kwargs["tool_choice"] = "none"

        return kwargs

    def _get_fallback(self):
        """Get or initialize fallback local LLM.

        Returns:
            Local LLM instance if configured, None otherwise.
        """
        if self._fallback_llm is not None:
            return self._fallback_llm

        # If the current instance IS the local one, it cannot have a fallback
        if self._settings.engine_name == "local":
            connection = LLMConnectionSetting()
            # Create settings for the local fallback instance
            fallback_settings = BaseLLMModelSetting(
                framework=self._settings.framework,
                engine_name="openai",
                ai_model_name="gpt-4o-mini",
                temperature=self._settings.temperature,
                connection_config={
                    "openai_api_token": connection.openai_api_token,
                    "base_openai_url": connection.base_openai_url,
                },
            )
            # Recursively create the fallback as a local instance
            self._fallback_llm = OpenAILangchainLLM(settings=fallback_settings)  # , kwargs=kwargs

            return self._fallback_llm
            # return None

        else:
            connection = LLMConnectionSetting()
            if not connection.backup_openai_url:
                return None
            connection_config: dict = {
                "openai_api_token": connection.backup_openai_token,
                "base_openai_url": connection.backup_openai_url,
            }
            if connection.backup_proxy:
                connection_config["backup_proxy"] = connection.backup_proxy
            fallback_settings = BaseLLMModelSetting(
                framework=self._settings.framework,
                engine_name="openai",
                ai_model_name="gpt-4o-mini",
                temperature=self._settings.temperature,
                connection_config=connection_config,
            )
            self._fallback_llm = OpenAILangchainLLM(settings=fallback_settings)

            return self._fallback_llm

