class Algorithm(ISpeech2Text):
    def __init__(
        self,
        config: AvanegarSettings,
    ):
        self.config = config

    def post_audio_for_transcription(self, audio_path):
        headers = {
            "gateway-token": self.config.TOKEN,
            "accept": "application/json",
        }

        # Prepare multipart form data with proper tuple format
        filename = os.path.basename(audio_path)

        # Determine mime type based on file extension
        ext = os.path.splitext(audio_path)[1].lower()
        mime_type_map = {
            ".wav": "audio/wav",
            ".mp3": "audio/mpeg",
            ".ogg": "audio/ogg",
            ".flac": "audio/flac",
            ".m4a": "audio/mp4",
        }
        mime_type = mime_type_map.get(ext, "audio/wav")

        with open(audio_path, "rb") as audio_file:
            files = [("audio", (filename, audio_file, mime_type))]
            data = {
                "model": "default",
                "srt": "false",
                "inverseNormalizer": "false",
                "timestamp": "false",
                "spokenPunctuation": "false",
                "punctuation": "false",
                "numSpeakers": "0",
                "diarize": "false",
            }

            response = requests.post(
                self.config.BASE_URL,
                headers=headers,
                files=files,
                data=data,
            )

        if response.status_code in (200, 201):
            response_data = response.json()["data"]

            # Check if the request was successful
            if response_data.get("status") == "success":
                # Extract text from the nested response structure
                ai_response = response_data.get("data", {}).get("aiResponse", {})
                result = ai_response.get("result", {})
                text = result.get("text", "")
                return text
            else:
                LOGGER.error(
                    f"API returned non-success status: {response_data.get('message')}",
                )
                return None
        else:
            LOGGER.error(
                f"Failed to submit audio for transcription: {response.status_code}, {response.text}",
            )
            return None

    def process(self, _input: Speech2TextInput) -> Speech2TextOutput:
        try:
            transcription = self.post_audio_for_transcription(_input.audio_file)
            if transcription:
                return Speech2TextOutput(text=transcription)
            else:
                LOGGER.error("Transcription returned empty result")
                return None
        except Exception as e:
            LOGGER.error("failed to transcribing audio using avanegar! error: %s" % e)
            return None

    async def aprocess(self, _input: Speech2TextInput) -> Speech2TextOutput:
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, self.process, _input)

