class AuthDependency:
    oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/token")

    def __init__(self, token_service: ITokenService):
        self.token_service = token_service

    def __call__(self, token: str = Depends(oauth2_scheme)) -> str:
        try:
            if not token:
                raise ValueError("Token not provided")

            payload = self.token_service.verify_access_token(token)
            username = payload.get("sub")

            if not username:
                raise ValueError("Invalid token payload")

            return username  # Return the username stored in the "sub" claim
        except ValueError as e:
            LOGGER.error(f"error during authentication = {e}")
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail=str(e),
            )
        except Exception as e:
            LOGGER.error(f"unexpected error during authentication = {e}")
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Invalid authentication credentials",
            )

def invalidate_cache(
    key_pattern: str | Callable[..., str],
) -> Callable[[F], F]:
    """Decorator for invalidating cache entries after write operations.

    Args:
        key_pattern: Either a string pattern with '{arg_name}' placeholders
                    or a function that generates cache keys.

    Example:
        @invalidate_cache("product:{product_id}")
        async def update_product(self, product_id: str, data: dict) -> None:
            ...
    """
    def decorator(func: F) -> F:
        @functools.wraps(func)
        async def wrapper(self, *args: Any, **kwargs: Any):  # type: ignore[override]
            # Call the original function first
            result = await func(self, *args, **kwargs)

            # Skip invalidation if no cache is configured
            if not hasattr(self, "_cache") or self._cache is None:
                return result

            cache_repo: CacheRepositoryInterface = self._cache

            try:
                # Create context for key pattern formatting
                call_args = kwargs.copy()
                # Add positional arguments from signature
                import inspect
                sig = inspect.signature(func)
                param_names = list(sig.parameters.keys())[1:]  # Skip 'self'
                for i, arg in enumerate(args):
                    if i < len(param_names):
                        call_args[param_names[i]] = arg

                # Generate the key(s) to invalidate
                if callable(key_pattern):
                    keys_to_invalidate = key_pattern(**call_args)
                    if isinstance(keys_to_invalidate, str):
                        keys_to_invalidate = [keys_to_invalidate]
                else:
                    try:
                        keys_to_invalidate = [key_pattern.format(**call_args)]
                    except KeyError:
                        LOGGER.warning(
                            f"Invalidation key pattern {key_pattern} "
                            f"couldn't be formatted with {call_args}"
                        )
                        keys_to_invalidate = []

                # Invalidate each key
                for key in keys_to_invalidate:
                    await cache_repo.delete(key)
                    LOGGER.debug(f"Invalidated cache key: {key}")

            except Exception as e:
                LOGGER.warning(f"Cache invalidation error in {func.__qualname__}: {str(e)}")

            return result

        return wrapper  # type: ignore[return-value]

    return decorator

def handle_exceptions(func: Callable[..., Any]):
    # FIXME: Implement sync wrapper too
    async def wrapper(*args, **kwargs):
        self = args[0]
        operation = func.__name__
        try:
            return await func(*args, **kwargs)
        except (
            CollectionCreationError,
            CollectionDeletionError,
            CollectionUpdateError,
            ReferenceDataDeletionError,
        ) as e:
            LOGGER.error(f"Error during {operation}: {e}")
            return self.create_status_result(OperationStatus.FAILURE, str(e), operation)
        except SendResultError as e:
            LOGGER.error(f"Failed to send result for {operation}: {e}")
            return self.create_status_result(OperationStatus.FAILURE, str(e), operation)
        except Exception as e:
            LOGGER.error(f"Unexpected error during {operation}: {e}")
            return self.create_status_result(OperationStatus.FAILURE, str(e), operation)

    return wrapper

class OverallQueue:
    def __init__(self) -> None:
        self.collections_task: Dict[str, Dict[str, asyncio.Queue | asyncio.Semaphore | asyncio.Task]] = {}

    async def __call__(self, collection_identifier: str, func: Callable, params: Dict) -> CollectionInfo:
        future: asyncio.Future = asyncio.Future()

        if collection_identifier not in self.collections_task:
            self.collections_task[collection_identifier] = {
                "queue": asyncio.Queue(),
                "semaphore": asyncio.Semaphore(1),
                "worker_task": None,
            }

        await self.collections_task[collection_identifier]["queue"].put((func, params, future))

        if (
            not self.collections_task[collection_identifier]["worker_task"]
            or self.collections_task[collection_identifier]["worker_task"].done()
        ):
            self.collections_task[collection_identifier]["worker_task"] = asyncio.create_task(
                self._worker(collection_identifier)
            )

        result = await future
        return result

    async def _worker(self, collection_identifier) -> None:
        while not self.collections_task[collection_identifier]["queue"].empty():
            try:
                (
                    func,
                    params,
                    future,
                ) = await self.collections_task[
                    collection_identifier
                ]["queue"].get()
                await self.collections_task[collection_identifier]["semaphore"].acquire()

                asyncio.create_task(
                    self._process_request(
                        collection_identifier,
                        func,
                        params,
                        future,
                    )
                )

            except asyncio.CancelledError:
                break
            except Exception as exc:
                LOGGER.error(f"Worker encountered an error: {exc}")

    async def _process_request(
        self,
        collection_identifier: str,
        func: Callable,
        params: Dict,
        future: asyncio.Future,
    ) -> None:
        try:
            result = await func(**params)
            self.collections_task[collection_identifier]["semaphore"].release()
            future.set_result(result)
        except Exception as exc:
            LOGGER.error(
                f"failed executing fuction {func} in OverallQueue for collection_models {collection_identifier}"
                f" due to: {exc}"
            )
            self.collections_task[collection_identifier]["semaphore"].release()
            future.set_result(None)

    async def shutdown(self) -> None:
        """Shutdown the OverallQueue by cancelling the worker task."""
        for key, value in self.collections_task.items():
            if value["worker_task"] is not None:
                value["worker_task"].cancel()
                try:
                    await value["worker_task"]
                except asyncio.CancelledError:
                    LOGGER.debug("Worker task for collection_models %s was cancelled during shutdown." % key)

    async def __aenter__(self) -> OverallQueue:
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb) -> None:
        await self.shutdown()

class IndexingWebhookController:
    # FIXME: ai logic must not be in here
    def __init__(
        self,
        send_result_use_case: SendResultUseCase,
        ai_logic: ParsChatLogic,
        inference_controller: InferenceWebhookController,
        authenticator: BackendAuthenticator,
    ):
        self.data_indexing_use_case: DataIndexing = ai_logic.data_indexing_algorithm
        self.ecommerce_data_indexing_use_case: EcommerceDataIndexing = ai_logic.ecommerce_data_indexing_algorithm

        self.send_result_use_case = send_result_use_case
        self.authenticator = authenticator
        self.auto_rag_pipelines = ai_logic.auto_rag_algorithms
        self.ai_logic = ai_logic
        self.inference_controller = inference_controller
        self.overall_queue = OverallQueue()

    @staticmethod
    def create_status_result(
        status: OperationStatus,
        message: str,
        operation: str,
        details: dict = None,
    ) -> StatusResult:
        data = {"operation": operation, "message": message, "details": details}
        return StatusResult(
            status=status,
            data=data,
            message=message,
        )

    @handle_exceptions
    async def create_collection(self, collection: CollectionRecord) -> StatusResult:
        await self.data_indexing_use_case.create_collection(collection)

        collection_info = await self.data_indexing_use_case.get_collection_info_by_id(
            collection.identifier,
        )
        self.ai_logic.auto_rag_algorithms[collection.identifier] = await self.ai_logic.load_auto_rag(
            collection.identifier, collection_info
        )
        self.ai_logic.collection_identifiers.append(collection.identifier)

        return self.create_status_result(
            OperationStatus.SUCCESS,
            "Collection created successfully",
            "create_collection",
            {"identifier": collection.identifier},
        )

    @handle_exceptions
    async def delete_collection(self, collection_identifier: str) -> StatusResult:
        await self.data_indexing_use_case.delete_collection(collection_identifier)
        self.auto_rag_pipelines.pop(collection_identifier, None)
        await self.ai_logic.update_collection_identifiers()
        return self.create_status_result(
            OperationStatus.SUCCESS,
            "Collection deleted successfully",
            "delete_collection",
            {"identifier": collection_identifier},
        )

    async def start_overall(self, collection_identifier, reference_datum_wrappers, reference_datum, datum):
        try:
            updated_collection_info = await self.overall_queue(
                collection_identifier,
                self.data_indexing_use_case.update_overall_data,
                {
                    "collection_identifier": collection_identifier,
                    "reference_datum_wrappers": reference_datum_wrappers,
                    "reference_datum": reference_datum,
                },
            )

            if updated_collection_info is not None:
                # load/reload autorag algorithm
                if collection_identifier in self.auto_rag_pipelines:
                    self.auto_rag_pipelines[collection_identifier].collection_info = updated_collection_info
                else:
                    self.auto_rag_pipelines[collection_identifier] = await self.ai_logic.load_auto_rag(
                        collection_identifier, updated_collection_info
                    )

                LOGGER.debug("update collection_models for %s completed" % collection_identifier)
                return True

            elif (
                updated_collection_info is None
                and not self.ai_logic.auto_rag_algorithms[collection_identifier].collection_info.title
            ):
                LOGGER.error("Error in Extracting Overall Collection info for  %s  ." % collection_identifier)
                return True
            else:
                LOGGER.error(
                    "Error in Extracting Overall Collection info for  %s  in init times ." % collection_identifier
                )
                return False

        except Exception as e:
            LOGGER.error(
                "Error updating collection_models %s with data %s: %s" % (collection_identifier, datum, e),
            )
            return False

    @handle_exceptions
    async def update_collection_data(
        self,
        collection_identifier: str,
        datum: List[DataRecord],
        user_current_characters: int,
        user_maximum_characters: int,
        user_remaining_pages: int,
    ) -> Dict[str, StatusResult] | None:
        try:
            collection = await self.data_indexing_use_case.get_collection(collection_identifier, partial=True)
            datum, reference_datum = await self.check_collection_update_preconditions(
                collection,
                collection_identifier,
                datum,
                user_current_characters,
                user_maximum_characters,
                user_remaining_pages,
            )

            if not reference_datum:
                return

            reference_data_characters = self.data_indexing_use_case.get_reference_datum_num_characters(
                reference_datum,
            )

            reference_datum_wrappers = await self.data_indexing_use_case.extract_file_dependent_data(
                collection, reference_datum, self.send_intermediate_update_result
            )

            await self.inference_controller.reload_algorithm(collection_identifier)

            if not reference_datum_wrappers:
                return

            if collection.collection_info.total_num_characters > 1e6:
                updated_collection_info = True
            else:
                updated_collection_info = await self.start_overall(
                    collection_identifier,
                    reference_datum_wrappers,
                    reference_datum,
                    datum,
                )

            if collection_identifier in self.ai_logic.ecommerce_identifiers:
                self.ai_logic.auto_langgraph_algorithms[
                    collection_identifier
                ] = await self.ai_logic.load_auto_langgraph(ecommerce_identifier=collection_identifier)

            status_result = await self.send_final_training_result(
                collection_identifier,
                reference_datum_wrappers,
                reference_data_characters,
                updated_collection_info,
            )

        except Exception as e:
            LOGGER.error(
                "Error updating collection_models %s with data %s: %s" % (collection_identifier, datum, e),
            )
            status_result = await self.send_intermediate_update_result(
                collection_identifier,
                {data.identifier: 0 for data in datum},
                {data.identifier: DataRecordStatus.REJECTED for data in datum},
                {data.identifier: str(TrainMessages.overall_error_message) for data in datum},
            )

        return status_result

    async def send_final_training_result(
        self,
        collection_identifier,
        datum,
        reference_data_characters,
        updated_collection_info,
    ) -> Dict[str, StatusResult]:
        if updated_collection_info:
            status_result = await self.send_intermediate_update_result(
                collection_identifier,
                reference_data_characters,
                {data.identifier: DataRecordStatus.ACCEPTED for data in datum},
                status_codes={data.identifier: 200 for data in datum},
            )

        else:
            status_result = await self.send_intermediate_update_result(
                collection_identifier,
                {data.identifier: 0 for data in datum},
                {data.identifier: DataRecordStatus.REJECTED for data in datum},
                {data.identifier: str(TrainMessages.overall_error_message) for data in datum},
            )
        return status_result

    async def check_collection_update_preconditions(
        self,
        collection: Collection,
        collection_identifier: str,
        datum: List[DataRecord],
        user_current_characters: int,
        user_maximum_characters: int,
        user_remaining_pages: int,
    ) -> Tuple[List[DataRecord], List[ReferenceData]]:
        datum = await self.filter_pdf_records_collection_update(collection_identifier, datum, user_remaining_pages)

        reference_datum = await self.filter_data_records_character_limit_collection_update(
            collection,
            collection_identifier,
            datum,
            user_current_characters,
            user_maximum_characters,
        )
        return datum, reference_datum

    async def filter_data_records_character_limit_collection_update(
        self,
        collection: Collection,
        collection_identifier: str,
        datum: List[DataRecord],
        user_current_characters: int,
        user_maximum_characters: int,
    ) -> List[ReferenceData]:
        datum_identifiers = [data_record.identifier for data_record in datum]
        collection.reference_datum = [
            ref_data
            for ref_data in collection.reference_datum
            if ref_data.identifier in datum_identifiers or len(ref_data.training_stage.split(".")) == len(TrainingStage)
        ]
        reference_datum = await self.data_indexing_use_case.load_data(
            collection, datum, self.send_intermediate_update_result
        )
        reference_datum = await self.pop_over_limit_characters_data(
            collection_identifier,
            reference_datum,
            user_current_characters,
            user_maximum_characters,
        )
        return reference_datum

    async def filter_pdf_records_collection_update(
        self,
        collection_identifier: str,
        datum: List[DataRecord],
        user_remaining_pages: int,
    ) -> List[DataRecord]:
        """Check PDF records in data record to only train those that meet the criteria of allowed page count"""
        await self.data_indexing_use_case.download_file_datum(datum)
        datum = await self.pop_over_limit_pdf_data(
            collection_identifier,
            data_records=datum,
            user_remaining_page_count=user_remaining_pages,
        )
        return datum

    async def send_pdf_page_numbers(
        self,
        collection_identifier: str,
        statuses: Dict[str, DataRecordStatus],
        pdf_records_pages: Dict[str, int],
        status_messages: Optional[Dict[str, str]] = None,
        status_codes: Optional[Dict[str, int]] = None,
    ):
        if status_messages is None:
            status_messages = {}

        if status_codes is None:
            status_codes = {}

        for data_identifier, num_pages in pdf_records_pages.items():
            try:
                status = statuses.get(data_identifier)
                operation_result = (
                    OperationStatus.FAILURE if status == DataRecordStatus.REJECTED else OperationStatus.SUCCESS
                )
                message = (
                    "Something went wrong during update collection_models."
                    if status == DataRecordStatus.REJECTED
                    else "Collection data updated successfully"
                )
                details = {
                    "identifier": data_identifier,
                    "status": status,
                    "status_message": status_messages.get(
                        data_identifier,
                        None if status == DataRecordStatus.ACCEPTED else message,
                    ),
                    "status_code": status_codes.get(data_identifier, 200),
                }
                if num_pages is not None:
                    details["pages_count"] = num_pages

                status_result = self.create_status_result(
                    operation_result,
                    message,
                    "update_collection_data",
                    details,
                )
                LOGGER.info(f"status result = {status_result}")
                token = await self.authenticator.get_valid_token()
                headers = {
                    "Authorization": f"Bearer {token}",
                    "Content-Type": "application/json",
                }
                backend_message = Message(
                    data=json.dumps(details),
                    headers=headers,
                )
                backend_success = await self.send_result_use_case.execute(
                    backend_message,
                )

                if backend_success:
                    LOGGER.info(
                        f"update_collection_data successful for collection_models {collection_identifier}",
                    )
                else:
                    LOGGER.error(
                        f"Failed to send update_collection_data for {collection_identifier}",
                    )
            except Exception as e:
                LOGGER.error(f"Error processing {data_identifier}: {e}")

    def log_training_result(
        self,
        reference_data_characters: Dict[str, int],
        statuses: Dict[str, DataRecordStatus],
        status_messages: Optional[Dict[str, str]] = None,
    ) -> None:
        training_result = TrainingResult(
            trace_id=get_trace_id(),
            submitted_at=datetime.now().strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
            intermediate_data=[
                *[
                    {
                        "data_name": "reference_data_characters",
                        "identifier": key,
                        "value": value,
                    }
                    for key, value in reference_data_characters.items()
                ],
                *[
                    {
                        "data_name": "statuses",
                        "identifier": key,
                        "value": value,
                    }
                    for key, value in statuses.items()
                ],
                *[
                    {
                        "data_name": "status_messages",
                        "identifier": key,
                        "value": value,
                    }
                    for key, value in (status_messages or {}).items()
                ],
            ],
        )
        context = get_current_trace()
        if context:
            context.training_results.append(training_result)

    @handle_exceptions
    async def send_intermediate_update_result(
        self,
        collection_identifier: str,
        reference_data_characters: Dict[str, int],
        statuses: Dict[str, DataRecordStatus],
        status_messages: Optional[Dict[str, str]] = None,
        status_codes: Optional[Dict[str, int]] = None,
    ) -> Dict[str, StatusResult]:
        # self.log_training_result(
        #     reference_data_characters=reference_data_characters,
        #     statuses=statuses,
        #     status_messages=status_messages,
        # )

        # FIXME: if the message is not found, error code is 404
        if status_messages is None:
            status_messages = {}

        if status_codes is None:
            status_codes = {}

        status_results = {}

        for data_identifier, num_data_character in reference_data_characters.items():
            try:
                status = statuses.get(data_identifier)
                operation_result = (
                    OperationStatus.FAILURE if status == DataRecordStatus.REJECTED else OperationStatus.SUCCESS
                )
                message = (
                    "Something went wrong during update collection_models."
                    if status == DataRecordStatus.REJECTED
                    else "Collection data updated successfully"
                )
                details = {
                    "identifier": data_identifier,
                    "status": status,
                    "status_message": status_messages.get(
                        data_identifier,
                        None if status == DataRecordStatus.ACCEPTED else message,
                    ),
                    "status_code": status_codes.get(data_identifier, 200),
                }
                if num_data_character is not None:
                    details["character_count"] = num_data_character

                status_result = self.create_status_result(
                    operation_result,
                    message,
                    "update_collection_data",
                    details,
                )
                LOGGER.info(f"status result = {status_result}")
                token = await self.authenticator.get_valid_token()
                headers = {
                    "Authorization": f"Bearer {token}",
                    "Content-Type": "application/json",
                }
                backend_message = Message(
                    data=json.dumps(details),
                    headers=headers,
                )
                backend_success = await self.send_result_use_case.execute(
                    backend_message,
                )

                if not backend_success:
                    LOGGER.error(
                        f"Failed to send update_collection_data for {collection_identifier}",
                    )
                status_results[data_identifier] = status_result
            except Exception as e:
                LOGGER.error(f"Error processing {data_identifier}: {e}")
                status_results[data_identifier] = None

        return status_results

    async def send_ecommerce_update_result(
        self,
        ecommerce_record_identifier: str,
        status: DataRecordStatus,
    ):
        details = {"identifier": ecommerce_record_identifier, "status": status}
        status_result = self.create_status_result(
            OperationStatus.SUCCESS,
            "Ecommerce data updated successfully.",
            "update_ecommerce_data",
            details,
