        LOGGER.info(f"status result = {status_result}")
        token = await self.authenticator.get_valid_token()
        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        }
        backend_message = Message(
            data=json.dumps(details),
            headers=headers,
        )
