            )
        return {ecommerce_record_identifier: status_result}

    @handle_exceptions
    async def pop_over_limit_characters_data(
        self,
        collection_identifier: str,
        reference_datum: List[ReferenceData],
        user_current_characters: int,
        user_maximum_characters: int,
    ) -> List[ReferenceData]:
        character_limit = (user_maximum_characters - user_current_characters) * 1.15
        sorted_reference_datum = sorted(
            reference_datum,
            key=lambda rd: rd.num_characters or 0,
        )
        total_characters = 0
        candidates = []
        for ref_data in sorted_reference_datum:
            if total_characters + (ref_data.num_characters or 0) <= character_limit:
                total_characters += ref_data.num_characters or 0
                candidates.append(ref_data)
            else:
                break
        final_reference_datum = [ref_data for ref_data in reference_datum if ref_data in candidates]
        for ref_data in reference_datum:
            if ref_data not in candidates:
                await self.send_intermediate_update_result(
                    collection_identifier,
                    {ref_data.identifier: ref_data.num_characters},
                    {ref_data.identifier: DataRecordStatus.NO_SPACE_LEFT},
                    status_messages={ref_data.identifier: TrainMessages.character_limit_message},
                )

        return final_reference_datum

    @handle_exceptions
    async def pop_over_limit_pdf_data(
        self,
        collection_identifier: str,
        data_records: List[DataRecord],
        user_remaining_page_count: int,
    ) -> List[DataRecord]:
        page_limit = int(user_remaining_page_count * 1.15)
        pdf_records = await self.data_indexing_use_case.count_data_records_pdf_pages(data_records)

        sorted_data_records = sorted(
            pdf_records,
            key=lambda key: pdf_records[key] or 0,
        )
        candidates = await self._get_all_accepted_data_records(
            collection_identifier,
            data_records,
            page_limit,
            pdf_records,
            sorted_data_records,
        )

        await self.send_status_over_limit_pdfs(candidates, collection_identifier, data_records, pdf_records)

        return candidates

    async def _get_all_accepted_data_records(
        self,
        collection_identifier: str,
        data_records: List[DataRecord],
        page_limit: int,
        pdf_records_num_page: Dict[DataRecord, int],
        sorted_data_records: List[DataRecord],
    ):
        total_pages = 0
        candidates = []
        for data_record in sorted_data_records:
            page_count = pdf_records_num_page[data_record]
            if total_pages + page_count <= page_limit:
                total_pages += page_count
                candidates.append(data_record)
                await self.send_pdf_page_numbers(
                    collection_identifier,
                    {data_record.identifier: DataRecordStatus.PENDING},
                    pdf_records_pages={data_record.identifier: page_count},
                )
            else:
                break
        for data_record in data_records:
            if data_record.data_type != DataType.PDF:
                candidates.append(data_record)
        return candidates

    async def send_status_over_limit_pdfs(
        self,
        candidates: List[DataRecord],
        collection_identifier: str,
        data_records: List[DataRecord],
        pdf_records: Dict[DataRecord, int],
    ):
        for data_record in data_records:
            if data_record not in candidates:
                await self.send_pdf_page_numbers(
                    collection_identifier,
                    {data_record.identifier: DataRecordStatus.NO_SPACE_LEFT},
                    status_messages={data_record.identifier: TrainMessages.page_limit_message},
                    pdf_records_pages={data_record.identifier: pdf_records[data_record]},
                )

