    @tracer(trace_type="training", identifier_path="collection_identifier")
    async def batch_update_collection_data(
        self,
        collection_identifier: str,
        datum: List[DataRecord],
        user_current_characters: int,
        user_maximum_characters: int,
        user_remaining_doc_pages: int,
        batch_size: int,
    ) -> list[Dict[str, StatusResult]]:
        LOGGER.debug(f"the length of the datum is {len(datum)}")

        ecommerce_datum = [
            data_record for data_record in datum if data_record.data_type in ["woocommerce", "mixin", "digify"]
        ]
        # TODO: add other shop frameworks e.g. Prestashop

        ecommerce_results = []
        descriptions_list = []
        for ecommerce_record in ecommerce_datum:
            ecommerce_result, descriptions = await self.update_ecommerce_data(
                ecommerce_identifier=collection_identifier,
                ecommerce_data_record=ecommerce_record,
            )
            ecommerce_results.append(ecommerce_result)
            descriptions_list.extend(descriptions)

        datum = [record for record in datum if record not in ecommerce_datum]
        datum = sorted(datum, key=lambda e: len(e.data_path))
        results = []

        for i in range(0, len(datum), batch_size):
            batched_datum = datum[i : i + batch_size]
            try:
                result = await self.update_collection_data(
                    collection_identifier,
                    batched_datum,
                    user_current_characters,
                    user_maximum_characters,
                    user_remaining_doc_pages,
                )
                results.append(result)
                collection = await self.data_indexing_use_case.get_collection(collection_identifier, partial=True)
                user_current_characters = (
                    await self.data_indexing_use_case.get_collection_total_characters_by_collection(collection)
                )
                user_remaining_doc_pages = (
                    await self.data_indexing_use_case.get_collection_total_pdf_pages_by_collection(collection)
                )
            except Exception:
                continue

        results.extend(ecommerce_results)
        return results

    async def update_ecommerce_data(
        self,
        ecommerce_identifier: str,
        ecommerce_data_record: DataRecord,
    ) -> tuple[Dict[str, StatusResult], List[tuple[int, str]]]:
        # Handle different ecommerce platforms
        if ecommerce_data_record.data_type == "woocommerce":
            ecommerce_auth = WoocommerceAuth(
                store_url=ecommerce_data_record.data_path,
                consumer_key=ecommerce_data_record.metadata.consumer_key,
                consumer_secret=ecommerce_data_record.metadata.consumer_secret,
                woocommerce_version=ecommerce_data_record.metadata.woocommerce_version,
            )
        elif ecommerce_data_record.data_type == "mixin":
            ecommerce_auth = MixinAuth(
                store_url=ecommerce_data_record.data_path,
                api_token=ecommerce_data_record.metadata.api_token,
                mixin_version=ecommerce_data_record.metadata.mixin_version,
            )
        elif ecommerce_data_record.data_type == "digify":
            ecommerce_auth = DigifyAuth(
                store_url=ecommerce_data_record.data_path,
                api_token=ecommerce_data_record.metadata.api_token,
                store_id=ecommerce_data_record.metadata.store_id,
                digify_version=getattr(ecommerce_data_record.metadata, "digify_version", "v1"),
            )
        else:
            raise ValueError(f"Unsupported ecommerce platform: {ecommerce_data_record.data_type}")

        ecommerce_reference_data = ReferenceData(
            name=ecommerce_data_record.name,
            identifier=ecommerce_data_record.identifier,
            user_id=ecommerce_data_record.user_id,
            data_type=ecommerce_data_record.data_type,
            content_type=ecommerce_data_record.content_type,
            created_at=ecommerce_data_record.created_at,
            updated_at=datetime.now(),
            training_stage=TrainingStage.ZERO.value,
        )

        result = await self.ecommerce_data_indexing_use_case.load_and_index_products(
            ecommerce_identifier, ecommerce_auth, ecommerce_reference_data
        )
        if len(result) == 2:  # Case when indexing is basic
            descriptions, indexing_success = result
            if indexing_success and ecommerce_identifier not in self.ai_logic.ecommerce_identifiers:
                self.ai_logic.ecommerce_identifiers.append(ecommerce_identifier)
                self.ai_logic.auto_langgraph_algorithms[ecommerce_identifier] = await self.ai_logic.load_auto_langgraph(
                    ecommerce_identifier=ecommerce_identifier
                )

            ecommerce_record_status = DataRecordStatus.ACCEPTED if indexing_success else DataRecordStatus.REJECTED
            ecommerce_result = await self.send_ecommerce_update_result(
                ecommerce_data_record.identifier, ecommerce_record_status
            )
            return ecommerce_result, descriptions

        else:
            # TODO: BIG TODO
            categories, attributes, updated_products = result
            if ecommerce_identifier not in self.ai_logic.ecommerce_identifiers:
                self.ai_logic.ecommerce_identifiers.append(ecommerce_identifier)
                self.ai_logic.auto_langgraph_algorithms[ecommerce_identifier] = await self.ai_logic.load_auto_langgraph(
                    ecommerce_identifier=ecommerce_identifier
                )

            indexing_success = len(categories) > 0
            ecommerce_record_status = DataRecordStatus.ACCEPTED if indexing_success else DataRecordStatus.REJECTED
            ecommerce_result = await self.send_ecommerce_update_result(
                ecommerce_data_record.identifier, ecommerce_record_status
            )
            descriptions = ["Okay"]
            return ecommerce_result, descriptions

