class InMemoryTaskRegistry(TaskRegistryInterface):
    def __init__(self):
        self.tasks: dict[str, Any] = {}
        self.task_objects: dict[str, Any] = {}  # Store actual task objects separately
        self._lock = asyncio.Lock()

    async def initialize(self) -> None:
        logger.info("Initialized in-memory task registry")
        return

    async def shutdown(self) -> None:
        logger.info("Shutting down in-memory task registry")
        return

    async def register_task(
        self, client_task_id: str, task_id: UUID, task: asyncio.Task, parameters: dict[str, Any] = None
    ) -> None:
        async with self._lock:
            # Cancel existing task if present
            await self.cancel_task_if_exists(client_task_id, task_id)

            # Store the task object separately
            if self.task_objects.get(client_task_id) is None:
                self.task_objects[client_task_id] = {
                    task_id: task,
                }
            else:
                self.task_objects[client_task_id][task_id] = task

            # Store task metadata
            if self.tasks.get(client_task_id) is None:
                self.tasks[client_task_id] = {
                    task_id: {
                        "client_task_id": client_task_id,
                        "start_time": time.time(),
                        "status": "running",
                        "progress": 0,
                        "result": None,
                        "error": None,
                        "parameters": parameters or {},
                    }
                }

            else:
                self.tasks[client_task_id][task_id] = {
                    "client_task_id": client_task_id,
                    "start_time": time.time(),
                    "status": "running",
                    "progress": 0,
                    "result": None,
                    "error": None,
                    "parameters": parameters or {},
                }

            logger.info(f"Registered task {client_task_id}")

    async def cancel_task_if_exists(self, client_task_id: str, task_id: UUID) -> bool:
        old_tasks = self.task_objects.get(client_task_id)
        if old_tasks is None:
            return False

        for task_id, task in old_tasks.items():
            if not task.done():
                logger.info(f"Cancelling existing task {client_task_id} {task_id}")
                # task.cancel()
                #
                # # Wait for task to acknowledge cancellation
                # try:
                #     await asyncio.wait_for(asyncio.shield(task), timeout=2.0)
                # except asyncio.TimeoutError:
                #     logger.warning(f"Task {client_task_id} taking too long to cancel")
                # except asyncio.CancelledError:
                #     logger.info(f"Task {client_task_id} cancelled successfully")
                # except Exception as e:
                #     logger.error(f"Error during task cancellation: {str(e)}")

                if client_task_id in self.tasks:
                    self.tasks[client_task_id][task_id]["status"] = "cancelled"
                    self.tasks[client_task_id][task_id]["completion_time"] = time.time()

        return True

    async def get_task_info(self, client_task_id: str, task_id: UUID) -> Optional[stc_entity.TaskInfo]:
        async with self._lock:
            if client_task_id not in self.tasks:
                return None

            task_data = self.tasks[client_task_id][task_id].copy()

            # Update status based on current task state if we have the task object
            if client_task_id in self.task_objects:
                task = self.task_objects[client_task_id][task_id]

                if task.done():
                    if task.cancelled():
                        task_data["status"] = "cancelled"
                    elif task.exception() is not None:
                        task_data["status"] = "failed"
                        task_data["error"] = str(task.exception())
                    else:
                        task_data["status"] = "completed"
                        try:
                            task_data["result"] = task.result()
                        except Exception as e:
                            task_data["error"] = f"Error retrieving result: {str(e)}"

                    # Set completion time if not already set
                    if "completion_time" not in task_data or task_data["completion_time"] is None:
                        task_data["completion_time"] = time.time()

        # logger.info(f"Task registry updated for {client_task_id} with data: {task_data}")
        return stc_entity.TaskInfo(**task_data)

    async def update_task_progress(self, client_task_id: str, task_id: UUID, progress: int, status: str = None) -> bool:
        if client_task_id in self.tasks:
            self.tasks[client_task_id][task_id]["progress"] = progress
            if status:
                self.tasks[client_task_id][task_id]["status"] = status
            return True
        return False

    async def cleanup_task(self, client_task_id: str, task_id: UUID, result: Any = None, error: str = None) -> None:
        async with self._lock:
            if client_task_id in self.tasks:
                # Update task info with result/error
                if result is not None:
                    self.tasks[client_task_id][task_id]["result"] = result
                if error is not None:
                    self.tasks[client_task_id][task_id]["error"] = error

                # Mark completion time
                self.tasks[client_task_id][task_id]["completion_time"] = time.time()

                # Update status if needed
                if error:
                    self.tasks[client_task_id][task_id]["status"] = "failed"
                elif self.tasks[client_task_id][task_id]["status"] == "running":
                    self.tasks[client_task_id][task_id]["status"] = "completed"

    async def get_all_running_tasks(self) -> list[str]:
        running_tasks = []
        for client_task_id, task_info in self.tasks.items():
            for task_id in self.tasks[client_task_id]:
                if task_info[task_id]["status"] == "running":
                    running_tasks.append((client_task_id, task_id))
        return running_tasks

    async def cleanup_old_tasks(self, max_age_seconds: int = 3600) -> int:
        async with self._lock:
            now = time.time()
            to_remove = []

            for client_task_id, task_info in self.tasks.items():
                for task_id in self.tasks[client_task_id]:
                    if task_info[task_id].get("status") not in ["running"]:
                        # If task has a completion_time and it's older than retention period
                        completion_time = task_info[task_id].get("completion_time")
                        if completion_time and (now - completion_time > max_age_seconds):
                            to_remove.append((client_task_id, task_id))

            # Remove old tasks
            for client_task_id, task_id in to_remove:
                if client_task_id in self.task_objects:
                    del self.task_objects[client_task_id][task_id]
                    if not self.task_objects[client_task_id]:
                        del self.task_objects[client_task_id]
                del self.tasks[client_task_id][task_id]
                if not self.tasks[client_task_id]:
                    del self.tasks[client_task_id]

            return len(to_remove)

class LlamaParseClient(PdfParserInterface):
    """Concrete implementation for LlamaParse PDF processing service."""
    def __init__(self, llama_parse_settings: LLAMAParseSetting):
        """Initialize LlamaParseClient with settings.

        Args:
            llama_parse_settings: LlamaParse service settings.
        """
        self.llama_parse_settings = llama_parse_settings

    async def process_pdf(self, record: DataRecord) -> str:
        """Process PDF and return extracted text.

        Args:
            file_path: Path to the PDF file.

        Returns:
            Extracted text content.
        """
        if not self.llama_parse_settings.CLOUD_API_KEY:
            raise ValueError("LlamaParse API key (LLAMA_CLOUD_API_KEY) is not configured")
        try:
            LOGGER.info(f"Processing PDF with LlamaParse: {record.data_path}")
            parser = LlamaParse(
                api_key=self.llama_parse_settings.CLOUD_API_KEY,
                result_type="text",
                verbose=True
            )
            documents = await parser.aload_data(record.data_path)
            extracted_text = ""
            for doc in documents:
                if hasattr(doc, 'text'):
                    extracted_text += doc.text + "\n"
                elif hasattr(doc, 'get_content'):
                    extracted_text += doc.get_content() + "\n"
                else:
                    extracted_text += str(doc) + "\n"
            if not extracted_text.strip():
                raise RuntimeError(f"LlamaParse returned empty content for PDF: {record.data_path}")
            LOGGER.info(f"LlamaParse successfully processed PDF. Text length: {len(extracted_text)}")
            return extracted_text.strip()
        except Exception as exc:
            LOGGER.error(f"LlamaParse processing failed for {record.data_path}: {exc}")
            raise RuntimeError(f"LlamaParse processing failed: {exc}") from exc

async def fetch(session, url):
