    async def _run_with_rate_limit(self, coro, *args, **kwargs):
        await self.semaphore.acquire()
        try:
            await coro(*args, **kwargs)
        finally:
            await asyncio.sleep(61)
            self.semaphore.release()

    @staticmethod
    def _build_scrape_params(prompts: Dict[str, str], only_main_content: bool) -> Dict[str, Any]:
        params: Dict[str, Any] = {
            "formats": ["markdown"],
            "waitFor": 3000,
            "timeout": 40000,
            "onlyMainContent": only_main_content,
        }
        if isinstance(prompts, dict) and "scrape_prompt" in prompts:
            params["formats"] = ["extract"]
            schema: Dict[str, Any] = {
                "properties": {"content": {"title": "Content", "type": "string"}},
                "required": ["content"],
                "title": "Markdown",
                "type": "object",
            }
            if "scrape_schema" in prompts and prompts["scrape_schema"]:
                schema = (
                    prompts["scrape_schema"]
                    if isinstance(prompts["scrape_schema"], dict)
                    else json.loads(prompts["scrape_schema"])
                )
            params["extract"] = {"prompt": prompts["scrape_prompt"], "schema": schema}
        return params

    async def _process_request(
        self,
        prompts: Dict[str, str],
        url: str,
        future: asyncio.Future,
        dataloader_config: bool,
    ) -> None:
        params = self._build_scrape_params(prompts, dataloader_config)
        try:
            result = await self._request_for_scraping(url, params)
            if isinstance(prompts, dict) and "scrape_prompt" in prompts and not result.get("extract"):
                result = await self._request_for_scraping(url, params)
            result = await self._convert_to_result_obj(result)
            future.set_result(result)
        except Exception as exc:
            LOGGER.error(f"Failed to scrape {url} due to: {exc}")
            future.set_result(
                URLLoaderScraperResult(content="", error=TrainMessages.Crawl_timeout_error, status_code=408, url=url)
            )

    async def _request_for_scraping(self, url: str, params: Dict[str, Any], retry_attempts: int = 4) -> Dict[str, Any]:
        for i in range(retry_attempts):
            try:
                results = await asyncio.to_thread(
                    lambda: requests.post(
                        self._settings.scrape_endpoint,
                        headers={"Content-Type": "application/json"},
                        data=json.dumps(
                            {
                                "url": url,
                                "formats": params.get("formats", ["markdown"]),
                                "onlyMainContent": params.get("onlyMainContent", True),
                                "waitFor": params.get("waitFor"),
                                "timeout": params.get("timeout"),
                            }
                        ),
                    )
                )
                results = results.json()["data"]
                return _ensure_dict(results)
            except Exception as e:
                LOGGER.error(f"Error in requesting scrape (attempt {i+1}/{retry_attempts}): {e}")
                await asyncio.sleep(5 + i * 4)

        return {
            "metadata": {"sourceURL": url, "statusCode": 408, "error": "timeout"},
            "markdown": "",
            "links": [],
        }

    async def _convert_to_result_obj(self, json_result: Dict[str, Any]) -> URLLoaderScraperResult:
        meta = json_result.get("metadata", {}) or {}

        if "markdown" in json_result and json_result.get("markdown") is not None:
            markdown_content = json_result["markdown"]
        else:
            extract = json_result.get("extract", {})
            try:
                if isinstance(extract, dict):
                    items = next(
                        (d.items() for d in extract.values() if isinstance(d, dict) and len(d) > 1),
                        extract.items(),
                    )
                    markdown_content = "".join(f"# {k}:\n{v}\n\n" for k, v in items)
                else:
                    markdown_content = str(extract)
            except Exception as e:
                LOGGER.warning(f"Error converting extract {meta.get('sourceURL')} to markdown: {e}")
                markdown_content = str(extract)

        title = _safe_first(meta.get("title"))
        desc = _safe_first(meta.get("description")) or ""

        return URLLoaderScraperResult(
            content=markdown_content,
            title=title,
            description=desc,
            language=meta.get("language"),
            url=meta.get("sourceURL"),
            status_code=meta.get("statusCode"),
            error=meta.get("error"),
            page_error=meta.get("pageError"),
            links=json_result.get("links", []),
            warning=json_result.get("warning"),
        )

    async def shutdown(self) -> None:
        if self.worker_task is not None:
            self.worker_task.cancel()
            try:
                await self.worker_task
            except asyncio.CancelledError:
                LOGGER.debug("Worker task was cancelled during shutdown.")

    async def __aenter__(self) -> FirecrawlServerScraper:
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb) -> None:
        await self.shutdown()

def _normalize_include_paths(base_url: str, urls: List[str]) -> List[str]:
