        paths.append(p)
    return paths

def _timeout_crawler_result(urls: List[str]) -> URLLoaderCrawlerResult:
    return URLLoaderCrawlerResult(
        data=[
            URLLoaderCrawlerSinglePageResult(
                content=None, page=None, url=u, title=None, description=None, links=None,
                language=None, status_code=408,
                error="request time out for scraping the page!",
                page_error="request time out for scraping the page!",
            ) for u in urls
        ],
        status=None, total=None, completed=None, credits_used=None, expires_at=None, next_url=None,
    )

def _safe_first(v):
    if isinstance(v, list):
        return v[0] if v else None
    return v

def _ensure_dict(result: Any) -> Dict[str, Any]:
    """Return a plain dict representation of Firecrawl SDK result.

    Parameters
    ----------
    result : Any
        Object returned by Firecrawl SDK.

    Returns
    -------
    Dict[str, Any]
        Dictionary form of the result.
    """
    if isinstance(result, dict):
        return result
    for attr in ("dict", "model_dump", "to_dict"):
        if hasattr(result, attr):
            try:
                candidate = getattr(result, attr)()
                if isinstance(candidate, dict):
                    return candidate
            except Exception:
                pass
    if hasattr(result, "__dict__") and isinstance(result.__dict__, dict):
        return dict(result.__dict__)
    return {"data": result}

class FirecrawlScraper(BaseScraper):
    def __init__(self, settings: FireCrawlConnectionSetting) -> None:
        self.app = FirecrawlApp(settings.token)
        self.request_queue: asyncio.Queue = asyncio.Queue()
        self.rate_limit = 20
        self.semaphore = asyncio.Semaphore(self.rate_limit)
        self.worker_task: Optional[asyncio.Task] = None

    async def __call__(self, url: str, prompts: Dict[str, str], dataloader_config: bool) -> URLLoaderScraperResult:
        future: asyncio.Future = asyncio.Future()
        await self.request_queue.put((prompts, url, future, dataloader_config))
        if self.worker_task is None or self.worker_task.done():
            self.worker_task = asyncio.create_task(self._worker())
        return await future

    async def _worker(self) -> None:
        while True:
            try:
                item = await self.request_queue.get()
            except asyncio.CancelledError:
                break
            try:
                prompts, url, future, dataloader_config = item
                await self._run_with_rate_limit(self._process_request, prompts, url, future, dataloader_config)
            except asyncio.CancelledError:
                break
            except Exception as exc:
                LOGGER.error(f"Worker encountered an error: {exc}")
            finally:
                self.request_queue.task_done()

    async def _run_with_rate_limit(self, coro, *args, **kwargs):
        await self.semaphore.acquire()
        try:
            await coro(*args, **kwargs)
        finally:
            await asyncio.sleep(61)
            self.semaphore.release()

    @staticmethod
    def _build_scrape_params(prompts: Dict[str, str], only_main_content: bool) -> Dict[str, Any]:
        params: Dict[str, Any] = {
            "formats": ["markdown"],
            "waitFor": 3000,
            "timeout": 40000,
            "onlyMainContent": only_main_content,
        }
        if isinstance(prompts, dict) and "scrape_prompt" in prompts:
            params["formats"] = ["extract"]
            schema: Dict[str, Any] = {
                "properties": {"content": {"title": "Content", "type": "string"}},
                "required": ["content"],
                "title": "Markdown",
                "type": "object",
            }
            if "scrape_schema" in prompts and prompts["scrape_schema"]:
                schema = prompts["scrape_schema"] if isinstance(prompts["scrape_schema"], dict) \
                    else json.loads(prompts["scrape_schema"])
            params["extract"] = {"prompt": prompts["scrape_prompt"], "schema": schema}
        return params

    async def _process_request(
        self,
        prompts: Dict[str, str],
        url: str,
        future: asyncio.Future,
        dataloader_config: bool,
    ) -> None:
        params = self._build_scrape_params(prompts, dataloader_config)
        try:
            result = await self._request_for_scraping(url, params)
            if isinstance(prompts, dict) and "scrape_prompt" in prompts and not result.get("extract"):
                result = await self._request_for_scraping(url, params)
            result = await self._convert_to_result_obj(result)
            future.set_result(result)
        except Exception as exc:
            LOGGER.error(f"Failed to scrape {url} due to: {exc}")
            future.set_result(URLLoaderScraperResult(
                content="", error=TrainMessages.Crawl_timeout_error, status_code=408, url=url
            ))

    async def _request_for_scraping(self, url: str, params: Dict[str, Any], retry_attempts: int = 4) -> Dict[str, Any]:
        for i in range(retry_attempts):
            try:
                # Build arguments for scrape_url method based on Firecrawl API
                scrape_kwargs = {
                    "formats": params.get("formats", ["markdown"]),
                    "only_main_content": params.get("onlyMainContent", True),
                }

                # Add optional parameters if present
                if params.get("waitFor"):
                    scrape_kwargs["wait_for"] = params.get("waitFor")
                if params.get("timeout"):
                    scrape_kwargs["timeout"] = params.get("timeout")
                if params.get("extract"):
                    scrape_kwargs["extract"] = params.get("extract")

                results = await asyncio.to_thread(
                    lambda: self.app.scrape_url(url, **scrape_kwargs)
                )
                return _ensure_dict(results)
            except Exception as e:
                LOGGER.error(f"Error in requesting scrape (attempt {i+1}/{retry_attempts}): {e}")
                await asyncio.sleep(5 + i*4)

        return {
            "metadata": {"sourceURL": url, "statusCode": 408, "error": "timeout"},
            "markdown": "",
            "links": [],
        }

    async def _convert_to_result_obj(self, json_result: Dict[str, Any]) -> URLLoaderScraperResult:
        meta = json_result.get("metadata", {}) or {}

        if "markdown" in json_result and json_result.get("markdown") is not None:
            markdown_content = json_result["markdown"]
        else:
            extract = json_result.get("extract", {})
            try:
                if isinstance(extract, dict):
                    items = next(
                        (d.items() for d in extract.values() if isinstance(d, dict) and len(d) > 1),
                        extract.items(),
                    )
                    markdown_content = "".join(f"# {k}:\n{v}\n\n" for k, v in items)
                else:
                    markdown_content = str(extract)
            except Exception as e:
                LOGGER.warning(f"Error converting extract {meta.get('sourceURL')} to markdown: {e}")
                markdown_content = str(extract)

        title = _safe_first(meta.get("title"))
        desc = _safe_first(meta.get("description")) or ""

        return URLLoaderScraperResult(
            content=markdown_content,
            title=title,
            description=desc,
            language=meta.get("language"),
            url=meta.get("sourceURL"),
            status_code=meta.get("statusCode"),
            error=meta.get("error"),
            page_error=meta.get("pageError"),
            links=json_result.get("links", []),
            warning=json_result.get("warning"),
        )

    async def shutdown(self) -> None:
        if self.worker_task is not None:
            self.worker_task.cancel()
            try:
                await self.worker_task
            except asyncio.CancelledError:
                LOGGER.debug("Worker task was cancelled during shutdown.")

    async def __aenter__(self) -> FirecrawlScraper:
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb) -> None:
        await self.shutdown()

class URLLoaderAdapter(URLLoaderAdapterInterface):
    def __init__(
        self,
        firecrawl_server_crawler: FirecrawlServerCrawler,
        firecrawl_server_scraper: FirecrawlServerScraper,
        firecrawl_crawler: FirecrawlCrawler,
        firecrawl_scraper: FirecrawlScraper,
        usescraper_crawler: UsescraperCrawler,
        usescraper_scraper: UsescraperScraper,
    ) -> None:
        self.crawlers = {
            "firecrawl_server": firecrawl_server_crawler,
            "firecrawl": firecrawl_crawler,
            "usescraper": usescraper_crawler,
        }
        self.scrapers = {
            "firecrawl_server": firecrawl_server_scraper,
            "firecrawl": firecrawl_scraper,
            "usescraper": usescraper_scraper,
        }

    def remove_duplicates_preserve_order(self, original_list):
        seen = set()
        ordered_list = []

        for item in original_list:
            if item not in seen:
                ordered_list.append(item)
                seen.add(item)

        return ordered_list

    def ordered_difference(self, original_list, exclude_set):
        return [item for item in original_list if item not in exclude_set]

    async def __call__(
        self,
        prompts: Dict[str, str],
        urls: List[str],
        dataloader_config: bool,
        crawler_api_name: Optional[str] = "usescraper",
    ) -> List[Optional[Dict[str, Any]]]:
        # TODO: create enum for crawler_api names (['firecrawl', 'usescraper])
        crawler: BaseCrawler
        scraper: BaseScraper
        backup_scraper: BaseScraper | None

        if crawler_api_name == "firecrawl_server":
            crawler = self.crawlers["firecrawl_server"]
            scraper = self.scrapers["firecrawl_server"]
            backup_scraper = self.scrapers["firecrawl"]

        elif crawler_api_name == "firecrawl":
            crawler = self.crawlers["firecrawl"]
            scraper = self.scrapers["firecrawl"]
            backup_scraper = self.scrapers["usescraper"]
            # TODO: keep default crawler and scraper in settings
        else:
            crawler = self.crawlers[crawler_api_name]
            scraper = self.scrapers[crawler_api_name]
            backup_scraper = self.scrapers["firecrawl_server"]

        final_results: List[Union[URLLoaderCrawlerSinglePageResult, URLLoaderScraperResult]] = []

        try:
            if len(urls) == 1:
                result = await scraper(urls[0], prompts, dataloader_config)
                if (not result or not result.content) and backup_scraper:
                    result = await backup_scraper(urls[0], prompts, dataloader_config)
                final_results.append(result)
            else:
                results = await crawler(urls, prompts, dataloader_config)
                results = results.data

                extracted_urls = {result.url for result in results if result.status_code == 200}
                extracted_urls = self.remove_duplicates_preserve_order(
                    [unquote(url if url.endswith("/") else f"{url}/") for url in extracted_urls]
                )

                normalized_urls = self.remove_duplicates_preserve_order(
                    [unquote(url if url.endswith("/") else f"{url}/") for url in urls]
                )
                unextracted_urls = self.ordered_difference(normalized_urls, extracted_urls)

                if unextracted_urls:
                    LOGGER.warning(f"Unextracted URLs: {unextracted_urls}")

                    primary_scraped_results = await asyncio.gather(
                        *[scraper(url, prompts, dataloader_config) for url in unextracted_urls],
                    )

                    if backup_scraper:
                        backup_scrape_urls = [
                            url
                            for url, result in zip(unextracted_urls, primary_scraped_results)
                            if not result or not result.content
                        ]

                        if backup_scrape_urls:
                            backup_scraped_results = await asyncio.gather(
                                *[backup_scraper(url, prompts, dataloader_config) for url in backup_scrape_urls],
                            )

                            for i, url in enumerate(unextracted_urls):
                                if url in backup_scrape_urls:
                                    backup_idx = backup_scrape_urls.index(url)
                                    primary_scraped_results[i] = backup_scraped_results[backup_idx]

                    results.extend(primary_scraped_results)

                url_to_result = {
                    unquote(result.url if result.url.endswith("/") else f"{result.url}/"): result for result in results
                }

                for url in normalized_urls:
                    final_results.append(url_to_result.get(unquote(url)))

            final_results_dict = [result.to_url_loader_result().to_dict() for result in final_results]

            return final_results_dict

        except Exception as exc:
            parsed_url = urlparse(urls[0])
            base_url = f"{parsed_url.scheme}://{parsed_url.netloc}"
            LOGGER.error(f"Failed to extract data from {base_url} due to: {exc}")
            return [None] * len(urls)

class AzureEmbeddingsWithFallback:
    def __init__(self, settings: BaseEmbeddingModelSetting) -> None:
        """Create Azure embeddings and keep settings for fallback init.

        Args:
            settings: Embedding configuration with connection info.
        """
        self._settings = settings
        self._azure = AzureOpenAIEmbeddings(
            azure_endpoint=settings.connection_config.azure_endpoint,
            api_key=settings.connection_config.azure_api_key,
            openai_api_version=settings.connection_config.azure_api_version,
            model=settings.ai_model_name,
        )
        self._openai: Optional[OpenAIEmbeddings] = None

    def _init_openai(self) -> None:
        """Lazily initialize the OpenAI embeddings fallback."""
        if self._openai is None:
            self._openai = OpenAIEmbeddings(
                api_key=self._settings.connection_config.openai_api_token,
                model=self._settings.ai_model_name,
                base_url=self._settings.connection_config.base_openai_url,
            )

    def embed_documents(self, documents: Iterable[str]) -> List[List[float]]:
        """Embed a list of documents, falling back to OpenAI on failure.

        Args:
            documents: Iterable of document strings to embed.

        Returns:
            List of embedding vectors.
        """
        try:
            return self._azure.embed_documents(list(documents))
        except Exception as e:  # pragma: no cover - fallback path
            LOGGER.warning(
                "Azure embeddings.embed_documents failed (%s). Falling back to OpenAI.",
                type(e).__name__,
            )
            self._init_openai()
            return self._openai.embed_documents(list(documents))

    def embed_query(self, query: str) -> List[float]:
        """Embed a single query string, falling back to OpenAI on failure."""
        try:
            return self._azure.embed_query(query)
        except Exception as e:  # pragma: no cover - fallback path
            LOGGER.warning(
                "Azure embeddings.embed_query failed (%s). Falling back to OpenAI.",
                type(e).__name__,
            )
            self._init_openai()
            return self._openai.embed_query(query)

    async def aembed_documents(self, documents: Iterable[str]) -> List[List[float]]:
        """Async wrapper for embedding documents with fallback support."""
        try:
            if hasattr(self._azure, "aembed_documents"):
                return await self._azure.aembed_documents(list(documents))
            loop = asyncio.get_running_loop()
            return await loop.run_in_executor(None, self._azure.embed_documents, list(documents))
        except Exception as e:  # pragma: no cover - fallback path
            LOGGER.warning(
                "Azure aembed_documents failed (%s). Falling back to OpenAI.",
                type(e).__name__,
            )
            self._init_openai()
            if hasattr(self._openai, "aembed_documents"):
                return await self._openai.aembed_documents(list(documents))
            loop = asyncio.get_running_loop()
            return await loop.run_in_executor(None, self._openai.embed_documents, list(documents))

    async def aembed_query(self, query: str) -> List[float]:
        """Async wrapper for embedding a single query with fallback support."""
        try:
            if hasattr(self._azure, "aembed_query"):
                return await self._azure.aembed_query(query)
            loop = asyncio.get_running_loop()
            return await loop.run_in_executor(None, self._azure.embed_query, query)
        except Exception as e:  # pragma: no cover - fallback path
            LOGGER.warning(
                "Azure aembed_query failed (%s). Falling back to OpenAI.",
                type(e).__name__,
            )
            self._init_openai()
            if hasattr(self._openai, "aembed_query"):
                return await self._openai.aembed_query(query)
            loop = asyncio.get_running_loop()
            return await loop.run_in_executor(None, self._openai.embed_query, query)

    # Keep attribute access for compatibility with code that expects
    # the underlying embeddings object attributes (e.g., ``client``).
    def __getattr__(self, item: str) -> Any:
        return getattr(self._azure, item)

class LangChainOpenAIEmbeddingModel:
    def __init__(self, settings: BaseEmbeddingModelSetting) -> None:
        self.primary_model = OpenAIEmbeddings(
            api_key=settings.connection_config.openai_api_token,
            model=settings.ai_model_name,
            base_url=settings.connection_config.base_openai_url,
        )

        kwargs = {}
        if settings.connection_config.backup_proxy:
            kwargs["http_client"] = httpx.Client(proxy=settings.connection_config.backup_proxy)

        self.fallback_model = OpenAIEmbeddings(
            api_key=settings.connection_config.backup_openai_api_token,
            model=settings.ai_model_name,
            base_url=settings.connection_config.backup_openai_url,
            **kwargs,
        )

    def embed_documents(self, texts: List[str]) -> List[List[float]]:
        try:
            return self.primary_model.embed_documents(texts)
        except:
            return self.fallback_model.embed_documents(texts)

    async def aembed_documents(self, texts: List[str]) -> List[List[float]]:
        try:
            return await self.primary_model.aembed_documents(texts)
        except:
            return await self.fallback_model.aembed_documents(texts)

    def embed_query(self, text: str) -> List[float]:
        try:
            return self.primary_model.embed_query(text)
        except:
            return self.fallback_model.embed_query(text)

    async def aembed_query(self, text: str) -> List[float]:
        try:
            return await self.primary_model.aembed_query(text)
        except:
            return await self.fallback_model.aembed_query(text)

