class ExternalService(ExternalServiceInterface):
    MAX_RETRIES = 5

    def __init__(self, callback_url: str):
        super().__init__(callback_url)

    async def send(self, message: Message) -> bool:
        if message.files is None:
            message.files = []

        for i in range(self.MAX_RETRIES):
            try:
                response = await asyncio.to_thread(
                    requests.post,
                    url=self.callback_url,
                    headers=message.headers,
                    data=message.data,
                    files=message.files,
                    timeout=5,
                )

                response.raise_for_status()
                return True
            except requests.RequestException as e:
                # Handle exceptions (log them, re-raise, return False, etc.)
                if i == self.MAX_RETRIES - 1:
                    LOGGER.error(
                        f"An error occurred for sending {message} request to {self.callback_url} endpoint: {e}",
                    )
                    return False

async def send_message(
    response_data: Dict,
    response_url: str,
    response_header: Dict,
    retry_attempts: int,
):
    for i in range(1, retry_attempts):
        try:
            response = await asyncio.to_thread(
                requests.request,
                method="POST",
                url=response_url,
                headers=response_header,
                data=json.dumps(response_data.model_dump()),
                files=[],
                timeout=15,
            )
        except Exception as e:
            if i == retry_attempts - 1:
                LOGGER.error(
                    "wasn't able to send response to backend.\nError: %s" % e,
                )
            else:
                LOGGER.debug(
                    "wasn't able to send response to backend.\nError: %s" % e,
                )
            await asyncio.sleep(4)
            continue

        if response.status_code == 200:
            return True
        else:
            if i == retry_attempts:
                LOGGER.error(
                    "backend response was not 200!\nstatus_code: %s\nresponse: %s"
                    % (response.status_code, response.text),
                )
                continue

            await asyncio.sleep(4)
            continue
    return False

