async def find_collections_with_prompts(
    es: Elasticsearch, db_repository: RobotCollectionRepository
):
    collections_with_prompts = []

    try:
        query = {
            "query": {
                "bool": {"filter": {"exists": {"field": "collection_info.prompts"}}}
            },
            "size": 10000,
        }

        result = es.search(index="_all", body=query)

        for hit in result["hits"]["hits"]:
            index_name = hit["_index"]
            if index_name.startswith(db_repository.index_prefix):
                identifier = index_name[len(db_repository.index_prefix) :]
                collections_with_prompts.append(identifier)
                LOGGER.info(f"Found collection with prompts: {identifier}")

    except Exception as e:
        LOGGER.error(f"Error searching collections with prompts: {e}")

    return collections_with_prompts

async def update_collection_prompts(
    identifier,
    db_repository: RobotCollectionRepository,
    settings_modification_usecase: SettingsModificationUsecase,
):
    try:
        collection_info = await db_repository.get_collection_info_by_id(identifier)

        if (
            collection_info
            and collection_info.prompts
            and "basic_prompt" in collection_info.prompts
            and len(collection_info.prompts) == 1
        ):
            collection_setting = CollectionSetting(prompts=collection_info.prompts)

            await settings_modification_usecase.modify_settings(
                collection_info=collection_info,
                collection_setting=collection_setting,
            )

            LOGGER.info(f"Successfully updated prompts for collection {identifier}")
        else:
            LOGGER.warning(
                f"Collection {identifier} does not have a basic_prompt to update"
            )

    except Exception as e:
        LOGGER.error(f"Failed to update prompts for collection {identifier}: {e}")

