def swap_priorities_in_documents(index: str, es: Elasticsearch) -> int:
    """Swap priority values 3 with 1 in attribute_indexing and product.custom_attributes documents.

    Args:
        index: The index name to update.
        es: Elasticsearch client instance.

    Returns:
        Number of documents updated.
    """
    # First, get all documents that have priority 1 or 3 in either attribute_indexing or product.custom_attributes
    search_query = {
        "query": {
            "bool": {
                "should": [
                    {
                        "nested": {
                            "path": "attribute_indexing",
                            "query": {
                                "terms": {
                                    "attribute_indexing.priority": [1, 3]
                                }
                            }
                        }
                    },
                    {
                        "nested": {
                            "path": "product.custom_attributes",
                            "query": {
                                "terms": {
                                    "product.custom_attributes.priority": [1, 3]
                                }
                            }
                        }
                    }
                ]
            }
        },
        "_source": True,
        "size": 10000
    }

    response = es.search(index=index, body=search_query)
    documents = response["hits"]["hits"]

    if not documents:
        return 0

    updated_count = 0

    for doc in documents:
        doc_id = doc["_id"]
        source = doc["_source"]
        updated = False
        update_body = {}

        # Check if attribute_indexing exists and process it
        if "attribute_indexing" in source:
            if "priority" in source["attribute_indexing"]:
                if source["attribute_indexing"]["priority"] == 1:
                    source["attribute_indexing"]["priority"] = 3
                    updated = True
                elif source["attribute_indexing"]["priority"] == 3:
                    source["attribute_indexing"]["priority"] = 1
                    updated = True
            if updated:
                update_body["attribute_indexing"] = source["attribute_indexing"]

        # Check if product.custom_attributes exists and process it
        if "product" in source and isinstance(source["product"], dict):
            product = source["product"]
            if "custom_attributes" in product and isinstance(product["custom_attributes"], list):
                product_updated = False
                for attr in product["custom_attributes"]:
                    if "priority" in attr:
                        if attr["priority"] == 1:
                            attr["priority"] = 3
                            product_updated = True
                        elif attr["priority"] == 3:
                            attr["priority"] = 1
                            product_updated = True

                if product_updated:
                    update_body["product"] = product
                    updated = True

        if updated:
            # Update the document
            es.update(
                index=index,
                id=doc_id,
                body={
                    "doc": update_body
                }
            )
            updated_count += 1

    return updated_count

def check_documents_with_priorities(index: str, es: Elasticsearch) -> dict[str, dict[int, int]]:
    """Count documents with priority 1 and 3 in attribute_indexing and product.custom_attributes.

    Args:
        index: The index name to check.
        es: Elasticsearch client instance.

    Returns:
        Dictionary with priority counts for both locations.
    """
    try:
        results = {
            "attribute_indexing": {1: 0, 3: 0},
            "custom_attributes": {1: 0, 3: 0}
        }

        # Count documents with priority 1 and 3 in attribute_indexing
        for priority in [1, 3]:
            attr_indexing_query = {
                "query": {
                    "nested": {
                        "path": "attribute_indexing",
                        "query": {
                            "term": {
                                "attribute_indexing.priority": priority
                            }
                        }
                    }
                }
            }
            results["attribute_indexing"][priority] = es.count(index=index, body=attr_indexing_query)["count"]

        # Count documents with priority 1 and 3 in product.custom_attributes
        for priority in [1, 3]:
            custom_attr_query = {
                "query": {
                    "nested": {
                        "path": "product.custom_attributes",
                        "query": {
                            "term": {
                                "product.custom_attributes.priority": priority
                            }
                        }
                    }
                }
            }
            results["custom_attributes"][priority] = es.count(index=index, body=custom_attr_query)["count"]

        return results
    except Exception:
        return {
            "attribute_indexing": {1: 0, 3: 0},
            "custom_attributes": {1: 0, 3: 0}
        }

