class CategoryIndexingCopyMigration:
    def __init__(self, ecommerce_repository):
        self.ecommerce_repository = ecommerce_repository

    async def copy_category_indexing(
        self,
        source_index: str,
        target_index: str,
        overwrite_existing: bool = False
    ) -> None:
        """Copy category_indexing data from source index to target index

        Args:
            source_index: Name of the source index to copy from
            target_index: Name of the target index to copy to
            overwrite_existing: If True, overwrites existing category_indexing data.
                              If False, only copies to documents that don't have category_indexing.
        """
        es = self.ecommerce_repository.elastic_search_repository

        try:
            LOGGER.info(f"Starting category_indexing copy from {source_index} to {target_index} (overwrite={overwrite_existing})")

            # First, get all documents with category_indexing from source index
            source_data = await self._get_category_indexing_from_source(source_index)

            if not source_data:
                LOGGER.warning(f"No category_indexing data found in source index {source_index}")
                return

            LOGGER.info(f"Found {len(source_data)} documents with category_indexing in source index")

            # Then, copy the data to target index
            await self._copy_data_to_target(target_index, source_data, overwrite_existing)

        except Exception as e:
            LOGGER.error(f"Failed to copy category_indexing from {source_index} to {target_index}: {str(e)}")
            raise

    async def _get_category_indexing_from_source(self, source_index: str) -> List[dict]:
        """Get all documents with category_indexing from source index"""
        es = self.ecommerce_repository.elastic_search_repository

        # Search for all documents with category_indexing
        search_body = {
            "size": 10000,  # Adjust based on your needs
            "_source": ["product.id", "category_indexing"],
            "query": {
                "exists": {
                    "field": "category_indexing"
                }
            }
        }

        result = await es.search(index=source_index, body=search_body)

        source_data = []
        for hit in result["hits"]["hits"]:
            doc_id = hit["_id"]
            source = hit["_source"]

            if "category_indexing" in source and source["category_indexing"]:
                source_data.append({
                    "doc_id": doc_id,
                    "product_id": source.get("product", {}).get("id"),
                    "category_indexing": source["category_indexing"]
                })

        return source_data

    async def _copy_data_to_target(
        self,
        target_index: str,
        source_data: List[dict],
        overwrite_existing: bool
    ) -> None:
        """Copy category_indexing data to target index"""
        es = self.ecommerce_repository.elastic_search_repository

        # Determine condition based on overwrite_existing parameter
        if overwrite_existing:
            condition = ""
            action_comment = "// Always overwrite"
        else:
            condition = " && (ctx._source.category_indexing == null || ctx._source.category_indexing.size() == 0)"
            action_comment = "// Only copy if category_indexing doesn't exist or is empty"

        # Prepare the category_indexing data as a parameter
        category_data_json = json.dumps(source_data, ensure_ascii=False)

        # Script to copy category_indexing data
        update_script = {
            "script": {
                "source": f"""
                    {action_comment}
                    def sourceData = params.source_data;
                    def currentDocId = ctx._id;

                    // Find matching data for current document
                    for (def item : sourceData) {{
                        if (item.doc_id == currentDocId{condition}) {{
                            ctx._source.category_indexing = item.category_indexing;
                            break;
                        }}
                    }}
                """,
                "lang": "painless",
                "params": {
                    "source_data": source_data
                }
            },
            "query": {
                "ids": {
                    "values": [item["doc_id"] for item in source_data]
                }
            } if not overwrite_existing else {
                "match_all": {}
            }
        }

        # Execute update by query
        response = await es.update_by_query(
            index=target_index,
            body=update_script,
            wait_for_completion=True,
            refresh=True
        )

        updated_count = response.get('updated', 0)
        LOGGER.info(f"Successfully copied category_indexing data to {updated_count} documents in {target_index}")

    async def copy_specific_product_category_indexing(
        self,
        source_index: str,
        target_index: str,
        product_ids: List[str],
        overwrite_existing: bool = False
    ) -> None:
        """Copy category_indexing data for specific products only

        Args:
            source_index: Name of the source index to copy from
            target_index: Name of the target index to copy to
            product_ids: List of product IDs to copy category_indexing for
            overwrite_existing: If True, overwrites existing category_indexing data.
        """
        es = self.ecommerce_repository.elastic_search_repository

        try:
            LOGGER.info(f"Starting category_indexing copy for {len(product_ids)} specific products")

            # Get category_indexing data for specific products
            search_body = {
                "size": 10000,
                "_source": ["product.id", "category_indexing"],
                "query": {
                    "bool": {
                        "must": [
                            {"exists": {"field": "category_indexing"}},
                            {"terms": {"product.id": product_ids}}
                        ]
                    }
                }
            }

            result = await es.search(index=source_index, body=search_body)

            source_data = []
            for hit in result["hits"]["hits"]:
                doc_id = hit["_id"]
                source = hit["_source"]

                if "category_indexing" in source and source["category_indexing"]:
                    source_data.append({
                        "doc_id": doc_id,
                        "product_id": source.get("product", {}).get("id"),
                        "category_indexing": source["category_indexing"]
                    })

            if not source_data:
                LOGGER.warning(f"No category_indexing data found for specified products in {source_index}")
                return

            LOGGER.info(f"Found category_indexing data for {len(source_data)} products")

            # Copy to target index
            await self._copy_data_to_target(target_index, source_data, overwrite_existing)

        except Exception as e:
            LOGGER.error(f"Failed to copy specific product category_indexing: {str(e)}")
            raise

