def truncate_embeddings(embeddings, vector_size):
    """Truncate embedding vectors to the specified size."""
    return [embedding[:vector_size] for embedding in embeddings]

async def calculate_and_update_product_vectors(
    ecommerce_identifier: str,
    ecommerce_repo: IRobotEcommerceRepository,
    embedding_model: Dict[str, Any],
    vector_size: int,
    batch_size: int = 100,
):
    """Calculate embeddings for all products in the ecommerce index and update them."""
    try:
        LOGGER.info(
            f"Stage 2: Getting all products for ecommerce identifier {ecommerce_identifier}"
        )
        ecommerce = await ecommerce_repo.get_ecommerce_by_id(ecommerce_identifier)
        products = ecommerce.products

        if not products:
            LOGGER.warning(
                f"No products found for ecommerce identifier {ecommerce_identifier}"
            )
            return

        LOGGER.info(
            f"Found {len(products)} products for ecommerce identifier {ecommerce_identifier}"
        )

        # Process products in batches to avoid overwhelming the embedding service
        for i in range(0, len(products), batch_size):
            batch = products[i : i + batch_size]

            LOGGER.info(
                f"Processing batch {i // batch_size + 1} of {(len(products) + batch_size - 1) // batch_size} for {ecommerce_identifier}"
            )

            # Get product names for embedding
            product_names = [product.name for product in batch]

            # Calculate embeddings for product names
            try:
                embeddings = await embedding_model[
                    "embedding_model_name"
                ].aembed_documents(product_names)
                # Truncate embeddings to the configured size
                truncated_embeddings = truncate_embeddings(embeddings, vector_size)
                LOGGER.info(
                    f"Successfully calculated and truncated embeddings for batch {i // batch_size + 1}"
                )

                # Assign embeddings to products
                for j, product in enumerate(batch):
                    if j < len(truncated_embeddings):
                        product.product_vector = truncated_embeddings[j]
                    else:
                        LOGGER.warning(
                            f"Missing embedding for product {product.id} in batch {i // batch_size + 1}"
                        )

                # Update products in Elasticsearch
                await ecommerce_repo.add_products_to_ecommerce(
                    ecommerce_identifier, batch
                )
                LOGGER.info(
                    f"Successfully updated products with vectors for batch {i // batch_size + 1}"
                )

            except Exception as e:
                LOGGER.error(
                    f"Error calculating embeddings for batch {i // batch_size + 1}: {e}"
                )
                continue

        LOGGER.info(
            f"Completed vector updates for ecommerce identifier {ecommerce_identifier}"
        )

    except Exception as e:
        LOGGER.error(
            f"Error processing ecommerce identifier {ecommerce_identifier}: {e}"
        )

