    """Create the new index with updated mapping.

    Args:
        elastic_search: Elasticsearch client instance.
        target_index: Target index name to create.
    """
    mapping = {
        "mappings": {
            "properties": {
                "traces": {
                    "properties": {
                        "collection_identifier": {"type": "keyword"},
                        "type": {"type": "keyword"},  # inference | training | other
                        "trace_id": {"type": "keyword"},
                        "user_id": {"type": "keyword"},
                        "created_at": {"type": "date"},
                        "ended_at": {"type": "date"},
                        "total_cost": {"type": "float"},
                        "collection_info_version": {"type": "integer"},
                    }
                },
                "chain_calls": {
                    "properties": {
                        "trace_id": {"type": "keyword"},
                        "chain_name": {"type": "keyword"},
                        "input_data": {"type": "text"},
                        "output_data": {"type": "text"},
                        "metadata": {
                            "type": "object",
                            "dynamic": False,
                        },
                    },
                },
                "inference_results": {
                    "properties": {
                        "trace_id": {"type": "keyword"},
                        "chat_id": {"type": "keyword"},
                        "message_id": {"type": "keyword"},
                        "query": {"type": "text"},
                        "message_vector": {
                            "type": "dense_vector",
                            "index": True,
                        },
                        "generated_text": {"type": "text"},
                        "operator_response": {"type": "text"},
                        "query_language": {"type": "keyword"},
                        "result_state": {"type": "boolean"},
                        "refined_query": {"type": "text"},
                        "query_tag": {"type": "keyword"},
                        "is_insult": {"type": "boolean"},
                        "is_spam": {"type": "boolean"},
                        "relevancy": {"type": "keyword"},
                        "ai_tag": {"type": "integer"},
                        "history": {
                            "type": "object",
                            "dynamic": False,
                        },
                        "retrieved_docs": {
                            "type": "keyword",
                        },
                        "client_state": {
                            "type": "object",
                            "dynamic": False,
                        },
                    },
                },
                "training_results": {
                    "properties": {
                        "trace_id": {"type": "keyword"},
                        "submitted_at": {"type": "date"},
                        "intermediate_data": {
                            "type": "nested",
