        LOGGER.error(f"Error creating target index {target_index}: {e}")
        raise

def transform_training_result_data(old_training_result: Dict[str, Any]) -> Dict[str, Any]:
    """Transform old training result format to new nested format.

    Args:
        old_training_result: Training result in old format.

    Returns:
        Training result in new nested format.
    """
    transformed_data = {
        "trace_id": old_training_result.get("trace_id"),
        "submitted_at": old_training_result.get("submitted_at"),
        "intermediate_data": [],
    }

    old_intermediate_data = old_training_result.get("intermediate_data", {})

    # Transform reference_data_characters
    if "reference_data_characters" in old_intermediate_data:
        ref_data = old_intermediate_data["reference_data_characters"]
        for key, value in ref_data.items():
            data_entry = {
                "data_name": "reference_data_characters",
                "identifier": key,
            }

            # Determine value type and add appropriate field
            if isinstance(value, int):
                data_entry["value_int"] = value
            elif isinstance(value, float):
                data_entry["value_float"] = value
            else:
                data_entry["value"] = str(value)

            transformed_data["intermediate_data"].append(data_entry)

    # Transform statuses
    if "statuses" in old_intermediate_data:
        statuses = old_intermediate_data["statuses"]
        for key, value in statuses.items():
            data_entry = {"data_name": "statuses", "identifier": key, "value": str(value)}
            transformed_data["intermediate_data"].append(data_entry)

    # Transform status_messages
    if "status_messages" in old_intermediate_data:
        status_messages = old_intermediate_data["status_messages"]
        if status_messages:
            for key, value in status_messages.items():
                data_entry = {"data_name": "status_messages", "identifier": key, "value": str(value)}
                transformed_data["intermediate_data"].append(data_entry)

    return transformed_data

async def migrate_documents_batch(
    elastic_search_async, documents: List[Dict[str, Any]], source_index: str, target_index: str, batch_number: int
) -> int:
    """Migrate a batch of documents to the target index and delete from source.

    Args:
        elastic_search_async: Async Elasticsearch client.
        documents: List of documents to migrate.
        source_index: Source index name.
        target_index: Target index name.
        batch_number: Current batch number for logging.

    Returns:
        Number of successfully migrated documents.
    """
    actions = []
    document_ids = []

    for doc in documents:
        source_data = doc["_source"]
        new_doc = {"_op_type": "index", "_index": target_index, "_id": doc["_id"], "_source": {}}

        # Copy traces as-is
        if "traces" in source_data:
            new_doc["_source"]["traces"] = source_data["traces"]

        if "chain_call" in source_data:
            chain_call_data = source_data["chain_call"]
            transformed_chain_calls = {}

            for key, value in chain_call_data.items():
                if key in ["input_data", "output_data"]:
                    if isinstance(value, dict):
                        transformed_chain_calls[key] = json.dumps(value)
                    else:
                        transformed_chain_calls[key] = str(value) if value is not None else ""
                else:
                    transformed_chain_calls[key] = value

            new_doc["_source"]["chain_calls"] = transformed_chain_calls

        # Copy inference_results as-is
        if "inference_results" in source_data:
            new_doc["_source"]["inference_results"] = source_data["inference_results"]

        # Transform training_results
        if "training_results" in source_data:
            # old_training_result = source_data["training_results"]
            # transformed_training_result = transform_training_result_data(old_training_result)
            new_doc["_source"]["training_results"] = source_data["training_results"]

        actions.append(new_doc)
        document_ids.append(doc["_id"])

    if actions:
        try:
            success_count, failed_items = await async_bulk(
                elastic_search_async, actions, chunk_size=500, request_timeout=300
            )

            if success_count > 0:
                # Delete successfully migrated documents from source index
                delete_actions = []
                for doc_id in document_ids:
                    delete_actions.append({
                        "_op_type": "delete",
                        "_index": source_index,
                        "_id": doc_id
                    })

                try:
                    delete_success_count, delete_failed_items = await async_bulk(
                        elastic_search_async, delete_actions, chunk_size=500, request_timeout=300
                    )
                    LOGGER.info(f"Batch {batch_number}: Successfully migrated {success_count} documents and deleted {delete_success_count} from source")
                    if delete_failed_items:
                        LOGGER.warning(f"Batch {batch_number}: {len(delete_failed_items)} failed deletions from source")
                except Exception as e:
                    LOGGER.error(f"Batch {batch_number}: Error during bulk delete from source: {e}")

            if failed_items:
                LOGGER.warning(f"Batch {batch_number}: {len(failed_items)} failed items")
            return success_count
        except Exception as e:
            LOGGER.error(f"Batch {batch_number}: Error during bulk insert: {e}")
            return 0

    return 0

async def copy_back_documents_batch(
    elastic_search_async, documents: List[Dict[str, Any]], source_index: str, target_index: str, batch_number: int
) -> int:
    """Copy a batch of documents back to source index and delete from target.

    Args:
        elastic_search_async: Async Elasticsearch client.
        documents: List of documents to copy back.
        source_index: Source index name (destination for copy back).
        target_index: Target index name (source for copy back).
        batch_number: Current batch number for logging.

    Returns:
        Number of successfully copied documents.
    """
    actions = []
    document_ids = []

    for doc in documents:
        source_data = doc["_source"]
        new_doc = {
            "_op_type": "index",
            "_index": source_index,
            "_id": doc["_id"],
            "_source": source_data
        }
        actions.append(new_doc)
        document_ids.append(doc["_id"])

    if actions:
        try:
            success_count, failed_items = await async_bulk(
                elastic_search_async, actions, chunk_size=500, request_timeout=300
            )

            if success_count > 0:
                # Delete successfully copied documents from target index
                delete_actions = []
                for doc_id in document_ids:
                    delete_actions.append({
                        "_op_type": "delete",
                        "_index": target_index,
                        "_id": doc_id
                    })

                try:
                    delete_success_count, delete_failed_items = await async_bulk(
                        elastic_search_async, delete_actions, chunk_size=500, request_timeout=300
                    )
                    LOGGER.info(f"Copy back batch {batch_number}: Successfully copied {success_count} documents and deleted {delete_success_count} from target")
                    if delete_failed_items:
                        LOGGER.warning(f"Copy back batch {batch_number}: {len(delete_failed_items)} failed deletions from target")
                except Exception as e:
                    LOGGER.error(f"Copy back batch {batch_number}: Error during bulk delete from target: {e}")

            if failed_items:
                LOGGER.warning(f"Copy back batch {batch_number}: {len(failed_items)} failed items")
            return success_count
        except Exception as e:
            LOGGER.error(f"Copy back batch {batch_number}: Error during bulk insert: {e}")
            return 0

    return 0

