def parse_language_code(language_code: str | None) -> str:
    try:
        language = pycountry.languages.get(alpha_2=language_code)
        return language.name
    except Exception as e:
        LOGGER.warning(
            "Error during language detection language_code: %s: %s"
            % (language_code, e)
        )
        return "Persian"

async def update_documents(
    identifier, db_repository: RobotCollectionRepository
):
    collection_info = await db_repository.get_collection_info_by_id(identifier)
    ref_datum = await db_repository.get_collection_reference_datums_by_id(identifier)

    collection_info.language = parse_language_code(collection_info.language)
    for ref_data in ref_datum:
        new_language = {}
        for key, value in ref_data.language.items():
            new_language[parse_language_code(key)] = value
        ref_data.language = new_language

    await db_repository.add_collection_info_to_collection(
        identifier, collection_info
    )
    await db_repository.add_reference_data_to_collection(identifier, ref_datum)

