class IndexExporter:
    """
    Exports all documents from a given index into a JSON lines file.
    """

    def __init__(self, client: Elasticsearch) -> None:
        self._client = client

    def export_to_file(self, index_name: str, file_path: str) -> None:
        """
        Export all documents from an index to a JSON file (one line per doc).
        """
        query = {"query": {"match_all": {}}}
        results = helpers.scan(client=self._client, index=index_name, query=query)

        with open(file_path, "w", encoding="utf-8") as f:
            for doc in results:
                f.write(json.dumps(doc) + "\n")

        print(f"Exported data from index '{index_name}' to '{file_path}'")

def fetch_products(src: API, limit: int | None,
                   per_page: int = 100) -> Generator[Dict[str, Any], None, None]:
    page, seen = 1, 0
    while True:
        r = src.get("products", params={"page": page, "per_page": per_page})
        r.raise_for_status()
        batch: List[Dict[str, Any]] = r.json()
        if not batch:
            break
        for prod in batch:
            yield prod
            seen += 1
            if limit and seen >= limit:
                return
        page += 1

def _strip_id(o: Any) -> Any:
    if isinstance(o, dict):
        o.pop("id", None)
        o.pop("date_created", None)
        o.pop("date_modified", None)
    return o

def scrub_product(src: Dict[str, Any]) -> Dict[str, Any]:
    p = {k: v for k, v in src.items() if k in SAFE_FIELDS}

    for coll in ("images", "categories", "tags", "attributes", "default_attributes"):
        if coll in p:
            p[coll] = [_strip_id(i) for i in p[coll] if _non_empty(i)]

    p = {k: v for k, v in p.items() if _non_empty(v)}

    for price in ("regular_price", "sale_price"):
        if price in p:
            p[price] = str(p[price])

    return p

def transfer(src_url, src_key, src_sec, dst_url, dst_key, dst_sec,
             limit: int | None, debug: bool):
    src  = get_wc_client(src_url, src_key, src_sec,  query_string_auth=True)
    dest = get_wc_client(dst_url, dst_key, dst_sec, query_string_auth=False)

    total = limit
    if limit is None:
        total = int(src.get("products", params={"per_page": 1}).headers
                        .get("X-WP-Total", 0))

    for prod in tqdm(fetch_products(src, limit), total=total,
                     unit="item", desc="Copying"):
        clean = scrub_product(prod)
        try:
            post_product(dest, clean, debug, dst_url, dst_key, dst_sec)
        except Exception as e:
            print(f"\n⚠️  Failed on «{prod.get('name', '∅')}»: {e}", file=sys.stderr)

