class CategoryIndexingMixin:
    async def get_category_indexing(self, ecommerce_identifier: str, category_name: str) -> CategoryIndexing:
        """Retrieve category indexing by category name from the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            category_name: Category name.

        Returns:
            CategoryIndexing: The category indexing object.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        doc_id = f"{self.category_indexing_prefix}{category_name}"

        try:
            response = await self.elastic_search_repository.get(
                index=index_name,
                id=doc_id,
            )
            return CategoryIndexing(**response["_source"]["category_indexing"])
        except Exception as e:
            if isinstance(e, NotFoundError):
                raise exceptions.DocumentNotFound(
                    detail=f"Category indexing for category {category_name} not found in {ecommerce_identifier}"
                )
            LOGGER.error(f"Error retrieving category indexing: {e}")

    async def get_category_by_name(self, ecommerce_identifier: str, category_name: str) -> CategoryIndexing:
        """Retrieve category indexing by category name from the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            category_name: Category name to search for.

        Returns:
            CategoryIndexing: The category indexing object.

        Raises:
            DocumentNotFound: If category with the given name is not found.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        query = {
            "query": {
                "nested": {
                    "path": "category_indexing",
                    "query": {"term": {"category_indexing.category_name": category_name}},
                }
            }
        }

        try:
            response = await self.elastic_search_repository.search(
                index=index_name,
                body=query,
                size=1,
            )

            hits = response["hits"]["hits"]
            if not hits:
                raise exceptions.DocumentNotFound(
                    detail=f"Category '{category_name}' not found in {ecommerce_identifier}"
                )

            return CategoryIndexing(**hits[0]["_source"]["category_indexing"])

        except Exception as e:
            if isinstance(e, exceptions.DocumentNotFound):
                raise
            LOGGER.error(f"Error retrieving category by name '{category_name}': {e}")
            raise exceptions.DocumentNotFound(
                detail=f"Error retrieving category '{category_name}' from {ecommerce_identifier}: {str(e)}"
            )

    async def add_category_indexing(
        self,
        ecommerce_identifier: str,
        category_indexings: List[CategoryIndexing],
        bulk_size: int = 1000,
    ):
        """Add category indexing info to the ecommerce index in Elasticsearch.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            category_indexings: List of CategoryIndexing objects to add.
            bulk_size: Number of items to index in each bulk operation.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        actions = []

        for category_indexing in category_indexings:
            # doc_fields = {}
            # doc_fields["id"] = category_indexing.id
            # doc_fields["category_name"] = category_indexing.category_name
            # doc_fields["sub_categories"] = category_indexing.sub_categories
            # doc_fields["sampled_products"] = category_indexing.sampled_products

            doc_fields = {
                "id": category_indexing.id,
                "category_name": category_indexing.category_name,
                "sub_categories": category_indexing.sub_categories,
                "sampled_products": category_indexing.sampled_products,
                "first_messages": category_indexing.first_messages,
                "second_messages": category_indexing.second_messages,
                "client_db_categories": [
                    cat.model_dump() if hasattr(cat, "model_dump") else cat.__dict__
                    for cat in category_indexing.client_db_categories
                ],
            }
            actions.append(
                {
                    "_op_type": "update",
                    "_index": index_name,
                    "_id": f"{self.category_indexing_prefix}{category_indexing.id}",
                    "doc": {"category_indexing": doc_fields},
                    "doc_as_upsert": True,
                }
            )
        for i in range(0, len(actions), bulk_size):
            batch_actions = actions[i : i + bulk_size]
            try:
                (success, errors) = await async_bulk(
                    self.elastic_search_repository,
                    batch_actions,
                    refresh="wait_for",
                    raise_on_error=False,
                    stats_only=False,
                )
            except BulkIndexError as bulk_error:
                LOGGER.error(f"BulkIndexError in adding category indexing: {bulk_error.errors}")
                raise exceptions.DocumentAdditionError(
                    detail=f"Error adding category indexing batch {i // bulk_size + 1} to {index_name}"
                )
            except Exception as e:
                LOGGER.error(
                    f"Unable to add category indexing batch {i // bulk_size + 1} to {index_name}: {e}",
                )
                raise exceptions.DocumentAdditionError(detail=f"Error adding category indexing to {index_name}: {e}")

    async def get_all_category_indexings(self, ecommerce_identifier: str) -> List[CategoryIndexing]:
        """Retrieve all category indexings from the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.

        Returns:
            List[CategoryIndexing]: List of category indexing objects.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        query = {
            "query": {
                "nested": {
                    "path": "category_indexing",
                    "query": {"exists": {"field": "category_indexing"}},
                }
            },
        }
        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
            scroll="2m",
            size=1000,
        )

        hits = response["hits"]["hits"]
        scroll_id = response["_scroll_id"]

        category_indexings = []
        for hit in hits:
            category_indexings.append(CategoryIndexing(**hit["_source"]["category_indexing"]))

        while len(hits) > 0:
            response = await self.elastic_search_repository.scroll(
                scroll_id=scroll_id,
                scroll="2m",
            )
            hits = response["hits"]["hits"]
            scroll_id = response["_scroll_id"]

            for hit in hits:
                category_indexings.append(CategoryIndexing(**hit["_source"]["category_indexing"]))

        await self.elastic_search_repository.clear_scroll(scroll_id=scroll_id)
        return category_indexings

    async def get_category_indexing_from_url(self, robot_identifier: str, url: str) -> CategoryIndexing:
        index_name = self.get_index_name(robot_identifier)
        query = {
            "query": {
                "nested": {
                    "path": "category_indexing",
                    "query": {
                        "nested": {
                            "path": "category_indexing.client_db_categories",
                            "query": {"term": {"category_indexing.client_db_categories.slug": url}},
                        }
                    },
                }
            }
        }

        try:
            response = await self.elastic_search_repository.search(
                index=index_name,
                body=query,
                scroll="2m",
                size=1000,
            )

            hits = response["hits"]["hits"]
            scroll_id = response.get("_scroll_id")

            category_indexings = []

            for hit in hits:
                category_indexings.append(CategoryIndexing(**hit["_source"]["category_indexing"]))

            while len(hits) > 0 and scroll_id:
                response = await self.elastic_search_repository.scroll(
                    scroll_id=scroll_id,
                    scroll="2m",
                )
                hits = response["hits"]["hits"]
                scroll_id = response.get("_scroll_id")

                for hit in hits:
                    category_indexings.append(CategoryIndexing(**hit["_source"]["category_indexing"]))

            if scroll_id:
                await self.elastic_search_repository.clear_scroll(scroll_id=scroll_id)

            return category_indexings

        except Exception as e:
            pass

class IndexingInfoMixin:
    async def add_indexing_info_to_ecommerce(
        self,
        ecommerce_identifier: str,
        indexing_infos: List[IndexingInfo],
    ):
        """Add indexing info to the ecommerce index in Elasticsearch.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            indexing_infos: List of IndexingInfo objects to add.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        try:
            actions = []
            for indexing_info in indexing_infos:
                actions.append(
                    {
                        "_op_type": "index",
                        "_index": index_name,
                        "_id": f"{self.indexing_info_prefix}{indexing_info.id}",
                        "_source": {"indexing_info": json.loads(indexing_info.model_dump_json())},
                    }
                )
            await async_bulk(
                self.elastic_search_repository,
                actions,
                refresh="wait_for",
            )
        except Exception as e:
            LOGGER.error(
                f"unable to add indexing info {ecommerce_identifier} to {index_name}: {e}",
            )
            raise exceptions.CollectionInfoAdditionError(
                detail="unable to add indexing info to %s" % index_name,
            )

    async def get_all_indexing_info(self, ecommerce_identifier: str) -> List[IndexingInfo]:
        """Retrieve all indexing info from the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.

        Returns:
            List[IndexingInfo]: List of indexing info objects.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        part_name = "indexing_info"
        part_object = self.ecommerce_parts_mapping[part_name]
        query = {
            "query": {
                "bool": {
                    "filter": [],
                    "must": [
                        {
                            "nested": {
                                "path": "indexing_info",
                                "query": {"bool": {"must": []}},
                            }
                        }
                    ],
                }
            }
        }
        response = await self.elastic_search_repository.search(index=index_name, body=query, size=10000, _source=False)
        response = response["hits"]["hits"]

        parts = self._parse_ecommerce_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )

        return parts

    async def match_indexing_info(self, ecommerce_identifier: str, query: str) -> List[IndexingInfo]:
        """Match indexing info by query in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            query: Query string to match.

        Returns:
            List[IndexingInfo]: List of matching indexing info objects.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        part_name = "indexing_info"
        part_object = self.ecommerce_parts_mapping[part_name]
        es_query = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "nested": {
                                "path": "indexing_info",
                                "query": {"bool": {"must": [{"match": {"indexing_info.name": query}}]}},
                            }
                        }
                    ],
                }
            },
            "_source": {"excludes": "indexing_info.options"},
        }
        response = await self.elastic_search_repository.search(
            index=index_name, body=es_query, size=10000, _source=False
        )
        response = response["hits"]["hits"]

        parts = self._parse_ecommerce_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )

        return parts

    async def get_indexing_info_by_options(self, ecommerce_identifier: str, options: List[str]) -> List[IndexingInfo]:
        """Retrieve indexing info by options from the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            options: List of options to filter by.

        Returns:
            List[IndexingInfo]: List of indexing info objects.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        part_name = "indexing_info"
        part_object = self.ecommerce_parts_mapping[part_name]
        query = {
            "query": {"bool": {"must": [{"terms": {"indexing_info.options": options}}]}},
        }
        response = await self.elastic_search_repository.search(index=index_name, body=query, size=10000, _source=False)
        response = response["hits"]["hits"]

        parts = self._parse_ecommerce_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )

        return parts

class ParsingMixin:
    @staticmethod
    def _parse_ecommerce_part(
        documents: dict,
        part_object: Any,
        part_name: str,
    ) -> list:
        """Parse a part of ecommerce documents into model objects.

        Args:
            documents: List of Elasticsearch documents.
            part_object: The Pydantic model class to parse into.
            part_name: The part name in the document.

        Returns:
            list: List of parsed model objects.
        """
        data = []
        for doc in documents:
            _source = doc["_source"]
            data.append(part_object(**_source[part_name]))
        return data

    def _parse_documents(self, documents: dict):
        """Parse all ecommerce documents into an Ecommerce object.

        Args:
            documents: List of Elasticsearch documents.

        Returns:
            Ecommerce: The parsed Ecommerce object.
        """
        mapping = {
            "metadata": None,
            "product": [],
            "indexing_info": [],
            "category_indexing": [],
            "attribute_indexing": [],
            "adv_messages": [],
            "cta_response": [],
        }

        for doc in documents:
            _source = doc["_source"]
            for key, value in _source.items():
                try:
                    if key == "metadata":
                        mapping[key] = EcommerceMetadata(**value)
                    else:
                        if isinstance(value, list):
                            for item in value:
                                mapping[key].append(self.ecommerce_parts_mapping[key](**item))
                        elif isinstance(value, dict):
                            mapping[key].append(self.ecommerce_parts_mapping[key](**value))
                except Exception as e:
                    LOGGER.error(
                        f"Failed to parse ecommerce_models {key}. doc = {_source}, exception = {e}",
                    )
                    raise exceptions.ElasticDocumentParserException(
                        detail="ecommerce_models = %s, doc = %s" % (key, _source),
                    ) from e

        return Ecommerce(
            metadata=mapping["metadata"],
            products=mapping["product"],
            indexing_infos=mapping["indexing_info"],
            attribute_indexings=mapping["attribute_indexing"],
            category_indexings=mapping["category_indexing"],
            adv_messages=mapping["adv_messages"],
            cta_responses=mapping["cta_response"],
        )

