class SearchMixin:
    async def search_products_by_name(
        self,
        ecommerce_identifier: str,
        name: str,
        search_method: str = "match",
        max_results: int = 10,
    ) -> Tuple[List[Product], List[float]]:
        """Search products by name in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            name: Product name to search for.
            search_method: Search method ("match" or "fuzzy").
            max_results: Maximum number of results to return.

        Returns:
            Tuple[List[Product], List[float]]: Products and their scores.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        query = await self._construct_search_query_v2(
            ecommerce_identifier=ecommerce_identifier,
            name=name,
            max_results=max_results,
        )
        query["filter"].append({
          "term": {
            "product.stock_status": "instock"
          }
        })
        query["_source"] = {
            "excludes": [
                "product.product_vector",
                "product.custom_attributes.vector",
            ]
        }
        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )
        docs = response["hits"]["hits"]
        scores = [d["_score"] for d in docs]
        products = self._parse_ecommerce_part(
            docs,
            part_object=Product,
            part_name="product",
        )
        return products, scores

    async def search_products_by_language_and_accent(
        self,
        ecommerce_identifier: str,
        field_query: dict,
        search_method: str = "match",
        max_results: int = 10,
        minimum_should_match: str = "67%",
        acceptable_list: list | None = None,
        fuzziness: str | int = "AUTO",
    ) -> List[Product]:
        """Search products by language and accent in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            field_query: Query fields for search.
            search_method: Search method.
            max_results: Maximum number of results.
            minimum_should_match: Minimum should match parameter.
            acceptable_list: List of acceptable fields.
            fuzziness: Fuzziness parameter.

        Returns:
            List[Product]: List of matching products.
        """
        if acceptable_list is None:
            acceptable_list = [
                "accent",
                "language",
                "gender",
                "age",
                "popularity",
                "episode_count",
            ]

        index_name = self.get_index_name(ecommerce_identifier)

        LOGGER.debug(f"Search query fields: {field_query}")

        must_queries = []
        for key in acceptable_list:
            if key in field_query and field_query[key] is not None and field_query[key] != "":
                must_queries.append(
                    {
                        "match": {
                            f"costum_attribute.{key}": {
                                "query": field_query[key],
                                "minimum_should_match": minimum_should_match,
                            }
                        }
                    }
                )

        filter_queries = []
        if "age" in field_query and field_query["age"] is not None and field_query["age"] != "":
            try:
                age_value = int(field_query["age"])
                filter_queries.append({"range": {"costum_attribute.age_min": {"lte": age_value, "gte": 0}}})
                filter_queries.append({"range": {"costum_attribute.age_max": {"gte": age_value, "lte": 99}}})
            except (ValueError, TypeError):
                LOGGER.error(f"Invalid age value: {field_query['age']}")

        query = {"query": {"bool": {}}, "size": max_results}

        if must_queries:
            query["query"]["bool"]["must"] = must_queries

        if filter_queries:
            query["query"]["bool"]["filter"] = filter_queries

        if not must_queries and not filter_queries:
            query["query"] = {"match_all": {}}

        # Add sorting by average_rating
        query["sort"] = [{"product.average_rating": {"order": "desc"}}, "_score"]

        LOGGER.debug(f"Final Elasticsearch query: {query}")

        try:
            response = await self.elastic_search_repository.search(
                index=index_name,
                body=query,
            )

            docs = response["hits"]["hits"]
            LOGGER.debug(f"Search returned {len(docs)} results")
            products = self._parse_ecommerce_part(docs, part_object=Product, part_name="product")
            return products
        except Exception as e:
            LOGGER.error(f"Elasticsearch search error: {str(e)}")
            if hasattr(e, "info"):
                LOGGER.error(f"Error details: {e.info}")
            return []

    async def search_products_by_custom_attributes(
        self,
        ecommerce_identifier: str,
        custom_attributes: Dict[str, Any],
        max_results: int = 10,
    ) -> Tuple[List[Product], List[float]]:
        """Search products by custom attributes in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            custom_attributes: Dictionary of custom attributes.
            max_results: Maximum number of results.

        Returns:
            Tuple[List[Product], List[float]]: Products and their scores.
        """
        index_name = self.get_index_name(ecommerce_identifier)
        must_queries = []
        for key, value in custom_attributes.items():
            must_queries.append(
                {
                    "nested": {
                        "path": "product.custom_attributes",
                        "query": {
                            "bool": {
                                "must": [
                                    {"match": {"product.custom_attributes.name": key}},
                                    {
                                        "multi_match": {
                                            "query": value,
                                            "fields": [
                                                "product.custom_attributes.value",
                                                "product.custom_attributes.value_string",
                                                "product.custom_attributes.value_int",
                                                "product.custom_attributes.value_long",
                                                "product.custom_attributes.value_float",
                                                "product.custom_attributes.value_date",
                                            ],
                                        }
                                    },
                                ],
                            }
                        },
                    }
                }
            )

        query = {
            "query": {"bool": {"must": must_queries}},
            "size": max_results,
        }

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )
        docs = response["hits"]["hits"]
        scores = [d["_score"] for d in docs]
        products = self._parse_ecommerce_part(
            docs,
            part_object=Product,
            part_name="product",
        )
        return products, scores

    async def filter_products_by_numeric_custom_attributes(
        self,
        ecommerce_identifier: str,
        numeric_filters: List[dict[str, Any]],
        product_ids: List[str],
        max_results: int = 20,
    ) -> Tuple[List[Product], List[float]]:
        """Filter products by numeric custom attributes in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            numeric_filters: List of numeric filters.
            product_ids: List of product IDs.
            max_results: Maximum number of results.

        Returns:
            Tuple[List[Product], List[float]]: Filtered products and their scores.
        """
        index_name: str = self.get_index_name(ecommerce_identifier)
        must_queries: List[dict[str, Any]] = []
        for filter_item in numeric_filters:
            suffix: str = filter_item["suffix"]
            value: Any = filter_item["value"]
            value_type: str = filter_item["value_type"]
            value_field = f"value_{value_type}"
            if suffix == "min":
                must_queries.append(
                    {
                        "nested": {
                            "path": "product.custom_attributes",
                            "query": {
                                "bool": {
                                    "must": [
                                        {"term": {"product.custom_attributes.name": filter_item["bare_name"]}},
                                        {"range": {f"product.custom_attributes.{value_field}": {"gte": value}}},
                                    ]
                                }
                            },
                            "score_mode": "max",
                        }
                    }
                )
            elif suffix == "max":
                must_queries.append(
                    {
                        "nested": {
                            "path": "product.custom_attributes",
                            "query": {
                                "bool": {
                                    "must": [
                                        {"term": {"product.custom_attributes.name": filter_item["bare_name"]}},
                                        {"range": {f"product.custom_attributes.{value_field}": {"lte": value}}},
                                    ]
                                }
                            },
                            "score_mode": "max",
                        }
                    }
                )

        query: dict[str, Any] = {
            "size": max_results,
            "query": {"bool": {"must": [{"terms": {"product.id": product_ids}}] + must_queries}},
            "_source": {
                "excludes": [
                    "product.product_vector",
                    "product.custom_attributes.vector",
                ]
            },
        }

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )
        docs = response["hits"]["hits"]
        scores: List[float] = [doc["_score"] for doc in docs]
        products: List[Product] = self._parse_ecommerce_part(
            docs,
            part_object=Product,
            part_name="product",
        )
        return products, scores

    async def search_products_by_custom_attributes_vector(
        self,
        ecommerce_identifier: str,
        attribute_vectors: Dict[str, List[float]],
        product_ids_filter: List[str],
        max_results: int = 10,
        min_score: float = 0.6,
    ) -> Tuple[List[Product], List[float]]:
        """Search products by custom attribute vectors in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            attribute_vectors: Dictionary of attribute vectors.
            product_ids_filter: List of product IDs to filter.
            max_results: Maximum number of results.
            min_score: Minimum score threshold.

        Returns:
            Tuple[List[Product], List[float]]: Products and their scores.
        """
        index_name = self.get_index_name(ecommerce_identifier)

        if not attribute_vectors:
            return [], []

        if not product_ids_filter:
            return [], []

        should_queries = []
        for attr_name, vector in attribute_vectors.items():
            should_queries.append(
                {
                    "nested": {
                        "path": "product.custom_attributes",
                        "query": {
                            "bool": {
                                "must": [
                                    {"term": {"product.custom_attributes.name": attr_name}},
                                    {
                                        "script_score": {
                                            "query": {"exists": {"field": "product.custom_attributes.vector"}},
                                            "script": {
                                                "source": """
                                                if (doc['product.custom_attributes.vector'].size() == 0) {
                                                    return 0.0;
                                                }
                                                return cosineSimilarity(params.query_vector, 'product.custom_attributes.vector');
                                            """,
                                                "params": {"query_vector": vector},
                                            },
                                        }
                                    },
                                ]
                            }
                        },
                        "score_mode": "max",
                    }
                }
            )

        query = {
            "size": max_results,
            "min_score": min_score,
            "_source": {
                "excludes": [
                    "product.product_vector",
                    "product.custom_attributes.vector",
                ]
            },
            "query": {
                "bool": {
                    "must": [{"terms": {"product.id": product_ids_filter}}],
                    "should": should_queries,
                    "minimum_should_match": 1,
                }
            },
        }

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )
        docs = response["hits"]["hits"]
        # TODO: doesn't need to return scores from these methods anymore
        scores = [d["_score"] for d in docs]
        products = self._parse_ecommerce_part(
            docs,
            part_object=Product,
            part_name="product",
        )
        return products, scores

    async def _construct_search_query(
        self,
        ecommerce_identifier: str,
        name: str,
        search_method: Literal["match", "fuzzy"] = "match",
        minimum_should_match: str = "67%",
        fuzziness: str | int = "AUTO",
        max_results: int = 10,
    ) -> dict[str, Any]:
        product_search_filters = None
        if self.collection_repository:
            collection_info = await self.collection_repository.get_collection_info_by_id(ecommerce_identifier)
            if collection_info is not None:
                product_search_filters = collection_info.product_search_filters

        if search_method == "match":
            query = {
                "query": {
                    "bool": {
                        "must": [
                            {
                                "match": {
                                    "product.name": {
                                        "query": name,
                                        "minimum_should_match": minimum_should_match,
                                    }
                                }
                            }
                        ],
                        "filter": [],
                    }
                },
                "size": max_results,
            }
        elif search_method == "fuzzy":
            query = {
                "query": {
                    "bool": {
                        "must": [
                            {
                                "fuzzy": {
                                    "product.name": {
                                        "value": name,
                                        "fuzziness": fuzziness,
                                    }
                                }
                            }
                        ],
                        "filter": [],
                    }
                },
                "size": max_results,
            }
        else:
            error_message = f"search_method {search_method} is not supported."
            LOGGER.error(error_message)
            raise Exception(error_message)

        if product_search_filters is None:
            return query

        for field in product_search_filters.get("exists", []):
            query["query"]["bool"]["filter"].append({"exists": {"field": field}})

        for field, value in product_search_filters.get("term", {}).items():
            query["query"]["bool"]["filter"].append({"term": {field: value}})

        for field, values in product_search_filters.get("terms", {}).items():
            if isinstance(values, list) and values:
                query["query"]["bool"]["filter"].append({"terms": {field: values}})

        for field, range_filter in product_search_filters.get("range", {}).items():
            query["query"]["bool"]["filter"].append({"range": {field: range_filter}})

        return query

    async def _construct_search_query_v2(
        self,
        ecommerce_identifier: str,
        name: str,
        minimum_should_match: str = "90%",
        fuzziness: str | int = 1,
        max_results: int = 10,
    ) -> dict[str, Any]:
        product_search_filters = None
        if self.collection_repository:
            collection_info = await self.collection_repository.get_collection_info_by_id(ecommerce_identifier)
            if collection_info is not None:
                product_search_filters = collection_info.product_search_filters

        query = {
            "size": max_results,
            "query": {
                "bool": {
                    "should": [
                        {
                            "multi_match": {
                                "_name": "exact",
                                "query": name,
                                "fields": [
                                    "product.name^5",
                                    "product.short_description",
                                    "product.description",
                                ],
                                "operator": "and",
                                "minimum_should_match": minimum_should_match,
                                "boost": 5,
                            }
                        },
                        {
                            "fuzzy": {
                                "product.name": {
                                    "value": name,
                                    "fuzziness": fuzziness,
                                    "_name": "fuzzy",
                                    "boost": 6,
                                    "prefix_length": 1,
                                }
                            }
                        },
                        {
                            "fuzzy": {
                                "product.short_description": {
                                    "value": name,
                                    "fuzziness": fuzziness,
                                    "_name": "fuzzy_s_desc",
                                    "boost": 3,
                                    "prefix_length": 1,
                                }
                            }
                        },
                        {
                            "nested": {
                                "_name": "categories",
                                "boost": 1,
                                "path": "product.categories",
                                "query": {
                                    "match": {
                                        "product.categories.name": {
                                            "query": name,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                        {
                            "nested": {
                                "_name": "tags",
                                "boost": 1,
                                "path": "product.tags",
                                "query": {
                                    "match": {
                                        "product.tags.name": {
                                            "query": name,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                    ],
                    "minimum_should_match": 1,
                    "filter": [],
                }
            },
        }

        if product_search_filters is None:
            return query

        for field in product_search_filters.get("exists", []):
            query["query"]["bool"]["filter"].append({"exists": {"field": field}})

        for field, value in product_search_filters.get("term", {}).items():
            query["query"]["bool"]["filter"].append({"term": {field: value}})

        for field, values in product_search_filters.get("terms", {}).items():
            if isinstance(values, list) and values:
                query["query"]["bool"]["filter"].append({"terms": {field: values}})

        for field, range_filter in product_search_filters.get("range", {}).items():
            query["query"]["bool"]["filter"].append({"range": {field: range_filter}})

        return query

    async def filter_products_by_float_range_custom_attributes(
        self,
        ecommerce_identifier: str,
        float_range_filters: List[dict[str, Any]],
        product_ids: List[str],
        max_results: int = 20,
    ) -> Tuple[List[Product], List[float]]:
        """Filter products by float_range custom attributes in the ecommerce index.

        Args:
            ecommerce_identifier: Unique identifier for the ecommerce instance.
            float_range_filters: List of dicts, each with 'bare_name' and 'range' dict (with 'gte'/'lte').
            product_ids: List of product IDs.
            max_results: Maximum number of results.

        Returns:
            Tuple[List[Product], List[float]]: Filtered products and their scores.
        """
        index_name: str = self.get_index_name(ecommerce_identifier)
        must_queries: List[dict[str, Any]] = []
        for filter_item in float_range_filters:
            bare_name: str = filter_item["bare_name"]
            range_query: dict[str, float] = filter_item.get("range", {})
            if not range_query:
                continue
            must_queries.append(
                {
                    "nested": {
                        "path": "product.custom_attributes",
                        "query": {
                            "bool": {
                                "must": [
                                    {"term": {"product.custom_attributes.name": bare_name}},
                                    {"range": {"product.custom_attributes.value_float_range": range_query}},
                                ]
                            }
                        },
                        "score_mode": "max",
                    }
                }
            )
        query: dict[str, Any] = {
            "size": max_results,
            "query": {"bool": {"must": [{"terms": {"product.id": product_ids}}] + must_queries}},
            "_source": {
                "excludes": [
                    "product.product_vector",
                    "product.custom_attributes.vector",
                ]
            },
        }
        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )
        docs = response["hits"]["hits"]
        scores: List[float] = [doc["_score"] for doc in docs]
        products: List[Product] = self._parse_ecommerce_part(
            docs,
            part_object=Product,
            part_name="product",
        )
        return products, scores

