    def safe_json(self, obj):
        # Recursively convert JSON strings to dicts if needed
        if isinstance(obj, str):
            try:
                return json.loads(obj)
            except Exception:
                return obj
        else:
            return obj

    async def add_chain_call(
        self,
        chain_calls: List[ChainCall],
        bulk_size: int = 1000,
    ):
        actions = [
            {
                "_op_type": "index",
                "_index": self.index_name,
                "_id": f"{self.chain_calls_prefix}{get_current_utc_time()}",
                "_source": {"chain_calls": self.safe_json(chain_call.model_dump(mode="json"))},
            }
            for chain_call in chain_calls
        ]

        for i in range(0, len(actions), bulk_size):
            actions = actions[i : i + bulk_size]
            try:
                await async_bulk(
                    self.elastic_search_repository,
                    actions,
                    refresh="wait_for",
                )
            except Exception as e:
                LOGGER.error(
                    f"unable to add chain call batch {i // bulk_size + 1} to {self.index_name}: {e}",
                )
                raise RuntimeError(
                    "error adding chain call to %s" % self.index_name,
                )

