    async def get_inference_results_by_id(self, trace_ids: List[str], batch_size: int = 100) -> List[InferenceResult]:
        """Get inference results by trace IDs using batch processing and scroll pagination.

        Args:
            trace_ids: List of trace IDs to search for.
            batch_size: Number of trace IDs to process in each batch.

        Returns:
            A list of InferenceResult objects matching the trace IDs.
        """
        if not trace_ids:
            return []

        part_name = "inference_results"
        part_object = self.index_mapping[part_name]
        all_results = []

        # Process trace IDs in batches
        for i in range(0, len(trace_ids), batch_size):
            batch_trace_ids = trace_ids[i : i + batch_size]

            query = {"query": {"bool": {"must": [{"terms": {"inference_results.trace_id": batch_trace_ids}}]}}}

            try:
                response = await self.elastic_search_repository.search(
                    index=self.index_name,
                    body=query,
                    scroll="2m",
                    size=10000,
                )

                batch_docs = []
                batch_docs.extend(response["hits"]["hits"])

                scroll_id = response["_scroll_id"]

                while len(response["hits"]["hits"]) > 0:
                    response = await self.elastic_search_repository.scroll(
                        scroll_id=scroll_id,
                        scroll="2m",
                    )
                    batch_docs.extend(response["hits"]["hits"])
                    scroll_id = response["_scroll_id"]

                batch_results = self._parse_collection_part(
                    batch_docs,
                    part_object=part_object,
                    part_name=part_name,
                )

                all_results.extend(batch_results)

                await self.elastic_search_repository.clear_scroll(scroll_id=scroll_id)

            except Exception as e:
                LOGGER.error(f"Error processing batch {i // batch_size + 1} for inference results: {e}")
                continue

        return all_results

