    @staticmethod
    def _parse_collection_part(
        documents: dict,
        part_object: Any,
        part_name: str,
    ) -> list:
        data = []
        for doc in documents:
            _source = doc["_source"]
            data.append(part_object(**_source[part_name]))
        return data

    def _parse_documents(self, documents: dict):
        mapping = {
            "traces": [],
            "chain_calls": [],
            "inference_results": [],
            "training_results": [],
        }

        for doc in documents:
            _source = doc["_source"]
            for key, _ in _source.items():
                try:
                    mapping[key].append(
                        self.index_mapping[key](**_source[key]),
                    )
                except Exception as e:
                    LOGGER.error(
                        f"Failed to parse Logs {key}. doc = {_source}, exception = {e}",
                    )
                    raise exceptions.ElasticDocumentParserException(
                        detail="Logs = %s, doc = %s" % (key, _source),
                    ) from e

        return Logs(
            traces=mapping["traces"],
            chain_calls=mapping["chain_calls"],
            inference_results=mapping["inference_results"],
            training_results=mapping["training_results"],
        )

