    async def delete_logs_older_than_days(self, days: int = 50) -> None:
        """Delete logs older than the specified number of days.

        Args:
            days: Number of days to keep logs for (default 50).
                Logs older than this will be deleted.

        Returns:
            None

        Raises:
            RuntimeError: If there is an error during deletion process.
        """
        try:
            # Calculate the threshold date
            days = 70
            threshold_date = (datetime.utcnow() - timedelta(days=days)).isoformat()
            LOGGER.info(f"Deleting logs older than {threshold_date}")

            #     query = {"query": {"term": {"traces.trace_id": {"value": trace_id}}}}
            # response = await self.elastic_search_repository.search(
            #     index=self.index_name,
            #     body=query,
            #     size=10000,
            # )

            # First, identify all trace IDs older than the threshold
            query = {
                "query": {"range": {"traces.created_at": {"lt": threshold_date}}},
                "_source": ["traces.trace_id"],
            }

            # Get matching trace IDs
            response = await self.elastic_search_repository.search(index=self.index_name, body=query, size=10000)

            trace_documents = response["hits"]["hits"]
            old_trace_ids = []

            for doc in trace_documents:
                try:
                    # Extract trace ID from each document
                    trace_id = doc["_source"]["traces"]["trace_id"]
                    old_trace_ids.append(trace_id)
                except KeyError:
                    continue

            if not old_trace_ids:
                LOGGER.info(f"No logs found older than {days} days.")
                return

            LOGGER.info(f"Found {len(old_trace_ids)} trace IDs to delete.")

            # Delete documents with matching trace IDs
            total_deleted = 0

            # 1. Delete traces with matching trace_id
            trace_delete_query = {"query": {"terms": {"traces.trace_id": old_trace_ids}}}
            trace_response = await self.elastic_search_repository.delete_by_query(
                index=self.index_name, body=trace_delete_query, refresh=True
            )
            trace_deleted = trace_response.get("deleted", 0)

            # 2. Delete chain_calls with matching trace_id
            chain_delete_query = {"query": {"terms": {"chain_call.trace_id": old_trace_ids}}}
            chain_response = await self.elastic_search_repository.delete_by_query(
                index=self.index_name, body=chain_delete_query, refresh=True
            )
            chain_deleted = chain_response.get("deleted", 0)

            # 3. Delete inference_results with matching trace_id
            inference_delete_query = {"query": {"terms": {"inference_results.trace_id": old_trace_ids}}}
            inference_response = await self.elastic_search_repository.delete_by_query(
                index=self.index_name, body=inference_delete_query, refresh=True
            )
            inference_deleted = inference_response.get("deleted", 0)

            # 4. Delete training_results with matching trace_id
            training_delete_query = {"query": {"terms": {"training_results.trace_id": old_trace_ids}}}
            training_response = await self.elastic_search_repository.delete_by_query(
                index=self.index_name, body=training_delete_query, refresh=True
            )
            training_deleted = training_response.get("deleted", 0)

            total_deleted = trace_deleted + chain_deleted + inference_deleted + training_deleted

            LOGGER.info(
                f"Deleted logs older than {days} days. "
                f"Total deleted: {total_deleted} documents "
                f"(Traces: {trace_deleted}, Chain calls: {chain_deleted}, "
                f"Inference results: {inference_deleted}, Training results: {training_deleted})"
            )

        except Exception as e:
            LOGGER.error(f"Error deleting old logs: {e}")
            raise RuntimeError("Failed to delete old logs") from e

    async def get_inferences_by_specific_chain_output(
        self, collection_identifier: str, desired_output: Any
    ) -> List[InferenceResult]:
        query = {"query": {"term": {"traces.collection_identifier": {"value": collection_identifier}}}}
        response = await self.elastic_search_repository.search(
            index=self.index_name,
            body=query,
            size=2000,
        )
        traces = self._parse_collection_part(
            response["hits"]["hits"],
            part_object=Trace,
            part_name="traces",
        )

        chain_calls = await self.get_chain_calls_by_id([trace.trace_id for trace in traces])
        filtered_traces = []

        for chain_call in chain_calls:
            if desired_output in chain_call.output_data.values():
                filtered_traces.append(chain_call.trace_id)

        inference_results = await self.get_inference_results_by_id(filtered_traces)

        return inference_results

