        self,
        start_date: str,
        end_date: str,
        collection_identifier: str | None = None,
    ) -> List[Trace]:
        """Get traces within a time window and optionally filtered by collection.

        Args:
            start_date: Start date in ISO 8601 format.
            end_date: End date in ISO 8601 format.
            collection_identifier: Optional collection identifier to filter by.

        Returns:
            A list of Trace objects matching the criteria.

        Raises:
            ValueError: If date format is invalid.
            RuntimeError: If there is an error during the query.
        """
        try:
            query_filters = [{"range": {"traces.created_at": {"gte": start_date, "lte": end_date}}}]

            if collection_identifier is not None:
                query_filters.append({"term": {"traces.collection_identifier": {"value": collection_identifier}}})

            query = {"query": {"bool": {"must": query_filters}}}

            response = await self.elastic_search_repository.search(
                index=self.index_name,
                body=query,
                scroll="2m",
                size=2000,
            )

            all_docs = []
            all_docs.extend(response["hits"]["hits"])

            scroll_id = response["_scroll_id"]

            while len(response["hits"]["hits"]) > 0:
                response = await self.elastic_search_repository.scroll(
                    scroll_id=scroll_id,
                    scroll="2m",
                )
                all_docs.extend(response["hits"]["hits"])
                scroll_id = response["_scroll_id"]

            traces = self._parse_collection_part(
                all_docs,
                part_object=Trace,
                part_name="traces",
            )

            await self.elastic_search_repository.clear_scroll(scroll_id=scroll_id)

            return traces

        except Exception as e:
            LOGGER.error(f"Error querying traces by time window: {e}")
            raise RuntimeError(f"Failed to query traces by time window: {str(e)}") from e

