    async def create_index(self, collection_record: CollectionRecord) -> Any:
        index_name = self.get_index_name(collection_record.identifier)
        if not await self.collection_exists(index_name):
            try:
                await self.elastic_search_repository.indices.create(
                    index=index_name,
                    body=self.mappings,
                )
                collection_info = CollectionInfo(
                    id=collection_record.id,
                    user_id=collection_record.user_id,
                    name=collection_record.name,
                    identifier=collection_record.identifier,
                    created_at=collection_record.created_at,
                    updated_at=collection_record.created_at,
                )
                await self.add_collection_info_to_collection(
                    collection_identifier=collection_record.identifier,
                    collection_info=collection_info,
                )
            except Exception as e:
                LOGGER.error(
                    f"Error creating index {index_name} for collection_models {collection_record.identifier}: {e}",
                )
                raise Exception(f"Failed to create index {index_name}") from e
        else:
            LOGGER.warning(
                "collection_models %s already exists" % collection_record.identifier,
            )
            raise exceptions.CollectionExists(
                detail="collection_identifier = %s" % collection_record.identifier,
            )

    async def collection_exists(self, index_name: str) -> bool:
        return await self.elastic_search_repository.indices.exists(index=index_name)

    async def update_collection(self, collection: Collection):
        # TODO: use try except?
        identifier = collection.collection_info.identifier
        index_name = self.get_index_name(identifier)
        if await self.collection_exists(index_name):
            LOGGER.debug("chunk")
            await self.add_chunk_data_to_collection(identifier, collection.chunks)

            LOGGER.debug("child chunk")
            await self.add_child_chunk_to_collection(
                identifier,
                collection.child_chunks,
            )

            LOGGER.debug("summary")
            await self.add_summary_data_to_collection(
                identifier,
                collection.data_summaries,
            )

            LOGGER.debug("child summary")
            await self.add_child_summaries_to_collection(
                identifier,
                collection.child_summaries,
            )

            LOGGER.debug("faq")
            await self.add_faqs_to_collection(identifier, collection.faqs)

            LOGGER.debug("heading")
            await self.add_headings_to_collection(identifier, collection.headings)

            LOGGER.debug("reference file")
            await self.add_reference_data_to_collection(
                identifier,
                collection.reference_datum,
            )

            LOGGER.debug("info")
            await self.add_collection_info_to_collection(
