    async def add_collection_info_to_collection(
        self,
        collection_identifier: str,
        collection_info: CollectionInfo,
        version_up: bool = False,
    ):
        index_name = self.get_index_name(collection_identifier)
        try:
            if version_up:
                # add version to the current collection info
                collection_infos = await self._get_collection_part_by_id(
                    collection_identifier,
                    "collection_info",
                )

                if len(collection_infos) >= 1:
                    current_collection_info = [
                        collection_info for collection_info in collection_infos if len(collection_info.identifier) == 32
                    ][0]
                    current_collection_info.identifier = (
                        f"v{len(collection_infos)}_{current_collection_info.identifier}"
                    )
                    ref_file = {"collection_info": current_collection_info.model_dump()}
                    await self.elastic_search_repository.index(
                        index=index_name,
                        id=f"v{len(collection_infos)}_{self.collection_info_prefix}{collection_info.identifier}",
                        document=ref_file,
                        refresh="wait_for",
                    )
            # add new collection info
            ref_file = {"collection_info": collection_info.model_dump()}
            await self.elastic_search_repository.index(
                index=index_name,
                id=f"{self.collection_info_prefix}{collection_info.identifier}",
                document=ref_file,
                refresh="wait_for",
            )
        except Exception as e:
            LOGGER.error(
                f"unable to add collection_info {collection_info.identifier} to {index_name}: {e}",
            )
            raise exceptions.CollectionInfoAdditionError(
                detail="unable to add collection_info to %s" % index_name,
            )

