        self,
        collection_identifier: str,
        reference_datum: List[ReferenceData],
        bulk_size: int = 1000,
    ):
        index_name = self.get_index_name(collection_identifier)
        actions = [
            {
                "_op_type": "index",
                "_index": index_name,
                "_id": f"{self.reference_data_prefix}{reference.id}",
                "_source": {"reference_datum": reference.model_dump()},
            }
            for reference in reference_datum
        ]

        for i in range(0, len(actions), bulk_size):
            reference_actions = actions[i : i + bulk_size]
            try:
                await async_bulk(
                    self.elastic_search_repository,
                    reference_actions,
                    refresh="wait_for",
                )
            except Exception as e:
                LOGGER.error(
                    f"unable to add reference data batch {i // bulk_size + 1} to {index_name}: {e}",
