    async def update_faq(
        self,
        collection_identifier: str,
        faq_id: int,
        question: Optional[str] = None,
        answer: Optional[str] = None,
    ) -> None:
        index_name = self.get_index_name(collection_identifier)
        doc_id = self._get_faq_id_name(faq_id)

        script_parts = []
        params = {}

        if question is not None:
            script_parts.append("ctx._source.faqs.question = params.question")
            params["question"] = question

        if answer is not None:
            script_parts.append("ctx._source.faqs.answer = params.answer")
            params["answer"] = answer

        if not script_parts:
            return

        script = {"script": {"source": "; ".join(script_parts), "params": params}}

        try:
            await self.elastic_search_repository.update(index=index_name, id=doc_id, body=script, refresh="wait_for")
        except Exception as e:
            LOGGER.error(f"Failed to update FAQ {faq_id} in collection {collection_identifier}: {e}")
            raise exceptions.ReferenceDataAdditionError(detail=f"Failed to update FAQ {faq_id}")

