    async def delete_reference_data_from_collection(
        self,
        collection_identifier: str,
        reference_data_ids: List[str],
    ):
        tasks = []
        for identifier in reference_data_ids:
            tasks.append(
                self.delete_single_reference_data_from_collection(
                    collection_identifier,
                    identifier,
                ),
            )
        reference_datum = await asyncio.gather(*tasks, return_exceptions=True)

        collection_info = await self.get_collection_info_by_id(
            collection_identifier=collection_identifier,
        )

        errors = {}
        for reference_data, identifier in zip(
            reference_datum,
            reference_data_ids,
        ):
            if not isinstance(reference_data, ReferenceData):
                errors[identifier] = reference_data
                continue
            collection_info.num_data -= 1
            collection_info.total_num_words -= reference_data.num_words
            collection_info.total_num_characters -= reference_data.num_characters

        if any(errors.items()):
            LOGGER.error(
                ("Unexpected error happend during deleting" " reference datum %s from collection_models %s : %s")
                % (reference_data_ids, collection_identifier, errors),
            )
            raise exceptions.ReferenceDataDeletionError(
                detail="reference datum identifiers: %s , collection_models identifiers: %s"
                % (reference_data_ids, collection_identifier),
            )

        await self.add_collection_info_to_collection(
            collection_identifier,
            collection_info,
        )

    async def delete_single_reference_data_from_collection(
        self,
        collection_identifier: str,
        identifier: str,
    ) -> ReferenceData:
        index_name = self.get_index_name(collection_identifier)
        doc_type = "reference_data_models"
        reference_data_id = self._get_reference_data_id_name(identifier)
        reference_data = await self.get_document_by_id(
            index_name=index_name,
            doc_id=reference_data_id,
        )

        chunk_ids = reference_data.chunk_ids

        if chunk_ids is not None:
            LOGGER.debug(
                f"deleting child summaries for reference data identifier: {identifier}",
            )
            await self.delete_child_summaries_from_collection_by_chunk_ids(
                chunk_ids,
                collection_identifier,
                index_name,
            )
            LOGGER.debug(f"deleting summaries for reference data identifier: {identifier}")
            await self.delete_data_summaries_from_collection_by_chunk_ids(
                chunk_ids,
                collection_identifier,
                index_name,
            )
            LOGGER.debug(f"deleting headings for reference data identifier: {identifier}")
            await self.delete_headings_from_collection_by_chunk_ids(
                chunk_ids,
                collection_identifier,
                index_name,
            )
            LOGGER.debug(f"deleting faqs for reference data identifier: {identifier}")
            await self.delete_faqs_from_collection_by_chunk_ids(
                chunk_ids,
                collection_identifier,
                index_name,
            )
            # get chunk_ids from the self. find_chunks_by_reference_data_id method
            chunk_ids = await self.find_chunks_by_reference_data_id(
                collection_identifier,
                identifier,
            )
            LOGGER.debug(
                f"deleting child chunks for reference data identifier: {identifier}",
            )
            await self.delete_child_chunks_from_collection_by_chunk_ids(
                chunk_ids,
                collection_identifier,
                index_name,
            )
            LOGGER.debug(f"deleting chunks for reference data identifier: {identifier}")
            await self.delete_chunks_from_collection(
                collection_identifier=collection_identifier,
                chunk_ids=chunk_ids,
            )

            LOGGER.debug(f"deleting reference data with identifier: {identifier}")
            await self._delete_doc_from_collection(
                collection_identifier,
                doc_type,
                [reference_data_id],
                index_name,
            )

        return reference_data

