    async def delete_child_summaries_from_parent_id(
        self,
        collection_identifier: str,
        parent_id: int | list,
    ) -> None:
        index_name = self.get_index_name(collection_identifier)
        query = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "term": {
                                "child_summaries.parent_id": parent_id[0] if isinstance(parent_id, list) else parent_id
                            }
                        }
                    ]
                }
            }
        }

        try:
            # First find all child summaries with the given parent_id
            response = await self.elastic_search_repository.search(
                index=index_name,
                body=query,
                size=10000,
            )

            # Extract the IDs and format them for deletion
            child_summary_ids = [hit["_source"]["child_summaries"]["id"] for hit in response["hits"]["hits"]]

            if child_summary_ids:
                # Convert IDs to document IDs format
                doc_ids = [self._get_child_summary_id_name(id) for id in child_summary_ids]

                # Delete the child summaries
                await self._delete_doc_from_collection(
                    collection_identifier=collection_identifier,
                    doc_type="child_summary",
                    doc_ids=doc_ids,
                    index_name=index_name,
                )
        except Exception as e:
            LOGGER.warning(f"Error deleting child summaries for parent_id {parent_id}: {e}")

