    async def get_collection_by_id(
        self,
        collection_identifier: str,
        return_vectors=True,
    ) -> Collection:
        index_name = self.get_index_name(collection_identifier)
        query = {"query": {"match_all": {}}}
        if not return_vectors:
            excludes = [field for fields in self.part_vector_field_mapping.values() for field in fields]
            query["_source"] = {"excludes": excludes}

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
            scroll="2m",
            size=10000,
        )

        all_docs = []
        all_docs.extend(response["hits"]["hits"])

        scroll_id = response["_scroll_id"]

        while len(response["hits"]["hits"]) > 0:
            response = await self.elastic_search_repository.scroll(
                scroll_id=scroll_id,
                scroll="2m",
            )
            all_docs.extend(response["hits"]["hits"])
            scroll_id = response["_scroll_id"]

        collection = self._parse_documents(all_docs)

        await self.elastic_search_repository.clear_scroll(scroll_id=scroll_id)

        return collection

