    async def get_summaries_by_type(
        self,
        collection_identifier: str,
        summary_type: str,
        return_vectors: bool = True,
    ) -> List[Summary]:
        """
        Get summaries from a collection filtered by type.

        Args:
            collection_identifier: The collection identifier
            summary_type: The type of summaries to retrieve ("chunk", "heading", "main", "prompt")
            return_vectors: Whether to include vector embeddings in the response

        Returns:
            List of summaries matching the specified type
        """
        part_name = "data_summaries"
        part_object = self.collection_parts_mapping[part_name]
        index_name = self.get_index_name(collection_identifier)

        # Build Elasticsearch query to filter by type
        query = {
            "query": {
                "bool": {
                    "must": [{"exists": {"field": "data_summaries"}}, {"term": {"data_summaries.type": summary_type}}]
                }
            },
            "size": 10000,
        }

        # Exclude vectors if not needed
        if not return_vectors:
            query["_source"] = {"excludes": ["data_summaries.vector"]}

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
        )

        response = response["hits"]["hits"]
        parts = self._parse_collection_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )
        return parts

