    async def get_collection_info_by_id(self, collection_identifier: str, version: int = 0) -> CollectionInfo:
        try:
            LOGGER.debug(f"getting collection info for {collection_identifier}...")
            result = await self._get_collection_part_by_id(
                collection_identifier,
                "collection_info",
            )
            if version == -1:
                version = len(result) - 1
            for collection_info in result:
                if (version == 0 and len(collection_info.identifier) == 32) or (
                    collection_info.identifier.startswith(f"v{version}_")
                ):
                    return collection_info
        except Exception as e:
            LOGGER.error(
                "cannot load collection info for identifier %s correctly! Error: %s" % (collection_identifier, e)
            )

