    async def knn_search(
        self,
        collection_identifier: str,
        embeddings: List[int],
        part_name: str,
        k: int,
    ) -> List[Any]:
        part_object = self.collection_parts_mapping[part_name]
        index_name = self.get_index_name(collection_identifier)
        vector_fields = self.part_vector_field_mapping.get(part_name)
        if vector_fields:
            vector_field = vector_fields[0]
        else:
            raise RuntimeError(
                "Part %s does not contain vector field. So, cannot be used for knn search!" % part_name,
            )
        query = {
            "knn": {
                "field": f"{vector_field}",
                "filter": [],
                "k": k,
                "num_candidates": 50,
                "query_vector": embeddings,
            },
        }
        try:
            response = await self.elastic_search_repository.search(
                index=index_name,
                body=query,
                size=k,
            )
        except Exception as e:
            LOGGER.error(
                f"Failed to perform KNN search on {index_name} (Maybe no FAQ yet!). Old_FAQ : []\n {e}",
            )
            return []
        response = response["hits"]["hits"]
        parts = self._parse_collection_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )
        return parts

