    @staticmethod
    def _parse_collection_part(
        documents: dict,
        part_object: Any,
        part_name: str,
    ) -> list:
        data = []
        for doc in documents:
            _source = doc["_source"]
            data.append(part_object(**_source[part_name]))
        return data

    def _parse_documents(self, documents: dict):
        mapping = {
            "collection_info": None,
            "reference_datum": [],
            "chunks": [],
            "child_chunks": [],
            "faqs": [],
            "data_summaries": [],
            "child_summaries": [],
            "headings": [],
        }

        for doc in documents:
            _source = doc["_source"]
            for key, _ in _source.items():
                try:
                    if key == "collection_info":
                        if len(_source[key]["identifier"]) == 32:
                            mapping[key] = CollectionInfo(**_source[key])
                    else:
                        mapping[key].append(
                            self.collection_parts_mapping[key](**_source[key]),
                        )
                except Exception as e:
                    LOGGER.error(
                        f"Failed to parse collection_models {key}. doc = {_source}, exception = {e}",
                    )
                    raise exceptions.ElasticDocumentParserException(
                        detail="collection_models = %s, doc = %s" % (key, _source),
                    ) from e

        return Collection(
            collection_info=mapping["collection_info"],
            reference_datum=mapping["reference_datum"],
            headings=mapping["headings"],
            chunks=mapping["chunks"],
            child_chunks=mapping["child_chunks"],
            faqs=mapping["faqs"],
            data_summaries=mapping["data_summaries"],
            child_summaries=mapping["child_summaries"],
        )

    async def _delete_doc_from_collection(
        self,
        collection_identifier: str,
        doc_type: str,
        doc_ids: List[str],
        index_name: str,
        bulk_size: int = 1000,
    ):
        actions = [{"_op_type": "delete", "_index": index_name, "_id": doc_id} for doc_id in doc_ids]
        for i in range(0, len(actions), bulk_size):
            batch_number = i // bulk_size + 1
            bulk_actions = actions[i : i + bulk_size]

            try:
                await async_bulk(
                    self.elastic_search_repository,
                    bulk_actions,
                    refresh="wait_for",
                )

            except BulkIndexError as bulk_error:
                for error in bulk_error.errors:
                    if error["delete"]["result"] == "not_found":
                        LOGGER.warning("Document not found for deletion: %s" % error["delete"]["_id"])
                    else:
                        LOGGER.error("BulkIndexError in deleting document: %s" % error)
                        raise RuntimeError(
                            "BulkIndexError: doc type: %s batch: %s collection_identifier: %s"
                            % (doc_type, batch_number, collection_identifier),
                        )

            except Exception as e:
                LOGGER.error(
                    "unable to delete %s batch %s from %s collection_models: %s"
                    % (doc_type, batch_number, collection_identifier, e),
                )
                raise RuntimeError(
                    "doc type: %s batch: %s collection_identifier: %s"
                    % (doc_type, batch_number, collection_identifier),
                ) from e

