class SpeechRepository:
    db_type = "elasticsearch"

    def __init__(
        self, 
        settings: ElasticSearchSettings,
        elastic_search_connection: ElasticSearchConnectionInterface
    ):
        self.settings = settings
        self.elastic_search_repository = elastic_search_connection.async_client
        self.sync_elasticsearch_repository = elastic_search_connection.sync_client
        self.index_prefix = "speech_"
        self.collection_info_prefix = "collection_info_"
        self.operators_prefix = "operator_"
        self.shots_prefix = "shot_"
        self.mappings = {
            "mappings": {
                "properties": {
                    "collection_info": {
                        "properties": {
                            "name": {"type": "text"},
                            "title": {"type": "text"},
                            "identifier": {"type": "keyword"},
                            "created_at": {"type": "date"},
                            "language": {"type": "keyword"},
                            "updated_at": {"type": "date"},
                        },
                    },
                    "operators": {
                        "properties": {
                            "name": {"type": "keyword"},
                            "id": {"type": "long"},
                            "phone_number": {"type": "long"},
                            "information": {"type": "text"},
                        },
                    },
                    "shots": {
                        "properties": {
                            "id": {"type": "long"},
                            "text": {"type": "text"},
                            "operator_id": {"type": "long"},
                            "vector": {
                                "type": "dense_vector",
                                "index": True,
                            },
                        },
                    },
                },
            },
        }

        self.collection_parts_mapping = {
            "collection_info": SpeechCollectionInfo,
            "operators": Operator,
            "shots": Shot,
        }

    async def close(self):
        """Close the Elasticsearch connection.

        Note: Connection management is handled by ElasticSearchConnection.
        """
        pass

    async def create_index(self, collection_record: Dict) -> Any:
        index_name = self.get_index_name(collection_record["identifier"])
        if not await self.collection_exists(index_name):
            try:
                await self.elastic_search_repository.indices.create(
                    index=index_name,
                    body=self.mappings,
                )
                collection_info = SpeechCollectionInfo(
                    name=collection_record["name"],
                    title=collection_record["title"],
                    language=collection_record["language"],
                    identifier=collection_record["identifier"],
                    created_at=collection_record.get("created_at"),
                    updated_at=collection_record.get("updated_at"),
                )
                await self.add_collection_info_to_collection(
                    collection_identifier=collection_record["identifier"],
                    collection_info=collection_info,
                )
            except Exception as e:
                LOGGER.error(
                    f"Error creating index {index_name} for collection_models {collection_record['identifier']}: {e}",
                )
                raise Exception(f"Failed to create index {index_name}") from e
        else:
            LOGGER.warning(
                "collection_models %s already exists" % collection_record["identifier"],
            )
            raise exceptions.CollectionExists(
                detail="collection_identifier = %s" % collection_record["identifier"],
            )

    async def collection_exists(self, index_name: str) -> bool:
        return await self.elastic_search_repository.indices.exists(index=index_name)

    async def update_collection(self, collection: SpeechCollection):
        # TODO: use try except?
        identifier = collection.collection_info.identifier
        index_name = self.get_index_name(identifier)
        if await self.collection_exists(index_name):
            LOGGER.debug("info")
            await self.add_collection_info_to_collection(
                identifier,
                collection.collection_info,
            )
            LOGGER.debug("reference file")

            await self.add_reference_data_to_collection(
                identifier,
                collection.reference_datum,
            )
            LOGGER.debug("chunk")

            await self.add_chunk_data_to_collection(identifier, collection.chunks)
            LOGGER.debug("summary")

            await self.add_summary_data_to_collection(
                identifier,
                collection.data_summaries,
            )
            LOGGER.debug("child sumary")

            await self.add_child_summaries_to_collection(
                identifier,
                collection.child_summaries,
            )
            LOGGER.debug("faq")

            await self.add_faqs_to_collection(identifier, collection.faqs)
            LOGGER.debug("heading")

            await self.add_headings_to_collection(identifier, collection.headings)
        else:
            raise exceptions.CollectionNotExists(
                detail="Collection %s does not exist" % identifier,
            )

    async def add_collection_info_to_collection(
        self,
        collection_identifier: str,
        collection_info: SpeechCollectionInfo,
    ):
        index_name = self.get_index_name(collection_identifier)
        try:
            ref_file = {"collection_info": collection_info.model_dump()}
            await self.elastic_search_repository.index(
                index=index_name,
                id=f"{self.collection_info_prefix}{collection_info.identifier}",
                document=ref_file,
                refresh="wait_for",
            )
        except Exception as e:
            LOGGER.error(
                f"unable to add collection_info {collection_info.identifier} to {index_name}: {e}",
            )
            raise exceptions.CollectionInfoAdditionError(
                detail="unable to add collection_info to %s" % index_name,
            )

    async def add_operators_to_collection(
        self,
        collection_identifier: str,
        operators: List[Operator],
        bulk_size: int = 1000,
    ):
        index_name = self.get_index_name(collection_identifier)
        actions = [
            {
                "_op_type": "index",
                "_index": index_name,
                "_id": f"{self.operators_prefix}{operator.id}",
                "_source": {"operators": operator.model_dump()},
            }
            for operator in operators
        ]

        for i in range(0, len(actions), bulk_size):
            bulk_actions = actions[i : i + bulk_size]
            try:
                await async_bulk(
                    self.elastic_search_repository,
                    bulk_actions,
                    refresh="wait_for",
                )
                LOGGER.debug(f"Added operators batch {i // bulk_size + 1}")
            except Exception as e:
                LOGGER.error(
                    f"unable to add operators batch {i // bulk_size + 1} to {index_name}: {e}",
                )
                raise RuntimeError(
                    detail="error adding operators to %s" % index_name,
                )

    async def add_shots_to_collection(
        self,
        collection_identifier: str,
        shots: List[Shot],
        bulk_size: int = 1000,
    ):
        index_name = self.get_index_name(collection_identifier)
        actions = [
            {
                "_op_type": "index",
                "_index": index_name,
                "_id": f"{self.shots_prefix}{shot.id}",
                "_source": {"shots": shot.model_dump()},
            }
            for shot in shots
        ]

        for i in range(0, len(actions), bulk_size):
            bulk_actions = actions[i : i + bulk_size]
            try:
                await async_bulk(
                    self.elastic_search_repository,
                    bulk_actions,
                    refresh="wait_for",
                )
                LOGGER.debug(f"Added shot batch {i // bulk_size + 1}")
            except Exception as e:
                LOGGER.error(
                    f"unable to add shot batch {i // bulk_size + 1} to {index_name}: {e}",
                )

    async def delete_collection_by_index_name(self, index_name: str):
        try:
            await self.elastic_search_repository.options().indices.delete(
                index=index_name,
            )
            LOGGER.info(
                f"Successfully deleted {index_name} Index from elasticsearch db",
            )
        except NotFoundError:
            LOGGER.error(f"there is no such collection_models. {index_name} not found!")
            raise exceptions.CollectionDeletionError(
                detail=f"there is no such collection_models. {index_name} not found!",
            )
        except Exception as e:
            LOGGER.error(f"unable to delete collection_models {index_name}: {e}")
            raise exceptions.CollectionDeletionError(
                detail=f"unable to delete collection_models {index_name}: {e}",
            )

    async def delete_operators_from_collection(
        self,
        operators: List[Operator],
        collection_identifier: str,
    ):
        index_name = self.get_index_name(collection_identifier)
        operators_ids = [
            self._get_operator_id_name(operator.id) for operator in operators
        ]
        await self._delete_doc_from_collection(
            collection_identifier=collection_identifier,
            doc_type="operators",
            index_name=index_name,
            doc_ids=operators_ids,
        )

    async def delete_shots_from_collection(
        self,
        shots: List[Shot],
        collection_identifier: str,
    ):
        index_name = self.get_index_name(collection_identifier)
        shots_ids = [self._get_shot_id_name(shot.id) for shot in shots]
        await self._delete_doc_from_collection(
            collection_identifier=collection_identifier,
            doc_type="shots",
            index_name=index_name,
            doc_ids=shots_ids,
        )

    async def get_collection_by_id(
        self,
        collection_identifier: str,
    ) -> SpeechCollection:
        index_name = self.get_index_name(collection_identifier)
        query = {"query": {"match_all": {}}}

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
            size=10000,
        )
        response = response["hits"]["hits"]
        collection = self._parse_documents(response)
        return collection

    async def get_all_collections_identifiers(self) -> List[str]:
        all_indices = await self.elastic_search_repository.indices.get_alias(
            index=f"{self.index_prefix}*",
        )
        indices = [
            index.replace(self.index_prefix, "")
            for index in all_indices
            if index.startswith(self.index_prefix)
        ]
        return indices

    async def get_collection_operators(
        self,
        collection_identifier: str,
    ) -> List[Operator]:
        return await self._get_collection_part_by_id(collection_identifier, "operators")

    async def get_collection_shots(self, collection_identifier: str) -> List[Shot]:
        return await self._get_collection_part_by_id(collection_identifier, "shots")

    async def get_collection_info_by_id(
        self,
        collection_identifier: str,
    ) -> SpeechCollectionInfo:
        result = await self._get_collection_part_by_id(
            collection_identifier,
            "collection_info",
        )
        return result[0]

    async def get_operators_by_id(
        self,
        collection_identifier: str,
        operator_ids: List[int],
    ) -> List[Operator]:
        index_name = self.get_index_name(collection_identifier)
        query = {
            "query": {
                "bool": {"must": [{"terms": {"operators.id": operator_ids}}]},
            },
        }
        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
            size=10000,
        )
        response = response["hits"]["hits"]
        data_summaries = self._parse_collection_part(
            documents=response,
            part_name="operators",
            part_object=Operator,
        )
        return data_summaries

    async def get_document_by_id(self, index_name: str, doc_id: str) -> Any:
        try:
            response = await self.elastic_search_repository.get(
                index=index_name,
                id=doc_id,
            )
            part_name = list(response["_source"].keys())[0]
            part_type = self.collection_parts_mapping[part_name]
            document = part_type(**response["_source"][part_name])
            return document
        except Exception as e:
            LOGGER.error(f"Error retrieving document: {e}")
            return None

    async def _get_collection_part_by_id(
        self,
        collection_identifier: str,
        part_name: str,
    ) -> list:
        index_name = self.get_index_name(collection_identifier)
        part_object = self.collection_parts_mapping[part_name]
        query = {"query": {"exists": {"field": part_name}}}

        response = await self.elastic_search_repository.search(
            index=index_name,
            body=query,
            size=10000,
        )
        response = response["hits"]["hits"]
        parts = self._parse_collection_part(
            response,
            part_object=part_object,
            part_name=part_name,
        )
        return parts

    def get_index_name(self, identifier: str) -> str:
        return f"{self.index_prefix}{identifier}"

    def _get_operator_id_name(self, idx: int) -> str:
        return f"{self.operators_prefix}{idx}"

    def _get_shot_id_name(self, idx: int) -> str:
        return f"{self.shots_prefix}{idx}"

    @staticmethod
    def _parse_collection_part(
        documents: dict,
        part_object: Any,
        part_name: str,
    ) -> list:
        data = []
        for doc in documents:
            _source = doc["_source"]
            data.append(part_object(**_source[part_name]))
        return data

    def _parse_documents(self, documents: dict):
        mapping = {
            "collection_info": None,
            "users": [],
            "tags": [],
            "shots": [],
        }

        for doc in documents:
            _source = doc["_source"]
            for key, _ in _source.items():
                try:
                    if key == "collection_info":
                        mapping[key] = SpeechCollectionInfo(**_source[key])
                    else:
                        mapping[key].append(
                            self.collection_parts_mapping[key](**_source[key]),
                        )
                except Exception as e:
                    LOGGER.error(
                        f"Failed to parse collection_models {key}. doc = {_source}, exception = {e}",
                    )
                    raise exceptions.ElasticDocumentParserException(
                        detail="collection_models = %s, doc = %s" % (key, _source),
                    ) from e

        return SpeechCollection(
            collection_info=mapping["collection_info"],
            users=mapping["users"],
            tags=mapping["tags"],
            shots=mapping["shots"],
        )

    async def _delete_doc_from_collection(
        self,
        collection_identifier: str,
        doc_type: str,
        doc_ids: List[str],
        index_name: str,
        bulk_size: int = 1000,
    ):
        actions = [
            {"_op_type": "delete", "_index": index_name, "_id": doc_id}
            for doc_id in doc_ids
        ]
        for i in range(0, len(actions), bulk_size):
            batch_number = i // bulk_size + 1
            bulk_actions = actions[i : i + bulk_size]
            try:
                await async_bulk(
                    self.elastic_search_repository,
                    bulk_actions,
                    refresh="wait_for",
                )
                LOGGER.debug("Deleted %s batch %s" % (doc_type, batch_number))
            except Exception as e:
                LOGGER.error(
                    "unable to delete %s batch %s from %s collection_models: %s"
                    % (doc_type, batch_number, collection_identifier, e),
                )
                raise RuntimeError(
                    "doc type: %s batch: %s collection_identifier: %s"
                    % (doc_type, batch_number, collection_identifier),
                ) from e

