class RerankerModels(IRerankerModelFactory):
    def __init__(self):
        self.models = {}

    @staticmethod
    def register_opensource_openai_model(settings: BaseRerankerModelSetting, **kwargs):
        """
        Register gemma-3n-e4b-it-text as a local or custom reranker model.
        """
        return {
            "lm_model": "gemma-3n-e4b-it-text",
            "tokenizer": "local_tokenizer",
        }

    def __getitem__(self, settings: BaseRerankerModelSetting):
        return self.models[settings.framework][settings.engine_name][settings.ai_model_name]

    def register(self, settings: BaseRerankerModelSetting, **kwargs):
        try:
            if self.models.get(settings.framework) is None:
                self.models[settings.framework] = {}
            if self.models[settings.framework].get(settings.engine_name) is None:
                self.models[settings.framework][settings.engine_name] = {}

            if self.models[settings.framework][settings.engine_name].get(settings.ai_model_name) is not None:
                return

            self.models[settings.framework][settings.engine_name][settings.ai_model_name] = (
                self.__getattribute__(f"register_{settings.framework}_{settings.engine_name}_model")
            )(settings, **kwargs)
        except Exception as e:
            raise e

    @staticmethod
    def register_opensource_huggingface_model(settings: BaseEmbeddingModelSetting, **kwargs):
