        }

class OAuth:
    """API Class"""

    def __init__(self, url: str, consumer_key: str, consumer_secret: str, **kwargs: t.Any) -> None:
        self.url = url
        self.consumer_key = consumer_key
        self.consumer_secret = consumer_secret
        self.version = kwargs.get("version", "v3")
        self.method = kwargs.get("method", "GET")
        self.timestamp = kwargs.get("oauth_timestamp", int(time()))

    def get_oauth_url(self) -> str:
        """Returns the URL with OAuth params"""
        params = OrderedDict()

        if "?" in self.url:
            url = self.url[: self.url.find("?")]
            for key, value in parse_qsl(urlparse(self.url).query):
                params[key] = value
        else:
            url = self.url

        params["oauth_consumer_key"] = self.consumer_key
        params["oauth_timestamp"] = self.timestamp
        params["oauth_nonce"] = self.generate_nonce()
        params["oauth_signature_method"] = "HMAC-SHA256"
        params["oauth_signature"] = self.generate_oauth_signature(params, url)

        query_string = urlencode(params)

        return f"{url}?{query_string}"

    def generate_oauth_signature(self, params: t.Dict[str, t.Any], url: str) -> str:
        """Generate OAuth Signature"""
        if "oauth_signature" in params:
            del params["oauth_signature"]

        base_request_uri = quote(url, "")
        params = self.sorted_params(params)
        params = self.normalize_parameters(params)
        query_params = [
            "{param_key}%3D{param_value}".format(param_key=key, param_value=value) for key, value in params.items()
        ]

        query_string = "%26".join(query_params)
        string_to_sign = f"{self.method}&{base_request_uri}&{query_string}"

        consumer_secret = str(self.consumer_secret)
        if self.version not in ["v1", "v2"]:
            consumer_secret += "&"

        hash_signature = HMAC(consumer_secret.encode(), str(string_to_sign).encode(), sha256).digest()

        return b64encode(hash_signature).decode("utf-8").replace("\n", "")

    @staticmethod
    def sorted_params(params: t.Dict[str, t.Any]) -> t.OrderedDict[str, t.Any]:
        ordered = OrderedDict()
        base_keys = sorted({k.split("[")[0] for k in params.keys()})

        for base in base_keys:
            for key in params.keys():
                if key == base or key.startswith(base + "["):
                    ordered[key] = params[key]

        return ordered

    @staticmethod
    def normalize_parameters(params: t.Dict[str, t.Any]) -> t.OrderedDict[str, t.Any]:
        """Normalize parameters"""
        params = params or {}
        normalized_parameters = OrderedDict()

        def get_value_like_as_php(val):
            """Prepare value for quote"""
            base = (str, bytes)

            if isinstance(val, base):
                return val
            elif isinstance(val, bool):
                return "1" if val else ""
            elif isinstance(val, int):
                return str(val)
            elif isinstance(val, float):
                return str(int(val)) if val % 1 == 0 else str(val)
            else:
                return ""

        for key, value in params.items():
            value = get_value_like_as_php(value)
            key = quote(unquote(str(key))).replace("%", "%25")
            value = quote(unquote(str(value))).replace("%", "%25")
            normalized_parameters[key] = value

        return normalized_parameters

    @staticmethod
    def generate_nonce() -> str:
        """Generate nonce number"""
        nonce = "".join([str(randint(0, 9)) for i in range(8)])
        return HMAC(nonce.encode(), "secret".encode(), sha1).hexdigest()

def register_speech_services(dependency_container: Container, env_file_path: str = None) -> None:
    """Register speech services in the container.

    Args:
        dependency_container: The DI container to register services in
        env_file_path: Path to environment file. Default is None, which will use DEFAULT_PATH/.env
    """
    dependency_container[Speech2Text] = Singleton(
        lambda c: Speech2Text(
            algorithms={
                Speech2TextModels.WHISPER: WhisperAlgorithm(c[WhisperSettings]),
                Speech2TextModels.AVANEGAR: AvanegarAlgorithm(c[AvanegarSettings]),
            }
        )
    )

def _create_metadata_extractor(
    config: MetadataExtractorConfig,
    llm_models: LLMModels,
    embedding_models: EmbeddingModelsFactory,
    llm_connection_settings: LLMConnectionSetting,
    embedding_connection_settings: EmbeddingConnectionSetting,
    parschat_logic_settings: ParsChatLogicSettings,
) -> MetadataExtractor:
    """Create a metadata extractor with properly configured models.

    Args:
        config: Metadata extractor configuration
        llm_models: LLM models registry
        embedding_models: Embedding models registry
        llm_connection_settings: LLM connection settings
        embedding_connection_settings: Embedding connection settings
        parschat_logic_settings: ParsChatLogic settings

    Returns:
        Configured metadata extractor
    """
    # Configure and register models
    for model_setting in config.llm_models.values():
        if model_setting.connection_config is None:
            model_setting.connection_config = llm_connection_settings
        if parschat_logic_settings.debug:
            model_setting.engine_name = "mock"
        llm_models.register(model_setting)

    for model_setting in config.embedding_models.values():
        if model_setting.connection_config is None:
            model_setting.connection_config = embedding_connection_settings
        if parschat_logic_settings.debug:
            model_setting.engine_name = "mock"
        embedding_models.register(model_setting)

    # Create model mappings
    llm_models_dict = {key: llm_models[value] for key, value in config.llm_models.items()}
    embedding_models_dict = {key: embedding_models[value] for key, value in config.embedding_models.items()}

    return MetadataExtractor(
        config=config,
        llm_models=llm_models_dict,
        embedding_models=embedding_models_dict,
    )

