class URLType(BaseModel):
    url: HttpUrl = Field(
        ..., 
        description="The URL to be classified",
        examples=["https://youtube.com/watch?v=dQw4w9WgXcQ", "https://docs.google.com/document/d/123456"]
    )
    url_type: URLTypeEnum = Field(
        ..., 
        description="The type of the URL based on its domain and content",
        examples=["youtube", "google_doc", "image"]
    )

    @staticmethod
    def classify_url(url: str) -> URLTypeEnum:
        parsed_url = urlparse(url)
        domain = parsed_url.netloc

        if "youtube.com" in domain or "youtu.be" in domain:
            return URLTypeEnum.YOUTUBE
        elif "google.com" in domain:
            if re.search(r"/document/", parsed_url.path):
                return URLTypeEnum.GOOGLE_DOC
            return URLTypeEnum.GOOGLE
        elif re.search(
            r"\.(jpg|jpeg|png|gif|bmp|webp)$", parsed_url.path, re.IGNORECASE
        ):
            return URLTypeEnum.IMAGE
        elif re.search(
            r"\.(mp4|mov|wmv|avi|mkv|flv|webm)$", parsed_url.path, re.IGNORECASE
        ):
            return URLTypeEnum.VIDEO
        else:
            return URLTypeEnum.OTHER

    @classmethod
    def create(cls, url: str) -> "URLType":
        url_type = cls.classify_url(url)
        return cls(url=url, url_type=url_type)

