    value: Any

    @field_validator("value", mode="before")
    def convert_value_to_string(cls, v: Any) -> str:
        """Ensure value is always stored as a string for Elasticsearch keyword compatibility.

        Args:
            v: Raw value of any type.

        Returns:
            String representation of the value.
        """
        if isinstance(v, str):
            return v
        if isinstance(v, (dict, list)):
            return json.dumps(v, default=str)
        return str(v) if v is not None else ""

    def model_dump(self, **kwargs) -> dict:
        """Serialize the model to a dictionary.

        Returns:
            Dictionary representation with value as string.
        """
        data = super().model_dump(**kwargs)
        if "value" in data and not isinstance(data["value"], str):
            data["value"] = (
                json.dumps(data["value"], default=str)
                if isinstance(data["value"], (dict, list))
                else str(data["value"])
            )
        return data

    def model_dump_json(self, **kwargs) -> str:
        """Serialize the model to a JSON string.

        Returns:
            JSON string representation.
        """
        data = self.model_dump(**kwargs)
        return json.dumps(data, default=str)

