class AuthAPIEndpoint(ServiceAPIEndpointBluePrint):
    def __init__(
        self,
        deps: FastApiIntegration,
    ) -> None:
        super().__init__()
        self.api_route = APIRouter(prefix="/auth")
        self.deps = deps
        self.create_rest_api_route()

    def create_rest_api_route(self):
        @self.api_route.post(
            "/token",
            tags=["authentication"],
            response_model=TokenResponse,
            name="token",
            description="token",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {"description": "unable to get token"},
            },
        )
        async def get_token(
            request: Request,
            form_data: Annotated[OAuth2PasswordRequestForm, Depends()],
            auth_service=self.deps.depends(IAuthService),
            token_service=self.deps.depends(ITokenService),
        ):
            try:
                if not await auth_service.authenticate(form_data.username, form_data.password):
                    raise HTTPException(
                        status_code=status.HTTP_401_UNAUTHORIZED,
                        detail="Invalid credentials",
                    )
                access_token, expires_in = token_service.create_access_token(data={"sub": form_data.username})
                return TokenResponse(access_token=access_token, token_type="bearer", expires_in=expires_in)
            except exceptions.UserNotExists:
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="Invalid credentials",
                )
            except Exception as e:
                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail=f"Authentication error: {str(e)}",
                )

        @self.api_route.post(
            "/refresh",
            tags=["authentication"],
            response_model=TokenResponse,
            name="refresh_token",
            description="Refresh an authentication token",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_401_UNAUTHORIZED: {"description": "Invalid token"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {"description": "Unable to refresh token"},
            },
        )
        async def refresh_token(
            request: Request,
            token_service=self.deps.depends(ITokenService),
            auth_service=self.deps.depends(IAuthService),
            authorization: str = Depends(lambda x: x.headers.get("Authorization")),
        ):
            try:
                if not authorization or not authorization.startswith("Bearer "):
                    raise HTTPException(
                        status_code=status.HTTP_401_UNAUTHORIZED,
                        detail="Invalid token format",
                    )

                token = authorization.replace("Bearer ", "")
                token_data = token_service.verify_access_token(token)

                if not token_data or "sub" not in token_data:
                    raise HTTPException(
                        status_code=status.HTTP_401_UNAUTHORIZED,
                        detail="Invalid token",
                    )

                # Get a new token with a new expiration time
                username = token_data["sub"]
                access_token, expires_in = token_service.create_access_token(data={"sub": username})

                return TokenResponse(access_token=access_token, token_type="bearer", expires_in=expires_in)
            except Exception as e:
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail=f"Token refresh error: {str(e)}",
                )

class ServiceAPIEndpointBluePrint(ABC):
    @abstractmethod
    def __init__(
        self,
    ) -> None:
        pass

    @abstractmethod
    def create_rest_api_route(self):
        pass

    @staticmethod
    def execute_with_event_loop(coro: Coroutine, loop: asyncio.AbstractEventLoop):
        return asyncio.run_coroutine_threadsafe(
            coro=coro,
            loop=loop,
        ).result()

