            responses={
                status.HTTP_200_OK: {"description": "Connection successful"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {
                    "description": "Unable to connect to Elasticsearch"
                },
            },
        )
        async def healthcheck(db_repository=self.deps.depends(RobotCollectionRepository)):
            try:
                result = {
                    "database ping": await db_repository.elastic_search_repository.ping()
                }
                return JSONResponse(
                    content=result,
                    status_code=status.HTTP_200_OK,
                )
            except Exception as e:
                LOGGER.error(f"[API]. Error: {e}")
                LOGGER.error(f"[API] Traceback: {traceback.format_exc()}")
                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail=f"Database health check failed. Error: {e}",
                )

        @tracer
        @self.api_route.get(
            "/runner_count",
            tags=["Healthcheck"],
            name="Check Uvicorn Worker Count",
            description="Check how many Uvicorn worker processes are running",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {
                    "description": "Failed to fetch runner count"
                },
            },
        )
        async def runner_count():
            try:
                # pgrep returns the PIDs of processes whose names match "uvicorn"
                output = subprocess.check_output(["pgrep", "-f", "uvicorn"])
                lines = output.strip().split(b"\n")
                workers_count = len(lines)
                return JSONResponse(
                    content={"uvicorn_workers_count": workers_count},
                    status_code=status.HTTP_200_OK,
                )
            except subprocess.CalledProcessError:
                # pgrep returns non-zero if no matches are found
                return JSONResponse(
                    content={"uvicorn_workers_count": 0}, status_code=status.HTTP_200_OK
                )
            except Exception as e:
                LOGGER.error(f"[API]. Error: {e}")
                LOGGER.error(f"[API] Traceback: {traceback.format_exc()}")
                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail=f"Failed to fetch runner count. Error: {e}",
                )

class InferenceEndpoint(ServiceAPIEndpointBluePrint):
    def __init__(self, deps: FastApiIntegration, auth_dependency: AuthDependency) -> None:
        super().__init__()
        self.api_route = APIRouter(prefix="/inference")
        self.deps = deps
        self.auth_dependency = auth_dependency
        self.create_rest_api_route()

    async def _get_algorithm_with_retries(self, webhook_controller, identifier: str, retries: int):
        last_exc = None
        for attempt in range(1, retries + 1):
            try:
                return await webhook_controller.get_algorithm(identifier)
            except Exception as exc:
                last_exc = exc
                LOGGER.warning(f"get_algorithm attempt {attempt}/{retries} failed: {exc}")
        raise last_exc

    def save_data_to_file(self, input_: RequestPayload):
        file_path = (
            Path(DEFAULT_PATH)
            / "logs"
            / "inferences"
            / f"{input_.config.get('goftino_message_id', str(uuid.uuid4()))}.json"
        )
        file_path.parent.mkdir(parents=True, exist_ok=True)
        file_path.touch(exist_ok=True)
        with open(file_path, "a") as f:
            f.write(json.dumps(input_.model_dump(exclude={"token"})) + "\n")

    def create_rest_api_route(self):
        @tracer
        @self.api_route.post(
            "/logic_response",
            tags=["Inference"],
            name="AI Response",
            description="Create a new document to the database for specific user",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_400_BAD_REQUEST: {
                    "description": "the requested algorithm has not loaded!",
                },
            },
        )
        async def logic_response(
            input_: RequestPayload,
            background_tasks: BackgroundTasks,
            webhook_controller=self.deps.depends(InferenceWebhookController),
            token=Depends(self.auth_dependency),
        ):
            LOGGER.debug(f"input: {input_.model_dump(exclude='token')}")
            source_chat_id_map = {
                "live_chat": "user_session_id",
                "goftino": "goftino_chat_id",
                "telegram": "telegram_chat_id",
            }

            source = input_.config.get("source", "live_chat")  # default to live_chat if missing
            chat_id_field = source_chat_id_map.get(source, "user_session_id")  # fallback
            chat_id = input_.config.get(chat_id_field, "123")

            if not isinstance(chat_id, str):
                chat_id = str(chat_id)

            # Resolving the history problem in تست چت بات
            if input_.client_state is None:
                input_.client_state = {}
            if not input_.client_state.get("thread_id"):
                input_.client_state["thread_id"] = uuid.uuid4().hex[:5]
            # End

            ai_input_message = AlgorithmInput(
                message=input_.message,
                history=input_.history,
                client_state=input_.client_state,
                source=input_.config.get("source", "live_chat"),
                metadata=input_.config,
                chat_id=chat_id,
                message_id=str(input_.config.get("live_chat_message_id", "unknown")),
            )

            ai_pipeline = await self._get_algorithm_with_retries(
                webhook_controller,
                input_.collection_identifier,
                retries=3,
            )
            if isinstance(ai_pipeline, Exception):
                return JSONResponse(
                    content={"detail": str(ai_pipeline)},
                    status_code=status.HTTP_400_BAD_REQUEST,
                    headers=None,
                )

            if source == "telegram" and input_.message.lower() == "/start":
                LOGGER.info("Received /start from telegram, not processing.")
                return JSONResponse(
                    content={"detail": "got it"},
                    status_code=status.HTTP_200_OK,
                    headers=None,
                )

            background_tasks.add_task(
                func=webhook_controller.que_processing,
                input_=input_,
                ai_input_message=ai_input_message,
                ai_pipeline=ai_pipeline,
            )

            LOGGER.info("got it")
            return JSONResponse(
                content={"detail": "got it"},
                status_code=status.HTTP_200_OK,
                headers=None,
            )

