        @tracer
        @self.api_route.post(
            "/parsian_logic_response",
            tags=["Inference"],
            name="Parsian Logic Response",
            description=(
                "Synchronous inference endpoint for Parsian integration."
                " Accepts a simple request payload and returns the AI-generated response directly."
            ),
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_400_BAD_REQUEST: {
                    "description": "The requested algorithm has not loaded!",
                },
            },
            response_model=InferenceResponseModel,
        )
        async def parsian_logic_response(
            input_: SimpleRequestPayload,
            webhook_controller=self.deps.depends(InferenceWebhookController),
            token=Depends(self.auth_dependency),
        ):
            LOGGER.debug(f"parsian_logic_response input: {input_.model_dump(exclude='attachment')}")

            # Resolving the history problem in تست چت بات
            if input_.client_state is None:
                input_.client_state = {}
            if not input_.client_state.get("thread_id"):
                input_.client_state["thread_id"] = uuid.uuid4().hex[:5]
            # End

            if not input_.message:
                input_.message = ""

            if input_.attachment:
                # ۱. حذف پیشوند احتمالی (اگر از سمت فرانت‌اند وب ارسال شده باشد)

                try:
                    metadata, base64_content = input_.attachment.split(",")
                    _, mimetype, codecs, _ = metadata.replace(":", ";").split(";")
                    file_cat, file_ext = mimetype.split("/")

                    user_id = input_.config.get("user_id", "others")
                    filename: str = uuid.uuid4().hex[:8]
                    save_path = f"./data/parsian/{user_id}/{filename}.{file_ext}"

                    Path(f"./data/parsian/{user_id}/").mkdir(exist_ok=True, parents=True)
                    # ۲. تبدیل رشته Base64 به داده‌های باینری اصلی
                    try:
                        file_bytes = base64.b64decode(base64_content)
                    except Exception:
                        raise ValueError("رشته Base64 نامعتبر است.")

                    with open(save_path, "wb") as f:
                        f.write(file_bytes)

                    # ۳. تبدیل فایل صوتی به فرمت OGG
                    if file_ext == "ogg":
                        ogg_path = save_path
                    else:
                        try:
                            ogg_path = AudioProcessor.convert_to_ogg(save_path)
                            LOGGER.info(f"Audio file converted to OGG: {ogg_path}")
                        except Exception as e:
                            LOGGER.error(f"Failed to convert audio to OGG: {e}")
                            raise ValueError(f"Failed to convert audio file to OGG: {str(e)}")

                    voice_attachment = Attachment(
                        id=123,
                        identifier=f"{filename}.ogg",
                        given_name=f"{filename}.ogg",
                        type=AttachmentType.VOICE,
                        extension="audio/ogg",
                        size=len(file_bytes),
                        path=ogg_path,
                        url=None,
                    )

                    voice_message = VoiceMessage()
                    await webhook_controller._transcribe_voice_attachment(voice_attachment, voice_message)

                    if not voice_message.content:
                        voice_message.content = ""

                    input_.type = "message"
                    input_.message = input_.message + "\n\n" + voice_message.content

                except Exception as exc:
                    LOGGER.error(f"parsian_logic_response error: {exc}")
                    response = InferenceResponseModel(
                        status=ResponseStatus.ERROR,
                        config=input_.config,
                        message="",
                        history=input_.history,
                        client_state=input_.client_state,
                    )

            chat_id = str(input_.config.get("chat_id", uuid.uuid4().hex[:8]))

            ai_input_message = AlgorithmInput(
                message=input_.message,
                history=input_.history,
                client_state=input_.client_state,
                source=input_.config.get("source", "live_chat"),
                metadata=input_.config,
                chat_id=chat_id,
                message_id=str(input_.config.get("message_id", "unknown")),
            )

            try:
                result = await webhook_controller.process_direct(
                    ai_input_message=ai_input_message,
                    collection_identifier=PARSIAN_COLLECTION_IDENTIFIER,
                )
                response = InferenceResponseModel(
                    status=ResponseStatus.SUCCESS,
                    config=input_.config,
                    client_state=input_.client_state,
                    message=result.generated_text,
                    history=result.history or [],
                )
            except Exception as exc:
                LOGGER.error(f"parsian_logic_response error: {exc}")
                response = InferenceResponseModel(
                    status=ResponseStatus.ERROR,
                    config=input_.config,
                    message="",
                    history=input_.history,
                    client_state=input_.client_state,
                )

            return JSONResponse(
                content=response.model_dump(),
                status_code=status.HTTP_200_OK,
                headers=None,
            )

