class TrainingAPIEndpoint(ServiceAPIEndpointBluePrint):
    def __init__(self, deps: FastApiIntegration, auth_dependency: AuthDependency) -> None:
        super().__init__()
        self.api_route = APIRouter(prefix="/training")
        self.concurrent_size = 8
        self.deps = deps
        self.auth_dependency = auth_dependency
        self.create_rest_api_route()

    @staticmethod
    def _build_delete_request_descriptor(value: Any) -> str:
        """Build a stable descriptor for a delete request payload.

        Args:
            value: Request payload value.

        Returns:
            String descriptor for logging and cache state.
        """
        if hasattr(value, "model_dump"):
            return str(value.model_dump(mode="json"))
        return str(value)

    @staticmethod
    def _build_item_identifier_from_records(data_record_identifiers: DataRecordIdentifiers) -> str:
        """Build a stable item identifier from data record identifiers.

        Args:
            data_record_identifiers: The data record identifiers from the request.

        Returns:
            A short hex hash uniquely representing the set of identifiers.
        """
        sorted_ids = sorted(data_record_identifiers.data_record_identifiers)
        joined = "|".join(sorted_ids)
        return hashlib.sha256(joined.encode()).hexdigest()[:16]

    @staticmethod
    def _serialize_task_kwargs(kwargs: dict) -> dict:
        """Serialize callable kwargs to a JSON-safe dict for cache storage.

        Args:
            kwargs: Keyword arguments passed to the delete callable.

        Returns:
            Dict with Pydantic models converted via model_dump.
        """
        result = {}
        for key, value in kwargs.items():
            if hasattr(value, "model_dump"):
                result[key] = value.model_dump(mode="json")
            else:
                result[key] = value
        return result

    @staticmethod
    async def _run_tracked_delete_task(
        delete_task_tracker: DeleteTaskTracker,
        operation: str,
        tracked_collection_identifier: str,
        tracked_item_identifier: str,
        delete_callable,
        **kwargs,
    ) -> None:
        """Run a background delete task, marking it failed on error.

        Args:
            delete_task_tracker: Delete task tracker service.
            operation: Delete operation name.
            tracked_collection_identifier: Collection identifier.
            tracked_item_identifier: Unique identifier for the item being deleted.
            delete_callable: Async delete callable.
            **kwargs: Keyword arguments for the delete callable.
        """
        try:
            await delete_callable(**kwargs)
            await delete_task_tracker.complete_task(operation, tracked_collection_identifier, tracked_item_identifier)
        except Exception as exc:
            LOGGER.error(
                f"Background delete task failed: {operation} for "
                f"{tracked_collection_identifier}:{tracked_item_identifier}: {exc}"
            )
            serializable_kwargs = TrainingAPIEndpoint._serialize_task_kwargs(kwargs)
            await delete_task_tracker.fail_task(
                operation=operation,
                collection_identifier=tracked_collection_identifier,
                item_identifier=tracked_item_identifier,
                error_message=str(exc),
                task_kwargs=serializable_kwargs,
            )

    async def _register_delete_request(
        self,
        delete_task_tracker: DeleteTaskTracker,
        operation: str,
        collection_identifier: str,
        item_identifier: str,
        requested_item: str,
        task_kwargs: dict | None = None,
    ) -> None:
        """Register a delete request or reject it when one is already running.

        Args:
            delete_task_tracker: Delete task tracker service.
            operation: Delete operation name.
            collection_identifier: Collection identifier.
            item_identifier: Unique identifier for the item being deleted.
            requested_item: Delete request descriptor.
            task_kwargs: Serialized callable arguments for retry on failure.

        Raises:
            HTTPException: Raised when another delete task is still open.
        """
        # has_open_task = await delete_task_tracker.has_open_task(operation, collection_identifier, item_identifier)
        # if has_open_task:
        #     raise HTTPException(
        #         status_code=status.HTTP_409_CONFLICT,
        #         detail=(
        #             f"{operation} is already running for collection {collection_identifier} "
        #             f"item {item_identifier}. Wait for the current background task to finish."
        #         ),
        #     )
        was_registered = await delete_task_tracker.register_task(
            operation=operation,
            collection_identifier=collection_identifier,
            item_identifier=item_identifier,
            requested_item=requested_item,
            task_kwargs=task_kwargs or {},
        )
        if not was_registered:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail=(
                    f"{operation} is already running for collection {collection_identifier}. "
                    "Wait for the current background task to finish."
                ),
            )

    def create_rest_api_route(self):
        @tracer
        @self.api_route.post(
            "/create",
            tags=["Collection"],
            name="Create Collection",
            description="Create a new collection_models to the database for specific user",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {
                    "description": "Unable to Create Collection in the Database",
                },
            },
        )
        async def create_collection(
            collection: CollectionRecord,
            webhook_controller=self.deps.depends(IndexingWebhookController),
            token=Depends(self.auth_dependency),
        ):
            try:
                LOGGER.debug(f"collection_models = {collection}")
                result = await webhook_controller.create_collection(collection)
                if result.status == OperationStatus.FAILURE.value:
                    raise Exception(result.message)
                return JSONResponse(
                    content=result.model_dump(),
                    status_code=status.HTTP_200_OK,
                )
            except Exception as e:
                LOGGER.error(f"[API]. Error: {e}")
                LOGGER.error(f"[API] Traceback: {traceback.format_exc()}")
                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail=f"Create failed. Please try again. Error: {e}",
                )

        @tracer
        @self.api_route.delete(
            "/delete/{collection_identifier}",
            tags=["Collection"],
            name="Delete Collection",
            description="Delete an existing collection_models from the database",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {
                    "description": "Unable to Delete Collection from the Database",
                },
            },
        )
        async def delete_collection(
            collection_identifier: str,
            webhook_controller=self.deps.depends(IndexingWebhookController),
            token=Depends(self.auth_dependency),
        ):
            try:
                LOGGER.debug(f"collection_identifier = {collection_identifier}")
                result = await webhook_controller.delete_collection(
                    collection_identifier=collection_identifier,
                )
                if result.status == OperationStatus.FAILURE.value:
                    raise Exception(result.message)
                return JSONResponse(
                    content=result.model_dump(),
                    status_code=status.HTTP_200_OK,
                    headers=None,
                )
            except Exception as e:
                LOGGER.error(f"[API]. Error: {e}")
                LOGGER.error(f"[API] Traceback: {traceback.format_exc()}")
                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail=f"Delete failed. Please try again. Error: {e}",
                )

        @tracer
        @self.api_route.put(
            "/update/{collection_identifier}",
            tags=["Collection"],
            name="Update Collection Data",
            description="Update the data within an existing collection_models",
            responses={
                status.HTTP_200_OK: {"description": "Success"},
                status.HTTP_500_INTERNAL_SERVER_ERROR: {
                    "description": "Unable to Update Collection Data in the Database",
                },
            },
        )
        async def update_collection_data(
            background_tasks: BackgroundTasks,
            collection_identifier: str,
            datum: List[DataRecord],
            user_current_characters: int = 0,
            user_maximum_characters: int = 130000,
            user_remaining_doc_pages: int = 5,
            webhook_controller=self.deps.depends(IndexingWebhookController),
            ai_logic_pipeline=self.deps.depends(ParsChatLogic),
            token=Depends(self.auth_dependency),
        ):
            try:
                db_repository = ai_logic_pipeline.robot_collection_repository
                index_name = db_repository.get_index_name(collection_identifier)
                collection_exitst = await db_repository.collection_exists(index_name)
                if not collection_exitst:
                    raise exceptions.CollectionNotExists(
                        detail=f"{collection_identifier}",
                    )
                LOGGER.debug(
                    "updating %s with data : \n%s"
                    % (collection_identifier, [data.model_dump(mode="json") for data in datum]),
                )
                background_tasks.add_task(
                    func=webhook_controller.batch_update_collection_data,
                    collection_identifier=collection_identifier,
                    datum=datum,
                    user_current_characters=user_current_characters,
                    user_maximum_characters=user_maximum_characters,
                    user_remaining_doc_pages=user_remaining_doc_pages,
                    batch_size=self.concurrent_size,
