class WooCommerceWebhookEndpoint(ServiceAPIEndpointBluePrint):
    """
    Defines separate routes for coupon, customer, order, product.
    Each route uses _common_webhook_logic for reading headers/body
    and verifying the request in the background.
    """

    def __init__(self, woo_controller: WooWebhookController) -> None:
        super().__init__()
        self.api_route = APIRouter(prefix="/woocommerce")
        self.controller = woo_controller
        self.create_routes()

    def create_routes(self):
        @self.api_route.post("/coupon", tags=["WooCommerce"])
        async def coupon_webhook(request: Request, background_tasks: BackgroundTasks):
            return await self._common_webhook_logic(
                request=request,
                background_tasks=background_tasks,
                resource="coupon"
            )

        @self.api_route.post("/customer", tags=["WooCommerce"])
        async def customer_webhook(request: Request, background_tasks: BackgroundTasks):
            return await self._common_webhook_logic(
                request=request,
                background_tasks=background_tasks,
                resource="customer"
            )

        @self.api_route.post("/order", tags=["WooCommerce"])
        async def order_webhook(request: Request, background_tasks: BackgroundTasks):
            return await self._common_webhook_logic(
                request=request,
                background_tasks=background_tasks,
                resource="order"
            )

        @self.api_route.post("/product", tags=["WooCommerce"])
        async def product_webhook(request: Request, background_tasks: BackgroundTasks):
            return await self._common_webhook_logic(
                request=request,
                background_tasks=background_tasks,
                resource="product"
            )

    async def _common_webhook_logic(
            self,
            request: Request,
            background_tasks: BackgroundTasks,
            resource: str
    ) -> JSONResponse:
        # Headers
        signature = request.headers.get("x-wc-webhook-signature", "")
        delivery_id = request.headers.get("x-wc-webhook-id", "")
        event_name = request.headers.get("x-wc-webhook-event", "")  # "created", "updated", etc.
        topic = request.headers.get("x-wc-webhook-topic", "")  # "coupon.created", etc.

        raw_body = await request.body()

        try:
            payload_dict = await request.json()
        except Exception as ex:
            return JSONResponse(
                content={"detail": f"Invalid JSON: {str(ex)}"},
                status_code=status.HTTP_400_BAD_REQUEST
            )

        background_tasks.add_task(
            self.controller.handle_webhook,
            raw_body,
            signature,
            delivery_id,
            resource,
            event_name,
            topic,
            payload_dict
        )

        return JSONResponse(
            content={"detail": f"Webhook accepted for resource '{resource}'"},
            status_code=status.HTTP_200_OK
        )

