        return self.config.dwell_time_second

    async def _pick_random_message(
        self, current_url: str, collection_identifier: str, scope_type: ScopeType, scope_id: str, category_place_holders: Optional[Any] = None
    ) -> Optional[Dict[str, Any]]:
        """Pick a random second message from Elasticsearch.

        Args:
            current_url: The current URL to analyze.
            collection_identifier: The collection identifier.
            scope_type: The scope type (product or category).
            scope_id: The scope identifier.
            category_place_holders: Optional category placeholders for category messages.

        Returns:
            Random second message data or None.
        """
        if scope_type == ScopeType.CATEGORY:
            return await self._get_default_ad_category_message(collection_identifier, category_place_holders)
        try:
            return await self.ecommerce_repository.get_random_second_message(collection_identifier, current_url)
        except Exception as e:
            LOGGER.error(f"Error picking random second message: {str(e)}")
            return None

    async def _get_default_ad_category_message(self, collection_identifier: str, category_place_holders: Optional[Any] = None) -> Optional[Dict[str, Any]]:
        """Get category second message.

        Args:
            collection_identifier: The collection identifier.
            category_place_holders: Optional category placeholders for category messages.

        Returns:
            Category message data.
        """
        try:
            return await self.ecommerce_repository.get_random_category_second_message(collection_identifier, category_place_holders)
        except Exception as e:
            LOGGER.error(f"Error getting category message: {str(e)}")
            return None

class SendThirdAdMessageUseCase(SendAdMessageBaseUseCase):
    """Use case for sending third advertisement message after maximum dwell time.

    Implements enhanced business logic for third-level messages:
    - For categories: uses category_third_messages
    - For products: prioritizes by availability > percentage discount > discount code
    """

    @property
    def message_level(self) -> MessageLevel:
        """Get the message level for this use case."""
        return MessageLevel.THIRD

    @property
    def required_dwell_time(self) -> int:
        """Get the required dwell time in seconds for third message."""
        return self.config.dwell_time_third

    async def _pick_random_message(
        self, current_url: str, collection_identifier: str, scope_type: ScopeType, scope_id: str, category_place_holders: Optional[Any] = None
    ) -> Optional[Dict[str, Any]]:
        """Pick a smart third message based on enhanced business logic.

        The third messages are selected based on:
        1. For categories: use category_third_messages
        2. For products: prioritize by availability > percentage discount > discount_code

        Args:
            current_url: The current URL to analyze.
            collection_identifier: The collection identifier.
            scope_type: The scope type (product or category).
            scope_id: The scope identifier.
            category_place_holders: Optional category placeholders (not used in third messages).

        Returns:
            Message data with enhanced business logic or None.
        """
        # TODO: Implement logic to pick a random second message based on the scope type.
        if scope_type == ScopeType.CATEGORY:
            return None
        try:
            if scope_type == ScopeType.PRODUCT:
                # Get product info and apply business logic priority
                product = await self.ecommerce_repository.get_product_by_url(collection_identifier, current_url)
                if product:
                    return await self._get_smart_product_message(collection_identifier, product)

            # For categories or if product not found, use category messages
            return await self._get_default_third_ad_category_message(collection_identifier)

        except Exception as e:
            LOGGER.error(f"Error picking smart third message: {str(e)}")
            return None

    async def _get_smart_product_message(
        self, collection_identifier: str, product: Product
    ) -> Optional[Dict[str, Any]]:
        """Get smart product message based on business priority.

        Priority:
        1. Low stock (availability < 10)
        2. Percentage discount
        3. Discount code

        Args:
            collection_identifier: The collection identifier.
            product: Product object.

        Returns:
            Message data based on business logic.
        """
        try:
            # Priority 1: Check if product is low stock (< 10) and in stock (> 0)
            stock_quantity = self.ecommerce_repository.get_stock_quantity(product)
            if stock_quantity < 10 and stock_quantity > 0:
                LOGGER.debug(f"Product has low stock ({stock_quantity}), using low_stock message")
                return await self.ecommerce_repository.get_product_message_by_type_and_tone(
                    collection_identifier, "low_stock", "semi_formal", product
                )

            # Priority 2: Check if product has percentage discount
            if self.ecommerce_repository.has_percentage_discount(product):
                LOGGER.debug("Product has percentage discount, using percent_discount message")
                return await self.ecommerce_repository.get_product_message_by_type_and_tone(
                    collection_identifier, "percent_discount", "semi_formal", product
                )

            # Priority 3: Check if product has discount code
            if self.ecommerce_repository.has_discount_code(product):
                LOGGER.debug("Product has discount code, using discount message")
                return await self.ecommerce_repository.get_product_message_by_type_and_tone(
                    collection_identifier, "discount", "semi_formal", product
                )

            # Fallback to category message if no specific product conditions met
            LOGGER.debug("No specific product conditions met, falling back to category message")
            return await self._get_default_third_ad_product_message(collection_identifier)

        except Exception as e:
            # FIXME: fallback is to sending category message
            LOGGER.error(f"Error getting smart product message: {str(e)}")
            return await self._get_default_third_ad_category_message(collection_identifier)

    async def _get_default_third_ad_category_message(self, collection_identifier: str) -> Optional[Dict[str, Any]]:
        """Get category third message.

        Args:
            collection_identifier: The collection identifier.

        Returns:
            Category message data.
        """
        try:
            return await self.ecommerce_repository.get_random_category_third_message(collection_identifier)
        except Exception as e:
            LOGGER.error(f"Error getting category message: {str(e)}")
            return None

    async def _get_default_third_ad_product_message(self, collection_identifier: str) -> Optional[Dict[str, Any]]:
        """Get product third message.

        Args:
            collection_identifier: The collection identifier.

        Returns:
            Product message data.
        """
        try:
            return await self.ecommerce_repository.get_random_product_third_message(collection_identifier)
        except Exception as e:
            LOGGER.error(f"Error getting product message: {str(e)}")
            return None

class RAGChainDetectionUseCase(BaseAIAgentUseCase):
    """Use case for detecting which RAG chains need to be customized based on user prompt."""

    def __init__(
        self,
        prompt_catalog: PromptCatalogProtocol,
        ai_service: AIServiceProtocol,
    ) -> None:
        """Initialize the use case.

        Args:
            prompt_catalog: The catalog of available prompts.
            ai_service: The AI service to use for generating responses.
        """
        super().__init__(prompt_catalog, ai_service)
        self.prompt_name = PromptNames.RAG_CHAIN_DETECTION

    async def execute(
        self,
        input_data: RAGChainDetectionInput,
        robot_id: str | None = None,
        prompt_version: str = "latest",
    ) -> RAGChainDetectionOutput:
        """Detect required RAG chain customizations based on user prompt."""
        try:
            prompt = self._prompt_catalog.load_prompt(
                self.prompt_name, robot_id, prompt_version
            )
            result = await self._ai_service.process(prompt, input_data.model_dump())

            raw_chains = result.get("chains", [])
            if isinstance(raw_chains, str):
                raw_chains = []

            parsed: List[RAGChainInstructionItem] = []
            for itm in raw_chains:
                if isinstance(itm, dict):
                    name = itm.get("chain_name")
                    instr = itm.get("instructions")
                    if name and isinstance(instr, list):
                        parsed.append(RAGChainInstructionItem(chain_name=name, instructions=instr))
            return RAGChainDetectionOutput(chains=parsed)
        except Exception as e:
            raise AIServiceError(
                f"Error executing {self.__class__.__name__}: {e}"
            ) from e

