def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

class AssistantGraph:
    def __init__(
        self,
        assistant: Assistant,
        need_clarification_node: NeedClarificationNode,
        clarifying_question_node: ClarifyingQuestionNode,
        presentation_node: PresentationNode,
        order_tracker_subgraph,
    ):
        self.builder = StateGraph(State)

        self.builder.add_node(AutoEcommerceNode.ASSISTANT.value, assistant.__call__)
        self.builder.add_node(AutoEcommerceNode.ORDER_TRACKER_SUBGRAPH.value, order_tracker_subgraph)

        self.builder.add_node(
            AutoEcommerceNode.TOOLS.value,
            create_tool_node_with_fallback(assistant.tools),
            retry=RetryPolicy(max_attempts=3),
        )
        self.builder.add_node(AutoEcommerceNode.NEED_CLARIFICATION.value, need_clarification_node.__call__)
        self.builder.add_node(AutoEcommerceNode.CLARIFYING_QUESTION.value, clarifying_question_node.__call__)
        self.builder.add_node(AutoEcommerceNode.PRESENTATION.value, presentation_node.__call__)

        self.builder.add_edge(START, AutoEcommerceNode.ASSISTANT.value)
        self.builder.add_conditional_edges(
            AutoEcommerceNode.ASSISTANT.value,
            self.tools_condition,
            {
                AutoEcommerceNode.ORDER_TRACKER_TOOL.value: AutoEcommerceNode.ORDER_TRACKER_SUBGRAPH.value,
                AutoEcommerceNode.END_SIGNAL.value: END,
                AutoEcommerceNode.TOOLS.value: AutoEcommerceNode.TOOLS.value,
            },
        )
        self.builder.add_edge(AutoEcommerceNode.ORDER_TRACKER_SUBGRAPH.value, END)
        self.builder.add_conditional_edges(
            AutoEcommerceNode.TOOLS.value,
            self.after_search_condition,
            {
                AutoEcommerceNode.NEED_CLARIFICATION.value: AutoEcommerceNode.NEED_CLARIFICATION.value,
                AutoEcommerceNode.ASSISTANT.value: AutoEcommerceNode.ASSISTANT.value,
            },
        )
        self.builder.add_conditional_edges(
            AutoEcommerceNode.NEED_CLARIFICATION.value,
            self.need_clarification_routing,
            {
                AutoEcommerceNode.CLARIFYING_QUESTION.value: AutoEcommerceNode.CLARIFYING_QUESTION.value,
                AutoEcommerceNode.PRESENTATION.value: AutoEcommerceNode.PRESENTATION.value,
            },
        )
        self.builder.add_edge(AutoEcommerceNode.CLARIFYING_QUESTION.value, END)
        self.builder.add_edge(AutoEcommerceNode.PRESENTATION.value, END)

        self.memory = MemorySaver()
        self.graph = self.builder.compile(checkpointer=self.memory)

    def tools_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call in [AutoEcommerceNode.ORDER_TRACKER_TOOL.value, AutoEcommerceNode.END_SIGNAL.value]:
            return last_call
        else:
            return AutoEcommerceNode.TOOLS.value

    def after_search_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call == AutoEcommerceNode.PRODUCT_RETRIEVER_TOOL.value:
            return AutoEcommerceNode.NEED_CLARIFICATION.value
        else:
            return AutoEcommerceNode.ASSISTANT.value

    def need_clarification_routing(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call == AutoEcommerceNode.ASK_CLARIFICATION.value:
            return AutoEcommerceNode.CLARIFYING_QUESTION.value
        else:
            return AutoEcommerceNode.PRESENTATION.value

class NeedClarificationNode:
    def __init__(self, llm_models: dict, collection_info: CollectionInfo):
        self.collection_info = collection_info
        self.llm_models = llm_models
        need_clarification_prompt = AutoEcommercePrompts.create_need_clarification_prompt(collection_info)
        self._need_clarification_chain = need_clarification_prompt | llm_models["light-model"]

    async def __call__(self, state: State, config: RunnableConfig):
        cleaned_messages = get_cleaned_messages(state["messages"])
        tool_message = state["messages"][-1].model_copy()

        evaluated_tool_content = get_evaluated_tool_content(state["messages"][-1])

        last_tool_call_index = find_last_tool_call_index(state["messages"])
        last_tool_call = state["messages"][last_tool_call_index].tool_calls[0] if last_tool_call_index >= 0 else None

        if last_tool_call and last_tool_call["name"] == "product_retriever_tool":
            tool_message.content = [
                {"name": product["name"], "short_description": product["short_description"]}
                for product in evaluated_tool_content["products"]
            ]

            if last_tool_call["args"].get("max_price") or last_tool_call["args"].get("min_price", 0) > 1:
                return Command(
                    update={"last_call": "skip_clarification"},
                    goto="presentation",
                )

            if state.get("clarifying_question_generated", 0) >= 1:
                return Command(
                    update={"last_call": "skip_clarification"},
                    goto="presentation",
                )

            if self.collection_info.identifier in SpecificUsers.users_without_clarification:
                need_clarification_result_content = "skip"
            else:
                need_clarification_result = await self._need_clarification_chain.ainvoke(
                    {"history": create_full_history_string(cleaned_messages[:-1] + [tool_message])}
                )
                need_clarification_result_content = need_clarification_result.content

            if "generate" in need_clarification_result_content.lower():
                return Command(
                    update={"last_call": "ask_clarification"},
                    goto="clarifying_question",
                )

            return Command(
                update={"last_call": "generate_directly"},
                goto="presentation",
            )

        return Command(
            update={"last_call": "direct_to_generator"},
            goto="presentation",
        )

class PresentationNode:
    """Node for final presentation of results to user."""

    def __init__(
        self,
        ecommerce_identifier: str,
        ecommerce_repo: IRobotEcommerceRepository,
        llm_models: dict,
        collection_info: CollectionInfo,
    ):
        self.collection_info = collection_info
        self.llm_models = llm_models

        prompt_builder = PromptBuilder(collection_info)
        self.discount_price_examples = prompt_builder._get_prompt_value(
            "discount_price_examples", "discount_price_examples"
        )
        self.discount_percent_examples = prompt_builder._get_prompt_value(
            "discount_percent_examples", "discount_percent_examples"
        )
        self.popular_examples = prompt_builder._get_prompt_value("popular_examples", "popular_examples")
        self.bestseller_examples = prompt_builder._get_prompt_value("bestseller_examples", "bestseller_examples")
        self.introduction_examples = prompt_builder._get_prompt_value("introduction_examples", "introduction_examples")
        self.introduction_single_examples = prompt_builder._get_prompt_value(
            "introduction_single_examples", "introduction_single_examples"
        )
        self.final_presentation_sentence = prompt_builder._get_prompt_value(
            "final_presentation_sentence", "final_presentation_sentence"
        )

        generator_prompt = AutoEcommercePrompts.create_presentation_prompt(collection_info)
        self._generator_chain = generator_prompt | llm_models["generator-model"]

        generator_with_ambiguty_prompt = AutoEcommercePrompts.create_presentation_with_ambiguty_prompt(collection_info)
        self._generator_with_ambiguty_chain = generator_with_ambiguty_prompt | llm_models["generator-model"]

        generator_zero_prompt = AutoEcommercePrompts.create_zero_presentation_prompt(collection_info)
        self._generator_zero_product_chain = generator_zero_prompt | llm_models["generator-model"]

    async def __call__(self, state: State, config: RunnableConfig):
        last_call = "__end__"
        tool_message = state["messages"][-1].model_copy()
        cleaned_messages = get_cleaned_messages(state["messages"])
        intermediate_callback = config["configurable"]["intermediate_callback"]

        evaluated_tool_content = get_evaluated_tool_content(state["messages"][-1])

        if evaluated_tool_content and evaluated_tool_content.get("products", []) != []:
            tool_message.content = self._enrich_tool_message(evaluated_tool_content)

            discount_examples = self._get_discount_examples(tool_message)

            if evaluated_tool_content.get("query_adapted", False):
                stream = self._generator_with_ambiguty_chain.astream(
                    {
                        "final_search_term": tool_message.content["adapted_query_finde_product"],
                        "user_original_query": tool_message.content["original_input_query"],
                        "history": create_full_history_string(cleaned_messages[:-1] + [tool_message]),
                        "introduction_examples": self._get_introduction_examples(tool_message),
                        "final_presentation_sentence": self._format_samples_list(
                            random.sample(self.final_presentation_sentence, k=1)
                        ),
                    }
                )
            else:
                stream = self._generator_chain.astream(
                    {
                        "history": create_full_history_string(cleaned_messages[:-1] + [tool_message]),
                        "introduction_examples": self._get_introduction_examples(tool_message),
                        "discount_examples": self._format_samples_list(discount_examples),
                        "popular_examples": self._format_samples_list(random.sample(self.popular_examples, k=3)),
                        "bestseller_examples": self._format_samples_list(random.sample(self.bestseller_examples, k=3)),
                        "final_presentation_sentence": self._format_samples_list(
                            random.sample(self.final_presentation_sentence, k=1)
                        ),
                    }
                )

        else:
            stream = self._generator_zero_product_chain.astream(
                {
                    "history": create_full_history_string(cleaned_messages[:-1] + [tool_message]),
                    "user_query": json.loads(tool_message.content).get("original_input_query", ""),
                    "bestseller_examples": self._format_samples_list(random.sample(self.bestseller_examples, k=3)),
                    "final_presentation_sentence": self._format_samples_list(
                        random.sample(self.final_presentation_sentence, k=1)
                    ),
                }
            )

        generator_result = await process_stream_with_callback(stream, intermediate_callback)

        return Command(
            update={"messages": [generator_result], "last_call": last_call, "clarifying_question_generated": 0},
            goto="__end__",
        )

    def _get_discount_examples(self, tool_message: ToolMessage) -> list[dict]:
        discount_examples = []
        any_discount_percentage = False

        if isinstance(tool_message.content, List):
            any_discount_percentage = any(
                "discount_percentage" in product and product["discount_percentage"] > 0
                for product in tool_message.content
            )
        if any_discount_percentage:
            discount_percent_examples = random.sample(self.discount_percent_examples, k=2)
            discount_price_examples = random.sample(self.discount_price_examples, k=1)
            discount_examples = discount_percent_examples + discount_price_examples
        else:
            discount_examples = random.sample(self.discount_price_examples, k=3)

        return discount_examples

    def _format_samples_list(self, samples: list[str]) -> str:
        """Format samples list with proper indentation.

        Args:
            samples: List of sample strings.

        Returns:
            Formatted string with indented samples.
        """
        return "\n  ".join(["  " + samples[0]] + samples[1:])

    def _enrich_tool_message(self, evaluated_tool_content: list[dict]) -> list[dict]:
        """Enrich tool message content with discount percentages.

        Args:
            evaluated_tool_content: List of product dictionaries.

        Returns:
            Enriched product list with discount percentages.
        """
        try:
            enriched_products = []

            for product in evaluated_tool_content:
                enriched_product = product.copy()

                price = float(product.get("price", "0"))
                regular_price = float(product.get("regular_price", "0"))

                if (
                    price is not None
                    and regular_price is not None
                    and price > 0
                    and regular_price > 0
                    and price != regular_price
                ):
                    discount_percentage = round(((regular_price - price) / regular_price) * 100, 2)
                    enriched_product["discount_percentage"] = discount_percentage

                enriched_products.append(enriched_product)

            return enriched_products
        except Exception:
            return evaluated_tool_content

    def _get_introduction_examples(self, tool_message: ToolMessage) -> str:
        """Get appropriate introduction example based on product count.

        Args:
            tool_message: Tool message containing products.

        Returns:
            Single introduction example string.
        """
        evaluated_tool_content = self._extract_tool_content(tool_message)["products"]

        if evaluated_tool_content and len(evaluated_tool_content) == 1:
            return random.sample(self.introduction_single_examples, k=1)
        else:
            return random.sample(self.introduction_examples, k=1)

    def _extract_tool_content(self, tool_message: ToolMessage) -> list[dict]:
        """Extract tool content handling both list and JSON string formats.

        Args:
            tool_message: Tool message containing products.

        Returns:
            List of product dictionaries.
        """
        if isinstance(tool_message.content["products"], list):
            return tool_message.content
        else:
            return get_evaluated_tool_content(tool_message)

