class Assistant:
    def __init__(
        self,
        autorag_algo: AutoRag | None,
        config: Config,
        collection_info: CollectionInfo,
        llm_models: dict,
    ):
        self.llm_model = llm_models["llm_model"]
        mandatory_use_of_autorag_prompt = (
            AssistantPrompt.default_mandatory_use_of_autorag_prompt if autorag_algo else ""
        )

        if collection_info.prompts and "ecommerce_system_prompt" in collection_info.prompts:
            manual_ecommerce_system_prompt = collection_info.prompts["ecommerce_system_prompt"]

            ecommerce_system_prompt_template = copy.deepcopy(AssistantPrompt.ecommerce_system_prompt_template)
            ecommerce_system_prompt_template.template = manual_ecommerce_system_prompt
        else:
            ecommerce_system_prompt_template = AssistantPrompt.ecommerce_system_prompt_template

        ecommerce_system_prompt = ecommerce_system_prompt_template.invoke(
            {
                "language": "{{{language}}}",
                "Third_Autorag_Tool": mandatory_use_of_autorag_prompt,
                "نام چت بات": "",
                "نام مجموعه": "",
            }
        ).text

        self.primary_assistant_prompt = ChatPromptTemplate.from_messages(
            [
                ("system", ecommerce_system_prompt),
                ("system", "Current time: {time}."),
                ("system", "{current_product_context}"),
                ("placeholder", "{messages}"),
            ]
        ).partial(time=datetime.now)

        self.runnable = None

    async def init_tools_and_runnable(
        self,
        config: Config,
        ecommerce_repo: IRobotEcommerceRepository,
        collection_info: CollectionInfo,
        ecommerce_auth,
        autorag_algo: AutoRag,
        algorithm_embedding_models: dict = None,
        llm_models: dict = None,
        ecommerce_adapter_type: str = None,
    ):
        ecommerce_identifier = config.collection_identifier
        get_product_repo_tool = GetProductRepoTool(ecommerce_identifier, ecommerce_repo)

        if (
            collection_info.prompts is not None
            and "search_products_by_name_repo_tool_prompt" in collection_info.prompts
        ):
            search_products_by_name_repo_tool_prompt = collection_info.prompts[
                "search_products_by_name_repo_tool_prompt"
            ]
        else:
            search_products_by_name_repo_tool_prompt = None

        if collection_info.prompts is not None and "validator_search_prompt" in collection_info.prompts:
            validator_search_prompt = collection_info.prompts.get("validator_search_prompt")
        else:
            validator_search_prompt = None

        search_products_by_name_repo_tool = SearchProductsByNameRepoTool(
            ecommerce_identifier,
            ecommerce_repo,
            search_products_by_name_repo_tool_prompt,
            embedding_models=algorithm_embedding_models,
            llm_models=llm_models,
            validator_retriever_prompt=validator_search_prompt,
            ecommerce_adapter_type=ecommerce_adapter_type,
        )

        if collection_info.prompts is not None and "get_orders_tool_prompt" in collection_info.prompts:
            get_orders_tool_prompt = collection_info.prompts["get_orders_tool_prompt"]
        else:
            get_orders_tool_prompt = None

        # Get order tracking method config (default to "both" for backward compatibility)
        order_tracking_method = getattr(collection_info, "order_tracking_method", "both") or "both"

        # Add GetOrderTool if order_tracking_method is "order_number" or "both"
        if order_tracking_method in ["order_number", "both"]:
            get_order_tool = GetOrderTool(ecommerce_auth, get_orders_tool_prompt)
            await get_order_tool.get_custom_statuses()
        else:
            get_order_tool = None

        connect_operator_tool = ConnectOperatorTool()

        self.tools = [
            get_product_repo_tool,
            search_products_by_name_repo_tool,
            connect_operator_tool,
        ]

        # Add GetOrderTool if configured
        if get_order_tool:
            self.tools.insert(0, get_order_tool)

        # Add GetCustomersOrdersTool if order_tracking_method is "customer_info" or "both"
        # and adapter type is not Mixin or Digify
        if order_tracking_method in ["customer_info", "both"] and ecommerce_adapter_type not in ["Mixin", "Digify"]:
            if collection_info.prompts is not None and "get_customers_orders_tool_prompt" in collection_info.prompts:
                get_customers_orders_tool_prompt = collection_info.prompts["get_customers_orders_tool_prompt"]
            else:
                get_customers_orders_tool_prompt = None
            get_customers_orders_tool = GetCustomersOrdersTool(ecommerce_auth, get_customers_orders_tool_prompt)
            await get_customers_orders_tool.get_custom_statuses()
            self.tools.append(get_customers_orders_tool)
        if autorag_algo is not None:
            if collection_info.prompts is not None and "auto_rag_tool_prompt" in collection_info.prompts:
                auto_rag_tool_prompt = collection_info.prompts["auto_rag_tool_prompt"]
            else:
                auto_rag_tool_prompt = None
            autorag_tool = AutoRAGTool(autorag_algo, auto_rag_tool_prompt)
            self.tools.append(autorag_tool)

        self.runnable = self.primary_assistant_prompt | self.llm_model.bind_tools(self.tools)

    async def __call__(self, state: State, config: RunnableConfig):
        if not self.runnable:
            LOGGER.error("graph's runnable is not defined! Await assistant.init_tools_and_runnable() first.")
            return
        if state.get("ai_tag") == 3:
            return {}
        while True:
            configuration = config.get("configurable", {})
            language = configuration.get("query_language", "PERSIAN")
            state_with_context = {
                **state,
                "language": language,
                "current_product_context": self.get_product_context(state),
            }
            result = await self.runnable.ainvoke(state_with_context)
            if not result.tool_calls and (
                not result.content or isinstance(result.content, list) and not result.content[0].get("text")
            ):
                messages = state["messages"] + [("user", "Respond with a real output.")]
                state = {**state, "messages": messages}
            else:
                break
        return {"messages": result}

    def get_product_context(self, state: State) -> str:
        """Get the current product context for the assistant."""
        if state.get("current_product"):
            product = state["current_product"]
            current_product_context = f"""
────────────────────────────────────────────────
CURRENT PRODUCT OF INTEREST
────────────────────────────────────────────────
The user is currently viewing this product:
{product}

When the user asks questions, consider this product as their primary context unless they specify otherwise.
────────────────────────────────────────────────
"""
        else:
            current_product_context = "No current product context available."

        return current_product_context

