class CategoryRouter:
    """Routes user queries to the most relevant category and retrieves category attributes."""

    def __init__(
        self,
        llm_models: Dict,
        collection_info: CollectionInfo,
        ecommerce_repo: IRobotEcommerceRepository,
    ):
        self.llm = llm_models["llm_model"]
        self._collection_info = collection_info
        self._ecommerce_repo = ecommerce_repo
        self._ecommerce_identifier = collection_info.identifier

        if collection_info.prompts is not None and "category_router_prompt" in collection_info.prompts:
            category_router_prompt = collection_info.prompts["category_router_prompt"]
        else:
            category_router_prompt = """You are a category routing assistant for an e-commerce platform.

Your task is to analyze the user's query and determine the most relevant product category.

Available categories: {categories}

Sample products for each category:
{category_samples}

User messages: {user_messages}

Based on the user's query, determine:
1. The most relevant category from the available categories
2. If no relevant category is found, return "none"

Instructions:
- Only return one of the available categories or "none"
- Consider the context of the conversation
- Match the user's intent to the most appropriate category
- If the user's query doesn't match any category, return "none"

Return only the category name (exactly as listed) or "none"."""

        self.category_router_prompt = ChatPromptTemplate.from_messages(
            [
                ("system", category_router_prompt),
                ("human", "User query: {query}"),
            ]
        )

        self.runnable = self.category_router_prompt | self.llm

    def _get_messages_excluding_tool_calls(self, state: ProductSearcherState) -> List[str]:
        """Extract all messages from state, excluding AI messages with tool calls.

        Args:
            state: The current product searcher state.

        Returns:
            List of message contents excluding AI messages that contain tool calls.
        """
        return [
            msg.content
            for msg in state.get("messages", [])
            if hasattr(msg, "content") and msg.content and not (hasattr(msg, "tool_calls") and msg.tool_calls)
        ]

    async def __call__(
        self,
        state: ProductSearcherState,
        config: RunnableConfig,
    ) -> Dict[str, Any]:
        """Route user query to appropriate category and set up category attributes."""
        try:
            category_indexings = await self._ecommerce_repo.get_all_category_indexings(self._ecommerce_identifier)

            if not category_indexings:
                LOGGER.warning(f"No category indexings found for {self._ecommerce_identifier}")
                return await self._handle_no_categories(state)

            categories = []
            category_samples = {}

            for category_indexing in category_indexings:
                category_name = category_indexing.category_name
                categories.append(category_name)

                if category_indexing.sampled_products:
                    sample_products = await self._ecommerce_repo.get_products_by_ids(
                        self._ecommerce_identifier, category_indexing.sampled_products[:3]
                    )
                    category_samples[category_name] = [p.name for p in sample_products]
                else:
                    category_samples[category_name] = []

            user_messages = self._get_messages_excluding_tool_calls(state)

            if not user_messages:
                return await self._handle_no_categories(state)

            user_query = " ".join(user_messages[-2:])

            result = await self.runnable.ainvoke(
                {
                    "query": user_query,
                    "categories": categories,
                    "category_samples": category_samples,
                    "user_messages": user_messages,
                }
            )

            selected_category = result.content.strip()

            if selected_category == "none" or selected_category not in categories:
                return await self._handle_no_categories(state)

            category_attributes = await self._ecommerce_repo.search_category_attributes(
                ecommerce_identifier=self._ecommerce_identifier, category_name=selected_category, max_results=40
            )
            category_attributes = sorted(category_attributes, key=lambda attr: attr.get("priority", 0))
            retrieved_products = await self.get_category_products(selected_category)

            return {
                "selected_category": selected_category,
                "available_categories": categories,
                "category_attributes": category_attributes,
                "dialog_state": "category_router",
                "retrieved_products": retrieved_products,
            }

        except Exception as e:
            LOGGER.error(f"Error in CategoryRouter: {e}")
            return await self._handle_no_categories(state)

    async def get_category_products(self, selected_category: str) -> List[Dict[str, Any]]:
        """Retrieve and process products for a specific category.

        Args:
            selected_category: Name of the category to retrieve products for.

        Returns:
            List of product dictionaries containing essential product properties.
        """
        essential_product_properties = [
            "id",
            "name",
            "permalink",
            "price_html",
            "price",
            "regular_price",
            "sale_price",
            "on_sale",
            "stock_status",
            "average_rating",
            "categories",
            "custom_categories",
            "custom_attributes",
        ]

        retrieved_products = await self._ecommerce_repo.get_products_by_custom_category(
            ecommerce_identifier=self._ecommerce_identifier, category_name=selected_category, size=10000
        )

        product_dicts = []
        for product in retrieved_products:
            product.permalink = unquote(str(product.permalink))
            product_dict = product.model_dump(exclude_none=True)
            product_dicts.append(product_dict)

        processed_product_dicts = [
            {key: product_dict[key] for key in essential_product_properties if key in product_dict}
            for product_dict in product_dicts
        ]
        return processed_product_dicts

    async def _handle_no_categories(self, state: ProductSearcherState) -> Dict[str, Any]:
        """Handle case when no relevant category is found."""
        try:
            category_indexings = await self._ecommerce_repo.get_all_category_indexings(self._ecommerce_identifier)
            available_categories = [c.category_name for c in category_indexings]
        except Exception:
            available_categories = []

        language = state.get("language", "PERSIAN")

        if str.lower(language) == "persian":
            if available_categories:
                categories_text = "، ".join(available_categories)
                message = f"متاسفانه چنین محصولی نداریم. دسته‌بندی‌های موجود: {categories_text}"
            else:
                message = "متاسفانه هیچ دسته‌بندی محصولی موجود نیست."
        else:
            if available_categories:
                categories_text = ", ".join(available_categories)
                message = f"We don't have such products. Available categories are: {categories_text}"
            else:
                message = "No product categories are available."

        last_message = state.get("messages", [])[-1] if state.get("messages") else None
        if (
            hasattr(last_message, "tool_calls")
            and last_message.tool_calls
            and last_message.tool_calls[0].get("name") == "filter_products_by_attributes_tool"
        ):
            tool_call_id = last_message.tool_calls[0].get("id")
            return {
                "messages": [ToolMessage(content=message, tool_call_id=tool_call_id)],
                "available_categories": available_categories,
                "dialog_state": "category_router",
            }
        else:
            return {
                "messages": [AIMessage(content=message)],
                "available_categories": available_categories,
                "dialog_state": "category_router",
            }

