def _product_searcher_tools_condition(
    state: ProductSearcherState,
    messages_key: str = "messages",
) -> Literal["product_searcher_tools", "tool_input_validator", "category_router", "__end__"]:
    if isinstance(state, list):
        ai_message = state[-1]
    else:
        messages = _extract_messages_from_state(state, messages_key)
        if not messages:
            raise ValueError(f"No messages found in input state to tool_edge: {state}")
        ai_message = messages[-1]

    if hasattr(ai_message, "tool_calls") and len(ai_message.tool_calls) > 0:
        tool_name = ai_message.tool_calls[0].get("name")
        if tool_name == "filter_products_by_attributes_tool":
            # Check if category attributes are available, if not go to category router first
            if not state.get("category_attributes"):
                return "category_router"
            return "tool_input_validator"
