    state: ProductSearcherState,
) -> Literal["tool_input_validator", "product_searcher_assistant", "human", "__end__"]:
    """Determine routing after category router based on state."""
    if state.get("selected_category") and state.get("category_attributes"):
        return "tool_input_validator"

    if state.get("available_categories") is None:
        return "human"

    return "product_searcher_assistant"

