class ResultsEvaluator:
    def __init__(
        self,
        llm_models: Dict,
        collection_info: CollectionInfo,
        ecommerce_repo: IRobotEcommerceRepository,
    ):
        self._ecommerce_identifier = collection_info.identifier
        self._ecommerce_repo = ecommerce_repo

        self.llm = llm_models["llm_model"]

        # TODO: add new custom prompts to the collection settings prompts
        if (
            collection_info.prompts is not None
            and "product_searcher_results_evaluator_prompt" in collection_info.prompts
        ):
            product_searcher_results_evaluator_prompt = collection_info.prompts[
                "product_searcher_results_evaluator_prompt"
            ]
        else:
            # TODO: use identified tone mode during indexing
            product_searcher_results_evaluator_prompt = """\
You are helping a customer choose the best product from a list of matched options. You speak in {language}.

Show the customer a brief summary of the top matched products.

Then, ask the customer a clarifying question about the provided attribute to help narrow down the options further.

Use friendly and clear language. Encourage the customer to answer briefly, such as by choosing from suggested \
options or giving a preference.

Remember to speak in the {language} language.
"""

        self.product_searcher_results_evaluator_prompt = ChatPromptTemplate.from_messages(
            [
                ("system", product_searcher_results_evaluator_prompt),
                ("placeholder", "{messages}"),
                ("human", "top products: {top_products}\nattribute to ask about: {attribute}"),
            ]
        )

        self.runnable = self.product_searcher_results_evaluator_prompt | self.llm

    async def __call__(
        self,
        state: ProductSearcherState,
        config: RunnableConfig,
    ):
        configuration = config.get("configurable", {})
        language = configuration.get("query_language", "PERSIAN")
        products = state.get("retrieved_products", [])

        if len(products) == 0:
            if str.lower(language) == "persian":
                message = (
                    "متاسفانه با ویژگی های مشخص شده محصولی یافت نشد. لطفا گزینه دیگری را برای این ویژگی انتخاب کنید."
                )
            else:
                message = "No products found for this attribute! Please choose another option."
            return Command(
                update={
                    "messages": [AIMessage(message)],
                    "human_input_prompt": message,
                    "dialog_state": "results_evaluator",
                },
                goto="human",
            )
        elif len(products) <= 2:
            return Command(goto="product_searcher_assistant")
        else:
            top_products = return_top_n_products(products, n=2)
            for tp in top_products:
                [tp.pop(k, None) for k in ["categories", "attributes"]]
                if tp.get("custom_attributes"):
                    [att.pop("vector", None) for att in tp["custom_attributes"]]

            category_attributes = state.get("category_attributes", [])
            if not category_attributes:
                return Command(goto="product_searcher_assistant")

            if not state.get("attribute"):
                # First time - use highest priority attribute
                attribute = category_attributes[0]
            else:
                # Not the first time - get next attribute in priority order
                last_attribute = state.get("attribute")
                try:
                    last_index = next(
                        i for i, attr in enumerate(category_attributes) if attr["name"] == last_attribute["name"]
                    )
                    attribute = (
                        category_attributes[last_index + 1]
                        if last_index + 1 < len(category_attributes)
                        else category_attributes[0]
                    )
                except (ValueError, StopIteration, KeyError):
                    attribute = category_attributes[0]

            _input = {
                "language": language,
                "messages": state["messages"],
                "top_products": top_products,
                "attribute": {"name": attribute["name"], "description": attribute["description"]},
            }
            result = await self.runnable.ainvoke(_input)

            return Command(
                update={
                    "messages": [AIMessage(result.content)],
                    "human_input_prompt": result.content,
                    "category_attributes": category_attributes,
                    "attribute": attribute,
                    "dialog_state": "results_evaluator",
                    "top_products": top_products,
                    "language": language,
                },
                goto="human",
            )

