class FilterProductsByAttributesTool(BaseTool):
    name: str = "filter_products_by_attributes_tool"
    description: str = """\
USE THIS TOOL FOR ATTRIBUTE-BASED PRODUCT DISCOVERY AND FILTERING.

═══════════════════════════════════════════════════════════════════════════════
PRIMARY USE CASES:
═══════════════════════════════════════════════════════════════════════════════
1. GENERAL PRODUCT CATEGORY SEARCHES (no specific product name):
   - "کفش ورزشی میخوام" (I want sports shoes)
   - "دریل پیچ گوشتی قوی دارین؟" (Do you have powerful screwdrivers?)
   - "موبایل سامسونگ نشون بده" (Show me Samsung phones)

2. ATTRIBUTE-BASED FILTERING (after products are shown):
   - "کدوم یکی آبی هست؟" (Which one is blue?)
   - "سایز ۴۲ کدومه؟" (Which one is size 42?)
   - "رنگ قرمز دارین؟" (Do you have red color?)
   - "دسته قرمز کدومشونه؟" (Which ones have red handles?)

3. REFINEMENT QUESTIONS:
   - "ارزون‌ترشو نشون بده" (Show me the cheaper one)
   - "برند نایک دارین؟" (Do you have Nike brand?)
   - "کدومشون ضدآب هست؟" (Which ones are waterproof?)

═══════════════════════════════════════════════════════════════════════════════
DECISION FLOWCHART:
═══════════════════════════════════════════════════════════════════════════════
User Query → Does it mention EXACT product name/model/code?
    ├─ YES: Use search_products_repo_tool
    └─ NO: Does it ask about attributes/characteristics/categories?
        ├─ YES: Use filter_products_by_attributes_tool ✓
        └─ NO: Use filter_products_by_attributes_tool (general search)

EXAMPLES:
✓ "کفش کتونی میخوام" → filter_products_by_attributes_tool
✓ "کدومشون آبی رنگه؟" → filter_products_by_attributes_tool
✓ "سایز بزرگ دارین؟" → filter_products_by_attributes_tool
✗ "آیفون ۱۵ پرو دارین؟" → search_products_repo_tool (exact product name)
"""
    args_schema: Type[BaseModel] = FilterProductsByAttributesInput

    def __init__(
        self,
        ecommerce_identifier: str,
        ecommerce_repo: IRobotEcommerceRepository,
        embedding_models: Dict[str, Any],
        tool_prompt: str | None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self._ecommerce_identifier = ecommerce_identifier
        self._ecommerce_repo = ecommerce_repo
        self._embedding_models = embedding_models
        self._config = Config()
        if tool_prompt is not None:
            self.description = tool_prompt

    def _run(
        self,
        search_attributes: dict[str, Any],
        state: Annotated[Dict[str, Any], InjectedState],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> str:
        return "This method should be called asynchronously."

    async def _arun(
        self,
        search_attributes: dict[str, Any],
        state: Annotated[Dict[str, Any], InjectedState],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> Command:
        essential_product_properties = [
            "id",
            "name",
            "permalink",
            "price_html",
            "price",
            "regular_price",
            "sale_price",
            "on_sale",
            "stock_status",
            "average_rating",
            "categories",
            "custom_categories",
            "custom_attributes",
        ]
        tool_call_id = None
        try:
            tool_call_id = state["messages"][-1].tool_calls[-1]["id"]

            input_products = state.get("retrieved_products", [])

            if not input_products:
                LOGGER.warning("No input products found in state for filtering")
                tool_message_content = (
                    "No products available to filter. Please search for products first. "
                    f"Remember to answer in the {state.get('language', 'PERSIAN')} language."
                )
                return Command(
                    update={
                        "messages": [ToolMessage(tool_message_content, tool_call_id=tool_call_id)],
                    }
                )

            if not search_attributes:
                LOGGER.debug("Empty search attributes, returning all input products")
                return Command(
                    update={
                        "messages": [
                            ToolMessage(
                                f"# matches:\n {input_products[:5]}",
                                tool_call_id=tool_call_id,
                            )
                        ],
                        "retrieved_products": input_products,
                    }
                )

            product_ids = self._extract_product_ids(input_products)

            if not product_ids:
                LOGGER.warning("No valid product IDs found in input products")
                tool_message_content = (
                    "No valid products found to filter. "
                    f"Remember to answer in the {state.get('language', 'PERSIAN')} language."
                )
                return Command(
                    update={
                        "messages": [ToolMessage(tool_message_content, tool_call_id=tool_call_id)],
                    }
                )

            embedding_model = self._embedding_models.get("search_embedding_model")

            category_attributes = state.get("category_attributes", [])
            (
                keyword_search_attributes,
                numeric_search_attributes,
                float_range_search_attributes,
            ) = self._parse_search_attributes(search_attributes, category_attributes)

            attribute_vectors = {}
            for attr_key, attr_val in keyword_search_attributes.items():
                try:
                    vector = await embedding_model.aembed_query(str(attr_val))
                    attribute_vectors[attr_key] = normalize_l2(vector[: self._config.embed_size["attribute_search"]])
                except Exception as e:
                    LOGGER.warning(f"Failed to generate embedding for attribute {attr_key}: {e}")
                    continue

            products = input_products
            if attribute_vectors:
                products, _ = await self._vector_filter(attribute_vectors, product_ids, products)
                product_ids = [p.id for p in products]
            if float_range_search_attributes:
                products, _ = await self._float_range_filter(float_range_search_attributes, product_ids, products)
                product_ids = [p.id for p in products]
            if numeric_search_attributes:
                products, _ = await self._numeric_filter(numeric_search_attributes, product_ids, products)

            if len(products) == 0:
                LOGGER.warning(f"No products found for vector query {keyword_search_attributes}")
                tool_message_content = (
                    "No products found with this query. "
                    "Ask the user to refine their search query if they want. "
                    f"Remember to answer in the {state.get('language', 'PERSIAN')} language."
                )
                return Command(
                    update={
                        "messages": [ToolMessage(tool_message_content, tool_call_id=tool_call_id)],
                    }
                )

            processed_products = self._products_to_dicts(products, essential_product_properties)
            search_results = f"# matches:\n {processed_products[:5]}"
            return Command(
                update={
                    "messages": [ToolMessage(search_results, tool_call_id=tool_call_id)],
                    "retrieved_products": processed_products,
                }
            )
        except Exception as e:
            LOGGER.warning(
                f"There was a problem in searching for products with the attribute query '{search_attributes}': {e}"
            )
            tool_message_content = (
                "There was a problem in searching for the products. Ask the user if they want to try again. "
                f"Remember to answer in the {state.get('language', 'PERSIAN')} language."
            )
            if tool_call_id:
                tool_message = ToolMessage(tool_message_content, tool_call_id=tool_call_id)
            else:
                tool_message = SystemMessage(tool_message_content)
            return Command(
                update={
                    "messages": [tool_message],
                }
            )

    def _extract_product_ids(self, input_products: list[dict[str, Any]]) -> list[str]:
        """Extract valid product IDs from input products."""
        return [str(product.get("id")) for product in input_products if product.get("id")]

    def _parse_search_attributes(
        self, search_attributes: dict[str, Any], category_attributes: list[dict[str, Any]]
    ) -> tuple[dict[str, str], list[dict[str, Any]], list[dict[str, Any]]]:
        """Split search attributes into keyword, numeric, and float_range groups, grouping float_range by attribute and suffix."""
        keyword_search_attributes = {}
        numeric_search_attributes = []
        float_range_grouped: dict[str, dict[str, float]] = {}
        for attr_key, attr_val in search_attributes.items():
            if attr_key.endswith("_min"):
                bare_name = attr_key.removesuffix("_min")
                suffix = "min"
            elif attr_key.endswith("_max"):
                bare_name = attr_key.removesuffix("_max")
                suffix = "max"
            else:
                bare_name = attr_key
                suffix = None
            matching_attr = next((attr for attr in category_attributes if attr.get("name") == bare_name), None)
            if matching_attr:
                value_type = matching_attr.get("value_type")
                if value_type == "float_range":
                    if bare_name not in float_range_grouped:
                        float_range_grouped[bare_name] = {}
                    if suffix == "min":
                        float_range_grouped[bare_name]["gte"] = attr_val
                    elif suffix == "max":
                        float_range_grouped[bare_name]["lte"] = attr_val
                elif value_type in ["integer", "long", "float", "date"]:
                    value_type = "int" if value_type == "integer" else value_type
                    numeric_search_attributes.append(
                        {
                            "bare_name": bare_name,
                            "suffix": suffix,
                            "value_type": value_type,
                            "value": attr_val,
                        }
                    )
                else:
                    keyword_search_attributes[attr_key] = str(attr_val)
        # Convert grouped float_range to the expected list of dicts
        float_range_search_attributes = []
        for bare_name, range_dict in float_range_grouped.items():
            float_range_search_attributes.append(
                {
                    "bare_name": bare_name,
                    "value_type": "float_range",
                    "range": range_dict,
                }
            )
        return keyword_search_attributes, numeric_search_attributes, float_range_search_attributes

    async def _vector_filter(
        self, attribute_vectors: dict[str, Any], product_ids: list[str], products: list[Any]
    ) -> tuple[list[Any], list[float]]:
        if not attribute_vectors:
            return products, []
        products, scores = await self._ecommerce_repo.search_products_by_custom_attributes_vector(
            self._ecommerce_identifier,
            attribute_vectors,
            product_ids,
            max_results=20,
            min_score=0.5,
        )
        return products, scores

    async def _float_range_filter(
        self, float_range_search_attributes: list[dict[str, Any]], product_ids: list[str], products: list[Any]
    ) -> tuple[list[Any], list[float]]:
        if not float_range_search_attributes:
            return products, []
        products, scores = await self._ecommerce_repo.filter_products_by_float_range_custom_attributes(
            self._ecommerce_identifier, float_range_search_attributes, product_ids
        )
        return products, scores

    async def _numeric_filter(
        self, numeric_search_attributes: list[dict[str, Any]], product_ids: list[str], products: list[Any]
    ) -> tuple[list[Any], list[float]]:
        if not numeric_search_attributes:
            return products, []
        products, scores = await self._ecommerce_repo.filter_products_by_numeric_custom_attributes(
            self._ecommerce_identifier, numeric_search_attributes, product_ids
        )
        return products, scores

    def _products_to_dicts(self, products: list[Any], essential_product_properties: list[str]) -> list[dict[str, Any]]:
        product_dicts = []
        for product in products:
            product.permalink = unquote(str(product.permalink))
            product_dict = product.model_dump()
            product_dicts.append(product_dict)
        return [{key: product_dict.get(key) for key in essential_product_properties} for product_dict in product_dicts]

