            {"manufacturer": "samsung"},
        ],
    )
    state: Annotated[Dict[str, Any], InjectedState] = Field(description="The state of the graph.")

def print_event(event: dict, _printed: set, max_length=1500):
    current_state = event.get("dialog_state")
    if current_state:
        LOGGER.info(f"*** Currently in: {current_state}")
    message = event.get("messages")
    if message:
        if isinstance(message, list):
            message = message[-1]
        if message.id not in _printed:
            msg_repr = message.pretty_repr(html=True)
            if len(msg_repr) > max_length:
                msg_repr = msg_repr[:max_length] + " ... (truncated)"
            LOGGER.info(msg_repr)
            _printed.add(message.id)

def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    content = f"Error: {repr(error)}\n please fix your mistakes."
    if "validation" in str(error):
        content += " Fix your input to match the correct format."
    return {
        "messages": [
            ToolMessage(
                content=content,
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ],
    }

class AutoRag:
    def __init__(
        self,
        db_repository: RobotCollectionRepository,
        collection_identifier: str,
        llm_models: ILLMModel,
        embedding_models: IEmbeddingModelFactory,
        reranker_models: IRerankerModel,
        generation_prompts: IGenerationPrompts,
        config: AutoRagConfig,
        collection_info: CollectionInfo = None,
    ):
        self.db_repository = db_repository
        self.collection_identifier = collection_identifier
        self.llm_models = llm_models
        self.embedding_models = embedding_models
        self.collection_info = collection_info
        self.generation_prompts = deepcopy(generation_prompts)
        self.original_generation_prompts = deepcopy(generation_prompts)
        self.config = config
        self.reranker_models = reranker_models
        self.query_processor: QueryProcessor | None = None
        self.retriever: CustomRetriever | None = None
        self.reranker: ReRanker | None = None
        self.generator = None
        self.base_model = None

    async def load_autorag_processors(self):
        if self.collection_info is None:
            await self.get_collection_info()

        self.references_heading = references_language_mapping.get(
            self.collection_info.language,
            references_language_mapping["English"],
        )

        if self.collection_identifier in SpecificUsers().local_model_users:
            self.base_model = self.llm_models["local_model"]
            self.llm_models["light-model"] = self.llm_models["local_model"]
            self.embedding_models["embedding_model"] = self.embedding_models["embedding_local_model"]
        else:
            self.base_model = self.llm_models["light-model"]

        self.query_processor = QueryProcessor(
            collection_info=self.collection_info,
            llm_models=self.llm_models,
        )

        self.load_prompts()
        self.retriever = self.load_retriever()

        if self.collection_identifier in SpecificUsers().monitoring_user_reranker:
            reranker_llm_model = self.llm_models["4.1-nano"]
            reranker_llm_model._openai_fallback = self.base_model
        else:
            reranker_llm_model = self.base_model
        self.reranker = self.load_reranker(self.reranker_models, reranker_llm_model)

        self.generator = self.load_generator()
        self.show_reference_chain = self.load_show_reference_chain()
        if self.collection_identifier in SpecificUsers().hallucination_monitoring:
            hallucination_model = self.llm_models["gemini-model"]
            hallucination_model._openai_fallback = self.base_model
        else:
            hallucination_model = self.base_model

        self.hallucination_checker = HallucinationChecker(hallucination_model, self.collection_info)
        self.load_generation_chains()

    async def get_collection_info(self):
        _collection_info = await self.db_repository.get_collection_info_by_id(
            self.collection_identifier,
        )
        self.collection_info = _collection_info

    def load_retriever(self) -> CustomRetriever:
        return CustomRetriever(
            config=RetrieverConfig(),
            db_repository=self.db_repository,
            collection_info=self.collection_info,
            llm_models=self.llm_models,
            embedding_models=self.embedding_models,
            query_processor=self.query_processor,
        )

    def load_reranker(self, lm_model_dict, llm_model=None) -> ReRanker:
        return ReRanker(
            lm_model=lm_model_dict,
            llm_model=llm_model if llm_model is not None else self.base_model,
        )

    def load_generator(self):
        return self.base_model

    def load_prompts(self):
        if self.collection_info.prompts is not None:
            for attr_name in dir(self.generation_prompts):
                if attr_name.endswith("_prompt"):
                    prompt = self.collection_info.prompts.get(attr_name, False)
                    if not prompt:
                        prompt = self.original_generation_prompts.__getattribute__(
                            attr_name,
                        )
                    self.generation_prompts.__setattr__(attr_name, prompt)

    def load_generation_chains(self):
        try:
            self.hallucination_checker.load_chains(self.collection_info.prompts)
            for attr in dir(self.generation_prompts):
                if attr.endswith("_message_template"):
                    template = self.generation_prompts.__getattribute__(attr)
                    chain_name = attr.removesuffix("_message_template") + "_query_generation_chain"
                    chain = (
                        template
                        | self.base_model
                        | llm_result_correction_chain
                        | self.generation_prompts.auto_rag_output_parser
                    )
                    self.__setattr__(chain_name, chain)
        except Exception as e:
            LOGGER.error(f"Error loading generation chains: {e}")

    def load_show_reference_chain(self):
        prompt_object = ReferenceRelevancy()
        return (
            prompt_object.template | self.llm_models["light-model"] | llm_result_correction_chain | prompt_object.parser
        )

    def docs_retriever_to_string(self, retrieved_docs: Dict[str, List[Document] | List[dict]]) -> str:
        flatten_docs = (
            [doc for docs in retrieved_docs.values() for doc in docs]
            if isinstance(retrieved_docs, dict)
            else retrieved_docs
        )
        docs_ids = [doc.metadata["id"] for doc in flatten_docs]
        if flatten_docs:
            docs_string = DocFormatter.format_retrieved_docs(flatten_docs)
        else:
            docs_string = "didn't found any related information!"
        return docs_string, docs_ids

    async def docs_dependent_generation(
        self,
        input_message: str,
        refined_query: str,
        retrieved_docs: Dict[str, List[Document]],
        history_string: str,
        query_tag: QueryTag = QueryTag.NORMAL,
        language: str = "PERSIAN",
        input_source: str = "live_chat",
        ai_report_tag: ReportTag = None,
    ) -> GeneratorResult:
        for doc_type in retrieved_docs.keys():
            for doc in retrieved_docs[doc_type]:
                await self.cite_references_to_docs(doc)

        docs_string, docs_ids = self.docs_retriever_to_string(retrieved_docs)

        if query_tag == QueryTag.EXPLAIN_MORE:
            if docs_string.startswith("IMPORTANT DOCUMENTS:"):
                chain_name = "more_explain_manual_docs_query_generation_chain"
            else:
                chain_name = "more_explain_query_generation_chain"
        elif query_tag == QueryTag.NORMAL:
            # Do we need to talk about manual docs in generation prompt?
            if docs_string.startswith("IMPORTANT DOCUMENTS:"):
                chain_name = "related_manual_docs_query_generation_chain"
            else:
                chain_name = "related_query_generation_chain"

        LOGGER.debug("Stage4.1: The Generate Response has been Started.")

        today = jdatetime.date.today()
        result = await run_chain(
            chain=self.__getattribute__(chain_name),
            parameters={
                "title": self.collection_info.title
                if self.collection_info.manual_title is None
                else self.collection_info.manual_title,
                "language": language,
                "context": docs_string,
                "message": input_message,
                "history": history_string,
                "refined_query": refined_query,
                "name": self.collection_info.name + f" \n Current_Date:{str(today)} {today.strftime('%A')}",
            },
            config={"temperature": self.collection_info.temperature},
            max_retries=self.config.chain_call_max_retries,
            name=chain_name,
            assertion="result['generated_response']",
        )
        generated_response = result["generated_response"]

        reference_ids = self.remove_non_link_references(result.get("references", []))

        references = ""

        if reference_ids and self.collection_info.show_reference.get(input_source, False):
            references = self.references_heading
            for i, reference in enumerate(reference_ids, start=1):
                decoded_reference = unquote(reference)
                references = references + str(i) + ". " + decoded_reference + "\n"

        response = generated_response + references

        if result.get("tag", "normal") == "not_enough":
            query_tag = QueryTag.CONNECT_OPERATOR
            return GeneratorResult(
                generated_text=response + InferenceMessages.no_information_available[language],
                ai_tag=AiTagType.ASSIGN_OPERATOR,
                retrieved_docs=docs_ids,
                ai_report_tag=ReportTag.MISINFORMATION,
            )
        process_cost = 1

        if self.collection_info.use_response_verification:
            LOGGER.debug(
                f"""f"Stage4.2: The Verified Generate Response has been Started. \n Previous Response: \n\t{response}"""
            )

            if self.collection_info.identifier in SpecificUsers.monitoring_user_reranker:
                rerankes_docs = await self.reranker(
                    input_message, generated_response, retrieved_docs, identifier=self.collection_identifier
                )
                docs_string, _ = self.docs_retriever_to_string(rerankes_docs)
                if rerankes_docs == []:
                    return GeneratorResult(
                        generated_text=response,
                        ai_tag=AiTagType.ASSIGN_OPERATOR,
                        retrieved_docs=docs_ids,
                        client_state={},
                        process_cost=process_cost,
                        ai_report_tag=ReportTag.MISINFORMATION,
                    )

            revised_response = await self.hallucination_checker.revise_generated_answer(
                input_message,
                refined_query,
                history_string,
                generated_response,
                docs_string,
                language,
            )
            process_cost = 2 if self.collection_info.identifier not in SpecificUsers.discount_pricing_user else 1
            original_response = response
            response = f"{revised_response['revised_response']}\n{references}"
            if revised_response.get("tag", "normal") == "not_enough":
                query_tag = QueryTag.CONNECT_OPERATOR
            if revised_response.get("tag", "normal") == "unmatched_subject":
                response = f"{revised_response['revised_response']}\n\
{choice(InferenceMessages.further_help[language])}\n{references}"
                query_tag = QueryTag.NORMAL
                client_state = {
                    "last_state": {
                        "unmatched_subject": True,
                        "original_response": original_response,
                        "revised_response": response,
                        "challeng_num": 1,
                    }
                }

        return GeneratorResult(
            generated_text=response,
            ai_tag=AiTagType.ASSIGN_OPERATOR if query_tag == QueryTag.CONNECT_OPERATOR else AiTagType.INFO,
            retrieved_docs=docs_ids,
            client_state=client_state if "client_state" in locals() else {},
            process_cost=process_cost,
            ai_report_tag=ReportTag.SUCCESSFULLY_RESPONDED,
        )

    async def docs_independent_generation(
        self,
        input_data: AlgorithmInput,
        query_processor_tasks: Dict,
        history_string: str,
        query_tag: QueryTag = QueryTag.NORMAL,
        language: str = "Persian",
        docs_ids: List[str] = None,
        ai_report_tag: ReportTag = None,
    ) -> GeneratorResult:
        if query_processor_tasks["spam"]["result"] == SpamResult.SPAM:
            chain_name = "spam_query_generation_chain"
        elif query_processor_tasks["insult"]["result"] == InsultResult.INSULT:
            chain_name = "insult_query_generation_chain"
        elif query_tag == QueryTag.CONNECT_OPERATOR:
            chain_name = "connect_operator_query_generation_chain"
        elif query_processor_tasks["relevance"]["result"] == RelevanceDegree.NOT_RELATED:
            chain_name = "unrelated_query_generation_chain"
            ai_report_tag = ReportTag.UNRELATED
            if isinstance(input_data.client_state, dict) and "is_not_related" in (
                input_data.client_state.get("last_state", {})
            ):
                return GeneratorResult(
                    generated_text=InferenceMessages.not_related_message,
                    ai_tag=AiTagType.ASSIGN_OPERATOR,
                    client_state={},
                    retrieved_docs=docs_ids,
                    ai_report_tag=ReportTag.UNRELATED,
                )

            else:
                client_state = {"last_state": {"is_not_related": True}}

        elif query_processor_tasks["relevance"]["result"] == RelevanceDegree.GENERAL:
            chain_name = "general_query_generation_chain"
            ai_report_tag = ReportTag.SUCCESSFULLY_RESPONDED
            client_state = {}

        result = await run_chain(
            chain=self.__getattribute__(chain_name),
            parameters={
                "title": self.collection_info.title
                if self.collection_info.manual_title is None
                else self.collection_info.manual_title,
                "language": language,
                "history": history_string,
                "query": input_data.message,
                "name": self.collection_info.name,
            },
            config={"temperature": self.collection_info.temperature},
            max_retries=self.config.chain_call_max_retries,
            name=chain_name,
            assertion="result['generated_response']",
        )

        generated_response = result.get("generated_response", "")

        try:
            client_state_value = client_state
        except NameError:
            client_state_value = {}
        result = GeneratorResult(
            generated_text=generated_response,
            client_state=client_state_value,
            retrieved_docs=docs_ids,
            ai_report_tag=ReportTag.UNKNOWN if ai_report_tag is None else ai_report_tag,
        )
        return result

    async def cite_references_to_docs(self, doc: Document) -> None:
        try:
            if "chunk_ids" in doc.metadata:
                chunk_id = doc.metadata["chunk_ids"][0]
                chunk = await self.db_repository.get_chunk_by_id(
                    collection_identifier=self.collection_identifier,
                    chunk_id=chunk_id,
                )
                reference_data_id = chunk.reference_data_id
            else:
                reference_data_id = doc.metadata["reference_data_id"]

            reference_name = await self.db_repository.get_reference_data_name_by_id(
                collection_identifier=self.collection_identifier,
                reference_data_id=reference_data_id,
            )
            reference_text = f"\n\t Reference:\n\t {reference_name}"
            doc.page_content += reference_text
        except Exception:
            pass

    def remove_non_link_references(self, references_list: List[str]) -> List[str]:
        link_references = []

        link_pattern = (
            r"(https:\/\/www\.|http:\/\/www\.|https:\/\/|http:\/\/)?"
            r"[a-zA-Z0-9]{2,}(\.[a-zA-Z]{2,})(\.[a-zA-Z]{2,})?"
        )
        file_pattern = [ext.value for ext in DataType if ext != DataType.URL]
        regex = re.compile(link_pattern)

        for reference in references_list:
            if regex.match(reference) and not any(reference.endswith(ext) for ext in file_pattern):
                link_references.append(reference)

        return link_references

    def check_frequent_more_explain(
        self,
        history: List[Dict[str, str]],
        query_tag: QueryTag,
        query_processor_tasks: Dict,
    ):
        ai_report_tag = None
        if len(history) < 2:
            return query_tag, ai_report_tag

        is_frequent_more_explain = True
        for conversation in history[-2:]:
            if conversation.get("query_tag") != QueryTag.EXPLAIN_MORE.value:
                is_frequent_more_explain = False
        if is_frequent_more_explain and query_tag == QueryTag.EXPLAIN_MORE:
            query_tag = QueryTag.CONNECT_OPERATOR
            ai_report_tag = ReportTag.CHALLENGE

        is_frequent_not_related = True
        for conversation in history[-2:]:
            if conversation.get("relevance_tag") != RelevanceDegree.NOT_RELATED.value:
                is_frequent_not_related = False
        if is_frequent_not_related and query_processor_tasks["relevance"]["result"] == RelevanceDegree.NOT_RELATED:
            query_tag = QueryTag.CONNECT_OPERATOR
            ai_report_tag = ReportTag.UNRELATED

        is_frequent_unmatched_subject = True
        for conversation in history[-2:]:
            if not conversation.get("unmatched_subject"):
                is_frequent_unmatched_subject = False
        if is_frequent_unmatched_subject:
            query_tag = QueryTag.CONNECT_OPERATOR
            ai_report_tag = ReportTag.CHALLENGE

        return query_tag, ai_report_tag

    def align_with_manual_faqs(self, input_message: str, retrieved_docs: Dict[str, List[Document]]) -> str:
        manual_faqs = [doc for doc in retrieved_docs.get("faq_docs", []) if doc.metadata.get("type") == "manual"]
        for faq in manual_faqs:
            match = re.match(r"Question: `(.*?)`, Answer: (.*)", faq.page_content, re.DOTALL)
            if match:
                question, answer = match.groups()
                question = TextProcessingUtils.preprocess_text(question)
                query = TextProcessingUtils.preprocess_text(input_message)
                if query == question:
                    return answer

    async def detect_chain(
        self,
        input_data: AlgorithmInput,
        refined_query: str,
        retrieved_docs: Dict[str, List[Document]],
    ):
        flatten_docs = [doc for docs in retrieved_docs.values() for doc in docs]
        manual_docs_str = DocFormatter.format_retrieved_docs(
            flatten_docs,
            only_manuals=True,
        )
        retrieved_docs_str = DocFormatter.format_retrieved_docs(flatten_docs)

        query_processor_tasks = {
            "spam": {
                "task": functools.partial(
                    self.query_processor.spam_detection,
                    input_data.message,
                    manual_docs_str,
                ),
                "is_active": self.collection_info.use_spam_detection,
                "result": None,
            },
            "insult": {
                "task": functools.partial(
                    self.query_processor.insult_detection,
                    input_data.message,
                    manual_docs_str,
                ),
                "is_active": self.collection_info.use_insult_detection,
                "result": None,
            },
            "relevance": {
                "task": functools.partial(
                    self.query_processor.relevance_detection,
                    refined_query,
                    retrieved_docs_str,
                ),
                "is_active": self.collection_info.use_relevance_detection,
                "result": None,
            },
        }

        query_processor_result = await asyncio.gather(
            *[task["task"]() for task in query_processor_tasks.values() if task["is_active"]],
            return_exceptions=True,
        )
        for task_name, task in query_processor_tasks.items():
            if task["is_active"]:
                query_processor_tasks[task_name]["result"] = query_processor_result.pop(
                    0,
                )
        return query_processor_tasks

    async def check_new_state(self, input_data: AlgorithmInput) -> bool:
        last_state = input_data.client_state["last_state"]
        revised_response = last_state.get("revised_response")
        alignment_result = await self.query_processor.state_alignment(
            prev_user_query=input_data.history[-1]["human"],
            bot_response=revised_response,
            user_query=input_data.message,
        )
        return alignment_result

    async def send_inference_result(
        self,
        input_data: AlgorithmInput,
        result: GeneratorResult,
        refined_query: str,
        query_language: str,
        query_tag: QueryTag,
        query_processor_tasks: Dict,
        result_state: bool = False,
    ):
        if query_processor_tasks:
            is_insult = query_processor_tasks["insult"]["result"]
            is_spam = query_processor_tasks["spam"]["result"]
            relevancy = query_processor_tasks["relevance"]["result"]
        else:
            is_insult = None
            is_spam = None
            relevancy = None
        try:
            inference_result = InferenceResult(
                trace_id=get_trace_id(),
                chat_id=input_data.chat_id,
                message_id=input_data.message_id,
                query=input_data.message,
                query_language=query_language,
                result_state=result_state,
                is_insult=is_insult,
                is_spam=is_spam,
                relevancy=relevancy,
                refined_query=refined_query,
                generated_text=result.generated_text,
                ai_tag=result.ai_tag.value,
                query_tag=query_tag.value,
                retrieved_docs=result.retrieved_docs,
                client_state=result.client_state,
                history=result.history,
            )

            context = get_current_trace()
            if context:
                context.inference_result = inference_result

        except Exception as e:
            LOGGER.warning(f"Error saving inference result logs: {e}")

    async def __call__(self, input_data: AlgorithmInput, **kwargs) -> GeneratorResult:
        input_data.history = HistoryHandler.prune_history(
            chat_history=input_data.history or [],
            max_token_len=self.config.max_token_len,
            last_n_conversation=self.config.last_n_conversation,
        )
        query_language = (
            detect_language_percentages(input_data.message, state="inference")
            if self.collection_info.dynamic_language["use_dynamic_language"]
            else self.collection_info.dynamic_language["default_language"]
        )

        if not self.collection_info.title:
            result = (
                self._handle_early_queries(input_data)
                if input_data.source == "live_chat"
                else InferenceMessages.connect_operator_message
            )

            await self.send_inference_result(input_data, result, "", query_language, QueryTag.CONNECT_OPERATOR, {})
            return result

        elif isinstance(input_data.client_state, dict) and isinstance(input_data.client_state.get("last_state"), dict):
            result_state = await self.check_new_state(input_data)
            if result_state:
                result = GeneratorResult(
                    generated_text=InferenceMessages.connect_operator_message,
                    AiTag=AiTagType.ASSIGN_OPERATOR.value,
                    ai_report_tag=ReportTag.CHALLENGE,
                )
                self._update_result_history_and_tag(
                    input_data,
                    result,
                    QueryTag.CONNECT_OPERATOR,
                    {"relevance": {"result": RelevanceDegree.RELATED}},
                )
                await self.send_inference_result(
                    input_data,
                    result,
                    "",
                    query_language,
                    QueryTag.CONNECT_OPERATOR,
                    {},
                    result_state,
                )
                return result

        LOGGER.debug("Stage1: Refine_Qery Request has been sent.")
        history_string = HistoryHandler.create_history_string(input_data.history)
        refined_query, query_tag = await self._refine_and_tag_query(input_data.message, history_string)

        if query_tag == QueryTag.CONNECT_OPERATOR:
            result = GeneratorResult(
                generated_text=InferenceMessages.connect_operator_message,
                ai_tag=AiTagType.ASSIGN_OPERATOR,
                ai_report_tag=ReportTag.EXPLICIT_REQUEST,
            )
            self._update_result_history_and_tag(
                input_data,
                result,
                QueryTag.CONNECT_OPERATOR,
                {"relevance": {}},
            )
            await self.send_inference_result(
                input_data,
                result,
                refined_query,
                query_language,
                QueryTag.CONNECT_OPERATOR,
                {},
            )
            return result

        LOGGER.debug(f"Stage2: Retriver request has been sent. \n The result of Refined_message : {refined_query}. ")
        retrieved_docs = await self.retriever.ainvoke(
            refined_query,
            query_tag=query_tag,
            orginal_query=input_data.message,
            history=history_string,
        )

        _, docs_ids = self.docs_retriever_to_string(retrieved_docs)

        faq_response = self.align_with_manual_faqs(input_data.message, retrieved_docs)
        if faq_response:
            result = self._generate_faq_response(faq_response, input_data)
            await self.send_inference_result(input_data, result, refined_query, query_language, query_tag, {})
            return result

        LOGGER.debug(f"Stage3: Query_Processor request has been sent. \n Retrived docs: {docs_ids}")

        query_processor_tasks = await self.detect_chain(
            input_data,
            refined_query,
            retrieved_docs,
        )
        query_tag, ai_report_tag = self.check_frequent_more_explain(
            input_data.history, query_tag, query_processor_tasks
        )

        LOGGER.debug(
            f"""Stage4: The Generation has been Started. \n Query Processor result:
            is_spam: {query_processor_tasks["spam"]["result"]}
            is_insult: {query_processor_tasks["insult"]["result"]}
            relevance_degree: {query_processor_tasks["relevance"]["result"]}
            """,
        )

        result = await self._generate_response(
            input_data,
            refined_query,
            retrieved_docs,
            docs_ids,
            history_string,
            query_tag,
            query_processor_tasks,
            query_language,
            ai_report_tag=ai_report_tag,
        )

        self._update_result_history_and_tag(input_data, result, query_tag, query_processor_tasks)

        LOGGER.debug(
            f"ًStage5: Completed and send to the backend.\
\n Response: \n\t {result.generated_text}  \n\t AI_Tag: {result.ai_tag} \n\t Query_Tag:{query_tag} ",
        )
        await self.send_inference_result(
            input_data,
            result,
            refined_query,
            query_language,
            query_tag,
            query_processor_tasks,
        )
        return result

    async def _refine_and_tag_query(self, message: str, history_string: str):
        refined_query, query_tag = await asyncio.gather(
            self.query_processor.query_refiner(message, history_string),
            self.query_processor.query_tagger(message, history_string),
        )
        return refined_query, query_tag

    def _handle_early_queries(self, input_data: AlgorithmInput) -> GeneratorResult:
        message_response = self.generation_prompts.early_queries_response
        result = GeneratorResult(generated_text=message_response, ai_report_tag=ReportTag.SUCCESSFULLY_RESPONDED)
        self._update_result_history_and_tag(
            input_data,
            result,
            QueryTag.NORMAL,
            {
                "spam": {"result": SpamResult.NOT_SPAM},
                "insult": {"result": InsultResult.NOT_INSULT},
                "relevance": {"result": RelevanceDegree.GENERAL},
            },
        )
        return result

    def _generate_faq_response(self, faq_response: str, input_data: AlgorithmInput) -> GeneratorResult:
        result = GeneratorResult(generated_text=faq_response, ai_report_tag=ReportTag.SUCCESSFULLY_RESPONDED)
        self._update_result_history_and_tag(
            input_data,
            result,
            QueryTag.NORMAL,
            {
                "spam": {"result": SpamResult.NOT_SPAM},
                "insult": {"result": InsultResult.NOT_INSULT},
                "relevance": {"result": RelevanceDegree.GENERAL},
            },
        )
        return result

    async def _generate_response(
        self,
        input_data: AlgorithmInput,
        refined_query: str,
        retrieved_docs: Dict[str, List[Document]],
        docs_ids: List[str],
        history_string: str,
        query_tag: QueryTag,
        query_processor_tasks: Dict,
        query_language: str,
        ai_report_tag: ReportTag = None,
    ) -> GeneratorResult:
        docs_independency_conditions = [
            query_processor_tasks["spam"]["result"] == SpamResult.SPAM,
            query_processor_tasks["insult"]["result"] == InsultResult.INSULT,
            query_processor_tasks["relevance"]["result"] == RelevanceDegree.GENERAL,
            query_processor_tasks["relevance"]["result"] == RelevanceDegree.NOT_RELATED,
            query_tag == QueryTag.CONNECT_OPERATOR,
        ]
        if any(docs_independency_conditions):
            result = await self.docs_independent_generation(
                input_data=input_data,
                query_processor_tasks=query_processor_tasks,
                history_string=history_string,
                query_tag=query_tag,
                language=query_language,
                docs_ids=docs_ids,
                ai_report_tag=ai_report_tag,
            )
        else:
            result = await self.docs_dependent_generation(
                input_message=input_data.message,
                retrieved_docs=retrieved_docs,
                history_string=history_string,
                query_tag=query_tag,
                refined_query=refined_query,
                language=query_language,
                input_source=input_data.source,
                ai_report_tag=ai_report_tag,
            )
        return result

    def _update_result_history_and_tag(
        self,
        input_data: AlgorithmInput,
        result: GeneratorResult,
        query_tag: QueryTag,
        query_processor_tasks: Dict,
    ):
        history = input_data.history.copy()
        history.append(
            {
                "human": input_data.message,
                "ai": result.generated_text,
                "query_tag": QueryTag.CONNECT_OPERATOR.value
                if result.ai_tag == AiTagType.ASSIGN_OPERATOR
                else query_tag.value,
                "relevance_tag": query_processor_tasks["relevance"]["result"].value
                if query_processor_tasks["relevance"].get("result") is not None
                else "1",
            },
        )

        # if the generation chains specified `not_enough` tag, the last conversation in result.history
        # demonstrates that with setting the query_tag to `CONNECT_OPERATOR`, so updating the last conversation with it
        if result.history:
            history[-1].update(result.history[-1])
        result.history = history

        query_tag, _ = self.check_frequent_more_explain(input_data.history, query_tag, query_processor_tasks)

        if result.ai_tag == AiTagType.ASSIGN_OPERATOR:
            result.generated_text = (
                InferenceMessages.connect_operator_message
                if self.collection_info.default_assigning_operator_message is None
                else self.collection_info.default_assigning_operator_message
            )

        if query_tag == QueryTag.CONNECT_OPERATOR:
            result.ai_tag = AiTagType.ASSIGN_OPERATOR
            result.generated_text = (
                InferenceMessages.connect_operator_message
                if self.collection_info.default_assigning_operator_message is None
                else self.collection_info.default_assigning_operator_message
            )

    def remove_title(self, text: str) -> str:
        if isinstance(text, str):
            split_string = text.split("\n")
            if len(split_string) > 3:
                return "\n".join(split_string[2:])
            else:
                return text
        else:
            return text

    async def show_reference_id(self, chunk_id: ReferenceChunkIds) -> dict:
        LOGGER.info(
            "The input data is: %s" % chunk_id,
        )
        docs = await get_reference_content(self.db_repository, self.collection_identifier, chunk_id)

        try:
            rerank_docs = await run_chain(
                name="rerank references",
                chain=self.show_reference_chain,
                parameters={
                    "bot_response": chunk_id.user_response + "\n" + chunk_id.bot_response,
                    "chunk_docs": str(docs),
                },
                config={"temperature": self.collection_info.temperature},
                max_retries=self.config.chain_call_max_retries,
                assertion="result['reranke_refernces']",
            )
            reordered_docs = {}
            for idx, ref_id in enumerate(rerank_docs["reranke_refernces"]):
                if ref_id in docs:
                    reordered_docs[ref_id] = {"content": self.remove_title(docs[ref_id]), "rank": idx}
            return reordered_docs
        except Exception as e:
            LOGGER.warning(f"Error in show_reference_id: {e}")
            return {id: {"content": value, "rank": rank} for rank, (id, value) in enumerate(docs.items(), start=1)}

