class HallucinationChecker:
    def __init__(self, llm_model, collection_info: CollectionInfo) -> None:
        self.llm_model = llm_model
        self.collection_info = collection_info
        self.chains = self.load_chains(collection_info.prompts)

    def load_chains(self, dynamic_prompts: Dict) -> None:
        prompts = PromptFactory.create()
        chains = {}
        for prompt_name, prompt_object in prompts.items():
            template_copy = prompt_object.template.copy()
            if dynamic_prompts and prompt_name in dynamic_prompts:
                template_copy.template = dynamic_prompts[prompt_name]
            chains[prompt_name] = template_copy | self.llm_model | llm_result_correction_chain | prompt_object.parser
        return chains

    async def extract_verification_questions(
        self,
        query: str,
        refined_query: str,
        history_string: str,
        generated_response: str,
        available_information: str,
    ) -> str:
        try:
            verification_questions = await asyncio.gather(
                run_chain(
                    chain=self.chains["exact_verification"],
                    parameters={
                        "query": f"-User_Query : {query} \n-User_Query_with_history : {refined_query}",
                        "generated_response": generated_response,
                        "available_information": available_information,
                    },
                    max_retries=5,
                    name="exact_verification",
                    assertion="assert isinstance(result['questions'], list)",
                    config={"max_key_attempts": 2},
                ),
                run_chain(
                    chain=self.chains["exact_verification_response"],
                    parameters={
                        "query": f"-User_Query : {query} \n-User_Query_with_history : {refined_query}",
                        "generated_response": generated_response,
                        "available_information": available_information,
                    },
                    max_retries=5,
                    name="exact_verification_response",
                    assertion="assert isinstance(result['questions'], list)",
                    config={"max_key_attempts": 2},
                ),
                run_chain(
                    chain=self.chains["fact_verification"],
                    parameters={
                        "query": query,
                        "generated_response": generated_response,
                        "available_information": available_information,
                    },
                    max_retries=5,
                    name="fact_verification",
                    assertion="assert isinstance(result['questions'], list)",
                    config={"max_key_attempts": 2},
                ),
            )
            verification_questions = [question for result in verification_questions for question in result["questions"]]
            return verification_questions
        except Exception as e:
            LOGGER.error(
                "unexpected error during extracting verification question!\nError: %s" % e,
            )
            raise RuntimeError(
                "unexpected error during extracting verification question!\nError: %s" % e,
            )

    async def answer_verification_questions(
        self,
        verification_questions: List[str],
        available_information: str,
    ) -> List[str]:
        try:
            answers = await asyncio.gather(
                *[
                    run_chain(
                        chain=self.chains["verify_question"],
                        parameters={
                            "query": question,
                            "available_information": available_information,
                        },
                        max_retries=5,
                        name="verify_question",
                        assertion="assert result['generated_answer']",
                        ensure_value_quates=True,
                        double_quates2single_quate=True,
                        config={"max_key_attempts": 2},
                    )
                    for question in verification_questions
                ],
            )
            answers = [answer["generated_answer"] for answer in answers]
            return answers
        except Exception as e:
            LOGGER.error(
                "unexpected error during answering verification question!\nError: %s" % e,
            )
            raise RuntimeError(
                "unexpected error during answering verification question!\nError: %s" % e,
            )

    def determine_state(self, answers, verify_results_str):
        if (verify_results_str in answers[0]) and (verify_results_str in answers[1]):
            return QueryHallucinationTag.NO_INFORMATION
        elif verify_results_str in answers[0] or verify_results_str in answers[1]:
            return QueryHallucinationTag.MISMATCH
        else:
            return QueryHallucinationTag.EXACT_INFORMATION

    async def revise_generated_answer(
        self,
        query: str,
        refined_query: str,
        history_string: str,
        generated_response: str,
        available_information: str,
        language: str,
    ) -> str:
        try:
            LOGGER.debug("""Stage4.2.1: The generation verification question started.""")
            verification_questions = await self.extract_verification_questions(
                query,
                refined_query,
                history_string,
                generated_response,
                available_information,
            )
            LOGGER.debug("""Stage4.2.2: The generation verification answer started.""")
            answers = await self.answer_verification_questions(
                verification_questions,
                available_information,
            )

            no_info = "No information available."

            verify_results_str = ""

            for question, answer in zip(verification_questions, answers):
                verify_results_str += "".join(
                    f"Question: {question}\nAnswer: {answer}\n\n",
                )

            state = self.determine_state(answers, no_info)

            LOGGER.debug(
                f"""Stage4.2.3: The generation verified response started. \nState of the hallucination: {state} """
            )
            if no_info in verify_results_str:
                if state == QueryHallucinationTag.NO_INFORMATION or state == QueryHallucinationTag.MISMATCH:
                    final_response = await run_chain(
                        chain=self.chains["final_mismatch_response"],
                        parameters={
                            "query": query,
                            "base_response": generated_response,
                            "verify_results": verify_results_str,
                            "language": language,
                        },
                        max_retries=5,
                        name="final_mismatch_response",
                        assertion="assert result['revised_response']",
                        config={"max_key_attempts": 2},
                    )
                    return {**final_response, "tag": "unmatched_subject"}
                elif state == QueryHallucinationTag.EXACT_INFORMATION:
                    final_response = await run_chain(
                        chain=self.chains["final_response"],
                        parameters={
                            "query": query,
                            "base_response": generated_response,
                            "verify_results": verify_results_str,
                            "language": language,
                        },
                        max_retries=5,
                        name="final_response",
                        assertion="assert result['revised_response'] and \
    result['tag'] in ['normal', 'unmatched_subject', 'not_enough']",
                    )
                return final_response
            return {"revised_response": generated_response, "tag": "normal"}

        except Exception as e:
            LOGGER.error(
                "unexpected error when checking answer for hallucination!\nError: %s" % e,
            )
            return {"revised_response": generated_response, "tag": "normal"}

def sublist(lst1: List[str], lst2: List[str]) -> bool:
    """
    checks to see if lst1 is a sublist of lst2 or not.
    """
    return all(item in lst2 for item in lst1)

