class FAQRetriever(BaseRetriever):
    # necessary fields
    db_repository: RobotCollectionRepository
    collection_info: CollectionInfo
    llm_models: dict
    embedding_models: dict
    query_processor: QueryProcessor

    # inner fields
    config: Config = Config()
    retrieval: BaseRetriever = None

    def __init__(self, **data):
        super().__init__(**data)
        self.retrieval = self.load_retrieval()

    def load_retrieval(self, **kwargs):
        return self.__getattribute__(
            f"create_retrieval_chain_by_{self.config.retrieval_engine}",
        )()

    def custom_query(self, query_body: dict, query: str):
        query_body["knn"]["field"] = (
            "faqs.question_vector_local"
            if self.collection_info.identifier in SpecificUsers.local_model_users
            and len(query_body["knn"].get("query_vector")) == 1024
            else "faqs.question_vector"
        )
        # if (
        #     self.collection_info.identifier in SpecificUsers.local_model_users
        #     and len(query_body["knn"].get("query_vector")) == 1024
        # ):
        #     LOGGER.debug("embedding done with local model")

        if getattr(self.collection_info, "use_chunk_faqs", False):
            return query_body
        else:
            query_body["knn"]["filter"].append({"terms": {"faqs.type": ["manual", "title"]}})  # "general",
            query_body["knn"]["num_candidates"] = 1000
        return query_body

    def fuzzy_query(self, search_query: str) -> Dict:
        return {
            "query": {
                "match": {
                    "faqs.question": {
                        "query": search_query,
                        "fuzziness": "AUTO",
                    },
                },
            },
            "size": 5,
        }

    def doc_builder(self, hit: dict):
        faq = hit["_source"]["faqs"]
        content = (
            f"Question: `{faq['question']}`, Answer: {faq['answer']}"
            if faq["type"] == "manual"
            else f"Question: {faq['question']}, Answer: {faq['answer']}"
        )
        return Document(
            page_content=content,
            metadata={
                "id": hit["_id"],
                "chunk_ids": faq["chunk_ids"] if "chunk_ids" in faq and faq["chunk_ids"] else "",
                "type": faq["type"],
            },
        )

    def create_retrieval_chain_by_basic_and_fuzzy(self, **kwargs):
        vector_store = ElasticsearchStore(
            index_name=self.db_repository.get_index_name(self.collection_info.identifier),
            es_connection=self.db_repository.sync_elasticsearch_repository,
            embedding=self.embedding_models["embedding_model"],
            strategy=ElasticsearchStore.ApproxRetrievalStrategy(),
        )
        retriever = vector_store.as_retriever(
            search_type="similarity_score_threshold",
            search_kwargs={
                "k": 5,
                "score_threshold": 0.0,
            },
        )

        fuzzy_retriever = ElasticsearchRetriever(
            index_name=self.db_repository.get_index_name(self.collection_info.identifier),
            body_func=self.fuzzy_query,
            document_mapper=self.doc_builder,
            es_client=self.db_repository.sync_elasticsearch_repository,
        )

        ensemble_retriever = EnsembleRetriever(
            retrievers=[retriever, fuzzy_retriever],
            weights=[0.8, 0.2],
        )

        return ensemble_retriever

    def create_retrieval_chain_by_basic_retriever(self, **kwargs):
        vector_store = ElasticsearchStore(
            index_name=self.db_repository.get_index_name(self.collection_info.identifier),
            es_connection=self.db_repository.sync_elasticsearch_repository,
            embedding=self.embedding_models["embedding_model"],
            strategy=ElasticsearchStore.ApproxRetrievalStrategy(),
            vector_query_field="faqs.question_vector_local"
            if self.collection_info.identifier in SpecificUsers.local_model_users
            else "faqs.question_vector",
        )

        # Monkey Patching
        vector_store.similarity_search = similarity_search
        vector_store._store.max_marginal_relevance_search = types.MethodType(
            max_marginal_relevance_search,
            vector_store._store,
        )

        search_kwargs = {
            "k": 5,
            "lambda_mult": 0.25,
            "fetch_k": 20,
            "fields": [
                "faqs.question",
                "faqs.answer",
                "faqs.id",
                "faqs.chunk_ids",
                "faqs.question_vector",
                "faqs.type",
            ],
            "doc_builder": self.doc_builder,
        }

        if not self.collection_info.use_faq_generator:
            search_kwargs["custom_query"] = self.custom_query

        retriever = vector_store.as_retriever(search_type="mmr", search_kwargs=search_kwargs)

        return retriever

    def _get_relevant_documents(
        self,
        query: str,
        *,
        run_manager: CallbackManagerForRetrieverRun,
        **kwargs: Any,
    ) -> List[Document]:
        docs = asyncio.run(
            self.__getattribute__(f"retrieve_docs_by_{self.config.retrieval_method}")(
                query,
                **kwargs,
            ),
        )

        return docs

    async def _aget_relevant_documents(
        self,
        query: str,
        *,
        run_manager: AsyncCallbackManagerForRetrieverRun,
        **kwargs: Any,
    ) -> List[Document]:
        docs = await self.__getattribute__(
            f"retrieve_docs_by_{self.config.retrieval_method}",
        )(query, **kwargs)

        return docs

    async def retrieve_docs_by_similarity_search(self, query: str) -> List[Any]:
        retrieved_docs = await self.retrieval.ainvoke(query)
        return retrieved_docs[: self.config.num_retrieved_docs]

    async def retrieve_docs_by_multiquery_fusion(
        self,
        query: str,
        **kwargs,
    ) -> List[Any]:
        """
        Retrieves documents by performing a multi-query fusion process, which enhances the retrieval process by
        combining results from multiple queries.
        """

        retrieved_docs_dict = {}

        if "queries" in kwargs:
            queries = kwargs["queries"]
        else:
            queries = await self.query_processor.query_paraphrasing(
                input_message=query,
            )
            queries.append(query)

        retrieved_docs_dict = dict(
            zip(
                queries,
                await asyncio.gather(
                    *[self.retrieval.ainvoke(query) for query in queries],
                ),
            ),
        )
        reranked_docs = reciprocal_rank_fusion(retrieved_docs_dict)

        first_doc_from_exact_query = retrieved_docs_dict[queries[-1]][0]
        if first_doc_from_exact_query in reranked_docs:
            reranked_docs.remove(first_doc_from_exact_query)

        return [first_doc_from_exact_query] + reranked_docs[: self.retrieval.search_kwargs["k"] - 1]

