class DataIndexing:
    def __init__(
        self,
        db_repository: IRobotCollectionRepository,
        metadata_extractor: MetadataExtractor,
        dataloader: DataLoader,
        faq_generator: FAQGenerator,
        summarizer: Summarizer,
        ai_models: Dict = None,
    ):
        self.ai_models = ai_models
        self.dataloader = dataloader
        self.db_repository = db_repository
        self.metadata_extractor = metadata_extractor
        self.faq_generator = faq_generator
        self.summarizer = summarizer

    async def create_collection(self, collection_record: CollectionRecord) -> bool:
        try:
            await self.db_repository.create_index(collection_record)
            return True
        except Exception as e:
            LOGGER.error(e)
            raise exceptions.CollectionCreationError(detail=str(e)) from e

    async def load_data(
        self,
        collection: Collection,
        datum: List[DataRecord],
        send_intermediate_update_result: Callable,
    ) -> List[ReferenceData]:
        try:
            await send_intermediate_update_result(
                collection.collection_info.identifier,
                {ref_data.identifier: None for ref_data in datum},
                {ref_data.identifier: DataRecordStatus.PENDING for ref_data in datum},
                {
                    ref_data.identifier: TrainMessages.start_training_message
                    for ref_data in datum
                },
            )

            loaded_data = [
                self.find_trained_data(collection, data_record.identifier)
                for data_record in datum
                if self.find_trained_data(collection, data_record.identifier)
            ]

            completed_data = [
                ref_data.identifier
                for ref_data in loaded_data
                if TrainingStage.OVERALL_METADATA_EXTRACTION.value
                in ref_data.training_stage
            ]
            if completed_data:
                await self.delete_data_records_from_collection(
                    collection.collection_info.identifier,
                    DataRecordIdentifiers(data_record_identifiers=completed_data),
                )
            loaded_data = [
                ref_data
                for ref_data in loaded_data
                if ref_data.identifier not in completed_data
            ]
            loaded_data_identifiers = [ref_data.identifier for ref_data in loaded_data]

            new_data_records = [
                data_record
                for data_record in datum
                if data_record.identifier not in loaded_data_identifiers
            ]
            loaded_data.extend(
                await self.load_new_data(
                    collection, new_data_records, send_intermediate_update_result
                )
            )

            if loaded_data:
                collection.collection_info.language = (
                    self.dataloader.update_collection_language(
                        loaded_data + collection.reference_datum,
                    )
                )
            return loaded_data
        except Exception as e:
            LOGGER.error(
                "unable to load data for %s collection_models, %s"
                % (collection.collection_info.identifier, e),
            )
            raise exceptions.LoadDataError(
                detail=f"{collection.collection_info.identifier}, {str(e)}",
            )

    async def load_new_data(
        self,
        collection: Collection,
        datum: List[DataRecord],
        send_intermediate_update_result: Callable,
    ) -> List[ReferenceData]:
        if not datum:
            return []
        LOGGER.debug("loading data")
        dataloader_result = await self.dataloader(
            collection.collection_info.prompts,
            datum,
            collection.collection_info.url_main_content,
        )
        for ref_data in dataloader_result.reference_datum:
            ref_data.training_stage = (
                ref_data.training_stage + "." + TrainingStage.DATA_LOADING.value
            )

        final_reference_datum = []
        for ref_data in dataloader_result.reference_datum:
            data_record_validation = dataloader_result.validation_result[
                ref_data.identifier
            ]
            if data_record_validation["success"]:
                final_reference_datum.append(ref_data)
                await self.db_repository.add_reference_data_to_collection(
                    collection.collection_info.identifier, [ref_data]
                )
                await send_intermediate_update_result(
                    collection.collection_info.identifier,
                    {ref_data.identifier: ref_data.num_characters},
                    {ref_data.identifier: DataRecordStatus.PENDING},
                    {
                        ref_data.identifier: TrainMessages.get_step_train_message(
                            k=round(
                                (
                                    int(TrainingStage.DATA_LOADING.value)
                                    / len(TrainingStage)
                                )
                                * 100
                            )
                        )
                    },
                )
            else:
                await send_intermediate_update_result(
                    collection.collection_info.identifier,
                    {ref_data.identifier: ref_data.num_characters},
                    {ref_data.identifier: DataRecordStatus.REJECTED},
                    status_messages={
                        ref_data.identifier: data_record_validation["message"]
                    },
                )
        return final_reference_datum

    def update_collection_info(
        self, collection: Collection, reference_datum: List[ReferenceData]
    ) -> None:
        total_num_words = sum(
            [
                ref_data.num_words
                for ref_data in reference_datum
                if ref_data.num_words is not None
            ],
        )
        total_num_characters = sum(
            [
                ref_data.num_characters
                for ref_data in reference_datum
                if ref_data.num_characters is not None
            ],
        )
        total_page_count = sum(
            [
                ref_data.page_count
                for ref_data in reference_datum
                if ref_data.page_count is not None
                and ref_data.data_type == DataType.PDF
            ]
        )

        collection.collection_info.language = (
            self.dataloader.update_collection_language(
                collection.reference_datum + reference_datum,
            )
        )
        collection.collection_info.num_data += len(reference_datum)
        collection.collection_info.total_num_words += total_num_words
        collection.collection_info.total_num_characters += total_num_characters
        collection.collection_info.total_page_count += total_page_count

    async def extract_file_dependent_data(
        self,
        collection: Collection,
        reference_datum: List[ReferenceData],
        send_intermediate_update_result: Callable,
    ) -> List[ReferenceDataWrapper]:
        LOGGER.debug(
            "Extracting file dependant datum for collection_models %s"
            % collection.collection_info.identifier,
        )
        tasks = [
            self.extract_data_for_each_file(
                collection, ref_data, send_intermediate_update_result
            )
            for ref_data in reference_datum
        ]
        result = await asyncio.gather(*tasks, return_exceptions=True)
        return [
            ref_data_wrapper
            for ref_data_wrapper in result
            if ref_data_wrapper is not None
        ]

    async def extract_data_for_each_file(
        self,
        collection: Collection,
        ref_data: ReferenceData,
        send_intermediate_update_result: Callable,
    ) -> ReferenceDataWrapper:
        training_steps = [
            self.fill_detailed_metadata,
            self.fill_reference_metadata,
            self.fill_reference_data_summaries,
            self.fill_reference_data_faqs,
        ]
        len_stages = len(TrainingStage)

        if not collection.collection_info.use_summarizer:
            training_steps.remove(self.fill_reference_data_summaries)
            len_stages -= 1
        if not collection.collection_info.use_faq_generator:
            training_steps.remove(self.fill_reference_data_faqs)
            len_stages -= 1

        reference_data_wrapper = ReferenceDataWrapper(
            id=ref_data.id,
            identifier=ref_data.identifier,
            content=ref_data.content,
            language=ref_data.language,
            data_type=ref_data.data_type,
            title=ref_data.title,
            training_stage=ref_data.training_stage,
        )

        for step in training_steps:
            reference_data_wrapper, ref_data = await step(
                collection=collection,
                reference_data_wrapper=reference_data_wrapper,
                reference_data=ref_data,
                send_intermediate_update_result=send_intermediate_update_result,
                len_stages=len_stages,
            )
            if not reference_data_wrapper:
                return None

        return reference_data_wrapper

    async def fill_reference_data_faqs(
        self,
        collection: Collection,
        reference_data_wrapper: ReferenceDataWrapper,
        reference_data: ReferenceData,
        send_intermediate_update_result: Callable,
        len_stages: int,
    ) -> Tuple[ReferenceDataWrapper, ReferenceData] | None:
        try:
            if TrainingStage.FAQ_EXTRACTION.value in reference_data.training_stage:
                reference_data_wrapper.faqs = (
                    await self.db_repository.get_reference_data_faqs(
                        collection.collection_info.identifier, reference_data
                    )
                )
            else:
                LOGGER.debug(
                    "File faq generator in progress for collection_models %s and reference data %s"
                    % (
                        collection.collection_info.identifier,
                        reference_data.identifier,
                    ),
                )
                reference_data_wrapper.faqs = (
                    await self.faq_generator.file_faq_generator(
                        collection.collection_info,
                        reference_data_wrapper,
                    )
                )
                reference_data.training_stage = (
                    reference_data.training_stage
                    + "."
                    + TrainingStage.FAQ_EXTRACTION.value
                )
                await self.db_repository.add_faqs_to_collection(
                    collection.collection_info.identifier, reference_data_wrapper.faqs
                )
                await self.db_repository.add_reference_data_to_collection(
                    collection.collection_info.identifier, [reference_data]
                )

                await send_intermediate_update_result(
                    collection.collection_info.identifier,
                    {reference_data.identifier: None},
                    {reference_data.identifier: DataRecordStatus.PENDING},
                    {
                        reference_data.identifier: TrainMessages.get_step_train_message(
                            k=round(
                                (int(TrainingStage.FAQ_EXTRACTION.value) / len_stages)
                                * 100
                            )
                        )
                    },
                )
            return reference_data_wrapper, reference_data
        except Exception as e:
            LOGGER.error(
                "Error generating FAQs for file identifier %s and collection_models identifier %s\nbecause: %s"
                % (
                    reference_data.identifier,
                    collection.collection_info.identifier,
                    str(e),
                ),
            )
            await send_intermediate_update_result(
                collection.collection_info.identifier,
                {reference_data.identifier: None},
                {reference_data.identifier: DataRecordStatus.REJECTED},
                status_messages={
                    reference_data.identifier: TrainMessages.get_step_error_message(
                        k=round(
                            (int(TrainingStage.FAQ_EXTRACTION.value) / len_stages) * 100
                        )
                    ),
                },
            )
            return None, None

