    ) -> Tuple[ReferenceDataWrapper, ReferenceData] | None:
        try:
            if (
                TrainingStage.REF_METADATA_EXTRACTION.value
                in reference_data.training_stage
            ):
                reference_data_wrapper.applications = reference_data.applications
                reference_data_wrapper.business_applications = (
                    reference_data.business_applications
                )
                reference_data_wrapper.not_related_keywords = (
                    reference_data.not_related_keywords
                )
                reference_data_wrapper.related_keywords = (
                    reference_data.related_keywords
                )
            else:
                LOGGER.debug(
                    "file metadata extraction in progress for collection_models %s and reference data %s"
                    % (
                        collection.collection_info.identifier,
                        reference_data.identifier,
                    ),
                )

                await self.metadata_extractor.overall_metadata_extractor.file_metadata_extraction(
                    collection.collection_info, reference_data_wrapper
                )

                for chunk in reference_data_wrapper.chunks:
                    chunk.content = reference_data_wrapper.title + "\n" + chunk.content
                for chunk in reference_data_wrapper.child_chunks:
                    chunk.content = reference_data_wrapper.title + "\n" + chunk.content
                await self.metadata_extractor.detailed_metadata_extractor.vectorize(
                    reference_data_wrapper.child_chunks
                )
                await self.db_repository.add_chunk_data_to_collection(
                    collection_identifier=collection.collection_info.identifier,
                    chunks=reference_data_wrapper.chunks,
