    async def extract_collection_title(
        self, collection_info: CollectionInfo, ref_data_wrapper: ReferenceDataWrapper
    ) -> str:
        if not collection_info.title:
            title = (
                await self.metadata_extractor.overall_metadata_extractor.combine_titles(
                    collection_info,
                    ref_data_wrapper.headings,
                )
            )
        else:
            title = collection_info.title
        return title

    async def extract_overall_data(self, collection: Collection) -> Collection:
        try:
            LOGGER.debug(
                "Extracting overall datum for collection_models %s"
                % collection.collection_info.identifier,
            )
            LOGGER.debug(
                "Overall metadata extraction in progress for collection_models %s"
                % collection.collection_info.identifier,
            )
            collection.collection_info.title = (
                await self.metadata_extractor.overall_metadata_extractor.combine_titles(
                    collection.collection_info,
                    collection.headings,
                )
            )
            await self.metadata_extractor.overall_metadata_extractor.reference_datum_combiner(
                collection,
            )
            new_collection = Collection(
                collection_info=collection.collection_info,
                chunks=[],
                headings=[],
                reference_datum=[],
            )

            if collection.collection_info.use_summarizer:
                LOGGER.debug(
                    "Overall summarizer in progress for collection_models %s"
                    % collection.collection_info.identifier,
                )
                (
                    new_collection.data_summaries,
                    new_collection.child_summaries,
                ) = await self.summarizer.overall_summarizer(collection)

            LOGGER.debug(
                "Overall faq generator in progress for collection_models %s"
                % collection.collection_info.identifier,
            )
            new_collection.faqs = await self.faq_generator.overall_faq_generator(
                collection,
            )
            return new_collection
        except Exception as e:
            LOGGER.error("Error extracting overall data: %s" % e)
            raise exceptions.OverallDataExtractionError(
                detail="Error extracting overall data: %s" % e,
            ) from e

    async def update_overall_data(
        self,
        collection_identifier: str,
        reference_datum_wrappers: List[ReferenceDataWrapper],
        reference_datum: List[ReferenceData],
    ) -> CollectionInfo:
        collection = await self.get_collection(
            collection_identifier,
        )
        collection.reference_datum = [
            ref_data
            for ref_data in collection.reference_datum
            if len(ref_data.training_stage.split(".")) == len(TrainingStage)
        ]

        self.update_collection_info(
            collection,
            reference_datum,
        )

        loop = asyncio.get_running_loop()
        for ref_data_wrapper in reference_datum_wrappers:
            wrapper_cython = ref_data_wrapper.cython_class
            collection_cython = collection.cython_class
            await loop.run_in_executor(
                None,
                prune_duplicate_chunks,
                wrapper_cython,
                collection_cython,
            )
            await loop.run_in_executor(
                None, prune_duplicate_faqs, wrapper_cython, collection_cython
            )
            ref_data_wrapper.cython_class = wrapper_cython
        await self.delete_old_overall_data(collection)

        self.concat_new_data(
            collection,
            reference_datum_wrappers,
            reference_datum,
        )
        new_collection = await self.extract_overall_data(
            collection,
        )

        self.concat_new_data(
            new_collection,
            reference_datum_wrappers,
            reference_datum,
        )

        for reference_data in reference_datum:
            reference_data.training_stage += (
                "." + TrainingStage.OVERALL_METADATA_EXTRACTION.value
            )

        await self.update_collection(new_collection)

        return new_collection.collection_info

    async def delete_old_overall_data(self, collection: Collection) -> None:
        LOGGER.debug(
            "Deletion old overall data in progress for collection_models %s"
            % collection.collection_info.identifier,
        )
        faq_candidates = []
        for faq in collection.faqs:
            if faq.type not in ["chunk", "heading_summary", "manual"]:
                faq_candidates.append(faq.id)
        await self.db_repository.delete_faq_from_collection(
            collection.collection_info.identifier,
            faq_candidates,
        )
        collection.faqs = [
            faq
            for faq in collection.faqs
            if faq.type in ["chunk", "heading_summary", "manual"]
        ]

        summary_candidates = []
        for summary in collection.data_summaries:
            if summary.type == "main":
                summary_candidates.append(summary.id)
        await self.db_repository.delete_summaries_from_collection(
            collection.collection_info.identifier,
            summary_candidates,
        )
        collection.data_summaries = [
            summary for summary in collection.data_summaries if summary.type != "main"
        ]

        child_summary_candidates = []
        child_summaries_cleaned = []
        for summary in collection.child_summaries:
            if summary.parent_id in summary_candidates:
                child_summary_candidates.append(summary.id)
            else:
                child_summaries_cleaned.append(summary)
        await self.db_repository.delete_child_summaries_from_collection(
            collection.collection_info.identifier,
            child_summary_candidates,
        )
        collection.child_summaries = child_summaries_cleaned

    def concat_new_data(
        self,
        collection: Collection,
        reference_datum_wrappers: List[ReferenceDataWrapper],
        reference_datum: List[ReferenceData],
    ) -> None:
        filtered_ref_datum = []
        for ref_data in reference_datum:
            file_data = self.get_file_data_by_id(
                ref_data.identifier, reference_datum_wrappers
            )
            if file_data is None:
                continue
            ref_data.applications = file_data.applications
            ref_data.business_applications = file_data.business_applications
            ref_data.related_keywords = file_data.related_keywords
            ref_data.not_related_keywords = file_data.not_related_keywords
            ref_data.chunk_ids = file_data.chunk_ids
            ref_data.content = file_data.content
            filtered_ref_datum.append(ref_data)

        collection.reference_datum.extend(filtered_ref_datum)
        collection.headings.extend(
            [
                heading
                for file_data in reference_datum_wrappers
                for heading in file_data.headings
            ],
        )
        collection.chunks.extend(
            [
                chunk
                for file_data in reference_datum_wrappers
                for chunk in file_data.chunks
            ],
        )
        collection.data_summaries.extend(
            [
                summary
                for file_data in reference_datum_wrappers
                for summary in file_data.data_summaries
            ],
        )
        collection.child_summaries.extend(
            [
                summary
                for file_data in reference_datum_wrappers
                for summary in file_data.child_summaries
            ],
        )
        collection.faqs.extend(
            [faq for file_data in reference_datum_wrappers for faq in file_data.faqs],
        )

    async def update_collection(
        self,
        collection: Collection,
    ) -> None:
        try:
            LOGGER.debug("updating collection_models with new data")
            await self.db_repository.update_collection(collection)
        except Exception as e:
            LOGGER.error("Error updating collection_models data in database: %s" % e)
            raise exceptions.UpdateCollectionError(
                detail="Error updating collection_models data in database: %s" % e,
            ) from e

    async def delete_data_records_from_collection(
        self,
        collection_identifier: str,
        data_record_identifiers: DataRecordIdentifiers,
    ) -> Collection:
        try:
            # TODO: if data type is ecommerce, another procedure must be executed
            reference_data_ids = await self.db_repository.get_reference_data_id_from_identifier(
                collection_identifier=collection_identifier,
                data_record_identifiers=data_record_identifiers.data_record_identifiers,
            )
            LOGGER.debug("deleting reference data from collection_models")
            await self.db_repository.delete_reference_data_from_collection(
                collection_identifier=collection_identifier,
                reference_data_ids=reference_data_ids,
            )
            LOGGER.debug(
                "updating collection_models info after deleting reference data"
            )
            collection = await self.get_collection(collection_identifier)
            await self.delete_old_overall_data(collection)

            if collection.collection_info.num_data == 0:
                collection.collection_info.title = ""
                collection.collection_info.applications = []
                collection.collection_info.business_applications = []
                collection.collection_info.related_keywords = []
                collection.collection_info.not_related_keywords = []
            else:
                collection = await self.extract_overall_data(collection)

            await self.update_collection(collection)
            return collection
        except exceptions.OverallDataExtractionError:
            LOGGER.error(
                "Deleted data records from database but faced an issue during extracting overall data!",
            )
            raise exceptions.ReferenceDataDeletionError(
                detail=f"identifier = {collection_identifier}. stage = overall data extraction",
            )
        except Exception as e:
            LOGGER.error(
                f"Unable to delete data records {data_record_identifiers} from collection_models "
                f"{collection_identifier} in {self.db_repository.db_type} database. Error: {e}",
            )
            raise exceptions.ReferenceDataDeletionError(detail=str(e)) from e

    async def add_faq(self, collection_identifier: str, raw_faq: RawFAQ):
        # TODO: Backend Sends list of reference data ids. Currently, only one of them will be picked
        try:
            chunk_ids = []
            if raw_faq.reference_data_ids:
                index_name = self.db_repository.get_index_name(collection_identifier)
                doc_id = self.db_repository._get_reference_data_id_name(
                    raw_faq.reference_data_ids[0],
                )
                reference_data = await self.db_repository.get_document_by_id(
                    index_name,
                    doc_id,
                )
                chunk_ids = reference_data.chunk_ids

            faq = await self.faq_generator.create_faq(raw_faq, chunk_ids=chunk_ids)

            collection_info = await self.db_repository.get_collection_info_by_id(
                collection_identifier,
            )

            if self.faq_generator.config.overwrite_backend_faq:
                await self.refine_faq_collection(
                    collection_identifier, faq, collection_info
                )
            else:
                await self.db_repository.add_faqs_to_collection(
                    collection_identifier,
                    [faq],
                )

        except Exception as e:
            LOGGER.error(
                "Unable to add new faq: %s  to collection_models %s\n"
                "Error: %s" % (raw_faq, collection_identifier, e),
            )
            raise exceptions.AddFAQError(detail=str(e)) from e

    async def refine_faq_collection(
        self, collection_identifier: str, faq: FAQ, collection_info: CollectionInfo
    ):
        """
        Refines the FAQ collection by updating existing FAQs with new information.
        This method performs a KNN search to find similar FAQs and updates them with the new FAQ data.
        If no similar FAQs are found, the new FAQ is added to the collection.
        Args:
            collection_identifier (str): The identifier of the collection to update.
            faq (FAQ): The FAQ object containing the new data.
            collection_info (CollectionInfo): Information about the collection.
        Returns:

        """
        old_similar_faqs = await self.db_repository.knn_search(
            collection_identifier,
            faq.question_vector,
            "faqs",
            5,
        )

        old_similar_faqs = [faq for faq in old_similar_faqs if faq.type != "manual"]

        updated_faqs = await self.faq_generator.update_faqs(
            faq,
            old_similar_faqs,
            collection_info,
        )

        await self.db_repository.add_faqs_to_collection(
            collection_identifier,
            updated_faqs,
        )

