    async def delete_batch_document_from_collection(
        self,
        collection_identifier: str,
        document_ids: List[str],
    ) -> List[str]:
        try:
            faq_ids, chunk_ids, summary_ids = self._categorize_document_ids(
                document_ids
            )
            faq_identifiers = await self._delete_faqs(collection_identifier, faq_ids)
            await self._delete_chunks(collection_identifier, chunk_ids)
            await self._delete_summaries(collection_identifier, summary_ids)
            return faq_identifiers
        except Exception as e:
            LOGGER.error(
                "Unable to delete document: %s  from collection_models %s\n"
                "Error: %s" % (document_ids, collection_identifier, e),
            )
            return None

    async def update_batch_document_from_collection(
        self,
        collection_identifier: str,
        document_updates: List[dict],
    ) -> dict:
        try:
            faq_ids, chunk_ids, summary_ids = self._categorize_document_ids(
                [doc.document_id for doc in document_updates]
            )
            faq_updates = [
                doc for doc in document_updates if doc.document_id.startswith("faq_")
            ]
            chunk_updates = [
                doc for doc in document_updates if doc.document_id.startswith("chunk_")
            ]
            summary_updates = [
                doc
                for doc in document_updates
                if doc.document_id.startswith("summary_")
            ]

            faq_identifiers = await self._update_faqs(
                collection_identifier, faq_updates
            )
            await self._update_chunks(collection_identifier, chunk_updates)
            await self._update_summaries(collection_identifier, summary_updates)

            return faq_identifiers
        except Exception as e:
            LOGGER.error(
                "Unable to update document: %s  in collection_models %s\n"
                "Error: %s" % (document_updates, collection_identifier, e),
            )
            return None

    async def _delete_faqs(
        self, collection_identifier: str, faq_ids: List[int]
    ) -> List[str]:
        if not faq_ids:
            return []
        faq_identifiers = await self.get_manual_faq_identifiers(
            collection_identifier, faq_ids
        )
        await self.db_repository.delete_faq_from_collection(
            collection_identifier=collection_identifier, faq_ids=faq_ids
        )
        return list(faq_identifiers.keys())

    async def _delete_chunks(
        self, collection_identifier: str, chunk_ids: List[int]
    ) -> None:
        if not chunk_ids:
            return
        await self.db_repository.delete_child_chunks_from_collection_by_chunk_ids(
            collection_identifier=collection_identifier,
            chunk_ids=chunk_ids,
            index_name="parschat_" + collection_identifier,
        )
        await self.db_repository.delete_chunks_from_collection(
            collection_identifier=collection_identifier, chunk_ids=chunk_ids
        )

    async def _delete_summaries(
        self, collection_identifier: str, summary_ids: List[int]
    ) -> None:
        if not summary_ids:
            return
        await self.db_repository.delete_child_summaries_from_parent_id(
            collection_identifier=collection_identifier,
            parent_id=summary_ids,
        )
        await self.db_repository.delete_summaries_from_collection(
            collection_identifier=collection_identifier,
            summary_ids=summary_ids,
        )

    async def _update_faqs(
        self, collection_identifier: str, faq_updates: List[dict]
    ) -> dict:
        tasks = [
            self.update_faq(
                collection_identifier,
                int(doc.document_id.replace("faq_", "")),
                doc.updated_value,
            )
            for doc in faq_updates
        ]
        await asyncio.gather(*tasks)
        faq_ids = [int(doc.document_id.replace("faq_", "")) for doc in faq_updates]
        return await self.get_manual_faq_identifiers(collection_identifier, faq_ids)

    async def _update_chunks(
        self, collection_identifier: str, chunk_updates: List[dict]
    ) -> None:
        if not chunk_updates:
            return
        initial_chunk_value = await self.db_repository.get_document_by_id(
            self.db_repository.get_index_name(collection_identifier),
            f"chunk_{chunk_updates[0].document_id.replace('chunk_', '')}",
            exclude_part=["child_chunks.vector", "chunks.vector"],
        )
        initial_heading_value = (
            (
                await self.db_repository.get_headings_by_id(
                    collection_identifier, initial_chunk_value.heading_id
                )
            )[0].heading_value
            if (
                await self.db_repository.get_headings_by_id(
                    collection_identifier, initial_chunk_value.heading_id
                )
            )
            else ""
        )
        reference_data_title = await self.db_repository.get_reference_data_title_by_id(
            collection_identifier, initial_chunk_value.reference_data_id
        )

        await self.db_repository.delete_child_chunks_from_collection_by_chunk_ids(
            chunk_ids=[
                int(doc.document_id.replace("chunk_", "")) for doc in chunk_updates
            ],
            collection_identifier=collection_identifier,
            index_name=self.db_repository.get_index_name(collection_identifier),
        )

        tasks = [
            self.update_chunk_documents(
                collection_identifier,
                int(doc.document_id.replace("chunk_", "")),
                doc.updated_value,
                initial_chunk_value,
                initial_heading_value,
                reference_data_title,
            )
            for doc in chunk_updates
        ]
        await asyncio.gather(*tasks)

        for doc in chunk_updates:
            initial_chunk_value.content = doc.updated_value
            await self.db_repository.add_chunk_data_to_collection(
                collection_identifier=collection_identifier,
                chunks=[initial_chunk_value],
            )

    async def _update_summaries(
        self, collection_identifier: str, summary_updates: List[dict]
    ) -> None:
        if not summary_updates:
            return
        initial_summary_value = await self.db_repository.get_document_by_id(
            self.db_repository.get_index_name(collection_identifier),
            f"summary_{summary_updates[0].document_id.replace('summary_', '')}",
            exclude_part=["data_summaries.vector", "child_summaries.vector"],
        )
        if initial_summary_value.type == "heading":
            initial_heading_value = (
                await self.db_repository.get_heading_value_from_chunk_id(
                    collection_identifier, initial_summary_value.chunk_ids
                )
            )
            reference_data_title = (
                await self.db_repository.get_reference_data_title_by_chunk_id(
                    collection_identifier, initial_summary_value.chunk_ids
                )
            )
        else:
            main_headline_mapper = {
                "PERSIAN": "خلاصه کلی",
                "ENGLISH": "General Summary",
            }
            collection_info = await self.db_repository.get_collection_info_by_id(
                collection_identifier
            )
            reference_data_title = collection_info.title
            initial_heading_value = main_headline_mapper[collection_info.language]

        await self.db_repository.delete_child_summaries_from_parent_id(
            parent_id=[
                int(doc.document_id.replace("summary_", "")) for doc in summary_updates
            ],
            collection_identifier=collection_identifier,
        )

        tasks = [
            self.update_summary_documents(
                collection_identifier,
                int(doc.document_id.replace("summary_", "")),
                doc.updated_value,
                initial_summary_value,
                initial_heading_value,
                reference_data_title,
            )
            for doc in summary_updates
        ]
        await asyncio.gather(*tasks)

        for doc in summary_updates:
            initial_summary_value.content = doc.updated_value
            await self.db_repository.add_summary_data_to_collection(
                collection_identifier=collection_identifier,
                data_summaries=[initial_summary_value],
            )

    def _categorize_document_ids(
        self, document_ids: List[str]
    ) -> Tuple[List[int], List[int], List[int]]:
        faq_ids, chunk_ids, summary_ids = [], [], []
        for doc_id in document_ids:
            if doc_id.startswith("faq_"):
                faq_ids.append(int(doc_id.replace("faq_", "")))
            elif doc_id.startswith("chunk_"):
                chunk_ids.append(int(doc_id.replace("chunk_", "")))
            elif doc_id.startswith("summary_"):
                summary_ids.append(int(doc_id.replace("summary_", "")))
        return faq_ids, chunk_ids, summary_ids

    async def get_manual_faq_identifiers(
        self, collection_identifier: str, faq_ids: list
    ) -> List[str]:
        identifiers = {}
        for faq_id in faq_ids:
            faq_doc = await self.db_repository.get_document_by_id(
                index_name=self.db_repository.get_index_name(collection_identifier),
                doc_id=f"faq_{faq_id}",
                exclude_part=[
                    "faqs.vector",
                    "faqs.question_vector",
                    "faqs.answer_vector",
                ],
            )
            if faq_doc.type == "manual":
                identifiers[faq_doc.identifier] = {
                    "Question": faq_doc.question,
                    "Answer": faq_doc.answer,
                }
        return identifiers

    async def update_faq(
        self, collection_identifier: str, faq_id: int, updated_faq: dict
    ) -> None:
        try:
            await self.db_repository.update_faq(
                collection_identifier=collection_identifier,
                faq_id=faq_id,
                question=updated_faq["Question"],
                answer=updated_faq["Answer"],
            )
        except Exception as e:
            LOGGER.error(
                f"Unable to update FAQ {faq_id} in collection {collection_identifier}: {str(e)}"
            )
            raise exceptions.UpdateFAQError(detail=str(e)) from e

    async def update_chunk_documents(
        self,
        collection_identifier,
        chunk_id,
        updated_value,
        initial_chunk,
        initial_heading_value,
        reference_data_title,
    ):
        child_chunks = self.metadata_extractor.detailed_metadata_extractor.create_child_from_update_docs(
            initial_chunk, reference_data_title, initial_heading_value, updated_value
        )
        await self.metadata_extractor.detailed_metadata_extractor.vectorize(
            child_chunks
        )
        await self.db_repository.add_child_chunk_to_collection(
            collection_identifier, child_chunks
        )

    async def update_summary_documents(
        self,
        collection_identifier,
        chunk_id,
        updated_value,
        initial_chunk,
        initial_heading_value,
        reference_data_title,
    ):
        child_summary = self.metadata_extractor.detailed_metadata_extractor.create_child_from_update_docs(
            initial_chunk, reference_data_title, initial_heading_value, updated_value
        )
        await self.metadata_extractor.detailed_metadata_extractor.vectorize(
            child_summary
        )
        await self.db_repository.add_child_summaries_to_collection(
            collection_identifier, child_summary
        )

    async def get_collection(
        self, collection_identifier: str, partial: bool = False
    ) -> Collection:
        if partial:
            collection_info = await self.db_repository.get_collection_info_by_id(
                collection_identifier
            )
            reference_datum = (
                await self.db_repository.get_collection_reference_datums_by_id(
                    collection_identifier
                )
            )
            headings = await self.db_repository.get_collection_headings_by_id(
                collection_identifier
            )
            return Collection(
                collection_info=collection_info,
                reference_datum=reference_datum,
                headings=headings,
            )
        return await self.db_repository.get_collection_by_id(
            collection_identifier,
            return_vectors=False,
        )

