    @staticmethod
    def get_reference_datum_num_characters(
        reference_datum: List[ReferenceData],
    ) -> Dict[str, int]:
        reference_datum_characters = {
            reference_data.identifier: reference_data.num_characters
            for reference_data in reference_datum
