            collection_identifier, reference_data_identifier
        )
        return content

    @staticmethod
    def get_file_data_by_id(
        identifier: str,
        file_datum: List[ReferenceDataWrapper],
    ) -> ReferenceDataWrapper | None:
        for file_data in file_datum:
            if file_data.identifier == identifier:
                return file_data
        return None

    @staticmethod
    def get_heading_from_heading_id(
        heading_id: int,
        ref_data_wrapper: ReferenceDataWrapper,
    ):
        for heading in ref_data_wrapper.headings:
            if heading.id == heading_id:
                return heading

    @staticmethod
    def find_trained_data(
        collection: Collection, data_record_identifier: str
    ) -> ReferenceData | None:
        for reference_data in collection.reference_datum:
            reference_data_identifier = reference_data.identifier
            if reference_data_identifier == data_record_identifier:
                return reference_data

    async def download_file_datum(self, datum: List[DataRecord]) -> None:
        for data in datum:
            if data.data_type != DataType.URL:
                data.data_path = await self.dataloader._ensure_file_exists(
                    data.data_path
                )
                # data.data_path = await self.dataloader.download_file_not_exist(
                #     data.data_path
                # )

    def get_pdf_page_number(self, data_path: str) -> int:
        return self.dataloader._get_pdf_page_count(data_path)

    async def count_data_records_pdf_pages(
        self, datum: List[DataRecord]
    ) -> Dict[DataRecord, int]:
        pdfs = {}
        for data in datum:
            if data.data_type == DataType.PDF:
                data.data_path = await self.dataloader._ensure_file_exists(
                    data.data_path
                )
                pdfs[data] = self.get_pdf_page_number(data.data_path)

        return pdfs

    async def get_collection_total_characters(self, collection_identifier: str) -> int:
        collection = await self.get_collection(collection_identifier, partial=True)
        return await self.get_collection_total_characters_by_collection(collection)

    @staticmethod
    async def get_collection_total_characters_by_collection(collection):
        total_characters = sum(
            ref_data.num_characters
            for ref_data in collection.reference_datum
            if len(ref_data.training_stage.split(".")) == len(TrainingStage)
        )
        return total_characters

    async def get_collection_total_pdf_pages(self, collection_identifier: str):
        collection = await self.get_collection(collection_identifier, partial=True)
        return await self.get_collection_total_pdf_pages_by_collection(collection)

    @staticmethod
    async def get_collection_total_pdf_pages_by_collection(collection):
        total_pages_count = sum(
            ref_data.page_count
            for ref_data in collection.reference_datum
            if len(ref_data.training_stage.split(".")) == len(TrainingStage)
        )
        return total_pages_count

