class DataLoaderUseCase:
    def _load_data(
        self, document_type: str, document_path: str, file_type: str, **kwargs
    ):
        return self.__getattribute__(f"_load_data_from_{document_type}")(
            document_path, file_type, **kwargs
        )

    @staticmethod
    def _load_data_from_text(document_path: str, file_type: str, **kwargs):
        file_type = f".{file_type}"
        if Path(document_path).is_dir():
            reader = SimpleDirectoryReader(
                input_dir=document_path, required_exts=[file_type]
            )
        else:
            reader = SimpleDirectoryReader(
                input_files=[document_path], required_exts=[file_type]
            )
        return reader.load_data()

    def __call__(self, doc_metadata: DocDataRepositoryInput):
        documents = self._load_data(
            document_type=doc_metadata.content_type,
            document_path=doc_metadata.document_path,
            file_type=doc_metadata.doc_type,
        )
        preprocessed_documents = self.preprocess_documents(
            documents, collection_name=doc_metadata.collection_name
        )
        return preprocessed_documents

    @staticmethod
    def preprocess_documents(documents, collection_name: str):
        if collection_name in DataPreprocessors:
            data_preprocessor = DataPreprocessors[collection_name]()
        else:
            data_preprocessor = DataPreprocessors["default"]()
        return data_preprocessor(documents)

def process(docx, img_dir=None):
    text = ""

    # unzip the docx in memory
    zipf = zipfile.ZipFile(docx)
    filelist = zipf.namelist()

    # get header text
    # there can be 3 header files in the zip
    header_xmls = "word/header[0-9]*.xml"
    for fname in filelist:
        if re.match(header_xmls, fname):
            text += xml2text(zipf.read(fname))

    # get main text
    doc_xmls = "word/document.*.xml"
    for fname in filelist:
        if re.match(doc_xmls, fname):
            text += xml2text(zipf.read(fname))

    # get footer text
    # there can be 3 footer files in the zip
    footer_xmls = "word/footer[0-9]*.xml"
    for fname in filelist:
        if re.match(footer_xmls, fname):
            text += xml2text(zipf.read(fname))

    if img_dir is not None:
        # extract images
        for fname in filelist:
            _, extension = os.path.splitext(fname)
            if extension in [".jpg", ".jpeg", ".png", ".bmp"]:
                dst_fname = os.path.join(img_dir, os.path.basename(fname))
                with open(dst_fname, "wb") as dst_f:
                    dst_f.write(zipf.read(fname))

    zipf.close()
    return text.strip()

class FileLoader(AbstractLoaderInterface):
    """Concrete implementation for loading file content."""

    def __init__(self):
        """Initialize the FileLoader."""
        pass

    async def __call__(self, record: DataRecord) -> str:
        """Process a file data record and return raw text.

        Args:
            record: The file data record to process.

        Returns:
            Raw text content extracted from the file.

        Raises:
            ValueError: When the file type is unsupported or processing fails.
            RuntimeError: For other processing errors.
        """
        if record.data_type not in [DataType.DOCX, DataType.DOC, DataType.TXT]:
            raise ValueError(f"FileLoader can only process file records, got {record.data_type}")

        return self.load_file(record.data_path)

    def load_file(self, file_path: str) -> str:
        """Load and extract text from a file.

        Args:
            file_path: Path to the file to be loaded

        Returns:
            The extracted text content

        Raises:
            ValueError: If the file type is unsupported or there's an issue with the file
        """
        self.file_path = file_path
        file_type = self.file_path.split(".")[-1]
        try:
            if file_type == DataType.DOCX:
                try:
                    text = docx2txt.process(self.file_path)
                except Exception as e:
                    try:
                        if str(e) == "File is not a zip file":
                            with open(self.file_path, "r", encoding="utf-8") as file:
                                text = file.read()
                        else:
                            raise e
                    except Exception:
                        raise ValueError("Bad formatted .docx file!!")
            elif file_type == DataType.DOC:
                text = self.extract_text_from_doc(self.file_path)
                text = self.get_restyled_doc_text(text)
            elif file_type == DataType.TXT:
                with open(self.file_path, "r", encoding="utf-8") as file:
                    text = file.read()
            else:
                raise ValueError(f"Unsupported file type: {file_type}")
        except Exception as e:
            raise e

        return text

    def extract_text_from_doc(self, file_path: str) -> str:
        try:
            result = subprocess.run(
                ["antiword", file_path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
            )
            if result.returncode == 0:
                return result.stdout
            else:
                raise Exception(f"Error processing file {file_path}: {result.stderr}")
        except FileNotFoundError:
            raise Exception(
                "antiword is not installed. Install it with `sudo apt-get install antiword`.",
            )
        except Exception as e:
            raise Exception(f"An error occurred: {str(e)}")

    def get_restyled_doc_text(self, text: str) -> str:
        text = re.sub(r" {8}", "\t", text)
        lines = text.split("\n")
        cleaned_text = "\n".join(lines)
        cleaned_text = re.sub(r"\n{2,}", "\n\n", cleaned_text)
        return cleaned_text.strip()

    def __call__(self, file_path: str) -> str:
        """Process a file and return its text content.

        Args:
            file_path: Path to the file to be processed

        Returns:
            The extracted text content
        """
        return self.load_file(file_path)

class FileLoader(AbstractLoaderInterface):
    """Concrete implementation for loading file content."""

    async def __call__(self, record: DataRecord) -> str:
        """Process a file data record and return raw text.

        Args:
            record: The file data record to process.

        Returns:
            Raw text content extracted from the file.

        Raises:
            PageEmptyError: When the file contains no usable content.
            ValueError: When the file type is unsupported or file is corrupted.
            RuntimeError: For other processing errors.
        """
        if record.data_type not in [DataType.DOCX, DataType.DOC, DataType.TXT]:
            raise ValueError(f"FileLoader can only process file records, got {record.data_type}")

        try:
            text = self._load_file_content(record.data_path, record.data_type)

            return text.strip()

        except PageEmptyError:
            raise
        except Exception as exc:
            raise RuntimeError(f"Failed to load file {record.data_path}: {exc}") from exc

    def _load_file_content(self, file_path: str, data_type: DataType) -> str:
        """Load content based on file type.

        Args:
            file_path: Path to the file.
            data_type: Type of the file.

        Returns:
            Extracted text content.

        Raises:
            ValueError: When file type is unsupported or file is corrupted.
        """
        if data_type == DataType.DOCX:
            return self._load_docx_file(file_path)
        elif data_type == DataType.DOC:
            return self._load_doc_file(file_path)
        elif data_type == DataType.TXT:
            return self._load_txt_file(file_path)
        else:
            raise ValueError(f"Unsupported file type: {data_type}")

    def _load_docx_file(self, file_path: str) -> str:
        """Load content from DOCX file.

        Args:
            file_path: Path to the DOCX file.

        Returns:
            Extracted text content.

        Raises:
            ValueError: When file is corrupted or cannot be processed.
        """
        try:
            return docx2txt.process(file_path)
        except Exception as e:
            # Fallback: try reading as plain text if zip error
            if str(e) == "File is not a zip file":
                try:
                    with open(file_path, "r", encoding="utf-8") as file:
                        return file.read()
                except Exception:
                    raise ValueError("Bad formatted .docx file!!") from e
            else:
                raise ValueError(f"Cannot process DOCX file: {e}") from e

    def _load_doc_file(self, file_path: str) -> str:
        """Load content from DOC file using antiword.

        Args:
            file_path: Path to the DOC file.

        Returns:
            Extracted and styled text content.

        Raises:
            ValueError: When antiword is not available or processing fails.
        """
        try:
            result = subprocess.run(
                ["antiword", file_path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
            )
            if result.returncode == 0:
                return self._restyle_doc_text(result.stdout)
            else:
                raise ValueError(f"Error processing file {file_path}: {result.stderr}")
        except FileNotFoundError:
            raise ValueError("antiword is not installed. Install it with `sudo apt-get install antiword`.")
        except Exception as e:
            raise ValueError(f"An error occurred processing DOC file: {e}") from e

    def _load_txt_file(self, file_path: str) -> str:
        """Load content from TXT file.

        Args:
            file_path: Path to the TXT file.

        Returns:
            File content as text.

        Raises:
            ValueError: When file cannot be read.
        """
        try:
            with open(file_path, "r", encoding="utf-8") as file:
                return file.read()
        except Exception as e:
            raise ValueError(f"Cannot read TXT file: {e}") from e

    def _restyle_doc_text(self, text: str) -> str:
        """Clean and restyle text extracted from DOC files.

        Args:
            text: Raw text from antiword.

        Returns:
            Cleaned and styled text.
        """
        # Replace 8 spaces with tab
        text = re.sub(r" {8}", "\t", text)

        # Split into lines and rejoin
        lines = text.split("\n")
        cleaned_text = "\n".join(lines)

        # Reduce multiple newlines to double newlines
        cleaned_text = re.sub(r"\n{2,}", "\n\n", cleaned_text)

        return cleaned_text.strip()

