class CategoryExtractor:
    """Return main categories and still‑unresolved products."""

    def __init__(
        self,
        ecommerce_repository: IRobotEcommerceRepository,
        collection_repository: IRobotCollectionRepository,
        ecommerce_loader: BaseProductLoader = None,
    ) -> None:
        self.ecommerce_repository = ecommerce_repository
        self.collection_repository = collection_repository
        self.ecommerce_loader = ecommerce_loader

        LOGGER.info("CategoryExtractor initialised")

    async def __call__(
        self, ecommerce_identifier: str, ecommerce: Ecommerce = None
    ) -> Tuple[Dict[str, List[str]], List[str], str]:
        """Return main categories with their relevant products and still‑unresolved products.

        Args:
            ecommerce_identifier: The unique identifier for the ecommerce.
            ecommerce: Optional Ecommerce object.

        Returns:
            A tuple containing:
                - A dictionary mapping each category to a list of relevant product names.
                - A list of product names with no resolved category.
                - The ecommerce address string.
        """
        if ecommerce is None:
            ecommerce = await self.ecommerce_repository.get_ecommerce_by_id(ecommerce_identifier)
        products = ecommerce.products or []
        address = products[0].permalink.split("product")[0] if products else ""

        seen_name_products: set[str] = set()
        final_products = []

        for prd in products:
            if prd.name in seen_name_products:
                continue
            final_products.append(prd)
            seen_name_products.add(prd.name)

        cat_counter: Counter[str] = Counter()
        cat_to_products: Dict[str, List[str]] = {}
        no_cat: List[str] = []

        # Track all products that get categorized
        categorized_products: Set[str] = set()

        client_db_categories_tree = []

        if self.ecommerce_loader is None:
            LOGGER.warning(f"No ecommerce_loader available for {ecommerce_identifier}")
        else:
            collection_info = await self.collection_repository.get_collection_info_by_id(ecommerce_identifier)
            if not collection_info or not collection_info.woocommerce_auth:
                LOGGER.error(f"No WooCommerce auth found for collection {ecommerce_identifier}")
            else:
                try:
                    woocommerce_auth = WoocommerceAuth.model_validate(collection_info.woocommerce_auth)
                    client_db_categories_tree = await self.ecommerce_loader.get_categories(
                        woocommerce_auth=woocommerce_auth,
                        from_page=1,
                        to_page=None,
                        page=None,
                        per_page=50,
                        modified_after=None,
                    )
                    LOGGER.info(f"Successfully fetched {len(client_db_categories_tree)} categories from WooCommerce")
                except Exception as e:
                    LOGGER.error(f"Error fetching WooCommerce categories for {ecommerce_identifier}: {e}")

        # First pass: categorize products with existing categories/tags
        for p in final_products:
            raw = (p.categories or []) + (p.tags or [])
            if raw:
                cands = [getattr(c, "name", str(c)) for c in raw]
                best = self._select_best_category(self._match(cands, p.name))
                if best:
                    cat_counter[best] += 1
                    cat_to_products.setdefault(best, []).append(p.name)
                    categorized_products.add(p.name)
                    continue
            no_cat.append(p.name)

        # Second pass: map uncategorized products to known categories
        if no_cat and cat_counter:
            newly_categorized: List[str] = []
            remaining_no_cat: List[str] = []

            for product_name in no_cat:
                ptoks = self._tok(product_name)
                matched_cat = None

                # Find best matching known category
                for known_cat in cat_counter.keys():
                    cat_toks = self._tok(known_cat)
                    if self._is_better_category_match(ptoks, cat_toks, matched_cat):
                        matched_cat = known_cat

                if matched_cat:
                    cat_counter[matched_cat] += 1
                    cat_to_products.setdefault(matched_cat, []).append(product_name)
                    newly_categorized.append(product_name)
                    categorized_products.add(product_name)
                else:
                    remaining_no_cat.append(product_name)

            no_cat = remaining_no_cat

        # Third pass: derive new categories from remaining uncategorized products
        if no_cat:
            derived_cats, still_unresolved = self._derive(no_cat)
            newly_categorized_from_derived: Set[str] = set()

            for product_name in no_cat:
                ptoks = self._tok(product_name)
                matched_derived_cat = None

                # Find best matching derived category
                for derived_cat in derived_cats.keys():
                    cat_toks = self._tok(derived_cat)
                    if self._is_better_category_match(ptoks, cat_toks, matched_derived_cat):
                        matched_derived_cat = derived_cat

                if matched_derived_cat and product_name not in still_unresolved:
                    cat_counter[matched_derived_cat] += derived_cats[matched_derived_cat]
                    cat_to_products.setdefault(matched_derived_cat, []).append(product_name)
                    newly_categorized_from_derived.add(product_name)
                    categorized_products.add(product_name)

            # Update no_cat to only include truly unresolved products
            no_cat = [p for p in still_unresolved if p not in newly_categorized_from_derived]

        # Apply deduplication to categories
        deduped_categories = self._dedup(cat_counter)

        # Build final categories dict with deduplicated categories
        final_categories: Dict[str, List[str]] = {}
        category_mapping = self._build_category_mapping(cat_counter, deduped_categories)

        for final_cat in deduped_categories:
            final_categories[final_cat] = []

        # Map products to final deduplicated categories
        for original_cat, products_list in cat_to_products.items():
            final_cat = category_mapping.get(original_cat, original_cat)
            if final_cat in final_categories:
                final_categories[final_cat].extend(products_list)

        # Remove duplicates from product lists
        for cat in final_categories:
            final_categories[cat] = list(set(final_categories[cat]))

        return final_categories, no_cat, client_db_categories_tree, address

    def _is_better_category_match(self, ptoks, cat_toks, matched_cat) -> bool:
        """Check if the current category match is better than the previous one."""
        if all(t in ptoks for t in cat_toks):
            return matched_cat is None or len(cat_toks) > len(self._tok(matched_cat))
        return False

    def _build_category_mapping(self, original_counter: Counter[str], deduped_categories: List[str]) -> Dict[str, str]:
        """Build mapping from original categories to deduplicated categories.

        Args:
            original_counter: Counter of original categories.
            deduped_categories: List of deduplicated categories.

        Returns:
            Dictionary mapping original category names to final category names.
        """
        mapping: Dict[str, str] = {}

        for original_cat in original_counter.keys():
            # Find the best match in deduped categories
            best_match = None
            best_score = 0

            for deduped_cat in deduped_categories:
                # Check if original category is a substring or vice versa
                if original_cat == deduped_cat:
                    best_match = deduped_cat
                    break
                elif original_cat in deduped_cat or deduped_cat in original_cat:
                    score = len(set(self._tok(original_cat)) & set(self._tok(deduped_cat)))
                    if score > best_score:
                        best_score = score
                        best_match = deduped_cat

            mapping[original_cat] = best_match or original_cat

        return mapping

    # helpers ------------------------------------------------------------
    @staticmethod
    def _tok(txt: str) -> List[str]:
        return [t.lower() for t in TOKEN_RE.findall(txt)]

    def _match(self, cats: List[str], pname: str) -> List[str]:
        ptoks = self._tok(pname)
        return [c for c in cats if all(t in ptoks for t in self._tok(c))]

    @staticmethod
    def _select_best_category(m: List[str]) -> str | None:
        return max(m, key=lambda x: len(x.split())) if m else None

    def _map_to_known(self, known: Set[str], names: List[str]) -> Tuple[Counter[str], List[str]]:
        res: Counter[str] = Counter()
        rem: List[str] = []
        for n in names:
            nt = self._tok(n)
            match = next((k for k in known if all(t in nt for t in self._tok(k))), None)
            if match:
                res[match] += 1
            else:
                rem.append(n)
        return res, rem

    def _derive(self, names: List[str]) -> Tuple[Counter[str], List[str]]:
        tok_freq: Counter[str] = Counter()
        for n in names:
            for t in self._tok(n):
                if not DIGIT_RE.search(t) and not LATIN_RE.search(t) and t not in STOPWORDS:
                    tok_freq[t] += 1

        derived: Counter[str] = Counter()
        unresolved: List[str] = []
        for n in names:
            cands: List[str] = []
            for t in self._tok(n):
                if t in STOPWORDS or DIGIT_RE.search(t) or LATIN_RE.search(t):
                    continue
                if tok_freq[t] < 3 and len(cands) >= 2:
                    break
                cands.append(t)
                if len(cands) == 4:
                    break
            if len(cands) >= 2:
                derived[" ".join(cands)] += 1
            else:
                unresolved.append(n)
        return derived, unresolved

    @staticmethod
    def _dedup(counter: Counter[str]) -> List[str]:
        groups: defaultdict[str, Tuple[str, int]] = defaultdict(lambda: ("", 0))
        for cat, cnt in counter.items():
            key = " ".join(cat.split()[:3])
            short = groups[key][0]
            if not short or len(cat.split()) < len(short.split()):
                groups[key] = (cat, cnt)
        cats = [v[0] for v in groups.values()]

        prefixes = {" ".join(c.split()[:i]) for c in cats for i in range(1, len(c.split()))}
        filtered = [
            c
            for c in cats
            if not any(
                p in counter and p != c and len(c.split()) == len(p.split()) + 1 and c.startswith(p) for p in prefixes
            )
        ]
        filtered.sort(key=lambda c: counter[c], reverse=True)
        return filtered

if __name__ == "__main__":

    async def main() -> None:
        from parschat_logic.app_container import get_container

        container = get_container()
        er = container[IRobotEcommerceRepository]
        cr = container[IRobotCollectionRepository]
        ext = CategoryExtractor(er, cr)
        ids = await er.get_all_ecommerce_identifiers()
        res: Dict[str, Dict[str, Set[str]]] = {}
        for i in tqdm(ids):
            try:
                cats, noc, addr = await ext(i)
                bucket = res.setdefault(addr, {"categories": set(), "no_categories": set()})
                bucket["categories"].update(cats)
                bucket["no_categories"].update(noc)
            except Exception as e:  # noqa: BLE001
                LOGGER.error("%s: %s", i, e)
        with open("categories_by_address_2.json", "w", encoding="utf-8") as f:
            json.dump(
                {
                    a: {
                        "categories": sorted(d["categories"], key=str.lower),
                        "no_categories": sorted(d["no_categories"]),
                    }
                    for a, d in res.items()
                },
                f,
                ensure_ascii=False,
                indent=2,
            )

    asyncio.run(main())

