class FAQGenerator:
    def __init__(
        self,
        config: Config,
        llm_models: Dict[str, ILLMModel],
        embedding_models,
        prompts: IFAQPrompts,
    ):
        self.config = config
        self.llm_models = llm_models
        self.embedding_models = embedding_models
        self.prompts = prompts
        self.load_chains()

    async def overall_faq_generator(
        self,
        collection: Collection,
        **kwargs,
    ) -> List[FAQ] | None:
        try:
            tasks = [
                self.generate_title_faq(collection),
                self.generate_chatbot_general_faq(collection),
            ]
            if collection.collection_info.use_faq_generator:
                tasks.extend(
                    [
                        self.generate_dislike_phrases(collection),
                        self.generate_full_content_faq_from_summary(collection),
                        self.generate_greeting_faq(collection),
                    ]
                )
            result = await asyncio.gather(*tasks)
            final_list = [faq for each_method in result for faq in each_method]
            return final_list
        except Exception as e:
            LOGGER.error(
                "Unable to generate overall QA for collection_models %s\nbecause: %s"
                % (collection.collection_info.identifier, str(e)),
            )
            raise RuntimeError(
                "Unable to generate overall QA for collection_models %s" % collection.collection_info.identifier,
            )

    async def file_faq_generator(
        self,
        collection_identifier: str,
        file_data: ReferenceDataWrapper,
        title: str,
    ) -> List[FAQ] | None:
        try:
            LOGGER.debug("Extracting questions from collection_models in FAQ")
            result = await asyncio.gather(
                self.question_generator(file_data, title),
                self.process_summary_faq(file_data),
            )
            final_list = [faq for each_method in result for faq in each_method]
            return final_list
        except Exception as e:
            LOGGER.error(
                "Unable to generate file QA for collection_models %s and reference data %s\nbecause: %s"
