    async def generate_heading_faq_from_summary(
        self,
        summarized_data: Summary,
        reference_data_wrapper: ReferenceDataWrapper,
    ) -> List[FAQ]:
        # FIXME: language for each summary
        try:
            chunk_language = self.get_chunk_language(
                self.get_chunk_from_chunk_id(
                    summarized_data.chunk_ids[0],
                    reference_data_wrapper.chunks,
                ).language,
            )
            questions = await self.heading_question_generator_chain.ainvoke(
                {
                    "language": chunk_language,
                    "summarized_data": summarized_data.content,
                    "heading_value": self.get_heading_from_chunk_id(
                        summarized_data.chunk_ids[0],
                        reference_data_wrapper,
                    ).heading_value,
                },
            )
            json_str_match = re.search(r"\{.*}", questions.content, re.DOTALL)

            question_list = []
            if json_str_match:
                json_str = json_str_match.group(0)
                json_str = json_str.replace("\\u200", "")

                try:
                    data = json.loads(json_str)
                    question_list = data.get("Question", [])
                except json.JSONDecodeError as e:
                    LOGGER.error(json_str_match)
                    LOGGER.error(f"JSONDecodeError: {e}")
                    LOGGER.warning("Invalid JSON format. Ignoring and continuing...")
            else:
                LOGGER.error("Generator = Bad Response!!")

            result = await self.heading_answer_generator_chain.ainvoke(
                {
                    "language": chunk_language,
                    "summarized_data": summarized_data.content,
                    "questions": question_list,
                },
            )
            post_processed_result = await self.post_process_generated_faq(
                generated_text=result.content,
                ids=summarized_data.chunk_ids,
                type="heading_summary",
                prefix="\n".join(summarized_data.content.splitlines()[:2]),
            )
            return post_processed_result
        except Exception as e:
            LOGGER.error(f"Error generating heading FAQ from summary: {e}")
            return []

    async def generate_full_content_faq_from_summary(
        self,
        collection: Collection,
    ) -> List[FAQ]:
        try:
            faqs = []
            for summary in collection.data_summaries:
                if summary.type == "main":
                    chunk_language = self.get_chunk_language(
                        self.get_chunk_from_chunk_id(
                            summary.chunk_ids[0],
                            collection.chunks,
                        ).language,
                    )
                    result = await self.full_content_faq_from_summary_chain.ainvoke(
