                        },
                    )
                    post_processed_result = await self.post_process_generated_faq(
                        generated_text=result.content,
                        ids=summary.chunk_ids,
                        type="main_summary",
                    )
                    faqs.extend(post_processed_result)
            return faqs
        except Exception as e:
            LOGGER.error(f"Error generating full content FAQ from summary: {e}")
            return []

    async def process_summary_faq(self, reference_data_wrapper: ReferenceDataWrapper) -> List[FAQ]:
        try:
            async_list_summary_func = []
            for summary in reference_data_wrapper.data_summaries:
                if summary.type == "heading":
                    async_list_summary_func.append(
                        functools.partial(
                            self.generate_heading_faq_from_summary,
                            summary,
                            reference_data_wrapper,
                        ),
                    )

            full_result = await asyncio.gather(
                *[func() for func in async_list_summary_func],
            )
            faqs = [faq for result in full_result for faq in result]
            return faqs
        except Exception as e:
            LOGGER.error(f"Error processing summary FAQ: {e}")
            return []

    async def question_generator(
        self,
        reference_data_wrapper: ReferenceDataWrapper,
    ) -> List[FAQ]:
        try:
            faqs = []

            async def process_chunk(chunk: Chunk, title: str):
                result = await self.chunk_faq_chain.ainvoke(
                    {
                        "language": self.get_chunk_language(chunk.language),
                        "chunk_content": chunk.content,
                        "title": title,
                    },
                )
                post_processed_result = await self.post_process_generated_faq(
                    generated_text=result.content,
                    ids=[chunk.id],
                    type="chunk",
                    prefix="\n".join(chunk.content.splitlines()[:3]),
                )
                return post_processed_result

            tasks = [process_chunk(chunk, reference_data_wrapper.title) for chunk in reference_data_wrapper.chunks]
            results = await asyncio.gather(*tasks)

            for result in results:
                faqs.extend(result)

            return faqs
        except Exception as e:
            LOGGER.error(f"Error generating questions for chunks: {e}")
            return []

    async def post_process_generated_faq(
        self,
        generated_text: str,
        ids: List[int],
        type: str,
        prefix: str = "",
    ) -> List[FAQ]:
        try:
            faqs = []
            faq_list = []
            json_str_match = re.search(r"\{.*}", generated_text, re.DOTALL)
            if json_str_match:
                json_str = json_str_match.group(0)
                json_str = json_str.strip()

                try:
                    data = json.loads(json_str)
                    faq_list = data.get("FAQ", [])
                except json.JSONDecodeError as e:
                    LOGGER.error(
                        f"JSONDecodeError: {e}. for {generated_text} and {ids}."
                        f"Invalid JSON format. Ignoring and continuing...",
                    )
            else:
                LOGGER.warning("No JSON string found in the generated text.")

            if isinstance(faq_list, list):
                for faq in faq_list:
                    # TODO: what if the language wasn't persian? then we cannot use this normalizer
                    clean_question = faq["Question"]
                    clean_answer = faq["Answer"]

                    faqs.append(
                        FAQ(
                            id=get_current_utc_time(),
                            question=clean_question,
                            answer=clean_answer,
                            type=type,
                            chunk_ids=ids,
                            question_vector=await self.create_embedding_vector(
                                "\n".join([prefix, clean_question, clean_answer])
                            ),
                            answer_vector=[0.1, 0.2],
                        ),
                    )
            else:
                clean_question = faq_list["Question"].replace("\u200c", "")
                clean_answer = faq_list["Answer"].replace("\u200c", "")
                faqs.append(
                    FAQ(
                        id=get_current_utc_time(),
                        question=clean_question,
                        answer=clean_answer,
                        chunk_ids=ids,
                        type=type,
                        question_vector=await self.embedding_models["faq_embedding_model"].aembed_query(clean_question),
                        answer_vector=[0.1, 0.2],
                    ),
                )
            return faqs
        except Exception as e:
            LOGGER.error(f"Error post-processing generated FAQ: {e}")
            return []

    @staticmethod
    def parse_string_to_list(input_str: str) -> List[str]:
        try:
            cleaned_str = input_str.strip("[]")
            items = cleaned_str.split("،")
            items = [item.strip() for item in items]
            return items
        except Exception as e:
            LOGGER.error(f"Error parsing string to list: {e}")
            return []

    def get_heading_from_chunk_id(
        self,
        chunk_id: int,
        reference_data_wrapper: ReferenceDataWrapper,
    ) -> Heading:
        try:
            for chunk in reference_data_wrapper.chunks:
                if chunk.id == chunk_id:
                    return self.get_heading_from_heading_id(chunk.heading_id, reference_data_wrapper)
        except Exception as e:
            LOGGER.error(f"Error getting heading from chunk ID: {e}")

    def get_chunk_from_chunk_id(self, id: int, chunks: List[Chunk]) -> Chunk:
        try:
            for chunk in chunks:
                if chunk.id == id:
                    return chunk
        except Exception as e:
            LOGGER.error(f"Error getting chunk from chunk ID: {e}")

    def get_heading_from_heading_id(
        self,
        heading_id: int,
        reference_data_wrapper: ReferenceDataWrapper,
    ) -> Heading:
        try:
            for heading in reference_data_wrapper.headings:
                if heading.id == heading_id:
                    return heading
        except Exception as e:
            LOGGER.error(f"Error getting heading from heading ID: {e}")

    async def create_embedding_vector(self, input_text: str) -> List[float]:
        try:
            embedding = await self.embedding_models["faq_embedding_model"].aembed_query(
                input_text,
            )
            return embedding
        except Exception as e:
            LOGGER.error(f"Error creating embedding vector: {e}")
            return []

    def get_chunk_language(self, language_dict: Dict[str, float]) -> str:
        language = sorted(language_dict.items(), key=lambda e: e[1], reverse=True)[0][0]
        return language

    async def create_faq(self, raw_faq: RawFAQ, chunk_ids: List[int]) -> FAQ:
        return FAQ(
            id=get_current_utc_time(),
            identifier=raw_faq.identifier,
            question=raw_faq.question,
            answer=raw_faq.answer,
            type="manual",
            chunk_ids=chunk_ids,
            question_vector=await self.create_embedding_vector(raw_faq.question),
            answer_vector=[0.1, 0.2],
        )

    async def update_faqs(
        self,
        new_faq: FAQ,
        old_faqs: List[FAQ],
        collection_info: CollectionInfo,
    ) -> List[FAQ]:
        try:
            new_faq_string = f"question: {new_faq.question}\nanswer: {new_faq.answer}"
            old_faqs_string = ""
            for index, faq in enumerate(old_faqs):
                old_faqs_string += f"FAQ id: {index}\n"
                old_faqs_string += f"question: {faq.question}\n"
                old_faqs_string += f"answer: {faq.answer}\n\n"

            if old_faqs_string != "":
                results = await run_chain(
                    chain=self.update_faq_chain | self.prompts.update_faq_output_parser,
                    parameters={
                        "language": collection_info.language,
                        "title": collection_info.title,
                        "new_faq": new_faq_string,
                        "old_faqs": old_faqs_string,
                    },
                    max_retries=5,
                    name="update_faq",
                    assertion="if result['updated_faqs']: assert 'id' in result['updated_faqs'][0]\nelse: None",
                )

                if len(results["updated_faqs"]) > 0:
                    updated_faqs = []
                    for result in results["updated_faqs"]:
                        index = int(result["id"])
                        faq = old_faqs[index]
                        faq.question = result["question"]
                        faq.answer = result["answer"]
                        faq.identifier = new_faq.identifier
                        faq.chunk_ids = new_faq.chunk_ids
                        faq.type = "manual"
                        updated_faqs.append(faq)

                    return updated_faqs

            return [new_faq]

        except Exception as e:
            LOGGER.error(
                "something went wrong with updating similar faqs!\nError: %s" % e,
            )
            return []

