def config_validator(constructor):
    """
    checks if the config has defined history limitations keys  or not.
    """

    def wrapper_1(self, *args, **kwargs):
        if not hasattr(kwargs["config"], "max_token_len") or not hasattr(
            kwargs["config"],
            "last_n_conversation",
        ):
            raise KeyError(
                "You must provide max_token_len and last_n_conversation keys in config!",
            )

        algorithm = constructor(self, *args, **kwargs)

        return algorithm

    return wrapper_1

