class BaseQueryProcessor(ABC):
    def __init__(self, config: BaseConfig, llm_model: ILLMModel) -> None:
        super().__init__()
        self.config = config
        self.llm_model = llm_model

    def preprocess(self, input_message: str, history: str, **kwargs) -> Query:
        query = Query(
            intent=self.intent_detection(input_message),
            emotion=self.emotion_detection(input_message),
            is_offensive=self.insult_detection(input_message),
            is_spam=self.spam_detection(input_message),
            similar_queries=self.query_paraphrasing(input_message, history),
        )
        return query

    @abstractmethod
    def intent_detection(self, input_message: str, history: str, **kwargs) -> List[str]:
        pass

    @abstractmethod
    def emotion_detection(self, input_message: str, **kwargs) -> Emotion:
        pass

    @abstractmethod
    def insult_detection(self, input_message: str, **kwargs) -> bool:
        pass

    def spam_detection(self, input_message: str, **kwargs) -> bool:
        return False

    @abstractmethod
    def query_paraphrasing(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        pass

    @abstractmethod
    def chain_of_thoughts(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        pass

    def __call__(self, input_message: str, history: str, **kwargs) -> Query:
        return self.preprocess(input_message, history)

