def get_cleaned_messages(messages: list) -> list:
    """Clean messages by removing previous function calls and tool messages between HumanMessage and AIMessage spans.

    Only keeps tool calls and tool messages after the last unresponded human message.

    Args:
        messages: List of messages to clean.

    Returns:
        List of cleaned messages with function calls and tool messages removed from completed spans,
        but preserved after the last unresponded human message.
    """
    if not messages:
        return []

    last_human_index = -1
    for i in range(len(messages) - 1, -1, -1):
        if isinstance(messages[i], HumanMessage):
            last_human_index = i
            break

    has_response_after_last_human = False
    if last_human_index >= 0:
        for i in range(last_human_index + 1, len(messages)):
            message = messages[i]
            if isinstance(message, AIMessage) and message.content and not getattr(message, "tool_calls", None):
                has_response_after_last_human = True
                break

    cleaned_messages = []
    i = 0

    while i < len(messages):
        current_message = messages[i]

        if isinstance(current_message, HumanMessage):
            cleaned_messages.append(current_message)
            i += 1

            if i - 1 == last_human_index and not has_response_after_last_human:
                while i < len(messages):
                    cleaned_messages.append(messages[i])
                    i += 1
                break

            while i < len(messages):
                message = messages[i]

                if isinstance(message, AIMessage) and message.content and not message.tool_calls:
                    cleaned_messages.append(message)
                    i += 1
                    break
                elif isinstance(message, (ToolMessage, AIMessage)):
                    i += 1
                    continue
                elif isinstance(message, HumanMessage):
                    break
                else:
                    i += 1
        else:
            cleaned_messages.append(current_message)
            i += 1

    return cleaned_messages

def get_evaluated_tool_content(message):
    """Safely evaluate tool message content.

    Args:
        message: The message containing content to evaluate.

    Returns:
        Evaluated content or None if evaluation fails.
    """
    try:
        return json.loads(message.content)
    except Exception:
        return None

def _print_event(event: dict, _printed: set, max_length=1500):
    """Print graph event for debugging."""
    current_state = event.get("dialog_state")
    if current_state:
        LOGGER.info("Currently in: ", current_state[-1])
    message = event.get("messages")
    if message:
        if isinstance(message, list):
            message = message[-1]
        if message.id not in _printed:
            msg_repr = message.pretty_repr(html=True)
            if len(msg_repr) > max_length:
                msg_repr = msg_repr[:max_length] + " ... (truncated)"
            LOGGER.info(msg_repr)
            _printed.add(message.id)

