            self.tools.append(autorag_tool)

        self.runnable = self.primary_assistant_prompt | self.llm_model.bind_tools(self.tools)

    def format_messages_for_prompt(self, state: State) -> str:
        """
        Format the messages in the state for inclusion in the prompt.
        """
        lines = ["\n"]
        msgs = state.get("messages", [])

        def _safe_text(content):
            if isinstance(content, list):
                parts = []
                for c in content:
                    if isinstance(c, dict) and "text" in c:
                        parts.append(str(c["text"]))
                    else:
                        parts.append(str(c))
                return "\n".join(parts).strip()
            return (content or "").strip()

        for m in msgs:
            if isinstance(m, tuple) and len(m) == 2:
                role, content = m
                text = _safe_text(content)
                if role == "user":
                    lines.append(f"HumanMessage: {text}\n")
                elif role == "ai":
                    if text:
                        lines.append(f"AIMessage: {text}\n")
                elif role == "tool":
                    lines.append(f"ToolMessage: {text}\n")
                else:
                    pass
                continue

            role = getattr(m, "type", None) or getattr(m, "role", None)
            content = _safe_text(getattr(m, "content", None))

            if role == "human":
                lines.append(f"HumanMessage: {content}\n")

            elif role == "ai":
                tool_calls = getattr(m, "tool_calls", None) or []
                if tool_calls:
                    for tc in tool_calls:
                        tname = (
                            tc.get("name") if isinstance(tc, dict) else getattr(tc, "name", None)
                        ) or "unknown_tool"
                        tid = (tc.get("id") if isinstance(tc, dict) else getattr(tc, "id", None)) or "unknown_id"
                        lines.append(f"AIMessage: tool name: {tname} -> Tool_id : {tid}\n")
                else:
                    if content:
                        lines.append(f"AIMessage: {content}\n")

            elif role == "tool":
                tname = getattr(m, "name", None) or "unknown_tool"
                tid = getattr(m, "tool_call_id", None) or "unknown_id"
                lines.append(f"ToolMessage: {tname} - {tid} : {content}\n")
            else:
                pass
        return "\n".join(lines).rstrip()

    async def __call__(self, state: State, config: RunnableConfig):
        if not self.runnable:
            LOGGER.error("graph's runnable is not defined! Await assistant.init_tools_and_runnable() first.")
            return
        if state.get("ai_tag") == 3:
            return {}
        while True:
            configuration = config.get("configurable", {})
            language = configuration.get("query_language", "PERSIAN")
            formatted_history = self.format_messages_for_prompt(state)
            time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            state_with_context = {
                **state,
                "language": language,
                "current_product_context": self.get_product_context(state),
                "messages": formatted_history,
                "time": time,
            }
            result = await self.runnable.ainvoke(state_with_context)
            if not result.tool_calls and (
                not result.content or isinstance(result.content, list) and not result.content[0].get("text")
            ):
                messages = state["messages"] + [("user", "Respond with a real output.")]
                state = {**state, "messages": messages}
            else:
                break
        return {"messages": result}

    def get_product_context(self, state: State) -> str:
        """Get the current product context for the assistant."""
        if state.get("current_product"):
            product = state["current_product"]
            current_product_context = f"""
────────────────────────────────────────────────
CURRENT PRODUCT OF INTEREST
────────────────────────────────────────────────
The user is currently viewing this product:
{product}

When the user asks questions, consider this product as their primary context unless they specify otherwise.
────────────────────────────────────────────────
"""
        else:
            current_product_context = "No current product context available."

        return current_product_context

