class ProductProcessingMixin:
    def combine_products_with_priority(self, keyword_products: List[Any], semantic_products: List[Any]) -> List[Any]:
        """Combine keyword and semantic products, prioritizing keyword results.

        Args:
            keyword_products: Products from keyword search.
            semantic_products: Products from semantic search.

        Returns:
            Combined list of products.
        """
        combined_products: List[Any] = []
        product_ids: set = set()
        for product in keyword_products:
            product_id = getattr(product, "id", None)
            if product_id and product_id not in product_ids:
                combined_products.append(product)
                product_ids.add(product_id)
        for product in semantic_products:
            product_id = self.get_product_id(product)
            if product_id and product_id not in product_ids:
                processed_product = self.process_product(product)
                if processed_product:
                    combined_products.append(processed_product)
                    product_ids.add(product_id)
        return combined_products

    def get_product_id(self, product: Any) -> Optional[Union[int, str]]:
        """Get the product ID from a product object or dict.

        Args:
            product: Product object or dict.

        Returns:
            Product ID or None.
        """
        if isinstance(product, dict):
            return product.get("id")
        return getattr(product, "id", None)

    def process_product(self, product: Any) -> Optional[Product]:
        """Convert a dict product to a Product model, or return as is if already a Product.

        Args:
            product: Product object or dict.

        Returns:
            Product model or None if conversion fails.
        """
        try:
            if isinstance(product, dict):
                self.prepare_product_data(product)
                return Product(**product)
            return product
        except Exception as e:
            LOGGER.warning(f"Failed to process product: {e}")
            return None

    def prepare_product_data(self, product_data: dict) -> None:
        """Prepare product data dict for Product model instantiation.

        Args:
            product_data: Product data dictionary.
        """
        if "short_description" not in product_data:
            product_data["short_description"] = None
        if "id" in product_data and isinstance(product_data["id"], str):
            try:
                product_data["id"] = int(product_data["id"])
            except Exception as e:
                LOGGER.warning(f"Failed to convert product id to int: {e}")
        if "upsell_ids" in product_data and isinstance(product_data["upsell_ids"], str):
            try:
                product_data["upsell_ids"] = [int(id_str.strip()) for id_str in product_data["upsell_ids"].split(",")]
            except Exception as e:
                LOGGER.warning(f"Failed to convert upsell_ids to list of ints: {e}")
        if "related_ids" in product_data and isinstance(product_data["related_ids"], str):
            try:
                if "," in product_data["related_ids"]:
                    product_data["related_ids"] = [
                        int(id_str.strip()) for id_str in product_data["related_ids"].split(",")
                    ]
                else:
                    product_data["related_ids"] = [int(product_data["related_ids"].strip())]
            except Exception as e:
                LOGGER.warning(f"Failed to convert related_ids to list of ints: {e}")
                product_data["related_ids"] = []
        if "variations" in product_data and isinstance(product_data["variations"], str):
            try:
                if "," in product_data["variations"]:
                    product_data["variations"] = [
                        int(id_str.strip()) for id_str in product_data["variations"].split(",")
                    ]
                else:
                    product_data["variations"] = [int(product_data["variations"].strip())]
            except Exception as e:
                LOGGER.warning(f"Failed to convert variations to list of ints: {e}")
                product_data["variations"] = []

    async def filter_irrelevant_products(self, queries: List[str], products: List[Any]) -> List[Any]:
        """Filter out irrelevant products using the validator chain.

        Args:
            queries: List of query variations.
            products: List of products to validate.

        Returns:
            List of validated products.
        """
        validated_products: List[Any] = []
        LOGGER.info(f"Validating {len(products)} products with validator chain")
        validation_tasks = [self.validate_product(queries[0], product) for product in products]
        validation_results = await asyncio.gather(*validation_tasks)
        for product, is_valid in zip(products, validation_results):
            product_name = getattr(product, "name", "Unknown")
            if is_valid:
                validated_products.append(product)
                LOGGER.debug(f"Product '{product_name}' passed validation")
            else:
                LOGGER.info(f"Filtered out irrelevant product: '{product_name}' for query: {queries[0]}")
        LOGGER.info(f"Validation complete: {len(validated_products)}/{len(products)} products passed validation")
        return validated_products

    def _extract_products_from_docs(self, retrieved_docs_list: List[List[Document]]) -> List[Any]:
        products = []

        for docs in retrieved_docs_list:
            for doc in docs:
                if hasattr(doc, "metadata") and "product" in doc.metadata:
                    product_data = doc.metadata["product"]

                    if isinstance(product_data, Product):
                        products.append(product_data)
                    elif isinstance(product_data, dict):
                        try:
                            self._prepare_product_data(product_data)
                            product_model = Product(**product_data)
                            products.append(product_model)
                        except Exception as e:
                            LOGGER.warning(f"Failed to convert product data to model: {e}")
                            products.append(product_data)

        return products

    async def _validate_products(self, query: str, products: List[Product]) -> List[Product]:
        """Validate products using multiple validation chains and reranking.

        Args:
            query: The user query string.
            products: List of products to validate.

        Returns:
            List of validated products.
        """
        try:
            if not products:
                return products

            # Step 1: Run validator_chain and name_validator_chain in parallel
            normal_validated_products = []
            names_validated_products = []

            validator_tasks = [
                self._validate_single_product_with_normal_validator(query, product) for product in products
            ]
            names_tasks = [self._validate_single_product_with_names_validator(query, product) for product in products]

            validator_results, names_results = await asyncio.gather(
                asyncio.gather(*validator_tasks, return_exceptions=True),
                asyncio.gather(*names_tasks, return_exceptions=True),
            )

            normal_validated_products = [
                product for product, is_valid in zip(products, validator_results) if is_valid == "YES"
            ]
            names_validated_products = [
                product for product, is_valid in zip(products, names_results) if is_valid == "YES"
            ]

            # Step 2: Take logical AND of results for final filtering decision
            final_validated_products = []
            if normal_validated_products and names_validated_products:
                validator_ids = {product.id for product in normal_validated_products}
                names_ids = {product.id for product in names_validated_products}
                intersected_ids = validator_ids & names_ids
                final_validated_products = [product for product in products if product.id in intersected_ids]
            elif normal_validated_products:
                final_validated_products = normal_validated_products
            elif names_validated_products:
                final_validated_products = names_validated_products

            LOGGER.info(
                f"Validation results - Normal Validated: {len(normal_validated_products)}, "
                f"Names Validated: {len(names_validated_products)}, "
                f"Final: {len(final_validated_products)}"
            )

            # Step 3-6: Apply reranking logic based on count
            if len(final_validated_products) > 5:
                # Rerank the final validated products
                return await self._rerank_products(query, final_validated_products)
            elif 1 < len(final_validated_products) <= 5:
                # Return as-is if between 1 and 5 products
                logging_result = "\n".join([p.name for p in final_validated_products])
                LOGGER.info(f"Selected products after validation (no reranking): {logging_result}")
                return final_validated_products
            else:
                # Use all normal_validated_products as fallback plan
                if len(normal_validated_products) > 5:
                    return await self._rerank_products(query, normal_validated_products)
                else:
                    logging_result = "\n".join([p.name for p in normal_validated_products])
                    LOGGER.info(f"Selected products after validator chain: {logging_result}")
                    return normal_validated_products

        except Exception as e:
            LOGGER.warning(f"Error in product validation: {e}")
            return products[:5]

    async def _validate_single_product_with_normal_validator(self, query: str, product: Product) -> bool:
        """Validate a single product using the normal validator chain.

        Args:
            query: The user query string.
            product: Product to validate.

        Returns:
            True if product is valid, False otherwise.
        """
        try:
            product_info = f"product name: {product.name}\n" f"product details: {product.short_description}"
            result = await self._validator_chain.ainvoke({"query": query, "product_info": product_info})
            return result
        except Exception as e:
            LOGGER.warning(f"Error in single product validation: {e}")
            return False

    async def _validate_single_product_with_names_validator(self, query: str, product: Product) -> bool:
        """Validate a single product using the names validator chain.

        Args:
            query: The user query string.
            product: Product to validate.

        Returns:
            True if product name is valid, False otherwise.
        """
        try:
            result = await self._name_validator_chain.ainvoke({"query": query, "product_name": product.name})
            return result
        except Exception as e:
            LOGGER.warning(f"Error in product name validation: {e}")
            return False

    async def _rerank_products(self, query: str, products: List[Product]) -> List[Product]:
        """Rerank products based on semantic similarity scores from metadata.

        Args:
            query: The user query string.
            products: List of products to rerank.

        Returns:
            List of reranked products sorted by semantic similarity score.
        """
        try:
            products_with_scores = []

            for product in products:
                score = float(product.metadata[0].value) or 0.0
                products_with_scores.append((product, score))

            sorted_products = sorted(products_with_scores, key=lambda x: x[1], reverse=True)
            reranked_products = [product for product, _ in sorted_products]

            logging_result = "\n".join(
                [f"{p.name} (score: {self._extract_semantic_score(p)})" for p in reranked_products]
            )
            LOGGER.info(f"Selected products after reranking by semantic score: {logging_result}")

            return reranked_products

        except Exception as e:
            LOGGER.warning(f"Error in product reranking by semantic score: {e}")
            return products[:5]

class TruncatedEmbeddingWrapper:
    def __init__(self, base_model: Any, max_dimensions: int) -> None:
        self.base_model = base_model
        self.max_dimensions = max_dimensions

    async def aembed_query(self, text: str) -> Any:
        embeddings = await self.base_model.aembed_query(text)
        return normalize_l2(embeddings[: self.max_dimensions])

    def embed_query(self, text: str) -> Any:
        embeddings = self.base_model.embed_query(text)
        return normalize_l2(embeddings[: self.max_dimensions])

class ProductSearchMixin:
    async def retrieve_docs_by_multiquery_fusion(
        self,
        query: str,
        **kwargs: Any,
    ) -> List[Product]:
        """Retrieve products using multi-query fusion (keyword + semantic).

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            Combined list of products from keyword and semantic search.
        """
        queries = self.extract_query_variations(query, **kwargs)
        # keyword_products, semantic_products = await asyncio.gather(
        #     self.perform_keyword_search(query, **kwargs),
        #     self.perform_semantic_search_if_needed(queries=queries, **kwargs),
        # )
        semantic_products = (await self.perform_semantic_search_if_needed(queries=queries, **kwargs),)
        # combined_products = self.combine_products_with_priority(keyword_products, semantic_products)
        return semantic_products[0]

    async def search_by_name(self, query: str, max_results: int = 4, **kwargs: Any) -> List[Any]:
        """Search products by name using the repository.

        Args:
            query: Product name query.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products matching the name.
        """
        try:
            min_price = kwargs.get("min_price")
            max_price = kwargs.get("max_price")

            if min_price is not None or max_price is not None:
                search_query = self._build_name_search_query_with_price_filter(query, min_price, max_price, max_results)
                return await self.ecommerce_repo.get_product_by_query(
                    ecommerce_identifier=self.ecommerce_identifier,
                    query=search_query,
                )
            else:
                traditional_products, _ = await self.ecommerce_repo.search_products_by_name(
                    ecommerce_identifier=self.ecommerce_identifier,
                    name=query,
                    max_results=max_results,
                )
                return traditional_products
        except Exception as e:
            LOGGER.warning(f"Error in product retriever search: {e}")
            return []

    def extract_query_variations(self, query: str, **kwargs: Any) -> List[str]:
        """Extract query variations for multi-query fusion.

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments.

        Returns:
            List of query variations.
        """
        if "queries" in kwargs and kwargs["queries"]:
            return kwargs["queries"]
        return [query]

    async def perform_keyword_search(self, query: str, **kwargs: Any) -> List[Any]:
        """Perform keyword-based product search.

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products from keyword search.
        """
        try:
            return await self.search_by_name(query, **kwargs)
        except Exception as e:
            LOGGER.warning(f"Error in keyword search: {e}")
            return []

    async def perform_semantic_search_if_needed(self, queries: List[str], **kwargs: Any) -> List[Any]:
        """Perform semantic search using dual retrieval if a retriever is available.

        Args:
            queries: List of query variations.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products from dual semantic search.
        """
        if self.retrieval:
            run_manager = AsyncCallbackManagerForRetrieverRun.get_noop_manager()
            raw_semantic_products = await asyncio.gather(
                *[self._aget_relevant_documents(q, run_manager=run_manager, **kwargs) for q in queries]
            )
            semantic_products = raw_semantic_products[0] if raw_semantic_products else []

            LOGGER.info(f"Dual retrieval returned {len(semantic_products)} products for queries: {queries}")
            return semantic_products
        return []

    def _build_name_search_query_with_price_filter(
        self, query: str, min_price: float = None, max_price: float = None, size: int = 4
    ) -> dict:
        """Build Elasticsearch query for name search with price filtering.

        Args:
            query: The product name query.
            min_price: Minimum price filter.
            max_price: Maximum price filter.
            size: Maximum number of results.

        Returns:
            Elasticsearch query dictionary.
        """
        price_filters = []
        if min_price is not None:
            price_filters.append({"range": {"product.price": {"gte": min_price}}})
        if max_price is not None:
            price_filters.append({"range": {"product.price": {"lte": max_price}}})

        query = {
            "size": size,
            "_source": {"excludes": ["product.product_vector", "product.custom_attributes.vector"]},
            "query": {
                "bool": {
                    "should": [
                        {
                            "multi_match": {
                                "query": query,
                                "fields": [
                                    "product.name^5",
                                    "product.short_description",
                                    "product.description",
                                ],
                                "operator": "and",
                                "minimum_should_match": "90%",
                                "boost": 5,
                            }
                        },
                        {
                            "fuzzy": {
                                "product.name": {
                                    "value": query,
                                    "fuzziness": 1,
                                    "boost": 6,
                                    "prefix_length": 1,
                                }
                            }
                        },
                        {
                            "nested": {
                                "boost": 1,
                                "path": "product.categories",
                                "query": {
                                    "match": {
                                        "product.categories.name": {
                                            "query": query,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                        {
                            "nested": {
                                "boost": 1,
                                "path": "product.tags",
                                "query": {
                                    "match": {
                                        "product.tags.name": {
                                            "query": query,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                    ],
                    "minimum_should_match": 1,
                    "filter": price_filters,
                }
            },
        }

        if max_price:
            query["sort"] = [{"product.price": {"order": "desc"}}]

        return query

