def is_jalali_date(date_str: str) -> bool:
    """
    تشخیص این که تاریخ جلالی است یا میلادی.
    قانون:
    - اگر فرمت ISO داشت → میلادی
    - اگر سال >= 1700 → میلادی
    - بقیه → جلالی
    """
    if date_str is None:
        return False
    s = str(date_str)
    if "T" in s or "Z" in s:
        return False
    s = s.translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    try:
        year = int(s[:4])
    except:
        return False
    if year >= 1700:
        return False
    if year >= 1000:
        return True
    return False

class GetOrderTool(BaseTool):
    name: str = "get_order"
    description: str = ToolDescriptionPrompt.GetOrderTool_prompt_template.invoke({}).text
    args_schema: Type[BaseModel] = GetOrderInput
    tags: Optional[List[str]] = ["tool:get_order_tool"]

    def __init__(self, woocommerce_auth: WoocommerceAuth, tool_prompt: str | None, **kwargs: Any):
        super().__init__(**kwargs)
        self._wc_auth = woocommerce_auth
        if tool_prompt is not None:
            self.description = tool_prompt
        self._essential_order_properties = [
            "id",
            "parent_id",
            "number",
            "status",
            "date_created",
            "date_modified",
            "customer_id",
            "customer_note",
            "shipping",
            "payment_method_title",
            "date_paid",
            "date_completed",
            "line_items",
            "refunds",
            "tracking_code",
            "shipping_type",
            "tracking_instructions",
            "shipping_advice",
        ]
        self._custom_statuses = None

    async def get_custom_statuses(self):
        self._custom_statuses = await wcpl.get_custom_statuses(self._wc_auth)

    def _run(
        self,
        order_id: int,
        state: Annotated[Dict[str, Any], InjectedState],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> str:
        return "ERROR! This tool must be called async!"

    async def _arun(
        self,
        order_id: int,
        state: Annotated[Dict[str, Any], InjectedState],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> dict[str, Any] | str:
        try:
            order = await wcpl.get_order(self._wc_auth, order_id)
            if not order:
                raise Exception("Empty order from Woocommerce!")
            order_dict = order.model_dump()
            order_dict["tracking_code"] = "No tracking code submitted yet."
            for key in ["date_created", "date_modified", "date_paid", "date_completed"]:
                if order_dict[key] is not None:
                    date_value = str(order_dict[key])
                    if not is_jalali_date(date_value):
                        order_dict[key] = convert_iso_datetime_to_jalali(date_value)
            if self._custom_statuses is not None:
                order_dict["status"] = self._custom_statuses.get(order_dict["status"], order_dict["status"])
                for meta in order_dict.get("meta_data", []):
                    if meta.get("key") == "post_track_number":
                        order_dict["tracking_code"] = meta.get("value")
                        break
                for shipping_line in order_dict.get("shipping_lines", []):
                    if "method_title" in shipping_line:
                        order_dict["shipping_type"] = shipping_line["method_title"]
                        break
            order_dict = {key: order_dict.get(key) for key in self._essential_order_properties}

            order_notes = await wcpl.get_order_notes(self._wc_auth, order_id, False)
            post_tracking_codes = []
            for order_note in order_notes:
                post_tracking_code = extract_post_tracking_code(order_note["note"])
                if post_tracking_code:
                    post_tracking_codes.append(post_tracking_code)
            if len(post_tracking_codes) > 0:
                order_dict["post_tracking_codes"] = post_tracking_codes

            city = (order_dict.get("shipping") or {}).get("city", "").strip().lower()
            total_amount = float(order_dict.get("total") or 0)
            hour = 12  # default hour

            # Extract hour from order creation date
            date_value = str(order_dict.get("date_created") or "")
            if " " in date_value and ":" in date_value:
                hour = int(date_value.split(" ")[1].split(":")[0])
            elif "T" in date_value:
                hour = int(date_value.split("T")[1].split(":")[0])

            # Check if the order was previously placed via messenger
            messenger_order = any(
                meta.get("key") in ["_billing_mnsjay_location", "_shipping_mnsjay_location"] and meta.get("value")
                for meta in order_dict.get("meta_data", [])
            )

            shipping_advice = ""
            if city in ["tehran", "تهران", "karaj", "کرج"]:
                if hour < 12:
                    shipping_advice = (
                        "✅ سفارش شما تهران/کرج است. ثبت قبل از ساعت ۱۲ با پرداخت ۱۵۰ هزار تومان، همان روز تحویل می‌شود."
                    )
                else:
                    shipping_advice = "✅ سفارش شما تهران/کرج است. ثبت بعد از ساعت ۱۲ به صبح روز بعد ارسال می‌شود."
            else:
                shipping_advice = (
                    "📦 سفارش‌های شهرستان معمولا با باربری وطن ارسال می‌شوند و تحویل بین ۲ تا ۳ روز کاری طول می‌کشد.\n"
                    "💡 برای اطلاع از هزینه ارسال، سفارش را در سایت ثبت کنید و گزینه باربری را انتخاب کنید."
                )
                if total_amount < 3_000_000:
                    shipping_advice += "\n💰 برای سفارش‌های زیر ۳ میلیون، پست به صرفه‌تر است."
                else:
                    shipping_advice += "\n💰 برای سفارش‌های بالای ۳ میلیون، باربری اقتصادی‌تر است."

            order_dict["shipping_advice"] = shipping_advice

            # Add tracking and messenger instructions
            tracking_message = (
                "اگر مشتری کد رهگیری می‌خواهد، شماره ثبت سفارش ۵ رقمی را اعلام کنید تا کد رهگیری ارسال شود.\n"
            )
            if messenger_order:
                tracking_message += "اگر سفارش قبلاً از طریق پیام‌رسان ثبت شده، بهتر است از همان پیام‌رسان پیگیری شود."

            order_dict["tracking_instructions"] = tracking_message

            return self._process_orders(order_dict)
        except Exception as e:
            LOGGER.warning(f"There was a problem in getting order with id {order_id}: {e}")
            return f"No order found! Ask the user to see if they have provided the correct order id.\
If it is happening after 3 times, ask the user to contact customer support.\
Remember to speak in the {state.get('language', 'PERSIAN')} language."

    def _process_orders(self, order_data: dict[str, Any]) -> list[dict[str, Any]]:
        """Process a single order dictionary and return it in a standardized format list."""
        if not order_data:
            return []

        order_dict = order_data.copy()

        # Ensure tracking code
        order_dict["tracking_code"] = order_dict.get("tracking_code", "No tracking code submitted yet.")

        # Extract tracking code from meta_data (if present)
        for meta in order_dict.get("meta_data", []):
            if meta.get("key") == "post_track_number":
                order_dict["tracking_code"] = meta.get("value")
                break

        # Extract shipping type (from shipping_lines or top-level field)
        if "shipping_lines" in order_dict:
            for shipping_line in order_dict.get("shipping_lines", []):
                if "method_title" in shipping_line:
                    order_dict["shipping_type"] = shipping_line["method_title"]
                    break
        else:
            # Fallback if already exists
            order_dict["shipping_type"] = order_dict.get("shipping_type", "نامشخص")

        # Keep only essential properties
        order_dict = {key: order_dict.get(key) for key in self._essential_order_properties if key in order_dict}

        # Remove address fields from shipping and billing
        address_fields = ["address_1", "address_2", "city"]

        if order_dict.get("shipping"):
            shipping = order_dict["shipping"].copy()
            for field in address_fields:
                shipping.pop(field, None)
            order_dict["shipping"] = shipping

        if order_dict.get("billing"):
            billing = order_dict["billing"].copy()
            for field in address_fields:
                billing.pop(field, None)
            order_dict["billing"] = billing

        # # Convert Jalali date fields if they exist
        # for key in ["date_created", "date_modified", "date_paid", "date_completed"]:
        #     if order_dict.get(key):
        #         order_dict[key] = convert_iso_datetime_to_jalali(str(order_dict[key]))

        # Apply custom statuses if defined
        if getattr(self, "_custom_statuses", None) and order_dict.get("status"):
            order_dict["status"] = self._custom_statuses.get(order_dict["status"], order_dict["status"])

        return [order_dict]

