class GeneratorNode:
    def __init__(
        self,
        ecommerce_identifier: str,
        ecommerce_repo: IRobotEcommerceRepository,
        llm_models: dict,
    ):
        get_product_by_id_tool = GetProductByIdTool(ecommerce_identifier, ecommerce_repo)
        self._need_clarification_chain = NeedClarificationPrompt.template | llm_models["light-model"]
        self._clearifying_question_chain = (
            ClearifyingQuestion.template | llm_models["light-model"] | ClearifyingQuestion.parser
        )
        self._generator_chain = GeneratorPrompt.template | llm_models["generator-model"].bind_tools(
            [get_product_by_id_tool]
        )

    def get_cleaned_messages(self, messages: list) -> list:
        """Clean messages by removing function calls and tool messages between HumanMessage and AIMessage spans.
        Only keeps tool calls and tool messages after the last unresponded human message.

        Args:
            messages: List of messages to clean.

        Returns:
            List of cleaned messages with function calls and tool messages removed from completed spans,
            but preserved after the last unresponded human message.
        """
        if not messages:
            return []

        last_human_index = -1
        for i in range(len(messages) - 1, -1, -1):
            if isinstance(messages[i], HumanMessage):
                last_human_index = i
                break

        has_response_after_last_human = False
        if last_human_index >= 0:
            for i in range(last_human_index + 1, len(messages)):
                message = messages[i]
                if isinstance(message, AIMessage) and message.content and not getattr(message, "tool_calls", None):
                    has_response_after_last_human = True
                    break

        cleaned_messages = []
        i = 0

        while i < len(messages):
            current_message = messages[i]

            if isinstance(current_message, HumanMessage):
                cleaned_messages.append(current_message)
                i += 1

                if i - 1 == last_human_index and not has_response_after_last_human:
                    while i < len(messages):
                        cleaned_messages.append(messages[i])
                        i += 1
                    break

                while i < len(messages):
                    message = messages[i]

                    if isinstance(message, AIMessage) and message.content and not message.tool_calls:
                        cleaned_messages.append(message)
                        i += 1
                        break
                    elif isinstance(message, (ToolMessage, AIMessage)):
                        i += 1
                        continue
                    elif isinstance(message, HumanMessage):
                        break
                    else:
                        i += 1
            else:
                cleaned_messages.append(current_message)
                i += 1

        return cleaned_messages

    async def __call__(self, state: State, config: RunnableConfig):
        last_tool_call_index = -1
        clearifying_questions = None
        last_call = "__end__"
        tool_message = state["messages"][-1].model_copy()
        cleaned_messages = self.get_cleaned_messages(state["messages"])
        need_clarification: bool = True

        if isinstance(state["messages"][-1], ToolMessage):
            for i, message in enumerate(reversed(state["messages"])):
                if hasattr(message, "tool_calls") and message.tool_calls:
                    last_tool_call_index = len(state["messages"]) - 1 - i
                    break
        last_tool_call = state["messages"][last_tool_call_index].tool_calls[0] if last_tool_call_index >= 0 else None

        if last_tool_call and last_tool_call["name"] == "product_retriever_tool":
            with contextlib.suppress(Exception):
                tool_message.content = [
                    {"name": product["name"], "short_description": product["short_description"]}
                    for product in eval(state["messages"][-1].content)
                ]

            if last_tool_call["args"].get("max_price") or last_tool_call["args"].get("min_price", 0) > 1:
                need_clarification = False

            if need_clarification:
                need_clarification_result = await self._need_clarification_chain.ainvoke(
                    {"history": create_full_history_string(cleaned_messages[:-1] + [tool_message])}
                )
                if "generate" not in need_clarification_result.content.lower():
                    need_clarification = False

            if need_clarification:
                clearifying_questions = await run_chain(
                    self._clearifying_question_chain,
                    {"history": create_full_history_string(cleaned_messages[:-1] + [tool_message])},
                    3,
                    "clearifying_question_chain",
                    "assert 'response_text' in result",
                )
                return Command(
                    update={
                        "messages": [AIMessage(clearifying_questions["response_text"])],
                        "last_call": last_call,
                        "benefit_mapping": clearifying_questions.get("benefit_mapping", {}),
                    },
                    goto="__end__",
                )

            else:
                generator_result = await self._generator_chain.ainvoke(
                    {
                        "history": create_full_history_string(cleaned_messages),
                    }
                )
                if generator_result.tool_calls:
                    last_call = generator_result.tool_calls[0]["name"]
                    return Command(
                        update={"messages": [generator_result], "last_call": last_call},
                        goto="tools",
                    )
                return Command(
                    update={"messages": [generator_result], "last_call": last_call},
                    goto="__end__",
                )

        elif last_tool_call and last_tool_call["name"] == "get_product_by_id_tool":
            generator_result = await self._generator_chain.ainvoke(
                {
                    "history": create_full_history_string(cleaned_messages),
                }
            )
            if generator_result.tool_calls:
                last_call = generator_result.tool_calls[0]["name"]
                return Command(
                    update={"messages": [generator_result], "last_call": last_call},
                    goto="tools",
                )
            return Command(
                update={"messages": [generator_result], "last_call": last_call},
                goto="__end__",
            )

def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

class AssistantGraph:
    def __init__(self, assistant: Assistant, generator: GeneratorNode, order_tracker_subgraph):
        self.builder = StateGraph(State)

        self.builder.add_node("assistant", assistant.__call__)
        self.builder.add_node("order_tracker_tool", order_tracker_subgraph)

        self.builder.add_node(
            "tools",
            create_tool_node_with_fallback(assistant.tools),
            retry=RetryPolicy(max_attempts=3),  # TODO: tune this
        )
        self.builder.add_node("generator", generator.__call__)

        self.builder.add_edge(START, "assistant")
        self.builder.add_conditional_edges("assistant", self.tools_condition)
        self.builder.add_edge("order_tracker_tool", END)
        self.builder.add_conditional_edges("tools", self.after_search_condition)

        self.memory = MemorySaver()
        self.graph = self.builder.compile(checkpointer=self.memory)

    def tools_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call in ["order_tracker_tool", "__end__"]:
            return last_call
        else:
            return "tools"

    def after_search_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call in ["product_retriever_tool", "get_product_by_id_tool"]:
            return "generator"
        else:
            return "assistant"

