def _print_event(event: dict, _printed: set, max_length=1500):
    current_state = event.get("dialog_state")
    if current_state:
        LOGGER.info("Currently in: ", current_state[-1])
    message = event.get("messages")
    if message:
        if isinstance(message, list):
            message = message[-1]
        if message.id not in _printed:
            msg_repr = message.pretty_repr(html=True)
            if len(msg_repr) > max_length:
                msg_repr = msg_repr[:max_length] + " ... (truncated)"
            LOGGER.info(msg_repr)
            _printed.add(message.id)

class Algorithm:
    def __init__(
        self,
        db_repository: RobotCollectionRepository,
        config,
        llm_models,
        autorag_algo,
        **kwargs,
    ):
        self.db_repository = db_repository
        self.config = config
        self.llm_models = llm_models
        self.autorag_algo = autorag_algo
        self.assistant = None
        self.graph = None
        self.collection_info = None

    async def get_collection_info(self):
        try:
            _collection_info = await self.db_repository.get_collection_info_by_id(
                self.config.collection_identifier["prod"],
            )
            if _collection_info is None:
                _collection_info = await self.db_repository.get_collection_info_by_id(
                    self.config.collection_identifier["dev"],
                )
        except Exception as e:
            LOGGER.warning(f"Loading hamichizdon warning: {e}")
            _collection_info = await self.db_repository.get_collection_info_by_id(
                self.config.collection_identifier["dev"],
            )

        self.collection_info = _collection_info
        self.ps_auth = APIAuth(base_url="")  # APIAuth.model_validate(self.config.auth)
        self.assistant = Assistant(self.ps_auth, self.autorag_algo, _collection_info)
        self.graph = AssistantGraph(self.assistant)

    def _update_result_history_and_tag(
        self,
        input_data: AlgorithmInput,
        result: GeneratorResult,
        query_tag: QueryTag,
    ):
        if not input_data.history:
            history = []
        else:
            history = input_data.history.copy()
        history.append(
            {
                "human": input_data.message,
                "ai": result.generated_text,
                "query_tag": (
                    QueryTag.CONNECT_OPERATOR.value if result.ai_tag == AiTagType.ASSIGN_OPERATOR else query_tag.value
                ),
                "relevance_tag": RelevanceDegree.GENERAL.value,
            },
        )
        # if the generation chains specified `not_enough` tag, the last conversation in result.history
        # demonstrates that with setting the query_tag to `CONNECT_OPERATOR`, so updating the last conversation with it
        if result.history:
            history[-1].update(result.history[-1])
        result.history = history

        # query_tag = self.check_frequent_more_explain(input_data.history, query_tag, query_processor_tasks)

        if query_tag == QueryTag.CONNECT_OPERATOR:
            result.ai_tag = AiTagType.ASSIGN_OPERATOR

    async def __call__(
        self,
        graph_input: AlgorithmInput,
    ) -> GeneratorResult:
        try:
            if not self.graph:
                raise ValueError("Error in calling the graph, you have to call Algorithm.get_collection_info() first!")

            query_language = (
                detect_language_percentages(graph_input.message, state="inference")
                if self.collection_info.dynamic_language["use_dynamic_language"]
                else self.collection_info.dynamic_language["default_language"]
            )

            message = graph_input.message

            thread_id = graph_input.chat_id
            user_id = graph_input.chat_id  # TODO: change for user_input
            config = {
                "configurable": {
                    "thread_id": thread_id,
                    "user_id": user_id,
                    "query_language": query_language,
                },
                "external_config": self.config.model_dump(),
            }

            events = self.graph.graph.astream(
                {
                    "messages": ("user", message),
                    "algorithm_input": graph_input,
                    "client_state": graph_input.client_state,
                    "ai_tag": 0,
                },
                config=config,
                stream_mode="values",
            )

            if isinstance(events, GeneratorType):
                for event in events:
                    _print_event(event, _printed)
                    ai_response = event["messages"][-1].content

                    if hasattr(event["messages"][-1], "tool_calls") and event["messages"][-1].tool_calls:
                        for tool_call in event["messages"][-1].tool_calls:
                            if tool_call["name"] == "connect_operator":
                                event["ai_tag"] = 3
            elif isinstance(events, AsyncGenerator):
                async for event in events:
                    _print_event(event, _printed)
                    ai_response = event["messages"][-1].content

                    if hasattr(event["messages"][-1], "tool_calls") and event["messages"][-1].tool_calls:
                        for tool_call in event["messages"][-1].tool_calls:
                            if tool_call["name"] == "connect_operator":
                                event["ai_tag"] = 3
            else:
                ai_response = events["messages"][-1].content

                if hasattr(events["messages"][-1], "tool_calls") and events["messages"][-1].tool_calls:
                    for tool_call in events["messages"][-1].tool_calls:
                        if tool_call["name"] == "connect_operator":
                            events["ai_tag"] = 3

            response = GeneratorResult(
                generated_text=ai_response,
                thread_id=thread_id,
                query_language=query_language,
                client_state=event.get("client_state", {}),
                ai_tag=event.get("ai_tag", 0),
            )

            self._update_result_history_and_tag(
                graph_input,
                response,
                QueryTag.NORMAL,
            )

            LOGGER.debug(f"\nRESPONSE = {response}\n")

            return response

        except Exception as e:
            LOGGER.error(f"Error invoking the graph: {e}")
            return GeneratorResult(
                generated_text=self.collection_info.default_assigning_operator_message,
                thread_id=thread_id,
                query_language=query_language,
                ai_tag=3,
            )

