class HamechizDanScraper:
    """Scrapes product data from HamechizDan website"""

    def __init__(self, base_url: str = "https://hamechizdan.com"):
        self.base_url = base_url
        self.api_url = f"{base_url}/api/parschat"
        self.session = requests.Session()
        self.session.headers.update(
            {
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                    "(KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
                ),
                "Accept": "application/json, text/plain, */*",
                "Accept-Language": "fa,en-US;q=0.9,en;q=0.8",
                "Referer": base_url,
            }
        )
        self.all_products = []
        self.product_ids = set()
        self.collection_ids = set()

    def fetch_all_products(self):
        self.extract_collections_from_homepage()
        self.extract_products_from_api()
        self.extract_products_from_collections_api()
        self.extract_products_by_sequential_ids()
        unique_products = self.remove_duplicate_products()
        return unique_products

    def extract_collections_from_homepage(self):
        try:
            response = self.session.get(f"{self.base_url}/collections")
            if response.status_code == 200:
                soup = BeautifulSoup(response.text, "html.parser")
                for a in soup.find_all("a", href=True):
                    href = a["href"]
                    collection_match = re.search(r"/collections/(\d+)", href)
                    if collection_match:
                        collection_id = int(collection_match.group(1))
                        if collection_id not in self.collection_ids:
                            self.collection_ids.add(collection_id)
                            self.extract_products_from_collection_page(collection_id)
        except Exception as e:
            LOGGER.error(f"Error extracting collections from the homepage: {e}")

    def extract_products_from_collection_page(self, collection_id, max_pages=20):
        for page in range(1, max_pages + 1):
            try:
                url = f"{self.base_url}/collections/{collection_id}"
                if page > 1:
                    url = f"{url}?pp={page}"

                response = self.session.get(url)
                if response.status_code == 200:
                    soup = BeautifulSoup(response.text, "html.parser")
                    product_cards = soup.select('.product-card, .card, [class*="product"]')
                    if not product_cards and page > 1:
                        break

                    new_products_found = False
                    for a in soup.find_all("a", href=True):
                        href = a["href"]
                        product_match = re.search(r"/c/(\d+)/", href)
                        if product_match:
                            product_id = int(product_match.group(1))
                            if product_id not in self.product_ids:
                                new_products_found = True
                                self.product_ids.add(product_id)
                                self.fetch_product_details(product_id)

                    if not new_products_found and page > 1:
                        break
            except Exception as e:
                LOGGER.error(f"Error extracting products from page {page} of collection {collection_id}: {e}")
                break
            time.sleep(0.5)

    def extract_products_from_api(self):
        page = 1
        max_pages = 100
        while page <= max_pages:
            try:
                params_options = [
                    {"page": page, "per_page": 100},
                    {"pp": page, "per_page": 100},
                    {"page": page, "limit": 100},
                    {"pp": page, "limit": 100},
                ]
                for params in params_options:
                    response = self.session.get(f"{self.api_url}/products", params=params)
                    if response.status_code == 200:
                        products = response.json()
                        if not products:
                            continue
                        for product in products:
                            product_id = product.get("id")
                            if product_id and product_id not in self.product_ids:
                                self.product_ids.add(product_id)
                                self.all_products.append(product)
                        if len(products) < 100:
                            break
                page += 1
                time.sleep(0.5)
            except Exception as e:
                LOGGER.error(f"Error extracting products from API (page {page}): {e}")
                break

    def extract_products_from_collections_api(self):
        try:
            response = self.session.get(f"{self.api_url}/collections")
            if response.status_code == 200:
                collections = response.json()
                for collection in collections:
                    collection_id = collection.get("id")
                    if not collection_id:
                        continue
                    self.collection_ids.add(collection_id)
                    try:
                        collection_response = self.session.get(f"{self.api_url}/collections/{collection_id}/products")
                        if collection_response.status_code == 200:
                            products = collection_response.json()
                            for product in products:
                                product_id = product.get("id")
                                if product_id and product_id not in self.product_ids:
                                    self.product_ids.add(product_id)
                                    self.all_products.append(product)
                    except Exception as e:
                        LOGGER.error(f"Error extracting products from collection {collection_id}: {e}")
                    time.sleep(0.5)
        except Exception as e:
            LOGGER.error(f"Error extracting collections from API: {e}")

    def extract_products_by_sequential_ids(self):
        if self.product_ids:
            min_id = max(1, min(self.product_ids) - 100)
            max_id = max(self.product_ids) + 100
            with ThreadPoolExecutor(max_workers=5) as executor:
                chunk_size = 50
                for start_id in range(min_id, max_id + 1, chunk_size):
                    end_id = min(start_id + chunk_size - 1, max_id)
                    executor.submit(self.fetch_product_range, start_id, end_id)

    def fetch_product_range(self, start_id, end_id):
        for product_id in range(start_id, end_id + 1):
            if product_id in self.product_ids:
                continue
            self.fetch_product_details(product_id)
            time.sleep(0.2)

    def fetch_product_details(self, product_id):
        try:
            response = self.session.get(f"{self.api_url}/products/{product_id}")
            if response.status_code == 200:
                product = response.json()
                self.product_ids.add(product_id)
                self.all_products.append(product)
                return product
        except Exception as e:
            LOGGER.error(f"Error retrieving product details for {product_id}: {e}")
        return None

    def remove_duplicate_products(self):
        unique_products = []
        seen_ids = set()
        for product in self.all_products:
            product_id = product.get("id")
            if product_id and product_id not in seen_ids:
                seen_ids.add(product_id)
                unique_products.append(product)
        return unique_products

class ProductUpdater:
    """Handles product updates and custom attribute management"""

    new_field_mapping = {
        "properties": {
            "costum_attribute": {
                "type": "flattened",
            },
        },
    }

    @staticmethod
    def extract_min_max_numbers(text: str) -> Tuple[Optional[int], Optional[int]]:
        if not text:
            return (None, None)

        pattern1 = r"(\d+)\s*(?:تا|الی|تا|-|–)\s*(\d+)"
        pattern2 = r"\d+"
        match = re.search(pattern1, text)
        if match:
            num1 = int(match.group(1))
            num2 = int(match.group(2))
            return (min(num1, num2), max(num1, num2))

        numbers = re.findall(pattern2, text)
        if numbers:
            numbers = [int(num) for num in numbers]
            return (min(numbers), max(numbers))

        return (None, None)

    @staticmethod
    def update_index_mapping_with_new_field(index: str, es: Elasticsearch):
        es.indices.put_mapping(index=index, body=ProductUpdater.new_field_mapping)

    @staticmethod
    def update_product_costum_attribute(index: str, es: Elasticsearch, i: int, product_api: Dict):
        age = product_api.get("age", "") or ""
        age_min, age_max = ProductUpdater.extract_min_max_numbers(age)

        update_body = {
            "query": {"term": {"product.id": i}},
            "script": {
                "source": """
                    ctx._source.costum_attribute = params.costum_attribute;
                """,
                "params": {
                    "costum_attribute": {
                        "age_min": age_min if age_min is not None else 0,
                        "age_max": age_max if age_max is not None else 0,
                        "language": str(product_api.get("language", "") or ""),
                        "accent": str(product_api.get("accent", "") or ""),
                        "gender": str(product_api.get("gender", "") or ""),
                        "average_rating": float(product_api.get("popularity_count", 0) or 0),
                        "episode_count": str(product_api.get("episode_count", "0") or "0"),
                    }
                },
            },
        }
        es.update_by_query(index=index, body=update_body)

    @staticmethod
    def update_product(products: List[Dict]) -> List[Dict]:
        updated_products = []
