def load_embedding_models(
    embedding_models_settings: Dict[str, BaseEmbeddingModelSetting],
) -> Dict[str, Any]:
    """Load embedding models using a simple approach.

    Args:
        embedding_models_settings: Dictionary of embedding model configurations.

    Returns:
        Dictionary of loaded embedding models.
    """
    embedding_models = EmbeddingModelsFactory()
    for model_setting in embedding_models_settings.values():
        if model_setting.connection_config is None:
            model_setting.connection_config = embedding_model_connection_settings
        embedding_models.register(model_setting)
    return {key: embedding_models[value] for key, value in embedding_models_settings.items()}

def _print_event(event: dict, _printed: set, max_length=1500):
    """Print graph event for debugging."""
    current_state = event.get("dialog_state")
    if current_state:
        LOGGER.info("Currently in: ", current_state[-1])
    message = event.get("messages")
    if message:
        if isinstance(message, list):
            message = message[-1]
        if message.id not in _printed:
            msg_repr = message.pretty_repr(html=True)
            if len(msg_repr) > max_length:
                msg_repr = msg_repr[:max_length] + " ... (truncated)"
            LOGGER.info(msg_repr)
            _printed.add(message.id)

