    def format_messages_for_prompt(self, state: State) -> str:
        """
        Format the messages in the state for inclusion in the prompt.
        """
        lines = ["\n"]
        msgs = state.get("messages", [])

        def _safe_text(content):
            if isinstance(content, list):
                parts = []
                for c in content:
                    if isinstance(c, dict) and "text" in c:
                        parts.append(str(c["text"]))
                    else:
                        parts.append(str(c))
                return "\n".join(parts).strip()
            return (content or "").strip()

        for m in msgs:
            if isinstance(m, tuple) and len(m) == 2:
                role, content = m
                text = _safe_text(content)
                if role == "user":
                    lines.append(f"HumanMessage: {text}\n")
                elif role == "ai":
                    if text:
                        lines.append(f"AIMessage: {text}\n")
                elif role == "tool":
                    lines.append(f"ToolMessage: {text}\n")
                else:
                    pass
                continue

            role = getattr(m, "type", None) or getattr(m, "role", None)
            content = _safe_text(getattr(m, "content", None))

            if role == "human":
                lines.append(f"HumanMessage: {content}\n")

            elif role == "ai":
                tool_calls = getattr(m, "tool_calls", None) or []
                if tool_calls:
                    for tc in tool_calls:
                        tname = (
                            tc.get("name") if isinstance(tc, dict) else getattr(tc, "name", None)
                        ) or "unknown_tool"
                        tid = (tc.get("id") if isinstance(tc, dict) else getattr(tc, "id", None)) or "unknown_id"
                        lines.append(f"AIMessage: tool name: {tname} -> Tool_id : {tid}\n")
                else:
                    if content:
                        lines.append(f"AIMessage: {content}\n")

            elif role == "tool":
                tname = getattr(m, "name", None) or "unknown_tool"
                tid = getattr(m, "tool_call_id", None) or "unknown_id"
                lines.append(f"ToolMessage: {tname} - {tid} : {content}\n")
            else:
                pass
        return "\n".join(lines).rstrip()

