class AssistantGraph:
    def __init__(self, assistant: Assistant):
        self.assistant = assistant

        self.builder = StateGraph(State)

        self.builder.add_node("assistant", assistant.__call__)

        self.builder.add_node(
            "tools",
            create_tool_node_with_fallback(assistant.tools, "tools"),
            retry=RetryPolicy(max_attempts=3),
        )

        self.builder.set_entry_point("assistant")
        self.builder.add_conditional_edges("assistant", self.assistant_tools_condition)
        self.builder.add_edge("tools", "assistant")

        self.memory = MemorySaver()
        self.graph = self.builder.compile(checkpointer=self.memory)

    @staticmethod
    def get_ai_message(state: dict[str, Any]) -> AIMessage:
        if isinstance(state, list):
            ai_message = state[-1]
        else:
            messages = state.get("messages", []) if isinstance(state, dict) else getattr(state, "messages", [])

            if messages:
                ai_message = messages[-1]
            else:
                raise ValueError(f"No messages found in input state to tool_edge: {state}")

        return ai_message

    def assistant_tools_condition(self, state: State) -> str:
        ai_message = self.get_ai_message(state)

        if hasattr(ai_message, "tool_calls") and len(ai_message.tool_calls) > 0:
            return "tools"
        return END

def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

class ProductProcessingMixin:
