class AutoRAGTool(BaseTool):
    name: str = "auto_rag_tool"
    description: str = """USE the `auto_rag_tool` for:
    1. When user describes any pain or symptom:
       - First: Search in chunks for specialty mapping (e.g. "درد عضلانی عمومی : داخلی، روماتولوژی، پزشکی فیزیکی")
       - Then: Use found specialties to search for relevant doctors
    2. General document search for FAQ/help content

    When to use this tool:
    - User describes any medical condition, pain, or symptoms
    - Need to map symptoms to medical specialties
    - Need to find doctors based on symptoms
    - General information requests when product search tools return no results

    How it works:
    1. Takes user's symptom/pain description
    2. Maps it to medical specialties using stored mappings
    3. Uses those specialties to find appropriate doctors
    4. Returns formatted response with doctor recommendations

    Input: Provide the graph state containing user's query
    Output: Returns specialty-mapped doctor recommendations or general info and ALWAYS say at the end of your\
     message : آیا میخواهید لیستی از پزشکان متخصص در ...  را به شما پیشهاد بدهم"""
    args_schema: Type[BaseModel] = AutoRAGInput
    tags: Optional[list[str]] = ["tool:auto_rag_tool"]

    def __init__(self, autorag_algo, tool_prompt: str | None, **kwargs: Any):
        super().__init__(**kwargs)
        self._autorag_algo = autorag_algo
        if tool_prompt is not None:
            self.description = tool_prompt

    def _run(
        self,
        state: Annotated[Dict[str, Any], InjectedState],
        tool_call_id: Annotated[str, InjectedToolCallId],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ):
        return "ERROR! This tool must be called async!"

    async def _arun(
        self,
        state: Annotated[Dict[str, Any], InjectedState],
        tool_call_id: Annotated[str, InjectedToolCallId],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> Command | str:
        try:
            algorithm_input = state.get("algorithm_input", {})
            autorag_output = await self._autorag_algo(algorithm_input)

            multiple_call = False
            selected_tool_id = ""
            messages = state.get("messages", [])
            if messages:
                last_msg = messages[-1]
                if isinstance(last_msg, AIMessage) and last_msg.tool_calls:
                    autorag_tool_calls = [tc for tc in last_msg.tool_calls if tc["name"] == "auto_rag_tool"]
                    if len(autorag_tool_calls) > 1:
                        multiple_call = True
                        selected_tool_id = autorag_tool_calls[0]["id"]

            if multiple_call:
                if selected_tool_id == tool_call_id:
                    return Command(
                        update={
                            "messages": [ToolMessage(autorag_output.generated_text, tool_call_id=tool_call_id)],
                            "ai_tag": autorag_output.ai_tag,
                            "retrieved_docs": autorag_output.retrieved_docs,
                            "client_state": autorag_output.client_state,
                        }
                    )
                else:
                    return Command(
                        update={
                            "messages": [ToolMessage(autorag_output.generated_text, tool_call_id=tool_call_id)],
                            "retrieved_docs": autorag_output.retrieved_docs,
                        }
                    )
            else:
                return Command(
                    update={
                        "messages": [ToolMessage(autorag_output.generated_text, tool_call_id=tool_call_id)],
                        "ai_tag": autorag_output.ai_tag,
                        "retrieved_docs": autorag_output.retrieved_docs,
                        "client_state": autorag_output.client_state,
                    }
                )
        except Exception as e:
            LOGGER.warning(f"There was a problem in the autorag tool: {e}")
            return "Could not retrieve related information from the docs!\
                Ask the user to clarify on their question."

