def process_text(text: str | None):
    if not text:
        return ""

    # Remove digits
    text = "".join([c for c in text if c not in "0123456789۰۱۲۳۴۵۶۷۸۹"])

    # Convert Arabic to Persian
    text = characters.ar_to_fa(text)

    return text.strip()

def _parse_appointment_options_from_attributes(attributes: List[dict]) -> List[dict]:
    """Parse custom attributes from the API schema.

    Each attribute with date options gets converted to a custom_attribute with value_date_range.

    Args:
        attributes: List of attribute dicts from the API.

    Returns:
        List of custom_attribute dicts with value_date_range.
    """
    custom_attributes: dict = {}

    for attr in attributes:
        attr_id = attr.get("id")
        attr_name = process_text(attr.get("name"))
        options = attr.get("options", [])

        if attr_name not in custom_attributes:
            custom_attributes[attr_name] = {
                "id": attr_id,
                "name": attr_name,
                "value_date_range": [],
            }

        for option in options:
            parsed_dt = _parse_jalali_datetime_from_text(option)

            if parsed_dt:
                gte = parsed_dt.isoformat()
                lte = (parsed_dt + datetime.timedelta(hours=2)).isoformat()

                custom_attributes[attr_name]["value_date_range"].append({"gte": gte, "lte": lte})
        custom_attributes[attr_name]["value_date_range"] = sorted(
            custom_attributes[attr_name]["value_date_range"], key=lambda x: x["gte"]
        )

    return list(custom_attributes.values())

async def _fetch_existing_product_ids(
    collection_identifier: str, ecommerce_repo: IRobotEcommerceRepository
) -> Set[int]:
    """Fetch all existing product IDs from the ecommerce Elasticsearch index.

    Queries the parschat_ecommerce_[collection_identifier] index to retrieve all product IDs.

    Args:
        collection_identifier: The collection identifier.
        ecommerce_repo: The ecommerce repository for database operations.

    Returns:
        Set of existing product IDs in the database.
    """
    try:
        product_id_strings = await ecommerce_repo.get_all_product_ids(collection_identifier)

        if not product_id_strings:
            LOGGER.info("No products found in ecommerce index")
            return set()

        existing_ids: Set[int] = set()
        for product_id_str in product_id_strings:
            try:
                product_id = int(product_id_str.replace("product_", ""))
                existing_ids.add(product_id)
            except (ValueError, AttributeError) as e:
                LOGGER.warning(f"Failed to parse product ID '{product_id_str}': {e}")

        LOGGER.info(f"Found {len(existing_ids)} existing products in ecommerce index")
        return existing_ids

    except Exception as e:
        LOGGER.error(f"Error fetching existing product IDs from ecommerce index: {e}", exc_info=True)
        return set()

def _print_event(event: dict, _printed: set, max_length=1500):
    """Print graph event for debugging."""
    current_state = event.get("dialog_state")
    if current_state:
        LOGGER.info("Currently in: ", current_state[-1])
    message = event.get("messages")
    if message:
        if isinstance(message, list):
            message = message[-1]
        if message.id not in _printed:
            msg_repr = message.pretty_repr(html=True)
            if len(msg_repr) > max_length:
                msg_repr = msg_repr[:max_length] + " ... (truncated)"
            LOGGER.info(msg_repr)
            _printed.add(message.id)

