class Algorithm:
    def __init__(
        self,
        db_repository: Any,
        config: Any,
        llm_models: dict,
        autorag_algo: Any,
        **kwargs,
    ):
        self.llm = llm_models["llm_model"]
        self.graph_builder = StateGraph(State)

        self.graph_builder.add_node("chatbot", self.chatbot)
        self.graph_builder.add_node("tools", self.tools)
        self.graph_builder.add_node("END", lambda state: state)
        self.graph_builder.add_node("route_message", self.route_message)

        self.graph_builder.add_edge(START, "route_message")
        self.graph_builder.add_conditional_edges(
            "route_message",
            lambda state: self.route_message(state)["route"],
            {"tools": "tools", "chatbot": "chatbot", "END": "END"},
        )
        self.graph_builder.add_edge("tools", "chatbot")
        self.graph_builder.add_edge("chatbot", END)
        self.graph = self.graph_builder.compile()
        self.history: List[Dict[str, str]] = []

    async def get_collection_info(self):
        pass

    def route_message(self, state: State) -> Dict[str, Any]:
        messages = state["messages"]

        if not messages:
            return {"route": "chatbot"}

        last_message = messages[-1]
        user_query = last_message.content.lower() if isinstance(last_message, BaseMessage) else str(last_message)

        if state["session"] == 0:
            return {"route": "tools"}

        if any(word in user_query for word in ["خروج", "خداحافظ", "exit", "quit"]):
            return {"route": "END"}

        formatted_prompt = prompt_template_for_intent.format(user_query=user_query)
        response = self.llm.invoke(formatted_prompt)
        intent = (response.content.strip().lower()).strip('"')

        if intent in ["next", "previous"]:
            return {"route": "tools"}

        return {"route": "chatbot"}

    def tools(self, state: State) -> Dict[str, Any]:
        session = state["session"]
        messages = state["messages"]

        last_message = messages[-1]
        user_query = last_message.content.lower() if isinstance(last_message, BaseMessage) else str(last_message)

        if session == 0:
            response_message = AIMessage(content=course_lookup(session), tools_response=True)
            return {
                "messages": messages + [response_message],
                "session": session + 1,
            }

        formatted_prompt = prompt_template_for_intent.format(user_query=user_query)
        response = self.llm.invoke(formatted_prompt)
        intent = (response.content.strip().lower()).strip('"')

        if intent == "previous":
            session = max(0, session - 1)

        course_info = course_lookup(session)
        response_message = AIMessage(content=f"جلسه {session}:\n{course_info}", tools_response=True)
        return {
            "messages": messages + [response_message],
            "session": session + 1,
        }

    def chatbot(self, state: State) -> Dict[str, Any]:
        messages = state["messages"]
        session = state["session"]

        last_message = messages[-1]
        if isinstance(last_message, AIMessage) and getattr(last_message, "tools_response", True):
            return {"messages": messages, "session": session}

        user_query = last_message.content if isinstance(last_message, BaseMessage) else str(last_message)

        formatted_prompt = prompt_template.format(
            user_query=user_query,
            history=json.dumps(self.history, ensure_ascii=False),
            session=session,
        )
        response = self.llm.invoke(formatted_prompt)

        return {
            "messages": messages + [AIMessage(content=response.content)],
            "session": session,
        }

    async def __call__(self, input: AlgorithmInput) -> GeneratorResult:
        LOGGER.debug("Entered the '__call__' method in algotithm.py")
        state = State(
            messages=input.message,
            session=(int(input.client_state.get("session", 0)) if input.client_state not in [None, {}] else 0),
        )
        if state["session"] > 12:
            response = GeneratorResult(
                generated_text="منون از شما، همکارم با شما ارتباط میگیرند تا لینک آزمون رو خدمتتون ارسال کنند.",
                ai_tag=AiTagType.ASSIGN_OPERATOR,
                client_state={"session": str(state["session"])},
            )
        else:
            result = self.graph.invoke(state)
            if not result["messages"]:
                raise ValueError("The messages list is empty.")
            if len(state["messages"]) > 1:
                new_history = [
                    {
                        "human": (result["messages"][0].content),
                        "ai_response": (result["messages"][-1].content),
                    }
                ]
            else:
                new_history = []
            MAX_HISTORY_SIZE = 5
            self.history += new_history
            if len(self.history) > MAX_HISTORY_SIZE:
                self.history = self.history[-MAX_HISTORY_SIZE:]
            response = GeneratorResult(
                generated_text=result["messages"][-1].content,
                ai_tag=AiTagType.INFO,
                history=self.history,
                client_state={"session": str(result["session"])},
            )

        return response

