def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

def route_after_tools(state: State) -> str:
    """Route after tools based on the last called tool and business analysis completion."""
    last_called_tool = state.get("last_called_tool")

    if last_called_tool == "business_analysis_tool":
        # Check if business analysis is completed
        business_analysis = state.get("business_analysis", {})
        if business_analysis.get("completed", False):
            state["business_analysis"] = {}
            return "__end__"
        else:
            # If business analysis tool was called but not completed (still gathering info)
            return "__end__"
    else:
        return "assistant"

