class BusinessAnalysisTool(BaseTool):
    """Tool for business analysis and consultation workflow."""

    name: str = "business_analysis_tool"
    description: str = """
     ابزار مشاوره کسب و کار برای جمع‌آوری اطلاعات کسب و کار و ارائه راه‌حل‌های بهبود فروش و تحلیل کسب و کار
    این ابزار به صورت انحصاری زمانی استفاده می‌شود که کاربر درخواست مشاوره کسب و کار، بهبود فروش یا توسعه کسب و کار داشته باشد.
    شامل کلمات کلیدی: مشاوره کسب و کار، بهبود فروش، توسعه کسب و کار، استراتژی بازاریابی، مشاوره تجاری
    زمانی که از این ابزار استفاده می‌کنید، هیچ ابزار دیگری را همزمان فراخوانی نکنید.

    ابزار مشاوره کسب‌وکار — وظیفهٔ اختصاصی: وقتی کاربر درخواست مشاوره کسب‌وکار، بهبود فروش، توسعه کسب‌وکار یا استراتژی بازاریابی دارد یا وقتی نیازسنجی (Needs Assessment) کاملاً تکمیل شده است، این ابزار باید صدا زده شود.
کلیدواژه‌ها (فارسی): مشاوره کسب و کار, بهبود فروش, توسعه کسب و کار, استراتژی بازاریابی, مشاوره تجاری, آنالیز کسب و کار, تحلیل کسب و کار, B2B, B2C,
قواعد:
- این ابزار باید تنها ابزاری باشد که در این حالت فراخوانی می‌شود.
- اگر payload نیازسنجی (JSON) شامل همهٔ فیلدهای غیرخالی باشد (business_field, target_audience, geographical_scope, online_presence.website یا social_media)، فوراً این ابزار فراخوانی شود.
- هیچ fallback یا ابزار دیگری نباید جایگزین شود.
    """
    args_schema: Type[BaseModel] = BusinessAnalysisInput
    tags: Optional[list[str]] = ["tool:business_analysis"]

    def __init__(self, llm_model, **kwargs: Any):
        super().__init__(**kwargs)
        self._llm_model = llm_model
        self._needs_assessment_chain = self._create_needs_assessment_chain()
        self._analysis_chain = self._create_analysis_chain()

    def _create_needs_assessment_chain(self):
        """Create the chain for gathering business information."""

        parser = JsonOutputParser()
        # return needs_assessment_prompt | self._llm_model | parser
        from parschat_logic.use_cases.manual_pipelines.mortezaazimi_20.prompts import NEEDS_ASSESSMENT_PROMPT

        return NEEDS_ASSESSMENT_PROMPT | self._llm_model | parser

    def _create_analysis_chain(self):
        """Create the chain for business analysis."""

        # return analysis_prompt | self._llm_model
        from parschat_logic.use_cases.manual_pipelines.mortezaazimi_20.prompts import ANALYSIS_PROMPT

        return ANALYSIS_PROMPT | self._llm_model

    def _parse_form_data(self, form_data: list) -> Dict[str, Any]:
        """Parse form_data from algorithm_input into business_information structure."""
        business_info = {
            "business_field": None,
            "target_audience": None,
            "geographical_scope": None,
            "online_presence": {"website": None, "social_media": []},
        }

        if not form_data:
            return business_info

        for item in form_data:
            key = item.get("key", "")
            value = item.get("value", "")

            if not value or value.strip() == "":
                continue

            # Map form keys to business_info fields
            if "کسب" in key and "زمینه" in key:
                business_info["business_field"] = value
            elif "مخاطب" in key:
                # Use raw user input without normalization
                business_info["target_audience"] = value
            elif "لوکیشن" in key or "محدود" in key:
                business_info["geographical_scope"] = value
            elif "شبکه اجتماعی" in key or "اینستاگرام" in key or "تلگرام" in key:
                if value and value.lower() not in ["ندارم", "خیر", "no"]:
                    social_media = [s.strip() for s in value.split(",") if s.strip()]
                    business_info["online_presence"]["social_media"] = social_media
                else:
                    # Store empty list to indicate question was answered
                    business_info["online_presence"]["social_media"] = []
            elif "وبسایت" in key or "سایت" in key:
                if value and value.lower() not in ["ندارم", "خیر", "no"]:
                    business_info["online_presence"]["website"] = value
                else:
                    # Store raw user answer
                    business_info["online_presence"]["website"] = value

        return business_info

    def _extract_form_data_from_messages(self, state: Dict[str, Any]) -> Dict[str, Any]:
        """Extract form data from the first human message if it contains form structure."""
        messages = state.get("messages", [])

        business_info = {
            "business_field": None,
            "target_audience": None,
            "geographical_scope": None,
            "online_presence": {"website": None, "social_media": []},
        }

        # Check first human message for form data pattern
        for msg in messages:
            if hasattr(msg, "type") and msg.type == "human":
                content = str(msg.content)

                # Check if this looks like form data (has multiple lines with key: value pattern)
                if "\n" in content and ":" in content:
                    lines = content.strip().split("\n")
                    form_like_lines = [line for line in lines if ":" in line]

                    # If more than 3 lines with ":" pattern, treat as form data
                    if len(form_like_lines) >= 3:
                        LOGGER.info(f"Detected form data in message with {len(form_like_lines)} entries")

                        for line in form_like_lines:
                            if ":" not in line:
                                continue

                            key, value = line.split(":", 1)
                            key = key.strip()
                            value = value.strip()

                            LOGGER.debug(f"Parsing form line - key: '{key}', value: '{value}'")

                            if not value or value == "":
                                continue

                            # Map to business_info fields
                            if "کسب" in key and "زمینه" in key:
                                business_info["business_field"] = value
                                LOGGER.debug(f"Mapped business_field: {value}")
                            elif "مخاطب" in key:
                                # Use raw user input without normalization
                                business_info["target_audience"] = value.strip()
                                LOGGER.debug(f"Mapped target_audience: {value.strip()}")
                            elif "لوکیشن" in key or "محدود" in key or "محصول" in key:
                                business_info["geographical_scope"] = value
                                LOGGER.debug(f"Mapped geographical_scope: {value}")
                            elif "شبکه" in key or "اجتماعی" in key:
                                if value and value.lower() not in ["ندارم", "خیر", "no", "هیچ"]:
                                    social_media = [s.strip() for s in value.split(",") if s.strip()]
                                    business_info["online_presence"]["social_media"] = social_media
                                    LOGGER.debug(f"Mapped social_media: {social_media}")
                                else:
                                    # User explicitly said they don't have social media
                                    business_info["online_presence"]["social_media"] = []
                                    LOGGER.debug("User doesn't have social media (answered)")
                            elif "وبسایت" in key or "سایت" in key:
                                if value and value.lower() not in ["ندارم", "خیر", "no", "هیچ"]:
                                    business_info["online_presence"]["website"] = value
                                    LOGGER.debug(f"Mapped website: {value}")
                                else:
                                    # Store raw user answer without modification
                                    business_info["online_presence"]["website"] = value
                                    LOGGER.debug(f"User answered about website: {value}")

                        LOGGER.info(f"Extracted from messages: {json.dumps(business_info, ensure_ascii=False)}")
                        return business_info
                break  # Only check first human message

        return business_info

    def _extract_business_info_from_history(self, state: Dict[str, Any]) -> Dict[str, Any]:
        """Extract existing business information from state and conversation history."""
        current_info = state.get("business_information", {})

        # Initialize with default structure if empty
        if not current_info:
            current_info = {
                "business_field": None,
                "target_audience": None,
                "geographical_scope": None,
                "online_presence": {"website": None, "social_media": []},
            }

        # First, try to extract from messages (form data pattern)
        extracted_from_messages = self._extract_form_data_from_messages(state)

        # Merge extracted data with current_info (extracted data takes precedence)
        for key, value in extracted_from_messages.items():
            if value:
                if key == "online_presence":
                    if not current_info.get("online_presence"):
                        current_info["online_presence"] = {"website": None, "social_media": []}
                    if value.get("website"):
                        current_info["online_presence"]["website"] = value["website"]
                    if value.get("social_media"):
                        current_info["online_presence"]["social_media"] = value["social_media"]
                else:
                    current_info[key] = value

        # Try to extract from form_data if available (as backup)
        algorithm_input = state.get("algorithm_input")
        if algorithm_input:
            form_data = (
                algorithm_input.get("form_data")
                if isinstance(algorithm_input, dict)
                else getattr(algorithm_input, "form_data", None)
            )
            if form_data:
                parsed_form_data = self._parse_form_data(form_data)
                # Merge parsed form data with existing info (form_data takes precedence)
                for key, value in parsed_form_data.items():
                    if value:
                        if key == "online_presence":
                            # Merge online_presence fields
                            if not current_info.get("online_presence"):
                                current_info["online_presence"] = {"website": None, "social_media": []}
                            if value.get("website"):
                                current_info["online_presence"]["website"] = value["website"]
                            if value.get("social_media"):
                                current_info["online_presence"]["social_media"] = value["social_media"]
                        else:
                            current_info[key] = value

        LOGGER.info(f"Final extracted business_info: {json.dumps(current_info, ensure_ascii=False)}")
        return current_info

    def _format_conversation_history(self, state: Dict[str, Any]) -> str:
        """Format conversation history for prompt."""
        messages = state.get("messages", [])
        history_lines = []

        for msg in messages[-10:]:  # Last 10 messages
            if hasattr(msg, "type") and hasattr(msg, "content"):
                role = "کاربر" if msg.type == "human" else "دستیار"
                content = str(msg.content)[:200]  # Limit length
                history_lines.append(f"{role}: {content}")

        return "\n".join(history_lines)

    def _check_completion_status(self, business_info: Dict[str, Any]) -> tuple[list, bool]:
        """Check which fields are still missing and if assessment is complete."""
        pending_fields = []

        if not business_info.get("business_field"):
            pending_fields.append("business_field")
        if not business_info.get("target_audience"):
            pending_fields.append("target_audience")
        if not business_info.get("geographical_scope"):
            pending_fields.append("geographical_scope")

        online_presence = business_info.get("online_presence", {})
        # Check if online_presence was answered (not just if it has value)
        # User might have said "ندارم" which means they answered the question
        website_answered = "website" in online_presence and online_presence.get("website") is not None
        social_answered = "social_media" in online_presence and online_presence.get("social_media") is not None

        if not website_answered and not social_answered:
            pending_fields.append("online_presence")

        is_complete = len(pending_fields) == 0

        LOGGER.info(f"Completion check - Pending fields: {pending_fields}, Is complete: {is_complete}")
        LOGGER.debug(f"Business info state: {json.dumps(business_info, ensure_ascii=False)}")

        return pending_fields, is_complete

    def _run(
        self,
        state: Annotated[Dict[str, Any], InjectedState],
        query: str,
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> str:
        return "ERROR! This tool must be called async!"

    async def _arun(
        self,
        state: Annotated[Dict[str, Any], InjectedState],
        query: str,
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> Command:
        """Execute business analysis workflow."""
        try:
            tool_call_id = state["messages"][-1].tool_calls[-1]["id"]

            # Extract current business information
            current_business_info = self._extract_business_info_from_history(state)
            conversation_history = self._format_conversation_history(state)

            # Check if we need to gather more information
            pending_fields, is_assessment_complete = self._check_completion_status(current_business_info)

            if not is_assessment_complete:
                # Run needs assessment chain
                needs_result = await self._needs_assessment_chain.ainvoke(
                    {
                        "current_business_info": json.dumps(current_business_info, ensure_ascii=False),
                        "conversation_history": conversation_history,
                        "user_input": query,
                    }
                )

                # Update business information in state
                updated_info = needs_result.get("updated_information", current_business_info)

                pending_fields, is_assessment_complete = self._check_completion_status(updated_info)

                if not is_assessment_complete:
                    response_message = needs_result.get(
                        "response_message", "لطفاً اطلاعات بیشتری درباره کسب‌وکارتان ارائه دهید."
                    )
                    return Command(
                        update={
                            "messages": [ToolMessage(response_message, tool_call_id=tool_call_id)],
                            "business_information": updated_info,
                            "last_called_tool": "business_analysis_tool",
                        }
                    )
                else:
                    try:
                        analysis_result = await self._analysis_chain.ainvoke(
                            {
                                "business_field": updated_info.get("business_field"),
                                "target_audience": updated_info.get("target_audience"),
                                "geographical_scope": updated_info.get("geographical_scope"),
                                "online_presence": str(
                                    json.dumps(updated_info.get("online_presence", {}), ensure_ascii=False)
                                ),
                            }
                        )
                    except Exception as e:
                        LOGGER.error(f"Error in business analysis tool: {e}")
                        return Command(
                            update={
                                "messages": [
                                    ToolMessage(f"خطا در تحلیل کسب‌وکار: {str(e)}", tool_call_id=tool_call_id)
                                ],
                                "last_called_tool": "business_analysis_tool",
                            }
                        )

                    analysis_content = (
                        analysis_result.content if hasattr(analysis_result, "content") else str(analysis_result)
                    )

                    return Command(
                        update={
                            "messages": [ToolMessage(analysis_content, tool_call_id=tool_call_id)],
                            "business_information": updated_info,
                            "business_analysis": {"analysis_content": analysis_content, "completed": True},
                            "last_called_tool": "business_analysis_tool",
                        }
                    )

            else:
                # Run business analysis chain
                analysis_result = await self._analysis_chain.ainvoke(
                    {
                        "business_field": current_business_info.get("business_field"),
                        "target_audience": current_business_info.get("target_audience"),
                        "geographical_scope": current_business_info.get("geographical_scope"),
                        "online_presence": json.dumps(
                            current_business_info.get("online_presence", {}), ensure_ascii=False
                        ),
                    }
                )

                analysis_content = (
                    analysis_result.content if hasattr(analysis_result, "content") else str(analysis_result)
                )

                return Command(
                    update={
                        "messages": [ToolMessage(analysis_content, tool_call_id=tool_call_id)],
                        "business_analysis": {"analysis_content": analysis_content, "completed": True},
