class ProductProcessingMixin:
    def _extract_all_product_variant_ids_for_validation(self, products: List[Product]) -> Dict[str, str]:
        """Extract all parent and variant IDs for validation mapping.

        Args:
            products: List of parent products with custom_attributes.

        Returns:
            Dict mapping ID to name for validation purposes.
        """
        id_to_name_mapping = {}

        for product in products:
            # Add parent product
            id_to_name_mapping[str(product.id)] = product.name

            # Add variants from custom_attributes
            if hasattr(product, "custom_attributes") and product.custom_attributes:
                for attr in product.custom_attributes:
                    if (
                        hasattr(attr, "value_long")
                        and attr.value_long is not None
                        and hasattr(attr, "name")
                        and attr.name
                    ):  # variant has ID and name
                        id_to_name_mapping[str(attr.value_long)] = attr.name

        return id_to_name_mapping

    def _process_validated_product_variant_ids(
        self, validated_ids: List[str], original_products: List[Product]
    ) -> List[Product]:
        """Convert validated IDs back to Product objects, creating variant-based products when needed.

        Args:
            validated_ids: List of validated product/variant ID strings.
            original_products: Original parent products with custom_attributes.

        Returns:
            List of Product objects (parent products + generated variant products).
        """
        result_products = []

        # Create mapping of original products by ID
        original_products_by_id = {str(p.id): p for p in original_products}

        for validated_id in validated_ids:
            validated_id = validated_id.strip()
            if not validated_id:
                continue

            # Check if it's a parent product ID
            if validated_id in original_products_by_id:
                result_products.append(original_products_by_id[validated_id])
            else:
                # It's a variant ID - find parent and create variant product
                variant_product = self._create_variant_product_from_id(validated_id, original_products)
                if variant_product:
                    result_products.append(variant_product)

        return result_products

    def _create_variant_product_from_id(self, variant_id: str, original_products: List[Product]) -> Optional[Product]:
        """Create a Product object for a variant by finding its data in parent's custom_attributes.

        Args:
            variant_id: The variant ID to create a product for.
            original_products: List of parent products to search.

        Returns:
            Product object representing the variant, or None if not found.
        """
        for parent_product in original_products:
            if not hasattr(parent_product, "custom_attributes") or not parent_product.custom_attributes:
                continue

            # Find the variant in custom_attributes
            variant_attr = None
            for attr in parent_product.custom_attributes:
                if hasattr(attr, "value_long") and str(attr.value_long) == variant_id:
                    variant_attr = attr
                    break

            if variant_attr:
                # Create variant product based on parent + custom_attribute overrides
                return self._build_variant_product(parent_product, variant_attr)

        LOGGER.warning(f"Could not find variant with ID {variant_id} in any parent product")
        return None

    def _build_variant_product(self, parent_product: Product, variant_attr: CustomAttribute) -> Product:
        """Build a variant product by copying parent and overriding with variant data.

        Args:
            parent_product: The parent product to use as base.
            variant_attr: CustomAttribute containing variant metadata.

        Returns:
            Product object representing the variant.
        """
        # Copy parent product data (use mode='json' to handle datetime serialization)
        variant_data = parent_product.model_dump(mode="json")

        # Override with variant-specific data from custom_attributes
        if hasattr(variant_attr, "value_long") and variant_attr.value_long:
            variant_data["id"] = variant_attr.value_long
        if hasattr(variant_attr, "name") and variant_attr.name:
            variant_data["name"] = variant_attr.name

        # Map custom_attribute fields to product fields based on the specification:
        # stock status → value_type
        if hasattr(variant_attr, "value_type") and variant_attr.value_type:
            variant_data["stock_status"] = variant_attr.value_type

        # price → value_int
        if hasattr(variant_attr, "value_int") and variant_attr.value_int is not None:
            price = variant_attr.value_int
            variant_data["price"] = price
            variant_data["regular_price"] = price
            variant_data["price_html"] = (
                f'<span class="woocommerce-Price-amount amount"><bdi>{price:,.0f}&nbsp;'
                f'<span class="woocommerce-Price-currencySymbol">تومان</span></bdi></span>'
            )
        # permalink → benefit
        if hasattr(variant_attr, "benefit") and variant_attr.benefit:
            variant_data["permalink"] = variant_attr.benefit

        # slug → value_string
        if hasattr(variant_attr, "value_string") and variant_attr.value_string:
            variant_data["slug"] = variant_attr.value_string

        # Clear vectors to avoid duplication
        variant_data["product_vector"] = None
        variant_data["extra_product_vector"] = None

        try:
            return Product(**variant_data)
        except Exception as e:
            LOGGER.warning(f"Failed to create variant product: {e}")
            return parent_product

    def combine_products_with_priority(self, keyword_products: List[Any], semantic_products: List[Any]) -> List[Any]:
        """Combine keyword and semantic products, prioritizing keyword results.

        Args:
            keyword_products: Products from keyword search.
            semantic_products: Products from semantic search.

        Returns:
            Combined list of products.
        """
        combined_products: List[Any] = []
        product_ids: set = set()
        for product in keyword_products:
            product_id = getattr(product, "id", None)
            if product_id and product_id not in product_ids:
                combined_products.append(product)
                product_ids.add(product_id)
        for product in semantic_products:
            product_id = self.get_product_id(product)
            if product_id and product_id not in product_ids:
                processed_product = self.process_product(product)
                if processed_product:
                    combined_products.append(processed_product)
                    product_ids.add(product_id)
        return combined_products

    def get_product_id(self, product: Any) -> Optional[Union[int, str]]:
        """Get the product ID from a product object or dict.

        Args:
            product: Product object or dict.

        Returns:
            Product ID or None.
        """
        if isinstance(product, dict):
            return product.get("id")
        return getattr(product, "id", None)

    def process_product(self, product: Any) -> Optional[Product]:
        """Convert a dict product to a Product model, or return as is if already a Product.

        Args:
            product: Product object or dict.

        Returns:
            Product model or None if conversion fails.
        """
        try:
            if isinstance(product, dict):
                self.prepare_product_data(product)
                return Product(**product)
            return product
        except Exception as e:
            LOGGER.warning(f"Failed to process product: {e}")
            return None

    def prepare_product_data(self, product_data: dict) -> None:
        """Prepare product data dict for Product model instantiation.

        Args:
            product_data: Product data dictionary.
        """
        if "short_description" not in product_data:
            product_data["short_description"] = None
        if "id" in product_data and isinstance(product_data["id"], str):
            try:
                product_data["id"] = int(product_data["id"])
            except Exception as e:
                LOGGER.warning(f"Failed to convert product id to int: {e}")
        if "upsell_ids" in product_data and isinstance(product_data["upsell_ids"], str):
            try:
                product_data["upsell_ids"] = [int(id_str.strip()) for id_str in product_data["upsell_ids"].split(",")]
            except Exception as e:
                LOGGER.warning(f"Failed to convert upsell_ids to list of ints: {e}")
        if "related_ids" in product_data and isinstance(product_data["related_ids"], str):
            try:
                if "," in product_data["related_ids"]:
                    product_data["related_ids"] = [
                        int(id_str.strip()) for id_str in product_data["related_ids"].split(",")
                    ]
                else:
                    product_data["related_ids"] = [int(product_data["related_ids"].strip())]
            except Exception as e:
                LOGGER.warning(f"Failed to convert related_ids to list of ints: {e}")
                product_data["related_ids"] = []
        if "variations" in product_data and isinstance(product_data["variations"], str):
            try:
                if "," in product_data["variations"]:
                    product_data["variations"] = [
                        int(id_str.strip()) for id_str in product_data["variations"].split(",")
                    ]
                else:
                    product_data["variations"] = [int(product_data["variations"].strip())]
            except Exception as e:
                LOGGER.warning(f"Failed to convert variations to list of ints: {e}")
                product_data["variations"] = []

    async def filter_irrelevant_products(self, queries: List[str], products: List[Any]) -> List[Any]:
        """Filter out irrelevant products using the validator chain with variant support.

        Args:
            queries: List of query variations.
            products: List of products to validate.

        Returns:
            List of validated products (including generated variants).
        """
        if not self.validator_chain:
            return products

        LOGGER.info(f"Validating {len(products)} products with variant-aware validator chain")

        # Extract all product and variant IDs with names for validation
        id_to_name_mapping = self._extract_all_product_variant_ids_for_validation(products)

        if not id_to_name_mapping:
            return products

        # Create mapping string for prompt
        mapping_lines = [f"ID: {id_val} -> Name: {name}" for id_val, name in id_to_name_mapping.items()]
        product_variant_mapping = "\n".join(mapping_lines)

        try:
            validation_input = {"query": queries[0], "product_variant_mapping": product_variant_mapping}
            result = await run_chain(
                chain=self.validator_chain,
                parameters=validation_input,
                max_retries=3,
                name="validate_search_variants",
                assertion="True",
            )

            # Parse validated IDs
            result_clean = result.strip().upper()
            if result_clean == "NONE":
                validated_ids = []
            else:
                validated_ids = [id_str.strip() for id_str in result.split(",") if id_str.strip()]

            # Convert validated IDs back to Product objects
            validated_products = self._process_validated_product_variant_ids(validated_ids, products)

            LOGGER.info(
                f"Validation complete: {len(validated_products)} products/variants selected from {len(products)} parent products"
            )
            return validated_products

        except Exception as e:
            LOGGER.warning(f"Error in variant-aware validation: {e}")
            return products

    def _extract_products_from_docs(self, retrieved_docs_list: List[List[Document]]) -> List[Any]:
        products = []

        for docs in retrieved_docs_list:
            for doc in docs:
                if hasattr(doc, "metadata") and "product" in doc.metadata:
                    product_data = doc.metadata["product"]

                    if isinstance(product_data, Product):
                        products.append(product_data)
                    elif isinstance(product_data, dict):
                        try:
                            self._prepare_product_data(product_data)
                            product_model = Product(**product_data)
                            products.append(product_model)
                        except Exception as e:
                            LOGGER.warning(f"Failed to convert product data to model: {e}")
                            products.append(product_data)

        return products

    async def validate_product(self, query: str, product: Any) -> bool:
        """Validate a product using the validator chain (legacy compatibility method).

        Args:
            query: The user query string.
            product: Product to validate.

        Returns:
            True if product is valid, False otherwise.
        """
        if not self.validator_chain:
            return True
        try:
            # Use new variant-aware validation for single product
            validated_products = await self.filter_irrelevant_products([query], [product])
            return len(validated_products) > 0
        except Exception as e:
            LOGGER.warning(f"Error validating product {getattr(product, 'name', 'Unknown')}: {e}")
            return True

class TruncatedEmbeddingWrapper:
    def __init__(self, base_model: Any, max_dimensions: int = 256) -> None:
