def is_jalali_date(date_str: str) -> bool:
    """
    تشخیص این که تاریخ جلالی است یا میلادی.
    قانون:
    - اگر فرمت ISO داشت → میلادی
    - اگر سال >= 1700 → میلادی
    - بقیه → جلالی
    """
    if date_str is None:
        return False
    s = str(date_str)
    if "T" in s or "Z" in s:
        return False
    s = s.translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    try:
        year = int(s[:4])
    except:
        return False
    if year >= 1700:
        return False
    if year >= 1000:
        return True
    return False

