    async def _arun(
        self,
        order_id: int,
        state: Annotated[Dict[str, Any], InjectedState],
        run_manager: Optional[CallbackManagerForToolRun] = None,
    ) -> dict[str, Any] | str:
        try:
            loader = _get_loader_for_auth(self._wc_auth)
            order = await loader.get_order(self._wc_auth, order_id)
            if not order:
                raise Exception("Empty order from Woocommerce!")
            order_dict = order.model_dump()
            order_dict["tracking_code"] = "No tracking code submitted yet."
            for key in ["date_created", "date_modified", "date_paid", "date_completed"]:
                if order_dict[key] is not None:
                    date_value = str(order_dict[key])
                    if not is_jalali_date(date_value):
                        order_dict[key] = convert_iso_datetime_to_jalali(date_value)
            if self._custom_statuses is not None:
                order_dict["status"] = self._custom_statuses.get(order_dict["status"], order_dict["status"])
                for meta in order_dict.get("meta_data", []):
                    if meta.get("key") in ["post_track_number", "marsule"]:
                        order_dict["tracking_code"] = meta.get("value")
                        break
                for shipping_line in order_dict.get("shipping_lines", []):
                    if "method_title" in shipping_line:
                        order_dict["shipping_type"] = shipping_line["method_title"]
                        break
            order_dict = {key: order_dict.get(key) for key in self._essential_order_properties}

            order_notes = await loader.get_order_notes(self._wc_auth, order_id, False)
            post_tracking_codes = []
            for order_note in order_notes:
                post_tracking_code = extract_post_tracking_code(order_note.get("note") or order_note.get("text", ""))
                if post_tracking_code:
                    post_tracking_codes.append(post_tracking_code)
            if len(post_tracking_codes) > 0:
                order_dict["post_tracking_codes"] = post_tracking_codes

            return self._process_orders(order_dict)
        except Exception as e:
            LOGGER.warning(f"There was a problem in getting order with id {order_id}: {e}")
            return f"No order found! Ask the user to see if they have provided the correct order id.\
If it is happening after 3 times, ask the user to contact customer support.\
Remember to speak in the {state.get('language', 'PERSIAN')} language."

    def _process_orders(self, order_data: dict[str, Any]) -> list[dict[str, Any]]:
        """Process a single order dictionary and return it in a standardized format list."""
        if not order_data:
            return []

        order_dict = order_data.copy()

        # Ensure tracking code
        order_dict["tracking_code"] = order_dict.get("tracking_code", "No tracking code submitted yet.")

        # Extract tracking code from meta_data (if present)
        for meta in order_dict.get("meta_data", []):
            if meta.get("key") in ["post_track_number", "marsule"]:
                order_dict["tracking_code"] = meta.get("value")
                break

        # Extract shipping type (from shipping_lines or top-level field)
        if "shipping_lines" in order_dict:
            for shipping_line in order_dict.get("shipping_lines", []):
                if "method_title" in shipping_line:
                    order_dict["shipping_type"] = shipping_line["method_title"]
                    break
        else:
            # Fallback if already exists
            order_dict["shipping_type"] = order_dict.get("shipping_type", "نامشخص")

        # Keep only essential properties
        order_dict = {key: order_dict.get(key) for key in self._essential_order_properties if key in order_dict}

        # Remove address fields from shipping and billing
        address_fields = ["address_1", "address_2", "city"]
        if order_dict.get("shipping"):
            shipping = order_dict["shipping"].copy()
            for field in address_fields:
                shipping.pop(field, None)
            order_dict["shipping"] = shipping

        if order_dict.get("billing"):
            billing = order_dict["billing"].copy()
            for field in address_fields:
                billing.pop(field, None)
            order_dict["billing"] = billing

        # Apply custom statuses if defined
        if getattr(self, "_custom_statuses", None) and order_dict.get("status"):
            order_dict["status"] = self._custom_statuses.get(order_dict["status"], order_dict["status"])

        return [order_dict]

