class GeneratorNode:
    def __init__(
        self,
        ecommerce_identifier: str,
        ecommerce_repo: IRobotEcommerceRepository,
        llm_models: dict,
    ):
        get_product_by_id_tool = GetProductByIdTool(ecommerce_identifier, ecommerce_repo)
        self._need_clarification_chain = NeedClarificationPrompt.template | llm_models["light-model"]
        self._clearifying_question_chain = ClearifyingQuestion.template | llm_models["light-model"]
        self._generator_chain = GeneratorPrompt.template | llm_models["generator-model"].bind_tools(
            [get_product_by_id_tool]
        )

    async def __call__(self, state: State, config: RunnableConfig):
        last_tool_call_index = -1
        clearifying_questions = None
        last_call = "__end__"
        tool_message = state["messages"][-1].model_copy()

        if isinstance(state["messages"][-1], ToolMessage):
            for i, message in enumerate(reversed(state["messages"])):
                if hasattr(message, "tool_calls") and message.tool_calls:
                    last_tool_call_index = len(state["messages"]) - 1 - i
                    break
        if (
            last_tool_call_index >= 0
            and state["messages"][last_tool_call_index].tool_calls[0]["name"] == "product_retriever_tool"
        ):
            with contextlib.suppress(Exception):
                tool_message.content = [
                    {"name": product["name"], "short_description": product["short_description"]}
                    for product in eval(state["messages"][-1].content)
                ]

            need_clarification_result = await self._need_clarification_chain.ainvoke(
                {"history": create_full_history_string(state["messages"][:-1] + [tool_message])}
            )

            if "generate" in need_clarification_result.content.lower():
                clearifying_questions = await self._clearifying_question_chain.ainvoke(
                    {"history": create_full_history_string(state["messages"][:-1] + [tool_message])}
                )
                return Command(
                    update={"messages": clearifying_questions, "last_call": last_call},
                    goto="__end__",
                )

            else:
                with contextlib.suppress(Exception):
                    new_message = []
                    for product in eval(state["messages"][-1].content):
                        new_message.append({key: value for key, value in product.items() if key != "short_description"})
                    tool_message.content = new_message

                generator_result = await self._generator_chain.ainvoke(
                    {
                        "history": create_full_history_string(state["messages"][:-1] + [tool_message]),
                    }
                )
                if generator_result.tool_calls:
                    last_call = generator_result.tool_calls[0]["name"]
                    return Command(
                        update={"messages": [generator_result], "last_call": last_call},
                        goto="tools",
                    )
                return Command(
                    update={"messages": [generator_result], "last_call": last_call},
                    goto="__end__",
                )

        elif (
            last_tool_call_index >= 0
            and state["messages"][last_tool_call_index].tool_calls[0]["name"] == "get_product_by_id_tool"
        ):
            generator_result = await self._generator_chain.ainvoke(
                {
                    "history": create_full_history_string(state["messages"]),
                }
            )
            if generator_result.tool_calls:
                last_call = generator_result.tool_calls[0]["name"]
                return Command(
                    update={"messages": [generator_result], "last_call": last_call},
                    goto="tools",
                )
            return Command(
                update={"messages": [generator_result], "last_call": last_call},
                goto="__end__",
            )

def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

class AssistantGraph:
    def __init__(self, assistant: Assistant, generator: GeneratorNode, order_tracker_subgraph):
        self.builder = StateGraph(State)

        self.builder.add_node("assistant", assistant.__call__)
        self.builder.add_node("order_tracker_tool", order_tracker_subgraph)

        self.builder.add_node(
            "tools",
            create_tool_node_with_fallback(assistant.tools),
            retry=RetryPolicy(max_attempts=3),  # TODO: tune this
        )
        self.builder.add_node("generator", generator.__call__)

        self.builder.add_edge(START, "assistant")
        self.builder.add_conditional_edges("assistant", self.tools_condition)
        self.builder.add_edge("order_tracker_tool", END)
        self.builder.add_conditional_edges("tools", self.after_search_condition)

        self.memory = MemorySaver()
        self.graph = self.builder.compile(checkpointer=self.memory)

    def tools_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call in ["order_tracker_tool", END]:
            return last_call
        else:
            return "tools"

    def after_search_condition(self, state: State) -> str:
        last_call = state.get("last_call")
        if last_call in ["product_retriever_tool", "get_product_by_id_tool"]:
            return "generator"
        else:
            return "assistant"

