def handle_tool_error(state) -> dict:
    error = state.get("error")
    tool_calls = state["messages"][-1].tool_calls
    return {
        "messages": [
            ToolMessage(
                content=f"Error: {repr(error)}\n please fix your mistakes.",
                tool_call_id=tc["id"],
            )
            for tc in tool_calls
        ]
    }

def get_qa_pairs(questions: List[str], answers: List[str]) -> str:
    if len(questions) != len(answers):
        return None, f"Number of questions ({len(questions)}) != answers ({len(answers)})"

    qas = ""
    for q, a in zip(questions, answers):
        qas += f"Assistant Question: {q}\n"
        qas += f"User Answer: {a}\n"
        qas += "----------"

    return qas, "successful"

class HITLAgent:
    def __init__(self, llm_models: Dict[str, Any] | None = None):
        self.llm_model = llm_models["llm_model"]
        self.validation_chain = deepcopy(HITLPrompts.prompt_template) | self.llm_model | HITLPrompts.parser

    async def __call__(self, state: State, config: RunnableConfig, **kwargs) -> Command[str]:
        # Initialize variables
        hitl_params: dict[str, Any] = state.get("hitl_params", {})

        current_retries: int = hitl_params.get("current_retries", 0)
        max_retries: int = hitl_params.get("max_retries", 3)

        if current_retries >= max_retries:
            return Command(
                goto="assistant",
                update={
                    "messages": [
                        AIMessage("Max tries exceeded in the HITL node. Immediately call the `connect_operator_tool`")
                    ]
                },
            )

        questions = hitl_params.get("questions", [])
        if not questions:
            return Command(
                goto="assistant",
                update={
                    "messages": [
                        AIMessage(
                            "No HITL Questions FOUND in the HITL node. Immediately call the `connect_operator_tool`"
                        )
                    ]
                },
            )

        if not hitl_params.get("activated", False):
            return Command(
                goto=END,
                update={"messages": [AIMessage(questions[-1])], "hitl_params": {**hitl_params, "activated": True}},
            )

        answers = hitl_params.get("answers", [])

        caller = hitl_params.get("caller")
        if not caller:
            return Command(
                goto="assistant",
                update={
                    "messages": [AIMessage("NO CALLER in the HITL node. Immediately call the `connect_operator_tool`")]
                },
            )

        update_field = hitl_params.get("update_field")
        if not update_field:
            return Command(
                goto="assistant",
                update={
                    "messages": [
                        AIMessage("NO UPDATE FIELD in the HITL node. Immediately call the `connect_operator_tool`")
                    ]
                },
            )

        qas, status = get_qa_pairs(questions, answers)
        if qas is None:
            return Command(
                goto="assistant",
                update={"messages": [AIMessage(f"{status}. Immediately call the `connect_operator_tool`")]},
            )

        resp = await self.validation_chain.ainvoke({"qas": qas})

        if not resp["related"]:
            return Command(goto="assistant", update={"hitl_params": {"activated": False}})

        if resp["product_id"]:
            return Command(
                goto=caller,
                update={
                    update_field: resp["product_id"],
                    "hitl_params": {
                        "activated": False,
                    },
                },
            )

        if resp["clarifying_question"]:
            return Command(
                goto="hitl_node",
                update={
                    "messages": [AIMessage(resp["clarifying_question"])],
                    "hitl_params": {
                        **hitl_params,
                        "activated": False,
                        "questions": questions + [resp["clarifying_question"]],
                        "answers": answers,
                        "current_retries": current_retries + 1,
                    },
                },
            )

        return Command(
            goto="assistant",
            update={
                "messages": [AIMessage("Unexpected Error. Immediately call the `connect_operator_tool`")],
                "hitl_params": {"activated": False},
            },
        )

class TruncatedEmbeddingWrapper:
    def __init__(self, base_model: Any, max_dimensions: int) -> None:
        self.base_model = base_model
        self.max_dimensions = max_dimensions

    async def aembed_query(self, text: str) -> Any:
        embeddings = await self.base_model.aembed_query(text)
        return normalize_l2(embeddings[: self.max_dimensions])

    def embed_query(self, text: str) -> Any:
        embeddings = self.base_model.embed_query(text)
        return normalize_l2(embeddings[: self.max_dimensions])

class ProductSearchMixin:
    async def retrieve_docs_by_multiquery_fusion(
        self,
        query: str,
        **kwargs: Any,
    ) -> List[Product]:
        """Retrieve products using multi-query fusion (keyword + semantic).

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            Combined list of products from keyword and semantic search.
        """
        queries = self.extract_query_variations(query, **kwargs)
        semantic_products = await self.perform_semantic_search_if_needed(queries=queries, **kwargs)
        return semantic_products

    async def search_by_name(self, query: str, max_results: int = 4, **kwargs: Any) -> List[Any]:
        """Search products by name using the repository.

        Args:
            query: Product name query.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products matching the name.
        """
        try:
            min_price = kwargs.get("min_price")
            max_price = kwargs.get("max_price")

            if min_price is not None or max_price is not None:
                search_query = self._build_name_search_query_with_price_filter(query, min_price, max_price, max_results)
                return await self.ecommerce_repo.get_product_by_query(
                    ecommerce_identifier=self.ecommerce_identifier,
                    query=search_query,
                )
            else:
                traditional_products, _ = await self.ecommerce_repo.search_products_by_name(
                    ecommerce_identifier=self.ecommerce_identifier,
                    name=query,
                    max_results=max_results,
                )
                return traditional_products
        except Exception as e:
            LOGGER.warning(f"Error in product retriever search: {e}")
            return []

    def extract_query_variations(self, query: str, **kwargs: Any) -> List[str]:
        """Extract query variations for multi-query fusion.

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments.

        Returns:
            List of query variations.
        """
        if "queries" in kwargs and kwargs["queries"]:
            return kwargs["queries"]
        return [query]

    async def perform_keyword_search(self, query: str, **kwargs: Any) -> List[Any]:
        """Perform keyword-based product search.

        Args:
            query: The user query string.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products from keyword search.
        """
        try:
            return await self.search_by_name(query, **kwargs)
        except Exception as e:
            LOGGER.warning(f"Error in keyword search: {e}")
            return []

    async def perform_semantic_search_if_needed(self, queries: List[str], **kwargs: Any) -> List[Any]:
        """Perform semantic search using dual retrieval if a retriever is available.

        Args:
            queries: List of query variations.
            kwargs: Additional keyword arguments including min_price, max_price.

        Returns:
            List of products from dual semantic search.
        """
        if self.retrieval:
            run_manager = AsyncCallbackManagerForRetrieverRun.get_noop_manager()
            raw_semantic_products = await asyncio.gather(
                *[self._aget_relevant_documents(q, run_manager=run_manager, **kwargs) for q in queries]
            )
            semantic_products = raw_semantic_products[0] if raw_semantic_products else []

            LOGGER.info(f"Dual retrieval returned {len(semantic_products)} products for queries: {queries}")

            return semantic_products
        return []

    def _build_name_search_query_with_price_filter(
        self, query: str, min_price: float = None, max_price: float = None, size: int = 4
    ) -> dict:
        """Build Elasticsearch query for name search with price filtering.

        Args:
            query: The product name query.
            min_price: Minimum price filter.
            max_price: Maximum price filter.
            size: Maximum number of results.

        Returns:
            Elasticsearch query dictionary.
        """
        price_filters = []
        if min_price is not None:
            price_filters.append({"range": {"product.price": {"gte": min_price}}})
        if max_price is not None:
            price_filters.append({"range": {"product.price": {"lte": max_price}}})

        query = {
            "size": size,
            "_source": {"excludes": ["product.product_vector", "product.custom_attributes.vector"]},
            "query": {
                "bool": {
                    "should": [
                        {
                            "multi_match": {
                                "query": query,
                                "fields": [
                                    "product.name^5",
                                    "product.short_description",
                                    "product.description",
                                ],
                                "operator": "and",
                                "minimum_should_match": "90%",
                                "boost": 5,
                            }
                        },
                        {
                            "fuzzy": {
                                "product.name": {
                                    "value": query,
                                    "fuzziness": 1,
                                    "boost": 6,
                                    "prefix_length": 1,
                                }
                            }
                        },
                        {
                            "nested": {
                                "boost": 1,
                                "path": "product.categories",
                                "query": {
                                    "match": {
                                        "product.categories.name": {
                                            "query": query,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                        {
                            "nested": {
                                "boost": 1,
                                "path": "product.tags",
                                "query": {
                                    "match": {
                                        "product.tags.name": {
                                            "query": query,
                                            "operator": "and",
                                        }
                                    }
                                },
                            }
                        },
                    ],
                    "minimum_should_match": 1,
                    "filter": price_filters,
                }
            },
        }

        if max_price:
            query["sort"] = [{"product.price": {"order": "desc"}}]

        return query

class RawRetriever(BaseRetriever):
    # necessary fields
    db_repository: RobotCollectionRepository
    collection_identifier: str
    llm_models: dict
    embedding_models: dict
    query_processor: QueryProcessor

    # inner fields
    config: Config = Config()
    retrieval: BaseRetriever = None

    async def load_retrieval(self, **kwargs):
        self.retrieval = await self.__getattribute__(
            f"create_retrieval_chain_by_{self.config.retrieval_engine}",
        )()

    def custom_query(self, query_body: dict, query: str):
        query_body["knn"]["field"] = "child_chunks.vector"
        query_body["fields"] = [
            "child_chunks.id",
            "child_chunks.content",
            "child_chunks.parent_id",
        ]
        return query_body

    def fuzzy_query(self, search_query: str) -> Dict:
        return {
            "query": {
                "match": {
                    "chunks.content": {
                        "query": search_query,
                        "minimum_should_match": 1,
                    },
                },
            },
            "size": 5,
        }

    def custom_document_builder(self, hit: dict):
        return Document(
            page_content=hit["fields"]["child_chunks.content"][0],
            metadata={
                "id": hit["fields"]["child_chunks.id"][0],
                "parent_id": str(hit["fields"]["child_chunks.parent_id"][0]),
            },
        )

    def doc_builder(self, hit: dict):
        chunk = hit["_source"]["chunks"]
        return Document(
            page_content=chunk["content"],
            metadata={
                "id": chunk["id"],
                "reference_data_id": chunk["reference_data_id"],
                "heading_id": chunk["heading_id"],
                "topic": chunk["topic"],
                "start_line": chunk["start_line"],
                "end_line": chunk["end_line"],
                "language": chunk["language"],
            },
        )

    async def create_retrieval_chain_by_pdr(self, **kwargs) -> ParentDocumentRetriever:
        index_name = self.db_repository.get_index_name(self.collection_identifier)
        vector_store = ElasticsearchStore(
            index_name=index_name,
            es_connection=self.db_repository.sync_elasticsearch_repository,
            embedding=self.embedding_models["embedding_model"],
            strategy=ElasticsearchStore.ApproxRetrievalStrategy(),
        )

        chunks = await self.db_repository.get_collection_chunk_by_id(
            self.collection_identifier,
            return_vectors=False,
        )

        parent_docs = []
        for chunk in chunks:
            parent_docs.append(
                (
                    str(chunk.id),
                    Document(
                        page_content=chunk.content,
                        metadata={
                            "id": "chunk_" + str(chunk.id),
                            "heading_id": chunk.heading_id,
                            "reference_data_id": chunk.reference_data_id,
                        },
                    ),
                ),
            )
        shutil.rmtree(f"{CACHE_DIR}/data/media/chunkstore/{self.collection_identifier}/chunks", ignore_errors=True)
        os.makedirs(f"{CACHE_DIR}/data/media/chunkstore/{self.collection_identifier}/chunks", exist_ok=True)
        fs = LocalFileStore(f"{CACHE_DIR}/data/media/chunkstore/{self.collection_identifier}/chunks")
        store = create_kv_docstore(fs)

        store.mset(parent_docs)

        pdr_retriver = ParentDocumentRetriever(
            search_type="similarity_score_threshold",
            vectorstore=vector_store,
            search_kwargs={
                "k": 11,
                "custom_query": self.custom_query,
                "doc_builder": self.custom_document_builder,
                "score_threshold": 0.0,
            },
            id_key="parent_id",
            docstore=store,
        )

        fuzzy_retriever = ElasticsearchRetriever(
            index_name=self.db_repository.get_index_name(self.collection_identifier),
            body_func=self.fuzzy_query,
            document_mapper=self.doc_builder,
            es_client=self.db_repository.sync_elasticsearch_repository,
        )

        ensemble_retriever = EnsembleRetriever(
            retrievers=[pdr_retriver, fuzzy_retriever],
            weights=[0.8, 0.2],
        )

        return ensemble_retriever

    def _get_relevant_documents(
        self,
        query: str,
        *,
        run_manager: CallbackManagerForRetrieverRun,
        **kwargs: Any,
    ) -> List[Document]:
        docs = asyncio.run(
            self.__getattribute__(f"retrieve_docs_by_{self.config.retrieval_method}")(
                query,
                **kwargs,
            ),
        )

        return docs

    async def _aget_relevant_documents(
        self,
        query: str,
        *,
        run_manager: AsyncCallbackManagerForRetrieverRun,
        **kwargs: Any,
    ) -> List[Document]:
        docs = await self.__getattribute__(
            f"retrieve_docs_by_{self.config.retrieval_method}",
        )(query, **kwargs)

        return docs

    async def retrieve_docs_by_multiquery_fusion(
        self,
        query: str,
        **kwargs,
    ) -> List[Any]:
        retrieved_docs_dict = {}

        if "queries" in kwargs:
            queries = kwargs["queries"]
        else:
            queries = await self.query_processor.query_paraphrasing(
                input_message=query,
            )
            queries.append(query)

        retrieved_docs_dict = dict(
            zip(
                queries,
                await asyncio.gather(
                    *[self.retrieval.ainvoke(query) for query in queries],
                ),
            ),
        )
        reranked_docs = reciprocal_rank_fusion(retrieved_docs_dict)
        return reranked_docs[:5]

def present_results(search_params, retrieved_data, chain, k=10):
    presentation_products = []
    clarification_products = []

    for product_params in search_params["product_queries"]:
        if len(retrieved_data[product_params["key"]]) > k:
            if product_params["should_clarify"]:
                clarification_products.append(
                    {
                        "product_query": product_params["query"],
                        "car_query": search_params["car_query"],
                        "min_price": min([p["price"] for p in retrieved_data[product_params["key"]]]),
                        "max_price": max([p["price"] for p in retrieved_data[product_params["key"]]]),
                        "num_results": len(retrieved_data[product_params["key"]]),
                    }
                )
                product_params["should_clarify"] = False
            else:
                presentation_products.append(
                    {
                        "car_query": search_params["car_query"],
                        "product_query": product_params["query"],
                        "min_price": product_params["min_price"],
                        "max_price": product_params["max_price"],
                        "products": retrieved_data[product_params["key"]][:5],
                    }
                )
        else:
            presentation_products.append(
                {
                    "car_query": search_params["car_query"],
                    "product_query": product_params["query"],
                    "min_price": product_params["min_price"],
                    "max_price": product_params["max_price"],
                    "products": retrieved_data[product_params["key"]],
                }
            )

    resp: str = "YOU MUST ALWAYS RESPOND IN PERSIAN\n\n----------------\n"

    # Presentation Products
    if presentation_products:
        resp += "You should Present these products to user:\n"
        for q_params in presentation_products:
            resp += f"Search Query = `{q_params['product_query']}` (Car Model=`{q_params['car_query']}`\
             | Min Price=`{q_params['min_price']}` | Max Price=`{q_params['max_price']}`):\n"
            for p in q_params["products"]:
                resp += f"\t- Product Name: {p['name']} | Price: {p['price']}\n"

    if presentation_products and clarification_products:
        resp += "\n----------------\n"

    if clarification_products:
        resp += "You should present following results to user and ask for a desired price range or brand\
         name to narrow down the search for each query:\n"
        for q_params in clarification_products:
            resp += f"\t- Search Query = `{q_params['product_query']}` | Car Model: {q_params['car_query']}\
 | Num Results: {q_params['num_results']} | Min Price: {q_params['min_price']} | Max Price: {q_params['max_price']}\n"

    result = chain.invoke(resp).content

    return result

def get_response(message: str, messages: list[AnyMessage]) -> list[AnyMessage]:
    last_msg: AnyMessage = messages[-1]

    if isinstance(last_msg, AIMessage) and getattr(last_msg, "tool_calls", []):
        search_tool_calls = [tc for tc in last_msg.tool_calls if tc["name"] == "search_tool"]

        if len(search_tool_calls) == 1:
            return [ToolMessage(message, tool_call_id=search_tool_calls[0]["id"])]

        multiple_tool_response: list[ToolMessage] = []
        for tc in search_tool_calls[:-1]:
            multiple_tool_response.append(ToolMessage("", tool_call_id=tc["id"]))
        multiple_tool_response.append(ToolMessage(message, tool_call_id=search_tool_calls[-1]["id"]))
        return multiple_tool_response

    return [AIMessage(message)]

class SearchAgent:
    def __init__(
        self,
        config: Config,
        ecommerce_repo: IRobotEcommerceRepository,
        embedding_models: Dict[str, Any] | None = None,
        llm_models: Dict[str, Any] | None = None,
    ):
        ecommerce_identifier = config.collection_identifier

        self.ecommerce_identifier = ecommerce_identifier
        self.ecommerce_repo = ecommerce_repo
        self.llm_models = llm_models
        self.llm_model = llm_models["llm_model"]

        self._product_retriever = ProductRetriever(
            ecommerce_repo=ecommerce_repo,
            ecommerce_identifier=ecommerce_identifier,
            embedding_models=embedding_models,
            llm_models=llm_models,
        )

    async def search_repo(
        self,
        search_query: str,
        min_price: int | float = 1,
        max_price: int | float | None = None,
        is_car: bool = False,
        variant_id: int | None = None,
    ) -> List[Any]:
        combined_products = await self._product_retriever.retrieve_docs_by_multiquery_fusion(
            query=search_query,
            min_price=min_price,
            max_price=max_price,
            instock_filter=False,  # Don't filter by stock status initially
            is_car=is_car,
            variant_id=variant_id,
        )

        combined_products = [prod.model_dump() for prod in combined_products]
        return combined_products

    async def __call__(self, state: State, config: RunnableConfig, **kwargs):
        # Stage 0: Process last message for multiple tool calls and merge search params.
        assert isinstance(state, dict), f"Unexpected Behaviour. State must be a dict, but is `{type(state)}`"
        assert state.get("messages", []), "Unexpected Behaviour. State have a non-empty messages key."

        search_params = state.get("search_params", {})

        # Merge tool calls
        last_message: AnyMessage = state["messages"][-1]
        if isinstance(last_message, AIMessage) and getattr(last_message, "tool_calls", []):
            search_tool_calls = [tc for tc in last_message.tool_calls if tc["name"] == "search_tool"]

            if search_tool_calls:
                for i, tc in enumerate(search_tool_calls):
                    car_query: str | None = tc["args"].get("car_query") or None
                    product_query: str | None = tc["args"].get("product_query", "") or ""
                    min_price = tc["args"].get("min_price", 1) or 1
                    max_price = tc["args"].get("max_price") or None
                    key = "{0}_{1}_{2}".format(product_query, min_price, max_price)
                    if car_query:
                        car_query = digits.en_to_fa(car_query)

                    if (min_price is not None) and (min_price == max_price):
                        min_price = min_price - (0.2 * min_price)
                        max_price = max_price + (0.2 * max_price)

                    if i == 0:
                        search_params = {
                            "id": tc["id"],
                            "car_query": car_query,
                            "product_queries": [
                                {
                                    "query": product_query,
                                    "min_price": min_price,
                                    "max_price": max_price,
                                    "key": key,
                                    "should_clarify": True,
                                }
                            ],
                        }
                    else:
                        search_params["product_queries"].append(
                            {
                                "query": product_query,
                                "min_price": min_price,
                                "max_price": max_price,
                                "key": key,
                                "should_clarify": True,
                            }
                        )

                car_models = {tc["args"]["car_query"] for tc in search_tool_calls}
                if len(car_models) > 1:
                    msg = f"I can only search for one car model. found: {car_models}"
                    return Command(goto="assistant", update={"messages": get_response(msg, state["messages"])})

        # Stage 1: Retrieve products from db if not already retrieved
        retrieved_data = state.get("retrieved_data", {})
        for product_params in search_params["product_queries"]:
            key = product_params["key"]
            if key not in retrieved_data:
                retrieved_data[key] = await self.search_repo(
                    search_query=product_params["query"],
                    min_price=product_params["min_price"],
                    max_price=product_params["max_price"],
                    is_car=False,
                )

        if all((len(value) == 0) for value in retrieved_data.values()):
            msg = "No products found. Immediately call the `connect_operator_tool`"
            return Command(
                goto="assistant",
                update={
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "messages": get_response(msg, state["messages"]),
                },
            )

        # Find out which one of search queries need HITL
        need_hitl = []
        for product_params in search_params["product_queries"]:
            has_related_ids = any((len(d["related_ids"]) != 0) for d in retrieved_data[product_params["key"]])

            if has_related_ids:
                product_params["car_specific"] = True
                if product_params["query"] not in need_hitl:
                    need_hitl.append(product_params["query"])
            else:
                product_params["car_specific"] = False

        # No products need HITL
        if not need_hitl:
            msg: str = present_results(search_params, retrieved_data, self.llm_model, 5)
            return Command(
                goto="assistant",
                update={
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "messages": get_response(msg, state["messages"]),
                },
            )

        # Stage 2: Ask car model if user doesn't provide it yet
        # In this stage at least one product needs HTLT
        if not search_params["car_query"]:
            msg = f"Ask the user to specify a car model for these products = {need_hitl}. Then make these\
 `search_tool` calls with the specified args:\n"
            for product_params in search_params["product_queries"]:
                msg += f"""\
**Tool Args**:
\t- `car_query`: (str) response from the user
\t- `product_query`: (str) = {product_params['query']}
\t- `min_price`: (int | float) = {product_params['min_price']}
\t- `max_price`: (int | float | null) = {product_params['max_price']}
-------
"""

            return Command(
                goto="assistant",
                update={
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "messages": get_response(msg, state["messages"]),
                },
            )

        if search_params["car_query"] not in retrieved_data:
            retrieved_data[search_params["car_query"]] = await self.search_repo(search_params["car_query"], is_car=True)

        if not retrieved_data[search_params["car_query"]]:
            msg = "Car model not found. Immediately call the `connect_operator_tool` with no explanation"
            return Command(
                goto="assistant",
                update={
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "messages": get_response(msg, state["messages"]),
                },
            )

        # Stage 3: Use HITL if for car query
        car_query: str | None = state.get("car_query")
        if car_query == search_params["car_query"]:
            car_category_idx: int | None = state.get("car_category_idx")
            car_variant_idx: int | None = state.get("car_variant_idx")
        else:
            car_category_idx: int | None = None
            car_variant_idx: int | None = None

        if len(retrieved_data[search_params["car_query"]]) == 1:
            car_category_idx = 1

        if not car_category_idx:
            first_question = "لطفا مشخص کنید خودرو شما جزو کدام یک از دسته های زیر است؟\n"
            for i, car_cat in enumerate(retrieved_data[search_params["car_query"]]):
                first_question += f"* {i + 1}) {car_cat['name']}\n"

            return Command(
                goto="hitl_agent",
                update={
                    "messages": get_response("", state["messages"])
                    + [
                        SystemMessage(
                            f"As long as the user has not changed the car model, always set the\
 search_tool parameter car_query=`{car_query}`. Only update car_query if the user explicitly provides a new car model."
                        )
                    ],
                    "car_query": search_params["car_query"],
                    "car_category_idx": car_category_idx,
                    "car_variant_idx": car_variant_idx,
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "hitl_params": {
                        "activated": False,
                        "caller": "search_agent",
                        "questions": [first_question],
                        "answers": [],
                        "update_field": "car_category_idx",
                        "current_retries": 1,
                        "max_retries": 3,
                    },
                },
            )

        selected_car_category = retrieved_data[search_params["car_query"]][car_category_idx - 1]
        selected_car_category["variation_items"] = [
            d for d in selected_car_category["variation_items"] if int(d["id"]) < 100000
        ]

        # Step 4: If not variation, raise error
        if not selected_car_category["variation_items"]:
            msg = "Unexpected Behaviour. Car category has no variations. Immediately call the `connect_operator_tool`"
            return Command(goto="assistant", update={"messages": get_response(msg, state["messages"])})

        if len(selected_car_category["variation_items"]) == 1:
            car_variant_idx = 1

        if car_variant_idx is None:
            first_question = "لطفا مشخص کنید خودرو شما جزو کدام یک از گونه های زیر است؟\n"
            for i, car_var in enumerate(selected_car_category["variation_items"]):
                first_question += f"* {i + 1}) {car_var['name']}\n"

            return Command(
                goto="hitl_agent",
                update={
                    "messages": get_response("", state["messages"])
                    + [
                        SystemMessage(
                            f"As long as the user has not changed the car model, always set the search_tool\
 parameter car_query=`{car_query}`. Only update car_query if the user explicitly provides a new car model."
                        )
                    ],
                    "car_query": search_params["car_query"],
                    "car_category_idx": car_category_idx,
                    "car_variant_idx": car_variant_idx,
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "hitl_params": {
                        "activated": False,
                        "caller": "search_agent",
                        "questions": [first_question],
                        "answers": [],
                        "update_field": "car_variant_idx",
                        "current_retries": 1,
                        "max_retries": 3,
                    },
                },
            )

        car_variant_id = selected_car_category["variation_items"][car_variant_idx - 1]["id"]

        for product_params in search_params["product_queries"]:
            retrieved_data[product_params["key"]] = await self.search_repo(
                search_query=product_params["query"],
                min_price=product_params["min_price"],
                max_price=product_params["max_price"],
                is_car=False,
                variant_id=car_variant_id,
            )

        if all((len(value) == 0) for value in retrieved_data.values()):
            msg = "No products found. Immediately call the `connect_operator_tool`"
            return Command(
                goto="assistant",
                update={
                    "messages": get_response(msg, state["messages"]),
                    "car_query": search_params["car_query"],
                    "car_category_idx": car_category_idx,
                    "car_variant_idx": car_variant_idx,
                    "search_params": search_params,
                    "retrieved_data": retrieved_data,
                    "hitl_params": {
                        "activated": False,
                    },
                },
            )

        result: str = present_results(search_params, retrieved_data, self.llm_model, k=5)

        return Command(
            goto=END,
            update={
                "messages": [
                    SystemMessage(
                        f"As long as the user has not changed the car model, always set the search_tool parameter\
 car_query=`{car_query}`. Only update car_query if the user explicitly provides a new car model."
                    )
                ]
                + get_response(result, state["messages"]),
                "car_query": search_params["car_query"],
                "car_category_idx": car_category_idx,
                "car_variant_idx": car_variant_idx,
                "search_params": search_params,
                "retrieved_data": retrieved_data,
                "hitl_params": {"activated": False},
            },
        )

