class MetadataExtractor:
    def __init__(
        self,
        config: Config,
        llm_models: dict,
        embedding_models: dict,
    ) -> None:
        self.llm_models = llm_models
        self.embedding_models = embedding_models
        self.config = config
        self.detailed_metadata_extractor = DetailedMetadataExtractor(
            config=config,
            llm_models=llm_models,
            embedding_models=embedding_models,
        )
        self.overall_metadata_extractor = OverallMetadataExtractor(
            config=config,
            llm_models=llm_models,
        )

    async def detailed_metadata_extraction(
        self,
        collection_identifier: str,
        reference_data_wrapper: ReferenceDataWrapper,
    ) -> ReferenceDataWrapper:
        try:
            LOGGER.debug(
                "Detailed metadata in progress for collection %s and reference data %s"
                % (collection_identifier, reference_data_wrapper.identifier),
                )
            return await self.detailed_metadata_extractor(
                collection_identifier=collection_identifier,
                reference_data_wrapper=reference_data_wrapper,
            )
        except Exception as e:
            LOGGER.error(
                "Unable to extract detailed metadata for collection_models %s and reference data %s\nbecause: %s"
                "\nTraceback: %s"
                % (
                    collection_identifier,
                    reference_data_wrapper.identifier,
                    str(e),
                    traceback.format_exc(),
                ),
            )
            raise RuntimeError(
                "Unable to extract detailed metadata for collection %s and reference data %s"
                % (collection_identifier, reference_data_wrapper.identifier),
            )

