        try:
            LOGGER.debug(
                "Overall metadata in progress for collection_models %s"
                % collection.collection_info.identifier,
            )
            return await self.overall_metadata_extractor(collection=collection)
        except Exception as e:
            LOGGER.error(
                "Unable to extract overall metadata for collection_models %s\nbecause: %s"
                % (collection.collection_info.identifier, str(e)),
            )
            raise RuntimeError(
                "Unable to extract overall metadata for collection_models %s"
                % (collection.collection_info.identifier),
            )

class MetaTextUtils:
    @staticmethod
    def parse_result(
        segment: str,
        llm_result: dict,
        **kwargs,
    ) -> dict:
        parsed_lines = MetaTextUtils.parse_lines(numbered_content=segment)
        first_chunk_touch = False

        for heading in llm_result["heading_1s"]:
            for chunk in heading["heading_2s"]:
                if not first_chunk_touch:
                    last_chunk = chunk
                    last_chunk["heading_value"] = heading["heading_value"]
                    first_chunk_touch = True
                    continue

                chunk["start_line"], last_chunk["end_line"] = (
                    int(chunk["start_line"]),
                    int(last_chunk["end_line"]),
                )

                if chunk["start_line"] > last_chunk["end_line"]:
                    chunk_content = MetaTextUtils.get_section(
                        parsed_lines=parsed_lines,
                        start_line=last_chunk["start_line"],
                        end_line=chunk["start_line"] - 1,
                        contain_numbering=False,
                        **kwargs,
                    )
                else:
                    chunk_content = MetaTextUtils.get_section(
                        parsed_lines=parsed_lines,
                        start_line=last_chunk["start_line"],
                        end_line=last_chunk["end_line"],
                        contain_numbering=False,
                        **kwargs,
                    )
                if not TextProcessingUtils.match_first_line(
                    last_chunk["title"],
                    chunk_content,
                ):
                    chunk_content = last_chunk["title"] + "\n" + chunk_content
                chunk_content = last_chunk["heading_value"] + "\n" + chunk_content
                last_chunk["content"] = chunk_content.strip()
                last_chunk = chunk
                last_chunk["heading_value"] = heading["heading_value"]

        max_line_nums = max(parsed_lines.keys())
        chunk_content = MetaTextUtils.get_section(
            parsed_lines=parsed_lines,
            start_line=last_chunk["start_line"],
            end_line=max_line_nums,
            contain_numbering=False,
            **kwargs,
        )
        if not TextProcessingUtils.match_first_line(last_chunk["title"], chunk_content):
            chunk_content = last_chunk["title"] + "\n" + chunk_content
        chunk_content = heading["heading_value"] + "\n" + chunk_content

        last_chunk["content"] = chunk_content.strip()
        return llm_result

    @staticmethod
    def line_numbering(document: str) -> str:
        lines = re.split(r"\\n|\n|<br>", document)
        document_with_num = ""
        for line_index, line in enumerate(lines, start=1):
            document_with_num += f"line number: {line_index} |\t{line}\n"
        return document_with_num

    @staticmethod
    def parse_lines(numbered_content: str, only_numbers: bool = True) -> Dict[int | str, str]:
        """
        returns a dictionary with keys demonstrating line number and values representing
        the corresponding line content.
        """
        try:
            pattern = re.compile(r"^line number: \d+ \|")
            d = {}
            lines = TextProcessingUtils.split_lines(numbered_content)
            for line in lines:
                if not line:  # the last line condition which is empty
                    continue
                if line.startswith("Hierarchical Path:") or line.startswith("> "):
                    continue
                match = pattern.search(line)
                index = line[: match.end() - 1] if only_numbers else line[: match.end()]
                line_content = line[match.end() :]
                line_number = int(index[13:].strip()) if only_numbers else index
                d[line_number] = line_content.strip()
            return d
        except Exception as e:
            raise RuntimeError(e)

    @staticmethod
    def get_section(
        parsed_lines: dict,
        start_line: int,
        end_line: int,
        contain_numbering: bool,
        **kwargs,
    ) -> str:
        content = ""
        try:
            for i in range(int(start_line), end_line + 1):
                if contain_numbering:
                    content += f"line number: {i} |\t{parsed_lines[i]}\n"
                else:
                    content += parsed_lines[i] + "\n"
            return content
        except Exception:
            LOGGER.warning(
                "can't parse a chunk for collection_models %s" % (kwargs["collection_identifier"]),
            )
            return content

    @staticmethod
    def recursive_splitter(
        text: str,
        max_length: int,
        len_func: Callable,
        separators: List[str] = None,
        min_length: int = None,
    ) -> List[str]:
        """
        Recursively splits the input text into segments based on specified separators and length constraints.
        """

        def recursive_split(parsed_lines: Dict[int, str], separators: List[str]) -> List[str]:
            if not separators:
                return ["\n".join([f"{k}\t{v}" for k, v in parsed_lines.items()])]

            separator = separators[0]
            parts = []
            current_segment = []
            current_segment_content = ""
            for line_num, line in parsed_lines.items():
                if separator in current_segment_content + line + "\n":
                    if all(l == "" for _, l in current_segment):
                        if parts:  # Ensure there is a previous part to append to
                            parts[-1].extend(current_segment)
                    else:
                        parts.append(current_segment)

                    current_segment = [(line_num, line)]
                    current_segment_content = line + "\n"
                else:
                    current_segment.append((line_num, line))
                    current_segment_content += line + "\n"

            if current_segment:
                if all(l == "" for _, l in current_segment) and parts:
                    parts[-1].extend(current_segment)
                else:
                    parts.append(current_segment)

            segments = []
            current_segment = parts[0]

            for part in parts[1:]:
                part_text = "\n".join([f"{ln}\t{l}" for ln, l in part])
                current_segment_text = "\n".join([f"{ln}\t{l}" for ln, l in current_segment])
                if len_func(current_segment_text + part_text) <= max_length:
                    current_segment.extend(part)
                else:
                    if len_func(current_segment_text) >= min_length:
                        segments.append(current_segment)
                        current_segment = part
                    else:
                        current_segment.extend(part)

            if current_segment:
                segments.append(current_segment)

            final_segments = []
            for segment in segments:
                segment_text = "\n".join([f"{ln}\t{l}" for ln, l in segment])
                if len_func(segment_text) > max_length:
                    final_segments.extend(recursive_split(dict(segment), separators[1:]))
                else:
                    final_segments.append(segment_text)

            return final_segments

        parsed_lines = MetaTextUtils.parse_lines(text, only_numbers=False)
        segments = []
        if separators:
            segments.extend(recursive_split(parsed_lines, separators))

        final_segments = []
        for segment in segments:
            if len_func(segment) > max_length:
                final_segments.extend(TextProcessingUtils.split_text_by_length(segment, max_length, len_func))
            else:
                final_segments.append(segment)

        return final_segments

    @staticmethod
    def heading_based_segmentation(
        text: str,
        max_length: int,
        min_length: int,
        len_func: Callable,
    ) -> Tuple[List[str], bool]:
        """
        Split the text based on heading ones, if the content between two heading ones(#) is
        more than max_length, it tries to split it based on the heading twos(##), and so on.
        If it couldn't find a segment between headings until heading four(####), it uses
        the `recursive_splitter` method, the `min_length` is used there.
        """

        def split_by_heading(text: str, parent_heading: str, heading: str) -> List[tuple]:
            segments = []
            current_segment = []
            current_heading = ""
            for index, line in MetaTextUtils.parse_lines(text, only_numbers=False).items():
                if line.strip().startswith(heading):
                    if current_segment:
                        if parent_heading and current_heading:
                            new_heading = f"> {current_heading}\n{parent_heading}"
                        elif parent_heading:
                            new_heading = parent_heading
                        elif current_heading:
                            new_heading = f"> {current_heading}"
                        else:
                            new_heading = ""
                        segments.append(
                            (
                                new_heading,
                                "\n".join(current_segment),
                            )
                        )
                        current_segment = []
                    current_heading = line
                current_segment.append(index + "\t" + line)
            if current_segment:
                if parent_heading and current_heading:
                    new_heading = f"> {current_heading}\n{parent_heading}"
                elif parent_heading:
                    new_heading = parent_heading
                elif current_heading:
                    new_heading = f"> {current_heading}"
                else:
                    new_heading = ""
                segments.append(
                    (
                        new_heading,
                        "\n".join(current_segment),
                    )
                )
            return segments

        used_recursive_splitter = False
        headings = ["# ", "## ", "### ", "#### "]
        segments = [("", text)]
        header = "Hierarchical Path:"

        for heading in headings:
            new_segments = []
            for parent_heading, segment in segments:
                if len_func(segment) > max_length:
                    new_segments.extend(split_by_heading(segment, parent_heading, heading))
                else:
                    new_segments.append((parent_heading, segment))
            segments = new_segments

        final_segments = []
        for parent_heading, segment in segments:
            if len_func(segment) < min_length:  # invalid segmentation, change strategy
                return (
                    MetaTextUtils.recursive_splitter(
                        text,
                        max_length,
                        len_func,
                        ["\n\n\n", "\n\n"],
                        min_length,
                    ),
                    True,
                )
            if len_func(segment) > max_length:
                used_recursive_splitter = True
                split_segments = MetaTextUtils.recursive_splitter(
                    segment,
                    max_length,
                    len_func,
                    ["\n\n\n", "\n\n"],
                    min_length,
                )
                final_segments.extend([(parent_heading, seg) for seg in split_segments])
            else:
                final_segments.append((parent_heading, segment))

        return [
            f"{header}\n{parent_heading}\n{segment}" for parent_heading, segment in final_segments
        ], used_recursive_splitter

