class DomainPromptRegistry:
    """Registry for domain-specific prompt configurations.

    This class manages domain configurations and prevents cross-collection interference
    by creating fresh instances on each retrieval.
    """

    _domain_classes = {
        DomainType.GENERAL: DomainPromptConfig,
        DomainType.COSMETICS: CosmeticsDomainPrompts,
        DomainType.MEDICAL: MedicalDomainPrompts,
        DomainType.DIGITAL: DigitalDomainPrompts,
        DomainType.FASHION: FashionDomainPrompts,
        DomainType.FOOD: FoodDomainPrompts,
    }

    @classmethod
    def get_domain_config(cls, domain_type: DomainType | str) -> DomainPromptConfig:
        """Get fresh domain configuration instance.

        Args:
            domain_type: Domain type enum or string.

        Returns:
            Fresh DomainPromptConfig instance for the domain.
        """
        if isinstance(domain_type, str):
            try:
                domain_type = DomainType(domain_type)
            except ValueError:
                domain_type = DomainType.GENERAL

        domain_class = cls._domain_classes.get(domain_type, DomainPromptConfig)
        return domain_class()

