def sublist(lst1, lst2):
    """
    checks to see if lst1 is a sublist of lst2 or not.
    """
    return all(item in lst2 for item in lst1)

class QueryProcessor(BaseQueryProcessor):
    def intent_detection(
        self,
        input_message: str = "",
        history: str = "",
        user_summary: str = None,
        candidate_intents: List[str] = None,
        **kwargs,
    ) -> List[str]:
        candidate_intents = (
            self.config.candidate_intents
            if candidate_intents is None
            else candidate_intents
        )
        failed_parse_trial = 0

        if user_summary is None:
            template = IntentDetectionSettings.template
            chain = template | self.llm_model | IntentDetectionSettings.output_parser

        else:
            template = IntentDetectionSettings.template_using_summary
            chain = template | self.llm_model | IntentDetectionSettings.output_parser

        while True:
            try:
                if user_summary is None:
                    response = chain.invoke(
                        {
                            "candidate_categories": candidate_intents,
                            "history": history,
                            "query": input_message,
                        }
                    )

                else:
                    response = chain.invoke(
                        {
                            "candidate_categories": candidate_intents,
                            "user_summary": user_summary,
                        }
                    )
                break
            except OutputParserException:
                failed_parse_trial += 1

                if failed_parse_trial >= self.config.max_failed_trial:
                    LOGGER.error("exceed max_failed_trial threshold in parsing output!")
                    return []

                continue

        intents = response["categories"]

        if not sublist(intents, candidate_intents):
            for intent in intents:
                if intent not in candidate_intents:
                    intents.remove(intent)

        return intents

    def emotion_detection(self, input_message: str, **kwargs) -> Emotion:
        result = self.llm_model.function_call(
            input_message=input_message,
            system_prompt=EmotionDetectionSettings.prompt,
            schema=EmotionDetectionSettings.get_schema(
                candidate_labels=[e.value for e in Emotion]
            ),
        )

        emotion = result.get("class", Emotion.neutral.value)
        return emotion

    def insult_detection(self, input_message: str, **kwargs) -> bool:
        result = self.llm_model.function_call(
            input_message=input_message,
            system_prompt=InsultDetectionSettings.prompt,
            schema=InsultDetectionSettings.get_schema(),
        )

        label = result.get("label", False)
        return label

    def spam_detection(self, input_message: str, history: str = "", **kwargs) -> bool:
        """
        determines if the input query is nonsensical or not.
        """
        chain = (
            SpamDetectionSettings.template
            | self.llm_model
            | SpamDetectionSettings.output_parser
        )
        result = chain.invoke(
            {
                "examples": self.config.spam_detection_examples,
                "history": history,
                "query": input_message,
            }
        )
        label = result.get("label", 2)
        return label in ["1", 1]

    def relevance_detection(
        self, input_message: str, history: str = "", topic: str = None, **kwargs
    ) -> int:
        """
        determines if the input query is relevance to topic or not.
        """
        related_keywords = ""
        for keyword in self.config.relevance_keywords["Related_Keywords"]:
            related_keywords += f"{keyword}\n"

        general_conversation_keywords = ""
        for keyword in self.config.relevance_keywords["General_Conversation_Keywords"]:
            general_conversation_keywords += f"{keyword}\n"

        not_related_keywords = ""
        for keyword in self.config.relevance_keywords["Not_Related_Keywords"]:
            not_related_keywords += f"{keyword}\n"

        chain = (
            RelevanceDetectionSettings.template
            | self.llm_model
            | RelevanceDetectionSettings.output_parser
        )
        result = chain.invoke(
            {
                "topic": self.config.topic if topic is None else topic,
                "referrer_examples": self.config.referrer_examples,
                "related_keywords": related_keywords,
                "general_conversation_keywords": general_conversation_keywords,
                "not_related_keywords": not_related_keywords,
                "history": history,
                "query": input_message,
            }
        )

        label = result.get("class", 2)
        return label

    def query_paraphrasing(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        template = ParaphrasingSettings.prompt.format(
            topic=self.config.topic,
            history=history,
            query=input_message,
            num_sentences=self.config.num_sentences,
            language=self.config.language,
        )

        result = self.llm_model.function_call(
            template=template,
            schema=ParaphrasingSettings.get_schema(self.config.num_sentences),
        )

        similar_sentences = result.get("sentences", [])
        return similar_sentences

    def chain_of_thoughts(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        template = ChainOfThoughtsSettings.prompt.format(
            document_topics=self.config.document_topics,
            language=self.config.language,
            examples=self.config.cot_examples,
            history=history,
            query=input_message,
        )

        result = self.llm_model.function_call(
            template=template,
            schema=ChainOfThoughtsSettings.get_schema(),
        )

        steps = result.get("queries", [])
        return steps

    def query_refiner(self, input_message: str, history: str) -> List[str]:
        chain = QueryRefiner.template | self.llm_model | QueryRefiner.parser
        result = chain.ainvoke(
            {
                "user_input": input_message,
                "history": history,
            }
        )

        return result.get("refined_input", "")

    #####################################
    # async functions:
    #####################################

    async def a_intent_detection(
        self,
        input_message: str = "",
        history: str = "",
        user_summary: str = None,
        candidate_intents: List[str] = None,
        **kwargs,
    ) -> List[str]:
        candidate_intents = (
            self.config.candidate_intents
            if candidate_intents is None
            else candidate_intents
        )
        failed_parse_trial = 0

        if user_summary is None:
            template = IntentDetectionSettings.template
            chain = template | self.llm_model | IntentDetectionSettings.output_parser

        else:
            template = IntentDetectionSettings.template_using_summary
            chain = template | self.llm_model | IntentDetectionSettings.output_parser

        while True:
            try:
                if user_summary is None:
                    response = await chain.ainvoke(
                        {
                            "candidate_categories": candidate_intents,
                            "history": history,
                            "query": input_message,
                        }
                    )

                else:
                    response = await chain.ainvoke(
                        {
                            "candidate_categories": candidate_intents,
                            "user_summary": user_summary,
                        }
                    )
                break
            except OutputParserException:
                failed_parse_trial += 1

                if failed_parse_trial >= self.config.max_failed_trial:
                    LOGGER.error("exceed max_failed_trial threshold in parsing output!")
                    return []

                continue

        intents = response["categories"]

        if not sublist(intents, candidate_intents):
            for intent in intents:
                if intent not in candidate_intents:
                    intents.remove(intent)

        return intents

    async def a_emotion_detection(self, input_message: str, **kwargs) -> Emotion:
        result = await self.llm_model.a_function_call(
            input_message=input_message,
            system_prompt=EmotionDetectionSettings.prompt,
            schema=EmotionDetectionSettings.get_schema(
                candidate_labels=[e.value for e in Emotion]
            ),
        )

        emotion = result.get("class", Emotion.neutral)
        return emotion

    async def a_insult_detection(self, input_message: str, **kwargs) -> bool:
        result = await self.llm_model.a_function_call(
            input_message=input_message,
            system_prompt=InsultDetectionSettings.prompt,
            schema=InsultDetectionSettings.get_schema(),
        )

        label = result.get("label", False)
        return label

    async def a_spam_detection(
        self, input_message: str, history: str = "", **kwargs
    ) -> bool:
        """
        determines if the input query is nonsensical or not.
        """
        chain = (
            SpamDetectionSettings.template
            | self.llm_model
            | SpamDetectionSettings.output_parser
        )
        result = await chain.ainvoke(
            {
                "examples": self.config.spam_detection_examples,
                "history": history,
                "query": input_message,
            }
        )
        label = result.get("label", 2)
        return label in ["1", 1]

    async def a_relevance_detection(
        self, input_message: str, history: str = "", topic: str = None, **kwargs
    ) -> int:
        """
        determines if the input query is relevance to topic or not.
        """
        related_keywords = ""
        for keyword in self.config.relevance_keywords["Related_Keywords"]:
            related_keywords += f"{keyword}\n"

        general_conversation_keywords = ""
        for keyword in self.config.relevance_keywords["General_Conversation_Keywords"]:
            general_conversation_keywords += f"{keyword}\n"

        not_related_keywords = ""
        for keyword in self.config.relevance_keywords["Not_Related_Keywords"]:
            not_related_keywords += f"{keyword}\n"

        chain = (
            RelevanceDetectionSettings.template
            | self.llm_model
            | RelevanceDetectionSettings.output_parser
        )
        result = await chain.ainvoke(
            {
                "topic": self.config.topic if topic is None else topic,
                "referrer_examples": self.config.referrer_examples,
                "related_keywords": related_keywords,
                "general_conversation_keywords": general_conversation_keywords,
                "not_related_keywords": not_related_keywords,
                "history": history,
                "query": input_message,
            }
        )

        label = result.get("class", 2)
        return label

    async def a_query_paraphrasing(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        template = ParaphrasingSettings.prompt.format(
            topic=self.config.topic,
            history=history,
            query=input_message,
            num_sentences=self.config.num_sentences,
            language=self.config.language,
        )

        result = await self.llm_model.a_function_call(
            template=template,
            schema=ParaphrasingSettings.get_schema(self.config.num_sentences),
        )

        similar_sentences = result.get("sentences", [])
        return similar_sentences

    async def a_chain_of_thoughts(
        self, input_message: str, history: str, **kwargs
    ) -> List[str]:
        template = ChainOfThoughtsSettings.prompt.format(
            document_topics=self.config.document_topics,
            language=self.config.language,
            examples=self.config.cot_examples,
            history=history,
            query=input_message,
        )

        result = await self.llm_model.a_function_call(
            template=template,
            schema=ChainOfThoughtsSettings.get_schema(),
        )

        steps = result.get("queries", [])
        return steps

    async def a_query_refiner(self, input_message: str, history: str) -> List[str]:
        chain = QueryRefiner.template | self.llm_model | QueryRefiner.parser
        result = await chain.ainvoke(
            {
                "user_input": input_message,
                "history": history,
            }
        )

        return result.get("refined_input", "")

class ReportGenerationUseCase(ReportGeneratorInterface):
    """Use case for generating statistical and semantic analytics reports from logs."""

    def __init__(self, logs_repository: ILogsRepository, collection_repository: IRobotCollectionRepository):
        """Initialize the report generation use case.

        Args:
            logs_repository: Repository for accessing log data.
            collection_repository: Repository for accessing collection data.
        """
        self.logs_repository = logs_repository
        self.collection_repository = collection_repository

    async def generate_stats(self, time_window: ReportTimeWindow) -> StatReport:
        """Generate a statistical report for the given time window.

        Args:
            time_window: Time window specification for the report.

        Returns:
            Statistical report containing raw counts and distribution metrics.

        Raises:
            ValueError: If the time window is invalid.
            RuntimeError: If report generation fails.
        """
        self._validate_time_window(time_window)

        try:
            traces = await self._get_traces_in_time_window(time_window)
            inference_results = await self._get_inference_results_for_traces(traces)

            normal_messages = [ir for ir in inference_results if ir.ai_tag == 0]
            LOGGER.debug(f"The number of the normal messages is {len(normal_messages)}")

            connect_to_operator_messages = [ir for ir in inference_results if ir.ai_tag == 3]

            total_messages = len(inference_results)
            processed_messages = self._count_processed_messages(inference_results)
            operator_routed_messages = len(connect_to_operator_messages)

            relevance_distribution = self._calculate_relevance_distribution(inference_results)

            connect_to_operator_tag_distribution = await self._analyze_connect_to_operator_tags(
                connect_to_operator_messages, traces
            )

            return StatReport(
                total_messages=total_messages,
                processed_messages=processed_messages,
                connect_operator_messages=operator_routed_messages,
                relevance_distribution=relevance_distribution,
                connect_to_operator_tag_distribution=connect_to_operator_tag_distribution,
                time_window=time_window,
                generated_at=str(datetime.datetime.now(tz=datetime.timezone.utc)),
            )
        except Exception as e:
            raise RuntimeError(f"Failed to generate statistical report: {str(e)}") from e

    async def generate_semantic(self, time_window: ReportTimeWindow) -> SemanticReport:
        """Generate a semantic analytics report for the given time window.

        Args:
            time_window: Time window specification for the report.

        Returns:
            Semantic report providing insights for knowledge base tuning.

        Raises:
            ValueError: If the time window is invalid.
            RuntimeError: If report generation fails.
        """
        self._validate_time_window(time_window)

        try:
            traces = await self._get_traces_in_time_window(time_window)
            inference_results = await self._get_inference_results_for_traces(traces)

            successful_documents = await self._analyze_successful_documents(inference_results)
            attention_gaps = await self._analyze_attention_gaps(inference_results)
            top_topics = self._extract_top_topics(inference_results)
            knowledge_coverage = self._calculate_knowledge_coverage(inference_results)
            retrieval_performance = self._calculate_retrieval_performance(inference_results)

            return SemanticReport(
                successful_documents=successful_documents,
                attention_gaps=attention_gaps,
                top_topics=top_topics,
                knowledge_coverage=knowledge_coverage,
                retrieval_performance=retrieval_performance,
                time_window=time_window,
                generated_at=get_current_utc_time(),
            )

        except Exception as e:
            raise RuntimeError(f"Failed to generate semantic report: {str(e)}") from e

    def _validate_time_window(self, time_window: ReportTimeWindow) -> None:
        """Validate the time window parameters."""
        try:
            start_dt = datetime.fromisoformat(time_window.start_date.replace("Z", "+00:00"))
            end_dt = datetime.fromisoformat(time_window.end_date.replace("Z", "+00:00"))

            if start_dt >= end_dt:
                raise ValueError("Start date must be before end date")

        except ValueError as e:
            if "Invalid isoformat" in str(e):
                raise ValueError("Invalid date format. Use ISO 8601 format") from e
            raise

    async def _get_traces_in_time_window(self, time_window: ReportTimeWindow) -> List[Trace]:
        """Get all traces within the specified time window."""
        return await self.logs_repository.get_traces_by_time_window_and_collection(
            start_date=time_window.start_date,
            end_date=time_window.end_date,
            collection_identifier=time_window.collection_identifier,
        )

    async def _get_inference_results_for_traces(self, traces: List[Trace]) -> List[InferenceResult]:
        """Get inference results for the given traces."""
        if not traces:
            return []

        trace_ids = [trace.trace_id for trace in traces]
        return await self.logs_repository.get_inference_results_by_id(trace_ids)

    def _count_processed_messages(self, inference_results: List[InferenceResult]) -> int:
        """Count successfully processed messages."""
        return len([ir for ir in inference_results if ir.generated_text and ir.generated_text.strip()])

    def _count_operator_routed_messages(self, inference_results: List[InferenceResult]) -> int:
        """Count messages routed to human operators."""
        return len([ir for ir in inference_results if ir.operator_response])

    def _calculate_total_cost(self, traces: List[Trace]) -> float:
        """Calculate total cost from traces."""
        return sum(trace.total_cost or 0.0 for trace in traces)

    def _calculate_query_tag_distribution(self, inference_results: List[InferenceResult]) -> List[QueryTagDistribution]:
        """Calculate distribution of query tags."""
        tag_counts = {}
        total_with_tags = 0

        for ir in inference_results:
            if ir.query_tag:
                tag_counts[ir.query_tag.value] = tag_counts.get(ir.query_tag.value, 0) + 1
                total_with_tags += 1

        distribution = []
        for tag, count in tag_counts.items():
            percentage = (count / max(1, total_with_tags)) * 100
            distribution.append(QueryTagDistribution(tag_name=tag, count=count, percentage=round(percentage, 2)))

        return sorted(distribution, key=lambda x: x.count, reverse=True)

    def _calculate_relevance_distribution(
        self, inference_results: List[InferenceResult]
    ) -> List[RelevanceDegreeDistribution]:
        """Calculate distribution of relevance degrees."""
        relevance_counts = {}
        total_with_relevance = 0

        for ir in inference_results:
            if ir.relevancy:
                relevance_counts[ir.relevancy.value] = relevance_counts.get(ir.relevancy.value, 0) + 1
                total_with_relevance += 1

        distribution = []
        for degree, count in relevance_counts.items():
            percentage = (count / max(1, total_with_relevance)) * 100
            distribution.append(
                RelevanceDegreeDistribution(degree=degree, count=count, percentage=round(percentage, 2))
            )

        return sorted(distribution, key=lambda x: x.count, reverse=True)

    def _count_spam_messages(self, inference_results: List[InferenceResult]) -> int:
        """Count messages detected as spam."""
        return len([ir for ir in inference_results if ir.is_spam == SpamResult.SPAM])

    def _count_insult_messages(self, inference_results: List[InferenceResult]) -> int:
        """Count messages detected as insults."""
        return len([ir for ir in inference_results if ir.is_insult == InsultResult.INSULT])

    async def _analyze_successful_documents(self, inference_results: List[InferenceResult]) -> List[RetrievedDocument]:
        """Analyze documents that frequently drive successful answers."""
        document_stats = {}

        for ir in inference_results:
            if ir.retrieved_docs and ir.generated_text and ir.generated_text.strip():
                for doc in ir.retrieved_docs:
                    doc_id = str(doc.get("id", doc.get("doc_id", "unknown")))
                    if doc_id not in document_stats:
                        document_stats[doc_id] = {"retrieval_count": 0, "success_count": 0, "topics": set()}

                    document_stats[doc_id]["retrieval_count"] += 1

                    if self._is_successful_answer(ir):
                        document_stats[doc_id]["success_count"] += 1

                    if "topics" in doc:
                        document_stats[doc_id]["topics"].update(doc.get("topics", []))

        successful_docs = []
        for doc_id, stats in document_stats.items():
            if stats["retrieval_count"] > 0:
                success_rate = stats["success_count"] / stats["retrieval_count"]
                if success_rate > 0.5:
                    successful_docs.append(
                        RetrievedDocument(
                            document_id=doc_id,
                            retrieval_count=stats["retrieval_count"],
                            success_rate=round(success_rate, 3),
                            topics=list(stats["topics"])[:10],
                        )
                    )

        return sorted(successful_docs, key=lambda x: x.retrieval_count, reverse=True)[:20]

    async def _analyze_attention_gaps(self, inference_results: List[InferenceResult]) -> List[AttentionGapDocument]:
        """Analyze documents that have attention gaps."""
        failed_queries = [ir for ir in inference_results if not self._is_successful_answer(ir)]
        LOGGER.debug(f"the len of the failed_queries is {len(failed_queries)}")

        attention_gaps = []

        return attention_gaps[:10]

    def _extract_top_topics(self, inference_results: List[InferenceResult]) -> List[str]:
        """Extract the most frequently queried topics."""
        topic_counts = {}

        for ir in inference_results:
            if ir.retrieved_docs:
                for doc in ir.retrieved_docs:
                    topics = doc.get("topics", [])
                    for topic in topics:
                        topic_counts[topic] = topic_counts.get(topic, 0) + 1

        sorted_topics = sorted(topic_counts.items(), key=lambda x: x[1], reverse=True)
        return [topic for topic, count in sorted_topics[:15]]

    def _calculate_knowledge_coverage(self, inference_results: List[InferenceResult]) -> float:
        """Calculate the percentage of queries adequately covered by knowledge base."""
        if not inference_results:
            return 0.0

        successful_answers = len([ir for ir in inference_results if self._is_successful_answer(ir)])
        return round(successful_answers / len(inference_results), 3)

    def _calculate_retrieval_performance(self, inference_results: List[InferenceResult]) -> Dict[str, float]:
        """Calculate performance metrics for document retrieval."""
        total_with_docs = len([ir for ir in inference_results if ir.retrieved_docs])
        successful_with_docs = len(
            [ir for ir in inference_results if ir.retrieved_docs and self._is_successful_answer(ir)]
        )

        precision = successful_with_docs / max(1, total_with_docs)
        recall = successful_with_docs / max(1, len(inference_results))
        f1_score = 2 * (precision * recall) / max(1, precision + recall) if (precision + recall) > 0 else 0.0

        return {"precision": round(precision, 3), "recall": round(recall, 3), "f1_score": round(f1_score, 3)}

    def _is_successful_answer(self, inference_result: InferenceResult) -> bool:
        """Determine if an inference result represents a successful answer."""
        return (
            inference_result.generated_text
            and len(inference_result.generated_text.strip()) > 10
            and not inference_result.operator_response
            and inference_result.relevancy not in [RelevanceDegree.LOW, None]
        )

    async def _analyze_connect_to_operator_tags(
        self, connect_to_operator_messages: List[InferenceResult], traces: List[Trace]
    ) -> ConnectToOperatorTagDistribution:
        """Analyze connect-to-operator messages and classify them into 4 categories."""
        if not connect_to_operator_messages:
            return self._create_empty_operator_tag_distribution()

        trace_chain_mapping = await self._build_trace_chain_mapping(connect_to_operator_messages)
        return self._classify_messages_by_categories(connect_to_operator_messages, trace_chain_mapping)

    def _create_empty_operator_tag_distribution(self) -> ConnectToOperatorTagDistribution:
        """Create empty connect-to-operator tag distribution."""
        return ConnectToOperatorTagDistribution(
            challenge_messages=[], not_related=[], explicit_request=[], miss_information=[]
        )

    async def _build_trace_chain_mapping(self, messages: List[InferenceResult]) -> Dict[str, List]:
        """Build mapping of trace IDs to their corresponding chain calls."""
        trace_ids = [message.trace_id for message in messages]
        chain_calls = await self.logs_repository.get_chain_calls_by_id(trace_ids)

        trace_chain_mapping = {}
        for chain_call in chain_calls:
            if chain_call.trace_id not in trace_chain_mapping:
                trace_chain_mapping[chain_call.trace_id] = []
            trace_chain_mapping[chain_call.trace_id].append(chain_call)

        return trace_chain_mapping

    def _classify_messages_by_categories(
        self, messages: List[InferenceResult], trace_chain_mapping: Dict[str, List]
    ) -> ConnectToOperatorTagDistribution:
        """Classify messages into categories and return distribution."""
        categories = {"challenge": [], "not_related": [], "explicit_request": [], "miss_information": [], "unknown": []}

        for message in messages:
            chains = trace_chain_mapping.get(message.trace_id, [])
            classification = self._classify_connect_to_operator_message(message, chains)
            categories[classification].append(message.message_id)

        return ConnectToOperatorTagDistribution(
            challenge_messages=categories["challenge"],
            not_related=categories["not_related"],
            explicit_request=categories["explicit_request"],
            miss_information=categories["miss_information"],
            unknown=categories["unknown"],
        )

    def _classify_connect_to_operator_message(self, inference_result: InferenceResult, chains: List) -> str:
        """Classify a single connect-to-operator message based on chain calls."""
        query_tag_chains = [c for c in chains if c.chain_name == "QueryTag"]
        for chain in query_tag_chains:
            if hasattr(chain, "output_data") and chain.output_data.get("tag") == "connect_operator":
                return "explicit_request"

        if inference_result.relevancy and inference_result.relevancy == RelevanceDegree.NOT_RELATED:
            return "not_related"

        for chain in query_tag_chains:
            if hasattr(chain, "output_data") and chain.output_data.get("output") == "explain_more":
                return "challenge"

        state_pass_chains = [c for c in chains if c.chain_name == "StatePass"]
        for chain in state_pass_chains:
            if hasattr(chain, "output_data") and chain.output_data.get("output") is True:
                return "miss_information"

        generation_chain_names = [
            "more_explain_manual_docs_query_generation_chain",
            "more_explain_query_generation_chain",
            "related_manual_docs_query_generation_chain",
            "related_query_generation_chain",
        ]

        for chain in chains:
            if (
                chain.chain_name in generation_chain_names
                and hasattr(chain, "output_data")
                and chain.output_data.get("tag") == "not_enough"
            ):
                return "miss_information"

        return "unknown"

