class JWTTokenService(ITokenService):
    def __init__(self, settings: AuthSettings):
        self.secret_key = settings.SECRET_KEY
        self.algorithm = settings.JWT_ALGORITHM
        self.expire_minutes = settings.ACCESS_TOKEN_EXPIRE_MINUTES

    def create_access_token(self, data: dict, expires_delta: Optional[timedelta] = None) -> tuple[str, int]:
        to_encode = data.copy()
        expire = datetime.utcnow() + (expires_delta or timedelta(minutes=self.expire_minutes))
        to_encode.update({"exp": expire})
        token = jwt.encode(to_encode, self.secret_key, algorithm=self.algorithm)
        expire_ms = int(expire.timestamp() * 1000)
        return token, expire_ms

    def verify_access_token(self, token: str) -> dict:
        try:
            return jwt.decode(
                token,
                self.secret_key,
                algorithms=[self.algorithm],
                options={"verify_exp": False, "verify_signature": True},
            )
        except ExpiredSignatureError:
            raise ValueError("Token expired")
        except InvalidTokenError:
            raise ValueError("Invalid token")

class TracerService(TracerServiceInterface):
    """Service for managing trace contexts using improved ContextVar approach."""

    def __init__(self, robot_collection_repository: IRobotCollectionRepository):
        """Initialize tracer service.

        Args:
            robot_collection_repository: Repository for accessing collection data.
        """
        self._repository = robot_collection_repository
        self._trace_context: contextvars.ContextVar[Optional[TraceContext]] = contextvars.ContextVar(
            "trace_context", default=None
        )

    def tracer(self, trace_type: str, identifier_path: str = None) -> Callable:
        """Configurable decorator for tracing functions.

        Args:
            trace_type: Type of trace (inference, training, other, etc.).
            identifier_path: Dot-separated path to collection identifier in function args.

        Returns:
            Decorator function for tracing.
        """

        def decorator(func: Callable) -> Callable:
            @wraps(func)
            async def wrapper(*args, **kwargs) -> Any:
                token = None

                try:
                    context = await self._create_trace_context(trace_type, identifier_path, kwargs)
                    token = self._trace_context.set(context)

                    self._update_trace_type_for_langgraph(kwargs, context)

                    result = await func(*args, **kwargs)

                    await self._finalize_trace(context)
                    return result

                except Exception as e:
                    current_context = self._trace_context.get()
                    if current_context:
                        LOGGER.warning(
                            f"Error in traced function {func.__name__} for trace {current_context.trace.trace_id}: {e}"
                        )
                    else:
                        LOGGER.warning(f"Error in traced function {func.__name__}: {e}")
                    raise

                finally:
                    if token:
                        self._trace_context.reset(token)

            return wrapper

        return decorator

    def get_current_trace(self) -> Optional[TraceContext]:
        """Get current trace context safely.

        Returns:
            Current trace context or None if no trace is active.
        """
        return self._trace_context.get()

    async def _create_trace_context(self, trace_type: str, identifier_path: str, kwargs: dict) -> TraceContext:
        """Create trace context with configurable identifier extraction.

        Args:
            trace_type: Type of trace (inference, training, other, etc.).
            identifier_path: Dot-separated path to collection identifier in function args.
            kwargs: Function keyword arguments.

        Returns:
            New trace context.
        """
        collection_identifier = self._extract_identifier_from_path(identifier_path, kwargs)
        user_id = self._extract_user_id_from_kwargs(kwargs, trace_type)

        try:
            version = await self._repository.get_current_collection_version(collection_identifier)
        except Exception as e:
            LOGGER.warning(f"Failed to get collection version: {e}")
            version = "unknown"

        if trace_type == "training":
            return TraceContext.create_training_context(
                trace_id=get_trace_id(), collection_identifier=collection_identifier, collection_version=version
            )
        elif trace_type in ["inference", "inference_lg"]:
            return TraceContext.create_inference_context(
                trace_id=get_trace_id(),
                collection_identifier=collection_identifier,
                user_id=user_id,
                collection_version=version,
            )
        else:
            return TraceContext.create_default_context(
                trace_id=get_trace_id(), collection_identifier=collection_identifier, collection_version=version
            )

    def _extract_identifier_from_path(self, identifier_path: str, kwargs: dict) -> str:
        """Extract collection identifier using the provided path.

        Args:
            identifier_path: Dot-separated path to the identifier in kwargs.
            kwargs: Function keyword arguments.

        Returns:
            Collection identifier string.
        """
        if not identifier_path:
            return self._extract_collection_identifier_fallback(kwargs)

        try:
            # Split the path and traverse the object
            keys = identifier_path.split(".")
            current = kwargs

            for key in keys:
                if isinstance(current, dict):
                    current = current.get(key)
                else:
                    current = getattr(current, key, None)

                if current is None:
                    break

            return str(current) if current is not None else "unknown"

        except (AttributeError, KeyError, TypeError):
            return "unknown"

    def _extract_collection_identifier_fallback(self, kwargs: dict) -> str:
        """Fallback method for extracting collection identifier (backwards compatibility).

        Args:
            kwargs: Function keyword arguments.

        Returns:
            Collection identifier string.
        """
        # Try various common parameter names
        if "collection_identifier" in kwargs:
            return kwargs["collection_identifier"]
        if "ecommerce_identifier" in kwargs:
            return kwargs["ecommerce_identifier"]

        input_data = kwargs.get("input_")
        if input_data:
            collection_id = getattr(input_data, "collection_identifier", None)
            if collection_id:
                return collection_id
            return getattr(input_data, "robot_identifier", "unknown")

        collection_info = kwargs.get("collection_info")
        if collection_info:
            return getattr(collection_info, "identifier", "unknown")

        return "unknown"

    def _extract_user_id_from_kwargs(self, kwargs: dict, trace_type: str) -> str:
        """Extract user ID from function kwargs based on trace type.

        Args:
            kwargs: Function keyword arguments.
            trace_type: Type of trace being created.

        Returns:
            User ID string.
        """
        if trace_type == "training":
            return "unknown"

        input_data = kwargs.get("input_")
        if not input_data:
            return "unknown"

        if hasattr(input_data, "config"):
            return input_data.config.get("user_id", "unknown")
        elif hasattr(input_data, "event"):
            return getattr(input_data.event.client, "id", "unknown")
        return "unknown"

    def _update_trace_type_for_langgraph(self, kwargs: dict, context: TraceContext) -> None:
        """Update trace type if using AutoLanggraph pipeline.

        Args:
            kwargs: Function keyword arguments.
            context: Current trace context.
        """
        ai_pipeline = kwargs.get("ai_pipeline")
        if isinstance(ai_pipeline, AutoLanggraph):
            context.trace.type = "inference_lg"

    async def _finalize_trace(self, context: TraceContext) -> None:
        """Finalize and persist trace data.

        Args:
            context: Trace context to finalize.
        """
        try:
            context.trace.ended_at = datetime.now().strftime("%Y-%m-%dT%H:%M:%S.%fZ")

            total_cost = sum(call.metadata.get("total_cost", 0) for call in context.chain_calls)
            context.trace.total_cost = total_cost

            logs_repository = self._repository.logs_repository
            await logs_repository.add_trace(context.trace)
            await logs_repository.add_chain_call(context.chain_calls)

            if context.inference_result:
                await logs_repository.add_inference_result(context.inference_result)

            if context.training_results:
                await logs_repository.add_training_result(context.training_results)

        except Exception as e:
            LOGGER.warning(f"Failed to finalize trace {context.trace.trace_id}: {e}")

class UserUseCase(IAuthService):
    def __init__(self, user_repository: ElasticsearchUserRepository):
        self.user_repository = user_repository

    async def create_user(self, user_data: UserData):
        try:
            await self.user_repository.create_user(user_data)
        except exceptions.UserNotExists as e:
            raise e
        except Exception as e:
            raise Exception(str(e))

    async def get_user_by_username(self, username: str) -> UserData:
        user = await self.user_repository.get_user_by_username(username)
        if user is None:
            raise exceptions.UserNotExists(detail=f"User {username} not found")
        return user

    async def delete_user(self, username: str):
        try:
            await self.user_repository.delete_user(username)
        except exceptions.UserDeletionError as e:
            raise e
        except Exception as e:
            raise exceptions.UserDeletionError(detail=str(e))

