async def run_chain(
    chain: Runnable,
    parameters: Dict,
    max_retries: int,
    name: str,
    assertion: str = "True",
    config: Dict | None = None,
    **kwargs,
):
    retries_count = 0
    if not config:
        config = {}

    while True:
        try:
            cb = None
            with get_openai_callback() as cb:
                result = await chain.with_config(configurable=config).ainvoke(
                    parameters,
                    **kwargs,
                )

            exec(assertion)

            try:
                chain_call = ChainCall(
                    trace_id=get_trace_id(),
                    chain_name=name,
                    input_data=json.dumps(parameters, ensure_ascii=False),
                    output_data=json.dumps(result, ensure_ascii=False),
                    metadata={
                        "completion_tokens": cb.completion_tokens,
                        "prompt_tokens": cb.prompt_tokens,
                        "total_cost": cb.total_cost,
                    },
                )
                context = get_current_trace()
                if context:
                    context.chain_calls.append(chain_call)
            except Exception:
                pass

            return result
        except Exception as e:
            retries_count += 1

            if retries_count > max_retries:
                LOGGER.error(f"error in invoking a chain!\nerror message: {e}")
                raise BrokenPipeError(
                    "can't invoke the chain correctly! it may be a problem with"
                    " reaching to openai or a problem with the chain itself!",
                )

def correction_chain(message: AIMessage, **kwargs) -> str:
    # match unquoted values until the next key or the end of the json object
    pattern = (
        r"(\"[a-zA-Z0-9_]*\"):\s*(.*?)(?=(,\n\s*(\"[a-zA-Z0-9_]*\"):|\n}$|\n}.{3,5}$))"
    )

    def correct_content(match):
        key, value = match.groups()[0], match.groups()[1]

        if kwargs.get("double_quates2single_quate", False):
            value = re.sub(r'"', "'", value)

        # single backslashes not indicating python special character should be removed
        PATTERN_WORD = r'(?<!\\)(?:\\\\)*\\(?!["\\\/]|[bfnrt](?![a-zA-Z])|u[0-9a-fA-F]{4})'
        corrected_value = re.sub(PATTERN_WORD, r'\\\\', value)

        if kwargs.get("ensure_value_quates", False):
            corrected_value = (
                corrected_value[1:-1]
                if (corrected_value.startswith("'") and corrected_value.endswith("'"))
                else corrected_value
            )
            # quote the corrected value
            return f'{key}: "{corrected_value}"'
        else:
            return f"{key}: {corrected_value}"

    return re.sub(pattern, correct_content, message.content, flags=re.DOTALL)

class CustomChatMessageHistory(BaseChatMessageHistory):
    messages: List[BaseMessage] = []  # Field(default_factory=list)

    def _grouper(iterable, n, fillvalue=None) -> zip_longest:
        "Collect data into fixed-length chunks or blocks"

        args = [iter(iterable)] * n
        return zip_longest(*args, fillvalue=fillvalue)

    def _get_message_of(type: str, content: str) -> BaseMessage:
        if type == "human":
            return HumanMessage(content=content)
        elif type == "ai":
            return AIMessage(content=content)
        # elif type == "system":
        #     return SystemMessage(content=content)
        # elif type == "chat":
        #     return ChatMessage(content=content)
        # elif type == "function":
        #     return FunctionMessage(content=content)
        # elif type == "tool":
        #     return ToolMessage(content=content)
        else:
            raise ValueError(f"Got unexpected message type: {type}")

    def _messages_from_history(history) -> List[BaseMessage]:
        try:
            messages = []
            sequence = [history[f"conversation{i + 1}"] for i in range(len(history))]
            for item in sequence:
                messages.append(
                    CustomChatMessageHistory._get_message_of(
                        type="human", content=item["human"]
                    )
                )
                messages.append(
                    CustomChatMessageHistory._get_message_of(
                        type="ai", content=item["ai"]
                    )
                )
            return messages

        except:
            return messages

    def __init__(self, history: Dict, max_saved_history: int):
        self.messages = CustomChatMessageHistory._messages_from_history(history)
        assert len(self.messages) <= max_saved_history * 2
        self.max_saved_history: int = max_saved_history

    def add_message(self, message: BaseMessage) -> None:
        """Append the message to the record"""
        if message.type in ["human", "ai"]:
            self.messages.append(message)

        # TODO: remove or uncomment
        # if len(self.messages) > 2 * self.max_saved_history:
        #     del self.messages[0]

    def clear(self) -> None:
        """Clear session memory"""
        self.messages = []

    def export(self) -> Dict:
        # assert len(self.messages) % 2 == 0

        history = {}
        messages = self.messages[(-self.max_saved_history * 2) :]
        tmp = {}
        for i, group in enumerate(
            CustomChatMessageHistory._grouper(
                iterable=messages,
                n=2,
            )
        ):
            conversation = {}
            for j, massage in enumerate(group):
                if j == 0:
                    assert massage.type == "human"
                else:
                    assert massage.type == "ai"

                conversation[massage.type] = massage.content

            history[f"conversation{i + 1}"] = conversation
        return history

def normalize_l2(x):
    x = np.array(x)
    if x.ndim == 1:
        norm = np.linalg.norm(x)
        if norm == 0:
            return x
        return x / norm
    else:
        norm = np.linalg.norm(x, 2, axis=1, keepdims=True)
        return np.where(norm == 0, x, x / norm)

class DocFormatter:
    @staticmethod
    def format_retrieved_docs(docs: List[Document], only_manuals: bool = False):
        output_string = ""

        manual_docs = [doc for doc in docs if doc.metadata.get("type") == "manual"]
        regular_docs = [doc for doc in docs if doc not in manual_docs]

        if only_manuals:
            output_string = DocFormatter._docs_to_string(
                manual_docs,
            )
        else:
            if manual_docs:
                output_string = "IMPORTANT DOCUMENTS:\n" + DocFormatter._docs_to_string(
                    manual_docs,
                )
                output_string += "\n\nREGULAR DOCUMENTS:\n" + DocFormatter._docs_to_string(
                    regular_docs,
                )
            else:
                output_string = DocFormatter._docs_to_string(
                    docs,
                )

        return output_string

    @staticmethod
    def _docs_to_string(docs: List[Document]) -> str:
        return "\n".join(f"[Doc {i}]\n{doc.page_content}\n" for i, doc in enumerate(docs))

    @staticmethod
    def show_retrieved_docs(docs: List[Document]) -> dict:
        return {
            key: {"Question": doc["Question"].page_content, "Answer": doc["Answer"].page_content}
            if "faq" in key and "Question" in doc
            else doc.page_content
            for key, doc in docs.items()
        }

def change_hyperlink_format(source: str, text: str) -> str:
    try:
        # Regular expression to find markdown links [text](url)
        pattern = r"\[(.*?)\]\((https?://[^\s\)]+)\)"

        # Replace markdown links with custom button format
        def replacer(match):
            title = match.group(1)
            url = match.group(2)
            return f"[button title='{title}' action='open_url' data='{url}']"

        return re.sub(pattern, replacer, text)
    except Exception as e:
        LOGGER.warning(f"Failed to change hyperlink format in {source} due to: {e}")
        return text

