class HistoryHandler:
    @staticmethod
    def user_history(chat_history: List) -> List:
        user_history = []

        for conversation in chat_history:
            user_history.append(conversation["human"])

        return user_history

    @staticmethod
    def prune_history(
        chat_history: List,
        last_n_conversation: int,
        max_token_len: int,
    ) -> List:
        """
        Updates history list in a way that it will contain last conversations until their joint token numbers
        is less than max_token_len or conversations number is less than last_n_conversation.
        Conversations with prune=False are always preserved and not subject to pruning logic.
        """
        preserved_conversations = []
        prunable_conversations = []

        for conversation in chat_history:
            if conversation.get("prune", True) is False:
                preserved_conversations.append(conversation)
            else:
                prunable_conversations.append(conversation)

        reversed_prunable = prunable_conversations[::-1]
        selected_prunable = []

        total_string = ""
        for conversation in reversed_prunable[:last_n_conversation]:
            conv = f"""
User: {conversation['human']}

Chatbot: {conversation['ai']}
"""
            total_string += conv
            if len(total_string.split(" ")) / 0.7 < max_token_len:
                selected_prunable.append(conversation)
            else:
                break

        selected_prunable = selected_prunable[::-1]

        final_history = []
        prunable_index = 0
        preserved_index = 0

        for conversation in chat_history:
            if conversation.get("prune", True) is False:
                if preserved_index < len(preserved_conversations):
                    final_history.append(preserved_conversations[preserved_index])
                    preserved_index += 1
            else:
                if prunable_index < len(selected_prunable) and conversation in selected_prunable:
                    final_history.append(conversation)
                    prunable_index += 1

        return final_history

    @staticmethod
    def add_conversation(chat_history: List, new_message: str, response: str) -> List:
        chat_history.append(
            {
                "human": new_message,
                "ai": response,
            },
        )
        return chat_history

    @staticmethod
    def create_history_string(chat_history: List) -> str:
        """Create a formatted string of the chat history.

        Args:
            chat_history: List of conversation dictionaries.

        Returns:
            A formatted string representing the chat history.
        """
        form_information = ""
        chat_history_content = ""

        for conversation in chat_history:
            if conversation.get("prune", True) is False:
                conv = f"""
Chatbot: {conversation['ai']}
User: {conversation['human']}
"""
                form_information += conv
            else:
                conv = f"""
User: {conversation['human']}
Chatbot: {conversation['ai']}
"""
                chat_history_content += conv

        total_string = ""
        if form_information:
            total_string += f"<form_information>\n{form_information}</form_information>\n\n"
        if chat_history_content:
            total_string += f"<chat_history>\n{chat_history_content}</chat_history>\n"

        return total_string

    @staticmethod
    def add_input_message(history_string: str, input_message: str) -> str:
        return history_string + f"\nUser: {input_message}\n"

def calculate_new_percentages(input_language, k):
    initial_persian_percentage = input_language.get("PERSIAN")

    if initial_persian_percentage is not None:
        new_persian_percentage = initial_persian_percentage + ((k - 1) * (100 - initial_persian_percentage)) / 4
        other_languages = {key: value for key, value in input_language.items() if key != "PERSIAN"}
        if other_languages:
            max_key = max(other_languages, key=other_languages.get)
            max_value = other_languages[max_key]

            new_max_value = max_value - ((k - 1) * (100 - new_persian_percentage)) / 4

            diff = new_persian_percentage + new_max_value - 100

            adjusted_persian = new_persian_percentage - (diff / 2)
            adjusted_max_value = new_max_value - (diff / 2)

            return {"PERSIAN": adjusted_persian, max_key: adjusted_max_value}
    return input_language

def confidence_language(Language_Word_Count):
    total_word_count = sum(result.word_count for result in Language_Word_Count)
    confidence = {}
    for result in Language_Word_Count:
        confidence[result.language.name] = (result.word_count / total_word_count) * 100 if total_word_count else 0
    return confidence

def detect_language_percentages(
    text: str,
    state: str = "train",
    check_email: bool = False,
    history: list[dict] | None = None,
):
    cleaned_text = re.sub(r"http\S+", "", text or "")

    bad_character = regex.compile(r"[\p{Cc}\p{Cs}]+")

    if text and text.strip().isdigit():
        return {"PERSIAN": 100} if state == "train" else "PERSIAN"

    if check_email:
        # اینجا چون text ممکن است None باشد، آن را مدیریت می‌کنیم
        return prepare_language_input(text, state=state, history=history)

    cleaned_text = bad_character.sub("", cleaned_text)
    try:
        Language_Word_Count = detector.detect_multiple_languages_of(cleaned_text)
        language_counts = confidence_language(Language_Word_Count)

        language_percentages = calculate_new_percentages(language_counts, 4)

        if state == "inference":
            if not language_percentages:
                return "PERSIAN"
            most_confident_language = max(language_percentages, key=language_percentages.get)
            return most_confident_language

        return language_percentages
    except Exception as e:
        LOGGER.warning("Error in detecting language for input text: %s" % e)
        return {"PERSIAN": 100} if state == "train" else "PERSIAN"

