def reciprocal_rank_fusion(retrieved_docs_dict, score_normalizer_constant=60):
    fused_scores = {} 
    doc_metadatas = []
    for query, docs_and_scores in retrieved_docs_dict.items():
        for rank, (doc, score) in enumerate(sorted(docs_and_scores, key=lambda x: x[1], reverse=True)):
            if doc.page_content not in fused_scores:
                fused_scores[doc.page_content] = 0
                doc_metadatas.append(doc.metadata)
            fused_scores[doc.page_content] += 1 / (rank + score_normalizer_constant)
    results = [(Document(x[0][0],x[1]), x[0][1]) for x in zip(list(fused_scores.items()), doc_metadatas)]
    reranked_results = [doc for doc, *_ in sorted(results, key=lambda x: x[1], reverse=True)]
    return reranked_results

def reciprocal_rank_fusion(
    retrieved_docs_dict: Dict[str, Document],
    score_normalizer_constant=60,
) -> List[Document]:
    """Performs Reciprocal Rank Fusion (RRF) on a dictionary of retrieved documents for multiple queries."""
    fused_scores = {}
    doc_metadatas = []
    for _query, docs in retrieved_docs_dict.items():
        for rank, doc in enumerate(docs):
            if doc.page_content not in fused_scores:
                fused_scores[doc.page_content] = 0
                doc_metadatas.append(doc.metadata)
            fused_scores[doc.page_content] += 1 / (rank + score_normalizer_constant)
    results = [
        (Document(x[0][0]), x[0][1])
        for x in zip(list(fused_scores.items()), doc_metadatas)
    ]
    for result, metadata in zip(results, doc_metadatas):
        result[0].metadata = metadata

    reranked_results = [
        doc for doc, *_ in sorted(results, key=lambda x: x[1], reverse=True)
    ]
    return reranked_results

