class StringMatcherUtils:
    TOKEN_RE = re.compile(r"[^\W_]+", re.UNICODE)
    LATIN_RE = re.compile(r"[A-Za-z]")
    DIGIT_RE = re.compile(r"[0-9۰-۹]")
    STOPWORDS = {"و", "از", "با", "به", "در", "برای", "the", "and", "of", "a", "an"}

    def __init__(self, stopwords: Optional[set] = None):
        if stopwords is not None:
            self.STOPWORDS = set(stopwords)

    @staticmethod
    def _tok(txt: str) -> List[str]:
        if not txt:
            return []
        return [t.lower() for t in StringMatcherUtils.TOKEN_RE.findall(txt)]

    @staticmethod
    def _match(cats: List[str], pname: str) -> List[str]:
        ptoks = set(StringMatcherUtils._tok(pname))
        matched: List[str] = []
        for c in cats:
            ctoks = [t for t in StringMatcherUtils._tok(c) if t]
            if ctoks and all(t in ptoks for t in ctoks):
                matched.append(c)
        return matched

    def _is_better_match(self, ptoks, cat_toks, matched_cat) -> bool:
        if all(t in ptoks for t in cat_toks):
            return matched_cat is None or len(cat_toks) > len(self._tok(matched_cat))
        return False

    @staticmethod
    def _select_best(m: List[str]) -> Optional[str]:
        return max(m, key=lambda x: len(x.split())) if m else None

class TextProcessingUtils:
    @staticmethod
    def clean_text(text: str) -> str:
        return re.sub(r"(<br>)|[\n\\n\-_=,\[\]\(\)\{\}.?!;:؛؟،]", " ", text).strip()

    @staticmethod
    def tokenize(text: str) -> List[str]:
        result = re.split(r"\\n|\n|<br>| |'|،|,", text)
        return [token for token in result if token]

    @staticmethod
    def preprocess_text(text: str) -> str:
        text = TextProcessingUtils.clean_text(text)
        return TextProcessingUtils.tokenize(text)

    @staticmethod
    def split_lines(text: str) -> List[str]:
        return re.split(r"\\n|\n|<br>", text)

    @staticmethod
    def match_first_line(string1, string2, max_diff=0.1):
        first_line = TextProcessingUtils.split_lines(string2)[0]
        similarity_ratio = difflib.SequenceMatcher(None, string1, first_line).ratio()
        return similarity_ratio >= (1 - max_diff)

    @staticmethod
    def recursive_splitter(
        text: str,
        max_length: int,
        len_func: Callable,
        separators: List[str] = None,
        min_length: int = None,
    ) -> List[str]:
        """
        Recursively splits the input text into segments based on specified separators and length constraints.
        """

        def recursive_split(text: str, separators: List[str]) -> List[str]:
            if not separators:
                return [text]

            separator = separators[0]
            parts = text.split(separator)
            segments = []
            current_segment = parts[0]

            for part in parts[1:]:
                if len_func(current_segment + separator + part) <= max_length:
                    current_segment += separator + part
                else:
                    if len_func(current_segment) >= min_length:
                        segments.append(current_segment)
                        current_segment = part
                    else:
                        current_segment += separator + part

            if current_segment:
                segments.append(current_segment)

            final_segments = []
            for segment in segments:
                if len_func(segment) > max_length:
                    final_segments.extend(recursive_split(segment, separators[1:]))
                else:
                    final_segments.append(segment)

            return final_segments

        segments = []
        if separators:
            segments.extend(recursive_split(text, separators))

        final_segments = []
        for segment in segments:
            if len_func(segment) > max_length:
                final_segments.extend(TextProcessingUtils.split_text_by_length(segment, max_length, len_func))
            else:
                final_segments.append(segment)

        return final_segments

    @staticmethod
    def split_text_with_overlap(text: str, max_length: int, len_func: Callable, overlap: int = 10) -> List[str]:
        """
        Splits text into overlapping segments using a moving window approach.
        Each segment starts `max_length - overlap` characters after the previous one.
        """
        segments = []
        start = 0
        step = max_length - overlap  # Define how much to move forward in each step

        while start < len(text):
            end = start + max_length  # Define the end index of the current segment
            segment = text[start:end]  # Extract substring for the segment
            segments.append(segment)

            # Move the window forward by step size, ensuring overlap
            start += step

        return segments

    @staticmethod
    def split_text_by_length(
        text: str,
        max_length: int,
        len_func: Callable,
    ) -> List[str]:
        lines = TextProcessingUtils.split_lines(text)
        segments = []
        current_segment = []
        current_length = 0

        for line in lines:
            line_length = len_func(line)

            if (
                line.startswith("line number:") and line.rstrip().endswith("|") and len(line.strip()) <= 17
            ):  # Adjust the length threshold as needed
                if current_segment:
                    current_segment[-1] += "\n" + line.strip()  # Append to the current segment
                continue

            if current_length + line_length > max_length:
                segment = "\n".join(current_segment)
                if segment:
                    segments.append(segment)
                current_segment = [line]
                current_length = line_length
            else:
                current_segment.append(line)
                current_length += line_length

        if current_segment:
            segments.append("\n".join(current_segment))

        return segments

    @staticmethod
    def break_lines_by_sentence(text: str, max_line_length: int, len_func: Callable) -> List[str]:
        """
        Breaks those lines that are longer than max_line_length into smaller
        lines based on sentence boundaries.
        """
        sentence_splitters = re.compile(r"([;.,!?؟؛،])")
        lines = TextProcessingUtils.split_lines(text)
        broken_lines = []

        for line in lines:
            if len_func(line) <= max_line_length:
                broken_lines.append(line)
                continue

            sentences = sentence_splitters.split(line)
            current_line = ""

            for i in range(0, len(sentences), 2):
                sentence = sentences[i]
                splitter = sentences[i + 1] if i + 1 < len(sentences) else ""

                if len_func(current_line + sentence + splitter) > max_line_length:
                    if current_line:
                        broken_lines.append(current_line.strip())
                    current_line = sentence + splitter
                else:
                    current_line += sentence + splitter

            if current_line:
                broken_lines.append(current_line.strip())

        # Further break lines by space if they are still too long
        final_broken_lines = []
        for line in broken_lines:
            if len_func(line) <= max_line_length:
                final_broken_lines.append(line)
            else:
                words = line.split(" ")
                current_line = ""
                for word in words:
                    if len_func(current_line + " " + word) > max_line_length:
                        if current_line:
                            final_broken_lines.append(current_line.strip())
                        current_line = word
                    else:
                        current_line = current_line + " " + word if current_line else word
                if current_line:
                    final_broken_lines.append(current_line.strip())

        return final_broken_lines

    @staticmethod
    def heading_based_segmentation(
        text: str,
        max_length: int,
        min_length: int,
        len_func: Callable,
    ) -> List[str]:
        """
        Split the text based on heading ones, if the content between two heading ones(#) is
        more than max_length, it tries to split it based on the heading twos(##), and so on.
        If it couldn't find a segment between headings until heading four(####), it uses
        the `recursive_splitter` method, the `min_length` is used there.
        """

        def split_by_heading(text: str, parent_heading: str, heading: str) -> List[tuple]:
            segments = []
            current_segment = []
            current_heading = ""
            for line in text.splitlines():
                if line.strip().startswith(heading):
                    if current_segment:
                        new_heading = parent_heading + " >> " + current_heading if current_heading else parent_heading
                        segments.append(
                            (
                                new_heading,
                                "\n".join(current_segment),
                            )
                        )
                        current_segment = []
                    current_heading = line
                current_segment.append(line)
            if current_segment:
                new_heading = parent_heading + " >> " + current_heading if current_heading else parent_heading
                segments.append(
                    (
                        new_heading,
                        "\n".join(current_segment),
                    )
                )
            return segments

        headings = ["# ", "## ", "### ", "#### "]
        segments = [("Hierarchical Path:", text)]

        for heading in headings:
            new_segments = []
            for parent_heading, segment in segments:
                if len_func(segment) > max_length:
                    new_segments.extend(split_by_heading(segment, parent_heading, heading))
                else:
                    new_segments.append((parent_heading, segment))
            segments = new_segments

        final_segments = []
        for parent_heading, segment in segments:
            if len_func(segment) > max_length:
                split_segments = TextProcessingUtils.recursive_splitter(
                    segment,
                    max_length,
                    len_func,
                    ["\n\n\n", "\n\n"],
                    min_length,
                )
                final_segments.extend([(parent_heading, seg) for seg in split_segments])
            else:
                final_segments.append((parent_heading, segment))

        return [f"{parent_heading}\n{segment}" for parent_heading, segment in final_segments]

