def to_dict(obj: Any) -> Dict[str, Any]:
    if hasattr(obj, "model_dump"):  # Pydantic v2
        return obj.model_dump()
    if hasattr(obj, "dict"):  # Pydantic v1
        return obj.dict()
    if dataclasses.is_dataclass(obj):
        return dataclasses.asdict(obj)
    if hasattr(obj, "__dict__"):
        return vars(obj)
    return obj

def decode_if_needed(text: str) -> str:
    try:
        decoded = urllib.parse.unquote(text)
        return decoded
    except Exception:
        return text

def replace_placeholders(messages_obj: Any, values_obj: Any) -> Any:
    messages_dict = to_dict(messages_obj)
    values_dict = to_dict(values_obj)

    values_dict = {k.upper(): decode_if_needed(str(v)) for k, v in values_dict.items()}

    def replace_in_text(text: str) -> str:
        new_text = text
        for placeholder, value in values_dict.items():
            new_text = new_text.replace(f"{{{{{placeholder}}}}}", value)
        return new_text

    def recurse(structure):
        if isinstance(structure, dict):
            return {k: recurse(v) for k, v in structure.items()}
        elif isinstance(structure, list):
            return [replace_in_text(x) if isinstance(x, str) else recurse(x) for x in structure]
        else:
            return structure

    return recurse(messages_dict)

