def git(*args: str) -> str:
    """Run a git command and return its stdout (stripped)."""
    return sp.check_output(["git", *args], text=True).strip()

def human_delta(delta: dt.timedelta) -> str:
    """Return a compact human-readable time delta, e.g. '2 d 3 h 4 m'."""
    seconds = int(delta.total_seconds())
    days, seconds = divmod(seconds, 86_400)
    hours, seconds = divmod(seconds, 3_600)
    minutes, seconds = divmod(seconds, 60)

    parts: List[str] = []
    if days:
        parts.append(f"{days}\u202f{'d'}")
    if hours:
        parts.append(f"{hours}\u202f{'h'}")
    if minutes:
        parts.append(f"{minutes}\u202f{'m'}")
    if seconds or not parts:
        parts.append(f"{seconds}\u202f{'s'}")
    return " ".join(parts)

def main() -> None:
    repo_root = Path(git("rev-parse", "--show-toplevel"))
    files = git("ls-files").splitlines()

    offenders: dict[str, list[tuple[str, dt.datetime, str, dt.datetime, dt.timedelta]]] = {}

    for path in files:
        commits = last_commits(path, n=5)
        jumps = list(find_jumps(commits))
        if jumps:
            offenders[path] = jumps

    if offenders:
        print("⚠️  Out-of-order author dates found:")
        for path, jumps in offenders.items():
            print(f"  • {path}")
            for sha_new, d_new, sha_old, d_old, delta in jumps:
                print(
                    f"      {sha_new[:7]} ({d_new.isoformat(timespec='seconds')}) "
                    f"is {human_delta(delta)} older than"
                )
                print(f"      {sha_old[:7]} ({d_old.isoformat(timespec='seconds')})")
                print(f"    git diff {sha_new[:7]}..{sha_old[:7]} -- {path}")
    else:
        print("✅  No anomalies in the last five commits of any file.")

    print("✅  Scan complete.")

def is_gregorian(date_str: str):
    try:
        year = int(date_str[:4])
        return 1900 <= year <= 2100
    except (ValueError, IndexError):
        return False

def convert_iso_datetime_to_jalali(gerigorian_iso_datetime: str) -> str:
    date_time = datetime.datetime.fromisoformat(gerigorian_iso_datetime)
    date = convert_date_to_jalali_date(date_time.date())
    time = date_time.time()
    return str(date) + "T" + str(time)

