def get_env_file_path(environment: Optional[Union[str, Environment]] = None, 
                      custom_path: Optional[str] = None) -> str:
    """Get the appropriate environment file path.

    Args:
        environment: Environment name or Environment enum
        custom_path: Custom path to an environment file

    Returns:
        Path to the environment file
    """
    # Custom path takes precedence
    if custom_path:
        env_path = Path(custom_path)
        LOGGER.info(f"Using custom environment file: {env_path}")
        return str(env_path)

    # Normalize environment
    if environment is None:
        env_type = Environment.DEFAULT
    elif isinstance(environment, str):
        try:
            env_type = Environment(environment.lower())
        except ValueError:
            LOGGER.warning(f"Unknown environment: {environment}, using default")
            env_type = Environment.DEFAULT
    else:
        env_type = environment

    # Map environment to file path
    env_files = {
        Environment.DEV: DEFAULT_PATH / "dev.env",
        Environment.TEST: DEFAULT_PATH / "test.env",
        Environment.PROD: DEFAULT_PATH / "prod.env",
        Environment.DEFAULT: DEFAULT_PATH / ".env",
    }

    env_path = env_files[env_type]
    LOGGER.info(f"Using {env_type.value} environment file: {env_path}")
    return str(env_path)

def _exception_factory(name: str, code: ErrorCodes):
    """Dynamically create an exception subclass bound to *code*."""

    return type(
        name,
        (CustomException,),
        {"__init__": lambda self, detail: super(type(self), self).__init__(status_code=code.value, detail=detail)},
    )

class DomainValidationError(CustomException):
    """Exception raised for domain validation errors (HTTP‑422)."""

    def __init__(self, detail: str | None = None):
        super().__init__(status_code=422, detail=detail or "Domain validation error occurred.")

def extract_post_tracking_code(text: str) -> str:
    pattern = r"\b\d{20,24}\b"
    matches = re.findall(pattern, text)
    if len(matches) > 0:
        return matches[0]
    else:
        return ""

def get_prompt_for_chain(chain_name: str) -> Optional[Dict[str, Any]]:
    """دریافت prompt برای یک chain بر اساس نام."""
    try:
        prompts = PromptFactory.create()
        if chain_name in prompts:
            prompt_obj = prompts[chain_name]
            result = {
                "prompt_string": prompt_obj.prompt,
                "template": prompt_obj.template if hasattr(prompt_obj, "template") else None,
            }
            return result

        if chain_name.endswith("_query_generation_chain"):
            template_name = chain_name.removesuffix("_query_generation_chain") + "_message_template"
            generation_prompts = AutoRagGeneratorPrompts()

            if hasattr(generation_prompts, template_name):
                template_obj = getattr(generation_prompts, template_name)
                result = {
                    "prompt_string": template_obj.template if hasattr(template_obj, "template") else str(template_obj),
                    "template": template_obj,
                }
                return result

        return None
    except Exception as e:
        st.error(f"خطا در بارگذاری prompt برای {chain_name}: {e}")
        return None

def format_prompt_with_input(prompt_data: Dict[str, Any], input_data_str: str) -> Dict[str, Any]:
    """پر کردن placeholder های prompt با input_data."""
    try:
        input_data = json.loads(input_data_str)

        prompt_str = prompt_data.get("prompt_string", "")
        template_obj = prompt_data.get("template")

        if template_obj:
            template = template_obj
        else:
            template = PromptTemplate.from_template(prompt_str)

        available_vars = template.input_variables
        filtered_input = {k: v for k, v in input_data.items() if k in available_vars}

        try:
            formatted = template.format(**filtered_input)
        except KeyError as ke:
            missing_var = str(ke).strip("'")
            filtered_input[missing_var] = ""
            formatted = template.format(**filtered_input)

        return {
            "formatted_prompt": formatted,
            "used_variables": filtered_input,
            "missing_variables": [v for v in available_vars if v not in input_data],
        }
    except json.JSONDecodeError as e:
        return {"error": f"خطا در parse کردن input_data: {e}", "formatted_prompt": prompt_data.get("prompt_string", "")}
    except Exception as e:
        return {"error": f"خطا در format کردن prompt: {e}", "formatted_prompt": prompt_data.get("prompt_string", "")}

def run_chain_with_local_model(
    formatted_prompt: str,
) -> str:
    """اجرای chain با مدل لوکال."""
    local_model_url = os.getenv("LOCAL_MODEL_URL", "http://localhost:8003/v1/chat/completions").strip()
    local_model_name = os.getenv("LOCAL_MODEL_NAME", "Qwen/Qwen3-8B").strip()
    local_model_auth = os.getenv("LOCAL_MODEL_AUTH", "").strip()

    payload = {
        "model": local_model_name,
        "messages": [{"role": "user", "content": formatted_prompt}],
        "tool_choice": "none",
        "chat_template_kwargs": {"enable_thinking": False},
    }

    headers = {
        "Content-Type": "application/json",
    }

    if local_model_auth:
        headers["Authorization"] = local_model_auth

    try:
        response = requests.post(local_model_url, headers=headers, json=payload, timeout=120)
        response.raise_for_status()

        result = response.json()
        if "choices" in result and len(result["choices"]) > 0:
            return result["choices"][0]["message"]["content"]
        else:
            return f"خطا: پاسخ نامعتبر از مدل - {result}"
    except requests.exceptions.RequestException as e:
        return f"خطا در ارتباط با مدل لوکال: {str(e)}"
    except Exception as e:
        return f"خطا در پردازش پاسخ مدل لوکال: {str(e)}"

