def _validate_products(products_data: List[dict]) -> List[Product]:
    products: List[Product] = []
    invalid = 0
    for idx, raw in enumerate(products_data, 1):
        try:
            item = _preprocess_product_item(raw)
            products.append(Product.model_validate(item))
        except Exception as e:
            invalid += 1
            LOGGER.warning(f"Skipping invalid product at position {idx}: {str(e)}")
            LOGGER.debug(f"Invalid product data: {raw}")
    if invalid:
        LOGGER.info(f"Validated products: {len(products)} ok, {invalid} invalid.")
    return products

def _ensure_tag_objects(tags: Any) -> List[dict]:
    if not isinstance(tags, list):
        return []
    out: List[dict] = []
    for t in tags:
        if isinstance(t, str):
            out.append({"id": 0, "name": t, "slug": ""})
        elif isinstance(t, dict):
            out.append(t)
    return out

def _normalize_dimensions_as_strings(dim: Any) -> dict:
    result = {"length": "0", "width": "0", "height": "0"}
    if not isinstance(dim, dict):
        return result
    for k in ("length", "width", "height"):
        v = dim.get(k, "")
        if v is None:
            result[k] = "0"
        elif isinstance(v, (int, float)):
            result[k] = str(v)
        elif isinstance(v, str):
            result[k] = v
        else:
            result[k] = "0"
    return result

def _preprocess_product_item(item: dict) -> dict:
    processed = dict(item)
    for price_field in ["price", "regular_price", "sale_price"]:
        val = processed.get(price_field)
        if isinstance(val, str):
            num, _ = parse_price_with_currency(val)
            processed[price_field] = num if num is not None else ""
        elif isinstance(val, (int, float)):
            processed[price_field] = float(val)
        else:
            processed[price_field] = ""
    ph = processed.get("price_html")
    if isinstance(ph, (list, dict)):
        processed["price_html"] = json.dumps(ph, ensure_ascii=False, separators=(",", ":"))
    elif ph is None:
        processed["price_html"] = ""
    processed["dimensions"] = _normalize_dimensions_as_strings(processed.get("dimensions", {}))
    ar = processed.get("average_rating")
    if ar is None:
        processed["average_rating"] = ""
    elif isinstance(ar, (int, float)):
        processed["average_rating"] = str(ar)
    else:
        processed["average_rating"] = str(ar)
    for k in ["short_description", "stock_status"]:
        if processed.get(k) is None:
            processed[k] = ""
    if "tags" in processed:
        processed["tags"] = _ensure_tag_objects(processed["tags"])
    return processed

def _to_str(v: Any) -> str:
    try:
        return str(v)
    except Exception:
        return ""

def _to_float(v: Any) -> Optional[float]:
    if v in (None, ""):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        try:
            return float(v)
        except ValueError:
            f, _ = parse_price_with_currency(v)
            return f
    return None

def _normalize_attributes(attrs: Any) -> Any:
    if not isinstance(attrs, list):
        return attrs
    out = []
    for a in attrs:
        if not isinstance(a, dict):
            continue
        b = a.copy()
        if "options" in b and b["options"] is not None:
            if isinstance(b["options"], list):
                b["options"] = [_to_str(x) for x in b["options"]]
            else:
                b["options"] = [_to_str(b["options"])]
        out.append(b)
    return out

def _prepare_product_update_data(products: List[Product]) -> List[dict]:
    docs: List[dict] = []
    for p in products:
        d = p.model_dump(mode="json")
        d = {k: v for k, v in d.items() if k not in ENHANCED_ATTRIBUTE_KEYS and v is not None}
        if "id" in d:
            d["id"] = _to_str(d["id"])
        if "sku" in d:
            d["sku"] = _to_str(d["sku"])
        for k in _STR_ARRAY_KEYWORDS:
            if k in d and isinstance(d[k], list):
                d[k] = [_to_str(x) for x in d[k] if x is not None]
        if "average_rating" in d:
            d["average_rating"] = _to_float(d["average_rating"])
        if "weight" in d:
            d["weight"] = _to_float(d["weight"])
        if "dimensions" in d and isinstance(d["dimensions"], dict):
            d["dimensions"] = _normalize_dimensions_as_strings(d["dimensions"])  # keep as strings
        if "meta_data" in d and isinstance(d["meta_data"], list):
            nm = []
            for m in d["meta_data"]:
                if isinstance(m, dict):
                    mc = m.copy()
                    if "value" in mc:
                        mc["value"] = _normalize_meta_value(mc["value"])
                    nm.append(mc)
            d["meta_data"] = nm
        if "attributes" in d:
            d["attributes"] = _normalize_attributes(d["attributes"])
        if "product_vector" in d and isinstance(d["product_vector"], list):
            vec = [_to_float(x) for x in d["product_vector"]]
            d["product_vector"] = [x for x in vec if x is not None] or None
        d = {k: v for k, v in d.items() if v is not None}
        docs.append(d)
    return docs

def _load_products_from_dir(directory: Path) -> List[dict]:
    products: List[dict] = []
    if not directory.exists() or not directory.is_dir():
        raise FileNotFoundError(f"Directory not found: {directory}")
    for path in directory.glob("*.json"):
        try:
            with path.open("r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                candidates = [x for x in data if isinstance(x, dict)]
                if not candidates:
                    LOGGER.warning(f"Skipping non-dict JSON array in {path.name}")
                    continue
            elif isinstance(data, dict):
                candidates = [data]
            else:
                LOGGER.warning(f"Skipping non-dict JSON in {path.name}")
                continue
            for product in candidates:
                if not isinstance(product, dict):
                    continue
                processed_product = _preprocess_product_item(product)
                products.append(processed_product)
        except json.JSONDecodeError as e:
            LOGGER.warning(f"Skipping invalid JSON file {path.name}: {e}")
        except Exception as e:
            LOGGER.warning(f"Error processing file {path.name}: {e}")
    return products

