def normalize_l2(x: list, floating_point_mode="FP32") -> list:
    # FIXME: the returning value remain fp16 after converting to list. 
    x = np.array(x)
    if x.ndim == 1:
        norm = np.linalg.norm(x)
        if norm == 0:
            result = x
        result = x / norm
    else:
        norm = np.linalg.norm(x, 2, axis=1, keepdims=True)
        result =  np.where(norm == 0, x, x / norm)
    if floating_point_mode == "FP32":
        result = result.astype(np.float32).tolist()
    elif floating_point_mode == "FP16":
        result = result.astype(np.float16).tolist()
    else:
        raise ValueError("Unsupported floating point mode")
    return result

def _iter_fields(model_instance):
    """Yield (name, field_info) pairs on both Pydantic versions."""
    if hasattr(model_instance, "__fields__"):           # v1
        return model_instance.__fields__.items()
    return model_instance.model_fields.items()          # v2

def _field_type(field_info):
    """Return the declared (outer) type of a field."""
    # v1: ModelField.outer_type_   |   v2: FieldInfo.annotation
    return (
        getattr(field_info, "outer_type_", None)
        or getattr(field_info, "annotation", Any)
        or Any
    )

class ObjectGenerator:
    """
    Parameters
    ----------
    model : `Type[BaseModel]`
        Any Pydantic model class.
    fields_of_interest : `Dict[str, List[Any]]`
        Mapping of *dotted paths* to the values you want to cycle through.
        Example: ``{"trace_id": ["a", "b"], "event.client.id": [1, 2, 3]}``
    number : int
        How many objects to emit.
    """

    def __init__(
        self,
        model: Type[BaseModel],
        fields_of_interest: Dict[str, List[Any]],
        number: int,
    ) -> None:
        self.model = model
        self.fields_of_interest = fields_of_interest
        self.number = number
        self.fake = Faker()

        # Never run out of values: each list becomes an infinite cycle
        self._cycles = {
            path: itertools.cycle(values) for path, values in fields_of_interest.items()
        }

    # ── public API ──────────────────────────────────────────────

    def generate(self) -> List[BaseModel]:
        """Return ``number`` populated model instances."""
        out: List[BaseModel] = []
        for _ in range(self.number):
            obj = self._blank_instance()
            self._apply_variations(obj)
            out.append(obj)
        return out

    # ── internal helpers ───────────────────────────────────────

    def _blank_instance(self) -> BaseModel:
        """
        Start with a skeletal model (``construct()``) and
        fill any *required* fields with simple fake data.
        """
        obj = self.model.construct()
        for name, field_info in _iter_fields(obj):
            if getattr(obj, name, None) is None:
                typ = _resolve(_field_type(field_info))
                setattr(obj, name, self._default_for(typ))
        return obj

    def _apply_variations(self, obj: BaseModel) -> None:
        """Overwrite dotted paths with the next value in each cycle."""
        for dotted_path, cycle in self._cycles.items():
            self._set_dotted(obj, dotted_path.split("."), next(cycle))

    # dotted-path setter ----------------------------------------

    def _set_dotted(self, cur: Any, segments: List[str], value: Any) -> None:
        head, *tail = segments
        if tail:
            nxt = getattr(cur, head, None)
            if nxt is None:                       # lazily create missing sub-model
                field_info = (
                    cur.__fields__.get(head) if hasattr(cur, "__fields__")
                    else cur.model_fields[head]
                )
                sub_cls: Type[BaseModel] = _resolve(_field_type(field_info))
                nxt = sub_cls.construct()
                setattr(cur, head, nxt)
            self._set_dotted(nxt, tail, value)
        else:
            setattr(cur, head, value)

    # crude default factory -------------------------------------

    def _default_for(self, typ):
        if isinstance(typ, type) and issubclass(typ, BaseModel):
            return typ.construct()
        if typ is str:
            return self.fake.word()
        if typ is int:
            return random.randint(1, 1000)
        if typ is float:
            return round(random.random() * 100, 2)
        if typ is bool:
            return random.choice([True, False])
        if typ in (list, List):
            return []
        if typ in (dict, Dict):
            return {}
        if typ is datetime:
            return datetime.now(tz=timezone.utc)
        return None

