def collect_imported_names(tree: ast.AST) -> Set[str]:
    """Return a set of top‑level names introduced via *import* statements."""
    names: Set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            names.update(alias.asname or alias.name.split(".")[0] for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            names.update(alias.asname or alias.name for alias in node.names)
    return names

def map_init_dependencies(cls: ast.ClassDef, imported: Set[str]) -> Dict[str, str]:
    """Return ``{attr_name: symbol}`` for deps initialised in *cls*.__init__.

    A dependency qualifies if *either*:
      1. ``self.<attr> = ImportedClass(...)`` where *ImportedClass* comes from a
         module‑level import, *or*
      2. ``self.<attr> = param`` **and** ``param`` is an ``__init__`` argument
         that carries a type annotation (class path or ``typing.Protocol``).  We
         register the annotation string as *symbol*.
    """

    mapping: Dict[str, str] = {}

    init = next(
        (n for n in cls.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == "__init__"),
        None,
    )
    if not init:
        return mapping

    # param → annotation string (skip *self*)
    param_ann: Dict[str, str] = {}
    for arg in init.args.args[1:]:
        if arg.annotation is not None:
            param_ann[arg.arg] = ast.unparse(arg.annotation)

    for stmt in (n for n in ast.walk(init) if isinstance(n, ast.Assign)):
        # Only consider assignments to self.<attr>
        targets = [t for t in stmt.targets if isinstance(t, ast.Attribute)]
        for tgt in targets:
            if not (isinstance(tgt.value, ast.Name) and tgt.value.id == "self"):
                continue
            attr = tgt.attr
            if attr == "logger":  # explicit exclusion
                continue

            symbol: str | None = None
            src = stmt.value

            # Case 1 – dependency injected via parameter
            if isinstance(src, ast.Name) and src.id in param_ann:
                symbol = param_ann[src.id]

            # Case 2 – instance created from an imported class / factory
            elif isinstance(src, ast.Call):
                fn = src.func
                # direct name ``ImportedClass()``
                if isinstance(fn, ast.Name) and fn.id in imported:
                    symbol = fn.id
                # attribute call ``module.Factory()``
                elif (
                    isinstance(fn, ast.Attribute)
                    and isinstance(fn.value, ast.Name)
                    and fn.value.id in imported
                ):
                    symbol = f"{fn.value.id}.{fn.attr}"

            # Case 3 – direct name assignment ``self.attr = ImportedSingleton``
            elif isinstance(src, ast.Name) and src.id in imported:
                symbol = src.id

            if symbol:
                mapping[attr] = symbol
    return mapping

def discover_calls(method: ast.FunctionDef | ast.AsyncFunctionDef, deps: Dict[str, str]) -> List[str]:
    """Return sorted list of ``attr.method`` calls made on recognised *deps*."""
    found: Set[str] = set()
    for node in (n for n in ast.walk(method) if isinstance(n, ast.Call)):
        chain = get_attr_chain(node.func)
        # need self.<dep>.<method>[.<subcall>…]
        if len(chain) < 3 or chain[0] != "self":
            continue
        base = chain[1]
        if base not in deps or base == "logger":
            continue
        found.add(".".join(chain[1:]))
    return sorted(found)

def analyse_file(path: Path) -> Tuple[
    List[str],
    List[str],
    List[str],
    Dict[str, Dict[str, Tuple[str, List[str]]]],
]:
    """Return structured info for *path*."""

    tree = ast.parse(path.read_text("utf-8"))
    imported = collect_imported_names(tree)

    imports, globals_, main = [], [], []
    classes: Dict[str, Dict[str, Tuple[str, List[str]]]] = {}

    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            imports.append(ast.unparse(node))
        elif isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name):
            globals_.append(ast.unparse(node))
        elif (
            isinstance(node, ast.If)
            and isinstance(node.test, ast.Compare)
            and isinstance(node.test.left, ast.Name)
            and node.test.left.id == "__name__"
            and isinstance(node.test.comparators[0], ast.Constant)
            and node.test.comparators[0].value == "__main__"
        ):
            main.append(ast.unparse(node))
        elif isinstance(node, ast.ClassDef):
            deps = map_init_dependencies(node, imported)
            meths: Dict[str, Tuple[str, List[str]]] = {}
            for m in node.body:
                if not isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                meths[m.name] = (signature(m), discover_calls(m, deps))
            classes[node.name] = meths

    return imports, globals_, main, classes

def _imported_modules(tree: ast.AST) -> Set[str]:
    """Collect *fully‑qualified* module paths from import nodes."""
    mods: Set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            mods.update(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                # Ignore relative level for simplicity – we treat only absolute
                mods.add(node.module)
    return mods

def tree_lines(dir_path: Path, prefix: str = "") -> List[str]:
    lines: List[str] = []
    try:
        entries = sorted(p for p in dir_path.iterdir() if not p.name.startswith(".git") and not p.name.endswith(".pyc"))
        for i, entry in enumerate(entries):
            last = i == len(entries) - 1
            branch = "└── " if last else "├── "
            if entry.is_dir() or entry.suffix == ".py":
                lines.append(f"{prefix}{branch}{entry.name}")
                if entry.is_dir():
                    extra = "    " if last else "│   "
                    lines.extend(tree_lines(entry, prefix + extra))
    except PermissionError:
        pass
    return lines

