def record_time_usage(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        time_start = time.time()
        rt = func(*args, **kwargs)
        time_end = time.time()
        diff_ms = (time_end - time_start) * 1000
        LOGGER.info("time usage of %s: %sms" % (func.__name__, diff_ms))
        return rt

    return wrapper

def record_cpu_time_usage(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        time_start = time.process_time()
        rt = func(*args, **kwargs)
        time_end = time.process_time()
        diff_ms = (time_end - time_start) * 1000
        LOGGER.info("CPU time usage of %s: %sms" % (func.__name__, diff_ms))
        return rt

    return wrapper

def get_version():
    version_file = f"{DEFAULT_PATH}/parschat_logic/__init__.py"
    with open(version_file, "r") as file:
        content = file.read()
    version_match = re.search(r"__version__ = ['\"]([^'\"]+)['\"]", content)
    if version_match:
        return version_match.group(1)
    else:
        raise ValueError("Version string not found in __init__.py")

def get_commits():
    """Fetches the list of commit messages between develop and main branches."""
    try:
        result = subprocess.run(
            ["git", "log", "main..develop", "--pretty=format:%s"],
            check=True,
            stdout=subprocess.PIPE,
            text=True,
        )
        return result.stdout.split("\n")
    except subprocess.CalledProcessError as e:
        logger.info(f"Error fetching commits: {e}")
        return []

def create_and_push_tag(version, commit_message):
    """Creates and pushes a Git tag with the version and commit message."""
    tag_name = version
    try:
        subprocess.run(["git", "tag", "-a", tag_name, "-m", commit_message], check=True)
        subprocess.run(["git", "push", "origin", "--tags"], check=True)
        logger.info(f"Successfully created and pushed tag {tag_name}")
    except subprocess.CalledProcessError as e:
        logger.info(f"Error creating or pushing tag: {e}")

