def _as_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except Exception:
        # strings like "12,345.00" -> strip commas
        try:
            return float(str(value).replace(",", ""))
        except Exception:
            return None

def _to_stock_status(stock_type: Optional[str], available: Optional[bool]) -> Optional[str]:
    """
    Map Mixin stock signals to WooCommerce-like stock_status.
    out_of_stock -> outofstock
    unlimited/limited/instock/True -> instock
    """
    if stock_type == "out_of_stock":
        return "outofstock"
    if stock_type in ("unlimited", "limited", "instock"):
        return "instock"
    if available is True:
        return "instock"
    if available is False:
        return "outofstock"
    return None

def _get_gmt_datetime_n_minutes_ago(n: int) -> str:
    """
    Returns the ISO 8601 datetime string in GMT/UTC for n minutes ago from now.
    """
    dt = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(minutes=n)
    return dt.strftime("%Y-%m-%dT%H:%M:%S")

