        return []

async def get_products_by_custom_category_with_messages(
    ecommerce_identifier: str, category_name: str, size: int = 100
) -> List:
    """Get products by custom category using the new query with first_messages requirement.

    Args:
        ecommerce_identifier: The ecommerce identifier.
        category_name: Custom category name to filter by.
        size: Maximum number of products to return.

    Returns:
        List of Product objects matching the custom category with first_messages.
    """
    try:
        index_name = db_repository.get_index_name(ecommerce_identifier)

        query = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "nested": {
                                "path": "product.custom_categories",
                                "query": {
                                    "bool": {
                                        "must": [
                                            {
                                                "match": {
                                                    "product.custom_categories.name": {
                                                        "query": category_name,
                                                        "operator": "and",
                                                    }
                                                }
                                            }
                                        ],
                                    }
                                },
                            }
                        },
                        {"exists": {"field": "product.first_messages"}},
                    ]
                }
            },
            "_source": {
                "excludes": [
                    "product.product_vector",
                    "product.custom_attributes.vector",
                ]
            },
            "size": size,
        }

        response = await db_repository.elastic_search_repository.search(index=index_name, body=query)
        hits = response["hits"]["hits"]

        if hits:
            products = db_repository._parse_ecommerce_part(
                hits,
                part_object=db_repository.ecommerce_parts_mapping["product"],
                part_name="product",
            )
            return products
        return []

    except Exception as e:
        print(f"   ⚠️  Error getting products with custom query: {e}")
        return []

def extract_attribute_value(custom_attr):
    """Extract value from custom attribute based on type."""
    if hasattr(custom_attr, "value_string") and custom_attr.value_string:
        return custom_attr.value_string
    elif hasattr(custom_attr, "value_int") and custom_attr.value_int is not None:
        return custom_attr.value_int
    elif hasattr(custom_attr, "value_long") and custom_attr.value_long is not None:
        return custom_attr.value_long
    elif hasattr(custom_attr, "value_float") and custom_attr.value_float is not None:
        return custom_attr.value_float
    elif hasattr(custom_attr, "value_date") and custom_attr.value_date:
        return custom_attr.value_date
    elif hasattr(custom_attr, "value_float_range") and custom_attr.value_float_range:
        return custom_attr.value_float_range
    return None

def create_category_sheet(
    worksheet,
    tables,
    vazir_font,
    header_font,
    header_fill,
    light_fill,
    white_fill,
    thin_border,
    center_alignment,
    right_alignment,
):
    """Create a category sheet with its tables."""
    current_row = 1

    if "Attributes" in tables:
        attributes_df = tables["Attributes"]

        for col_idx, col_name in enumerate(attributes_df.columns, 1):
            cell = worksheet.cell(row=current_row, column=col_idx, value=col_name)
            cell.font = header_font
            cell.fill = header_fill
            cell.border = thin_border
            cell.alignment = center_alignment
        current_row += 1

        for row_idx, (_, row) in enumerate(attributes_df.iterrows()):
            for col_idx, value in enumerate(row.values, 1):
                cell = worksheet.cell(row=current_row, column=col_idx, value=value)
                cell.font = vazir_font
                cell.border = thin_border
                if row_idx % 2 == 0:
                    cell.fill = white_fill
                else:
                    cell.fill = light_fill
                if col_idx in [1, 2]:
                    cell.alignment = right_alignment
                else:
                    cell.alignment = center_alignment
            current_row += 1

    if "Messages" in tables:
        messages_df = tables["Messages"]

        for col_idx, col_name in enumerate(messages_df.columns, 1):
            cell = worksheet.cell(row=current_row, column=col_idx, value=col_name)
            cell.font = header_font
            cell.fill = header_fill
            cell.border = thin_border
            cell.alignment = center_alignment
        current_row += 1

        for row_idx, (_, row) in enumerate(messages_df.iterrows()):
            for col_idx, value in enumerate(row.values, 1):
                cell = worksheet.cell(row=current_row, column=col_idx, value=value)
                cell.font = vazir_font
                cell.border = thin_border
                if row_idx % 2 == 0:
                    cell.fill = white_fill
                else:
                    cell.fill = light_fill

                cell.alignment = right_alignment
            current_row += 1

    for column in worksheet.columns:
        max_length = 0
        column_letter = column[0].column_letter

        for cell in column:
            try:
                if cell.value and len(str(cell.value)) > max_length:
                    max_length = len(str(cell.value))
            except:
                pass

        adjusted_width = min(max(max_length + 2, 15), 100)
        worksheet.column_dimensions[column_letter].width = adjusted_width

