class SimpleValidationParser:
    """Simple parser for YES/NO validation responses that mimics run_chain output."""

    def parse(self, ai_message) -> dict:
        """Parse YES/NO response to boolean.

        Args:
            ai_message: AIMessage object or string containing YES or NO.

        Returns:
            Dictionary with is_valid boolean.
        """
        # Handle both AIMessage objects and strings
        if hasattr(ai_message, "content"):
            text = ai_message.content
        else:
            text = str(ai_message)

        text = text.strip().upper()
        return {"is_valid": "YES" in text}

    def __call__(self, ai_message) -> dict:
        """Make the parser callable for LangChain compatibility."""
        return self.parse(ai_message)

