async def logic_response(input_: RequestPayload):
    LOGGER.info(f"input: {input_.message}")

    try:
        file_id = collection_to_algorithm[input_.collection_identifier]["algorithm_id"]
    except KeyError:
        return JSONResponse(
            content={"detail": "didn't find collection_models identifier!"},
            status_code=status.HTTP_400_BAD_REQUEST,
            headers=None,
        )

    if input_.history:
        history = input_.history
    else:
        history = sessions.get(input_.config["chat_id"], {})

    ai_input_message = AlgorithmInput(
        file_id=file_id,
        message=input_.message,
        history=history,
    )

    try:
        ai_pipeline = ai_pipelines.algorithms[str(file_id)]
    except KeyError:
        return JSONResponse(
            content={"detail": "the requested algorithm has not loaded!"},
            status_code=status.HTTP_400_BAD_REQUEST,
            headers=None,
        )

    ai_input_message.history = HistoryHandler.prune_history(
        ai_input_message.history,
        max_token_len=ai_pipeline.config.max_token_len,
        last_n_conversation=ai_pipeline.config.last_n_conversation,
    )

    result = await ai_pipeline(ai_input_message)

    sessions[input_.config["chat_id"]] = result.history

    LOGGER.info(result)
    return {"reply": result}

def reset(input_: dict):
    LOGGER.info(f"chat_id: {input_['chat_id']}")

    if input_["chat_id"] in sessions:
        sessions[input_["chat_id"]] = {}
        return {"reply": "deleted history successfully!"}
    else:
        return {"reply": "there is no such session!"}

