def remove_headers_from_chunk(chunks) -> str:
    """
    Clean the chunk by removing markdown header lines.
    For instance, any line starting with one or more '#' is cleaned."""
    removed_chunks = []
    for i, chunk in enumerate(chunks):
        if "heading_string" in chunk.content:
            # removed_chunks.append(chunk.id)
            chunks[i].content = clean_string(chunk.content)
    return removed_chunks

