def _create_test_app(
    auth_success: bool = True,
    webhook_controller_cls=DummyWebhookController,
    **webhook_kwargs,
):
    """Builds a FastAPI app wired with stub dependencies."""
    from parschat_logic.frameworks.fast_api.endpoints.inference_endpoint import (
        InferenceEndpoint,
    )
    from parschat_logic.adapters.controllers.inference_controller import (
        InferenceWebhookController,
    )
    from parschat_logic.frameworks.interfaces.controllers.successive_task_controller import (
        TaskRegistryInterface,
    )

    webhook_stub = webhook_controller_cls(**webhook_kwargs)
    registry_stub = DummyTaskRegistry()

    class _StubDeps:  # mimics FastApiIntegration.depends
        def __init__(self, mapping):
            self._mapping = mapping

        def depends(self, cls):
            async def _provider():
                return self._mapping[cls]

            return Depends(_provider)

    deps = _StubDeps(
        {
            InferenceWebhookController: webhook_stub,
            TaskRegistryInterface: registry_stub,
        }
    )
    auth_dep = DummyAuthDependency(success=auth_success)

    app = FastAPI()
    endpoint = InferenceEndpoint(deps=deps, auth_dependency=auth_dep)
    app.include_router(endpoint.api_route)
    return app, webhook_stub, registry_stub

