class TestCollectionToAlgorithmMapping(unittest.TestCase):
    """Test suite for collection_to_algorithm mapping to ensure no conflicts in manual pipelines loading."""

    def setUp(self):
        """Set up test fixtures for collection_to_algorithm mapping tests."""
        self.collection_to_algorithm = collection_to_algorithm

    def test_no_duplicate_collection_identifiers(self):
        """Test that there are no duplicate collection identifiers in the mapping.

        This ensures each collection identifier maps to exactly one algorithm configuration.
        """
        collection_ids = list(self.collection_to_algorithm.keys())
        unique_collection_ids = set(collection_ids)

        self.assertEqual(
            len(collection_ids),
            len(unique_collection_ids),
            f"Duplicate collection identifiers found. "
            f"Total: {len(collection_ids)}, Unique: {len(unique_collection_ids)}",
        )

    def test_no_conflicting_algorithm_ids(self):
        """Test that each algorithm_id maps to exactly one algorithm name.

        This prevents conflicts where the same algorithm_id points to different algorithms.
        """
        algorithm_id_to_name = {}
        conflicts = []

        for collection_id, config in self.collection_to_algorithm.items():
            algorithm_id = config["algorithm_id"]
            algorithm_name = config["algorithm"]

            if algorithm_id in algorithm_id_to_name:
                existing_name = algorithm_id_to_name[algorithm_id]
                if existing_name != algorithm_name:
                    conflicts.append(
                        {
                            "algorithm_id": algorithm_id,
                            "existing_algorithm": existing_name,
                            "conflicting_algorithm": algorithm_name,
                            "collection_id": collection_id,
                        }
                    )
            else:
                algorithm_id_to_name[algorithm_id] = algorithm_name

        self.assertEqual(
            len(conflicts),
            0,
            f"Algorithm ID conflicts detected: {conflicts}. "
            f"Each algorithm_id must map to exactly one algorithm name.",
        )

    def test_algorithm_names_match_ids(self):
        """Test that algorithm names follow the expected naming convention with their IDs.

        This ensures consistency between algorithm names and their corresponding IDs.
        """
        naming_violations = []

        for collection_id, config in self.collection_to_algorithm.items():
            algorithm_id = config["algorithm_id"]
            algorithm_name = config["algorithm"]

            # Check if the algorithm name ends with the algorithm_id
            expected_suffix = f"_{algorithm_id}"
            if not algorithm_name.endswith(expected_suffix):
                naming_violations.append(
                    {
                        "collection_id": collection_id,
                        "algorithm_name": algorithm_name,
                        "algorithm_id": algorithm_id,
                        "expected_suffix": expected_suffix,
                    }
                )

        self.assertEqual(
            len(naming_violations),
            0,
            f"Algorithm naming convention violations detected: {naming_violations}. "
            f"Algorithm names should end with their corresponding algorithm_id.",
        )

    def test_valid_collection_identifier_format(self):
        """Test that all collection identifiers follow the expected UUID-like format.

        This ensures consistency in collection identifier formatting.
        """

        # Pattern for 32-character hexadecimal string (UUID without hyphens)
        uuid_pattern = re.compile(r"^[a-f0-9]{32}$")
        invalid_identifiers = []

        for collection_id in self.collection_to_algorithm.keys():
            if not uuid_pattern.match(collection_id):
                invalid_identifiers.append(collection_id)

        self.assertEqual(
            len(invalid_identifiers),
            0,
            f"Invalid collection identifier formats detected: {invalid_identifiers}. "
            f"Collection identifiers should be 32-character hexadecimal strings.",
        )

    def test_mapping_structure_integrity(self):
        """Test that each mapping entry has the required structure and data types.

        This ensures all mapping entries contain the required keys with correct data types.
        """
        required_keys = {"algorithm", "algorithm_id"}
        structure_violations = []

        for collection_id, config in self.collection_to_algorithm.items():
            if not isinstance(config, dict):
                structure_violations.append(
                    {"collection_id": collection_id, "error": f"Config is not a dict, got {type(config)}"}
                )
                continue

            missing_keys = required_keys - set(config.keys())
            if missing_keys:
                structure_violations.append(
                    {"collection_id": collection_id, "error": f"Missing required keys: {missing_keys}"}
                )
                continue

            if not isinstance(config["algorithm"], str):
                structure_violations.append(
                    {
                        "collection_id": collection_id,
                        "error": f"algorithm must be string, got {type(config['algorithm'])}",
                    }
                )

            if not isinstance(config["algorithm_id"], int):
                structure_violations.append(
                    {
                        "collection_id": collection_id,
                        "error": f"algorithm_id must be int, got {type(config['algorithm_id'])}",
                    }
                )

            if isinstance(config["algorithm_id"], int) and config["algorithm_id"] < 0:
                structure_violations.append(
                    {
                        "collection_id": collection_id,
                        "error": f"algorithm_id must be non-negative, got {config['algorithm_id']}",
                    }
                )

        self.assertEqual(len(structure_violations), 0, f"Mapping structure violations detected: {structure_violations}")

    def test_algorithm_uniqueness_per_collection(self):
        """Test that multiple collections can share the same algorithm but with consistent configuration.

        This allows multiple collections to use the same algorithm while ensuring configuration consistency.
        """
        algorithm_configs = {}
        inconsistencies = []

        for collection_id, config in self.collection_to_algorithm.items():
            algorithm_name = config["algorithm"]

            if algorithm_name in algorithm_configs:
                existing_config = algorithm_configs[algorithm_name]
                if existing_config != config:
                    inconsistencies.append(
                        {
                            "algorithm": algorithm_name,
                            "existing_config": existing_config,
                            "conflicting_config": config,
                            "collection_id": collection_id,
                        }
                    )
            else:
                algorithm_configs[algorithm_name] = config

        self.assertEqual(
            len(inconsistencies),
            0,
            f"Algorithm configuration inconsistencies detected: {inconsistencies}. "
            f"Collections sharing the same algorithm must have identical configurations.",
        )

