class MockRegistry:
    """Registry to keep track of all mock instances for proper isolation and cleanup."""

    def __init__(self):
        self._mocks = {}
        self._cleanup_callbacks = []

    def register_mock(self, name: str, mock_obj: Any) -> Any:
        """Register a mock object with a name for tracking."""
        self._mocks[name] = mock_obj
        return mock_obj

    def get_mock(self, name: str) -> Optional[Any]:
        """Get a registered mock by name."""
        return self._mocks.get(name)

    def reset_all_mocks(self):
        """Reset all registered mocks to clean state."""
        for mock_obj in self._mocks.values():
            if hasattr(mock_obj, "reset_mock"):
                mock_obj.reset_mock()

    def clear_registry(self):
        """Clear all registered mocks."""
        self._mocks.clear()

