class SimpleLLMMock:
    """Simplified LLM mock for testing, now a proper Runnable for LangChain."""

    def __init__(self):
        self._result = AIMessage(content="Default AIMessage from base LLM")
        self._side_effects = None
        self._call_count = 0

        # The main LLM mock is a Runnable
        class LLMRunnable(FakeRunnable):
            def __init__(self, parent):
                super().__init__(parent._result)
                self._parent = parent
                self.last_args = None
                self.last_kwargs = None

            def set_result(self, result):
                self._parent.set_result(result)

            async def ainvoke(self, *args, **kwargs):
                self.last_args = args
                self.last_kwargs = kwargs
                return await self._parent._get_result()

            def invoke(self, *args, **kwargs):
                self.last_args = args
                self.last_kwargs = kwargs
                return self._parent._get_result_sync()

            def bind_tools(self, *args, **kwargs):
                return self

            def with_structured_output(self, *args, **kwargs):
                return self

            @property
            def call_count(self):
                return self._parent._call_count

        self._llm_runnable = LLMRunnable(self)
        self.bound_tools = self._llm_runnable
        self.structured_output = self._llm_runnable

    @property
    def llm(self):
        return self._llm_runnable

    def set_result(self, result):
        self._result = result
        self._side_effects = None
        self._call_count = 0
        if isinstance(result, list):
            self._side_effects = list(result)
        elif isinstance(result, Exception):
            self._side_effects = [result]

    async def _get_result(self):
        if self._side_effects is not None:
            if self._call_count < len(self._side_effects):
                val = self._side_effects[self._call_count]
                self._call_count += 1
                if isinstance(val, Exception):
                    raise val
                return val
            return self._side_effects[-1]
        self._call_count += 1
        if isinstance(self._result, Exception):
            raise self._result
        return self._result

    def _get_result_sync(self):
        if self._side_effects is not None:
            if self._call_count < len(self._side_effects):
                val = self._side_effects[self._call_count]
                self._call_count += 1
                if isinstance(val, Exception):
                    raise val
                return val
            return self._side_effects[-1]
        self._call_count += 1
        if isinstance(self._result, Exception):
            raise self._result
        return self._result

