def load_collections(
    path_to_dataloaders=f"{DEFAULT_PATH}/tests/samples/files/metadata_extractor/collections/",
) -> Dict[str, Collection]:
    collections = {}

    for filename in os.listdir(path_to_dataloaders):
        file_path = os.path.join(path_to_dataloaders, filename)

        if filename.endswith(".json"):
            with open(
                file_path,
                "r",
            ) as file:
                data = json.load(file)
                collections[data["collection_info"]["name"]] = Collection(**data)
    return collections

def load_llm_results(
    path_to_dataloaders=f"{DEFAULT_PATH}/tests/samples/files/metadata_extractor/llm_raw_results/",
):
    llm_results = {}

    for filename in os.listdir(path_to_dataloaders):
        file_path = os.path.join(path_to_dataloaders, filename)

        if filename.endswith(".json"):
            with open(
                file_path,
                "r",
            ) as file:
                llm_results[filename] = json.load(file)
    return llm_results

class TestMetaTextUtils(unittest.TestCase):
    def setUp(self):
        self.collections = load_collections()
        self.llm_results = load_llm_results()

        self.config = type(
            "Config",
            (object,),
            {
                "max_segment_size": 100,
                "min_segment_size": 10,
            },
        )()

    def test_line_numbering(self):
        self.document_content = self.collections["mahak"].reference_datum[0].content
        numbered_content = MetaTextUtils.line_numbering(document=self.document_content)
        self.assertIn(
            "line number: 395 |",
            numbered_content,
            "'line number: 395 | ' not found in numbered content",
        )

    def test_heading_based_segmentation(self):
        self.document_content = self.collections["golgohar"].reference_datum[0].content
        content = MetaTextUtils.line_numbering(document=self.document_content)
        segments, used_recursive_splitter = MetaTextUtils.heading_based_segmentation(
            content,
            max_length=self.config.max_segment_size,
            min_length=self.config.min_segment_size,
            len_func=lambda e: len(e.split()),
        )

        self.assertEqual(
            len(segments), 9, "used_recursive_splitter does not have 9 elements"
        )

